export const part2: Record<string, string[]> = {
  "10:1": ["Alif Lam Ra. Those are the ayat of the wise Kitab.", "অ, ল, র,  এসব (অক্ষরগুলো) এই প্রজ্ঞাময় গ্রন্থের প্রমান।"],
  "10:2": ["Is it a marvel for mankind that We revealed to a man among them: \"Warn mankind, and give good news to those who believe that for them is a footing of truth with their Rabb\"? The kafirin say: \"This is clear sorcery.\"", "এটা কি লোকদের জন্য খুব বেশি বিস্ময়কর যে আমরা তাদের মতো কোন লোককে অনুপ্রাণিত করেছি? তাকে (অনুপ্রাণিত করা হয়েছে বলার জন্য যে), “তুমি লোকদের সতর্ক করবে, এবং যারা বিশ্বাস করে তাদেরকে সুসংবাদ দিবে যে তারা তাদের প্রভুর কাছে বিশেষ অবস্থান অর্জন করেছে”। অবিশ্বাসীরা বলল, “এ তো এক চালাক যাদুকর!"],
  "10:3": ["Indeed your Rabb is Allah, who created the heavens and the earth in six days, then settled upon the high seat; Allah directs the affair. None intercedes except by leave from Allah. That is Allah, your Rabb — so worship Allah. Will you not remember?", "আল্লাহ-ই তোমাদের একমাত্র প্রভু; যিনি আকাশমণ্ডলী ও পৃথিবীকে ছয় দিনে সৃষ্টি করেছেন, এরপর সকল কর্তৃত্ব গ্রহণ করেছেন। তিনি সকল বিষয় নিয়ন্ত্রণ করেন। কোন সুপারিশকারী নেই, তাঁর ইচ্ছানুসারে ব্যতিত। এমনই হচ্ছেন তোমাদের প্রভু, আল্লাহ। তোমরা তাঁর উপাসনা করবে। তোমরা কি মনোযোগী হবে না?"],
  "10:4": ["To Allah is your return, all together; the promise of Allah is true. Indeed Allah begins the creation, then brings it back, to repay those who believe and do the salihin deeds with equity; and those who disbelieve — for them is a drink of scalding water and a painful punishment, for what they used to disbelieve.", "তাঁর কাছে তোমাদের চূড়ান্ত প্রত্যাবর্তন, তোমাদের সকলের। এটি আল্লাহর সত্য অঙ্গীকার। তিনি সৃষ্টির সূচনা করেন, এরপর এর পুনরাবৃত্তি করেন তাদের পুরস্কৃত করার জন্য যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, ন্যায়সঙ্গতভাবে। আর তাদের বিষয়ে যারা অবিশ্বাস করে, তারা নিজেদের প্রতি টেনে এনেছে নারকীয় পানীয়, এবং এক যন্ত্রণাদায়ক শাস্তি, তাদের অবিশ্বাসের জন্য।"],
  "10:5": ["It is Allah who made the sun a shining light and the moon a light, and set its measures, that you may know the count of years and the reckoning. Allah created that only in truth. Allah sets out the ayat in detail for a people who know.", "তিনিই সেই সত্ত্বা, যিনি সূর্যকে করেছেন প্রজ্বলিত, এবং চাঁদকে আলোকিত, এবং তিনি এর পর্যায়সমূহ নকশা করেছেন যাতে তোমরা বছর গণনা এবং এর হিসাব করা শিখতে পারো। আল্লাহ এই সবকিছু সৃষ্টি করেননি, কোন বিশেষ উদ্দেশ্য ছাড়া। তিনি সেসব লোকদের জন্য প্রকাশনাবলী ব্যাখ্যা করেন যারা জানে।"],
  "10:6": ["Indeed in the alternation of night and day, and in what Allah created in the heavens and the earth, are ayat for a people who are mindful.", "নিশ্চয়, রাত এবং দিনের পালা-বদলে, এবং যা আল্লাহ আকাশমন্ডলী ও পৃথিবীতে সৃষ্টি করেছেন, তাতে লোকদের জন্য প্রমান রয়েছে যারা সৎকর্মশীল।"],
  "10:7": ["Indeed those who do not hope for meeting Us, and are content with the life of this world and settled in it, and those who are unmindful of Our ayat —", "যারা আমাদের সাক্ষাতের আশা করছে না, এবং এই পার্থিব জীবনে নিবিষ্ট হয়ে আছে ও তাতেই পরিতৃপ্ত, এবং আমাদের প্রমাণগুলোতে মনোযোগ দিতে চায় না;"],
  "10:8": ["their shelter is the Fire, for what they used to earn.", "এরা নরক টেনে এনেছে তাদের চূড়ান্ত আবাস হিসেবে, তাদের নিজেদের কাজের পরিণামে।"],
  "10:9": ["Indeed those who believe and do the salihin deeds — their Rabb guides them by their faith; rivers flow beneath them in the gardens of bliss.", "আর যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, তাদের প্রভু তাদের পথ-প্রদর্শন করেন, তাদের বিশ্বাসের গুণে। সবচেয়ে সুখময় বাগানসমূহে যেখানে তাদের তলদেশে প্রবাহিত হবে নদ-নদী।"],
  "10:10": ["Their call in them is: \"Glory be to You, O Allah\", and their greeting in them is \"Peace\", and the last of their call is: \"Praise belongs to Allah, Rabb of all beings.\"", "সেখানে তাদের প্রার্থনা হচ্ছেঃ “আপনি মহিমান্বিত, আমাদের উপাস্য”। সেখানে তাদের সম্ভাষণ হচ্ছে, “শান্তি,”এবং তাদের পরম প্রার্থনা হচ্ছেঃ “প্রশংসা আল্লাহর, মহাবিশ্বের প্রভু”।"],
  "10:11": ["Were Allah to hasten for mankind the evil as they hasten the good, their term would already have been decreed for them. So We leave those who do not hope for meeting Us to wander blind in their transgression.", "যদি আল্লাহ লোকদের অর্জিত শাস্তি ত্বরান্বিত করতেন, যেভাবে তারা জীবিকা দাবি করে, তারা অনেক আগেই ধ্বংস হয়ে যেতো। যাহোক, যারা আমাদের সাথে সাক্ষাতে বিশ্বাস করে না আমরা তাদের সীমালঙ্ঘনে ছেড়ে দেই, পথভ্রষ্টতায় মগ্ন।"],
  "10:12": ["And when harm touches a human, he calls Us — on his side, or sitting, or standing. Then when We uncover the harm from him, he passes on as though he never called Us to the harm that touched him. Thus is made fair for the exceeders what they used to do.", "যখন দূর্দশা মানুষকে স্পর্শ করে, সে আমাদের কাছে শুয়ে, বসে, অথবা দাঁড়িয়ে মিনতি করে। কিন্তু, যখনই আমরা তার দূর্দশা দূর করি, সে এমনভাবে চলে যেন সে কখনোই আমাদের কাছে কোন কষ্ট দূর করতে মিনতি করেনি। সীমালঙ্ঘনকারীদের কাজ এভাবেই তাদের চোখে সজ্জিত করা হয়।"],
  "10:13": ["And We destroyed the generations before you when they did wrong, and their rusul came to them with clear proofs, yet they would not believe. Thus We repay the mujrim people.", "আমরা তোমাদের আগে কত প্রজন্মই না ধ্বংস করেছি যখন তারা সীমালঙ্ঘন করেছিল। তাদের কাছে তাদের বার্তাবাহকগন সুস্পষ্ট প্রমাণাদি নিয়ে গিয়েছিল, কিন্তু তারা বিশ্বাস করতে প্রত্যাক্ষান করেছিল। আমরা এভাবেই অপরাধী লোকদের প্রতিফল দেই।"],
  "10:14": ["Then We made you successors in the earth after them, to see how you do.", "এরপর আমরা তাদের পর তোমাদেরকে পৃথিবীর উত্তরাধিকারী করলাম, তোমরা কেমন করবে তা দেখতে।"],
  "10:15": ["And when Our ayat are recited to them, clear, those who do not hope for meeting Us say: \"Bring a reading other than this, or change it.\" Say: \"It is not for me to change it of my own accord; I only follow what is revealed to me. Indeed I fear, if I disobey my Rabb, the punishment of an immense day.\"", "যখন আমাদের প্রকাশনাবলি তাদের কাছে আবৃতি করা হয়, যারা আমাদের সাথে সাক্ষাতের আশা করে না তারা বলে, \"এটা ছাড়া অন্য কোন কুরআন নিয়ে আসো, অথবা একে পরিবর্তন করো।”বলএটা সম্ভবই না যে আমি নিজে নিজে এর পরিবর্তন করি। আমি শুধু অনুসরণ করি যা আমার কাছে প্রকাশিত হয়। আমি ভয় করি, সেই ভয়ঙ্কর দিনের শাস্তিকে, যদি আমি আমার প্রভুকে অমান্য করি। \""],
  "10:16": ["Say: \"Had Allah willed, I would not have recited it to you, nor would Allah have made it known to you. I tarried among you a lifetime before it. Will you not reason?\"", "বল, “আল্লাহ যদি চাইতেন, না আমি এটি তোমাদের কাছে আবৃতি করতাম, না তোমরা এটি সম্পর্কে কোনকিছু জানতে পারতে। আমি তোমাদের মধ্যে এর আগের পুরোটা জীবন পার করেছি (এবং তোমরা আমাকে একজন বিবেকবান, সত্যবাদী ব্যক্তি হিসেবে জেনেছো)। তোমরা কি বুঝো না?”"],
  "10:17": ["So who is more wrongful than one who fabricates against Allah a lie, or denies the ayat of Allah? Indeed the mujrimin do not attain success.", "কে তার চেয়ে বেশি মন্দ যে আল্লাহ সম্পর্কে মিথ্যা রচনা করে, অথবা তাঁর প্রকাশনাবলি প্রত্যাখ্যান করে? নিশ্চয়, সীমাতিক্রমকারীরা কখনো সফল হয় না।"],
  "10:18": ["And they worship besides Allah what can neither harm them nor benefit them, and they say: \"These are our intercessors with Allah.\" Say: \"Do you tell Allah of what Allah does not know in the heavens or the earth?\" Glory be to Allah, and exalted is Allah above what they associate.", "তারা আল্লাহর পাশে অংশীদারদের উপাসনা করে যা তাদের ক্ষতি বা উপকার করার কোন ক্ষমতা রাখে না, এবং তারা বলে, “এরা আল্লাহর কাছে আমাদের সুপারিশকারী!” বল, “তোমরা কি আল্লাহকে আকাশমন্ডলী বা পৃথিবীর কোনকিছু জানাচ্ছ যা তিনি জানেন না?” তিনি মহিমান্বিত। তিনি সর্বোচ্চ; অংশীদারের প্রয়োজন থেকে অনেক উর্ধ্বে।"],
  "10:19": ["Mankind was but a single community; then they differed. And had not a word gone before from your Rabb, judgment would have been passed between them over what they differ about.", "লোকেরা এক ধর্মীয় সম্প্রদায়ভূক্ত ছিল, এরপর তারা বিবাদ করলো। যদি এটা আল্লাহর পক্ষ থেকে কোন পূর্ব নির্ধারিত আদেশ না হতো, তারা তাৎক্ষণাৎ তাদের বিবাদের বিষয়ে রায় পেতো।"],
  "10:20": ["And they say: \"Why is an aya not sent down to him from his Rabb?\" Say: \"The unseen belongs to Allah alone — so wait; I am with you among the waiting.\"", "তারা বলে, “কেমন করে তার কাছে তার প্রভুর পক্ষ থেকে কোন অলৌকিকতা অবতীর্ণ হল না?’ বল, “ভবিষ্যৎ আল্লাহর অধীনে; তাই অপেক্ষা করো, এবং আমিও তোমাদের সাথে অপেক্ষা করছি”।"],
  "10:21": ["And when We let mankind taste mercy after hardship that touched them, at once they plot against Our ayat. Say: \"Allah is swifter in planning.\" Indeed Our envoys write down what you plot.", "লোকেরা দুর্দশাগ্রস্থ হওয়ার পর আমরা যখন তাদের উপর দয়া করলাম, তারা তৎক্ষনাৎ আমাদের প্রকাশনাবলির বিরুদ্ধে ষড়যন্ত্র করলো! বল, \"আল্লাহর পরিকল্পনা আরো অধিক কার্যকর। কারণ আমাদের বার্তাবাহকরা তোমাদের সকল ষড়যন্ত্র সংরক্ষণ করছে।"],
  "10:22": ["It is Allah who moves you on the dry land and the sea, until when you are in the ships and they sail with them on a fair wind, and they rejoice in it — a storm wind comes upon it, and waves come at them from every side, and they think they are uhit. Then they call Allah, devoting the religion to Allah alone: \"If You rescue us from this, we shall surely be among the thankful.\"", "তিনিই সে সত্ত্বা যিনি তোমাদেরকে ভূখণ্ড এবং সাগরে ভ্রমন করান। তোমরা জাহাজে আরোহন করো এবং এগুলো পাল খাটিয়ে চমৎকার মৃদু বাতাসে   মসৃণভাবে চলে। এরপর, যখন সেখানে তারা আনন্দ করতে থাকে, যখন প্রচণ্ড বাতাস প্রবাহিত হয়, এবং ঢেউ তাদেরকে সব দিক থেকে ঘিরে ফেলে। সেই মুহূর্তেই তারা আল্লাহর কাছে মিনতি করে, তাদের প্রার্থনা আন্তরিকভাবে একমাত্র তাঁর নিকট উৎসর্গ করে, \"আপনি যদি আমাদেরকে এবারের মতো রক্ষা করেন, আমরা চিরকাল কৃতজ্ঞ থাকবো।"],
  "10:23": ["But when Allah rescues them, at once they transgress in the earth without right. O mankind, your transgression is only against yourselves — an enjoyment of the life of this world. Then to Us is your return, and We will tell you what you used to do.", "কিন্তু যেই মুহূর্তে তিনি তাদের রক্ষা করেন, তারা পৃথিবীতে সীমালঙ্ঘন করে, এবং সত্যের বিরোধিতা করে। হে লোকেরা, তোমাদের সীমালঙ্ঘন শুধু তোমাদের নিজ আত্মার ক্ষতি করে। তোমরা এই পার্থিব জীবনে নিয়ে নিবিষ্ট থাকো, এরপর আমাদের কাছে তোমাদের চূড়ান্ত প্রত্যাবর্তন, এরপর আমরা তোমাদেরকে জানাবো যা তোমরা করেছিলে।"],
  "10:24": ["The likeness of the life of this world is only like water We send down from the heaven: the plants of the earth mingle with it, from what mankind and the livestock eat, until when the earth has taken its adornment and is beautified, and its people think they have power over it, Our command comes to it by night or by day, and We make it a harvested stubble, as if it had not flourished the day before. Thus We set out the ayat in detail for a people who reflect.", "এই পার্থিব জীবনের উপমা হচ্ছে এরকম: আমরা আকাশ থেকে পানি বর্ষণ করি, তা দিয়ে পৃথিবী থেকে সব ধরণের উদ্ভিদ উৎপন্ন করতে, এবং লোকদের ও প্রানীদের জন্য খাদ্যের সংস্থান করতে। এরপর, যখনই পৃথিবীকে যথাযথভাবে সজ্জিত করা হয়, এবং এর লোকেরা ভাবে যে তারা এর নিয়ন্ত্রনে, আমাদের বিচার আসে রাতে বা দিনে, একে সম্পূর্ণ ধূলিসাৎ করে দিয়ে, যেন আগের দিন কোনকিছুরই অস্তিত্ব ছিল না। আমরা এভাবে প্রকাশনাবলি ব্যাখ্যা করি সে লোকদের জন্য যারা গভীর ভাবে চিন্তা করে।"],
  "10:25": ["And Allah calls to the home of peace, and guides whomever Allah wills to a straight path.", "আল্লাহ শান্তির নীড়ের দিকে আমন্ত্রন করেন, এবং যাকে ইচ্ছা তিনি সরল পথে পরিচালিত করেন।"],
  "10:26": ["For those who do good is the finest reward, and more; neither gloom nor abasement will overwhelm their faces. Those are the companions of the garden; they abide in it forever.", "সৎকর্মশীলদের জন্য, পুরুস্কার বহুগুনে বৃদ্ধি করা হবে। তাদের মুখমণ্ডলসমূহ কখনো কোন বঞ্চনা বা লজ্জা অনুভব করবে না। এরাই স্বর্গের বাসিন্দা; তারা সেখানে চিরকাল বাস করে।"],
  "10:27": ["And those who earn evil deeds — the repayment of an evil deed is its like, and abasement will overwhelm them. They have none to shield them from Allah. As if their faces are covered by pieces of dark night. Those are the companions of the Fire; they abide in it forever.", "আর তাদের ক্ষেত্রে যারা পাপ অর্জন করেছে, তাদের প্রতিফল তাদের পাপের সমতুল্য। অপমান হচ্ছে তাদের ভাগ্য, এবং আল্লাহর পাশে অন্য কেউ তাদেরকে রক্ষা করতে পারে না। তাদের মুখমণ্ডলকে মনে হবে যেন অন্ধকার রাতের টুকরা দিয়ে ছেয়ে আছে। তারা হবে নরকের বাসিন্দা; তারা সেখানে চিরকাল বাস করবে।"],
  "10:28": ["And the day We gather them all, then We say to those who associated: \"Take your places, you and your associates.\" Then We part them, and their associates say: \"You were not worshipping us.\"", "সেদিন যখন আমরা তাদের সকলকে সমবেত করবো, যারা অংশীদার উপাসনা করেছিল আমরা তাদের বলব, “আমরা তোমাদের একত্রিত করেছি, তোমাদের উপাস্যদের সাথে”। আমরা তাদেরকে একে অন্যের মুখোমুখি করবো, এবং তাদের উপাস্যরা তাদেরকে বলবে, “আমাদের কোন ধারনা ছিল না যে তোমরা আমাদের উপাস্য করেছ”।"],
  "10:29": ["\"Allah is sufficient as witness between us and you — we were indeed unaware of your worship.\"", "“আমাদের এবং তোমাদের মাঝে সাক্ষী হিসাবে আল্লাহ যথেষ্ট, যে আমরা সম্পূর্ণ অনবগত ছিলাম আমাদেরকে তোমাদের উপাসনার ব্যাপারে”।"],
  "10:30": ["There each nafs is tested for what it sent before, and they are returned to Allah, their true protector; and lost to them is what they used to fabricate.", "সেই সময় প্রত্যেক আত্মা পরীক্ষা করবে সবকিছু যা সে করেছিল। তারা তাদের ন্যায়সঙ্গত প্রভু এবং মনিব, আল্লাহর কাছে ফিরে যাবে এবং তাদের বানানো উপাস্যরা তাদেরকে প্রত্যাক্ষান করবে।"],
  "10:31": ["Say: \"Who provides for you from the heaven and the earth? Who holds the hearing and the sight? Who brings out the living from the dead and brings out the dead from the living? Who directs the affair?\" They will say: \"Allah.\" Say: \"Will you not then be mindful?\"", "বল, “কে আকাশ এবং পৃথিবী থেকে তোমাদের জন্য জীবিকা প্রদান করেন? কে তোমাদের সকল শ্রবন এবং দৃষ্টিশক্তি নিয়ন্ত্রন করেন? কে মৃত থেকে জীবিতকে বের করেন, এবং জীবিত থেকে মৃতকে বের করেন? কে সবকিছুর নিয়ন্ত্রনে রয়েছেন? তারা বলবে, “আল্লাহ”। বল, “তাহলে কেন তোমরা প্রত্যাদেশগুলো পালন করো না?”"],
  "10:32": ["That then is Allah, your true Rabb. So what is there after the truth but wandering? How then are you turned away?", "এমনই আল্লাহ, তোমাদের ন্যয়সঙ্গত প্রভু। সত্যের পর আর কি থাকতে পারে, মিথ্যা ছাড়া? কিভাবে তোমরা এই সবকিছু উপেক্ষা করতে পারো?"],
  "10:33": ["Thus the word of your Rabb comes true upon those who fasuqu, that they will not believe.", "এটিই হচ্ছে আল্লাহর সিদ্ধান্ত তাদের প্রতি যারা মন্দ হতে চায়; তারা বিশ্বাস করতে পারে না।"],
  "10:34": ["Say: \"Is there any of your associates who begins the creation then brings it back?\" Say: \"Allah begins the creation then brings it back. So how are you turned away?\"", "বল, “তোমাদের কোন উপাস্য কি সৃষ্টির সূচনা করে, এরপর এর পূনঃরাবৃতি করে? বল, “আল্লাহ সৃষ্টির সূচনা করেন, এরপর এর পূনঃরাবৃতি করেন?”"],
  "10:35": ["Say: \"Is there any of your associates who guides to the truth?\" Say: \"Allah guides to the truth.\" Is one who guides to the truth worthier to be followed, or one who cannot guide unless guided? What is the matter with you? How do you judge?", "বল, “তোমাদের কোন উপাস্য কি সত্যের দিকে পথ-প্রদর্শন করেন?”বল, “আল্লাহ সত্যের দিকে পথ-প্রদর্শন করেন। যে সত্যের দিকে পথ-প্রদর্শন করে সে কি অনুসরণের অধিক যোগ্য, নাকি যে পথ-প্রদর্শন করে না, বরং নিজের জন্যই পথ-নির্দেশনার দরকার হয়? তোমাদের বিচার-বিবেচনায় সমস্যা কি?"],
  "10:36": ["And most of them follow only conjecture. Indeed conjecture avails nothing against the truth. Indeed Allah knows what they do.", "তাদের অধিকাংশই অনুমান ছাড়া কিছু অনুসরণ করে না, এবং অনুমান সত্যের কোন বিকল্প নয়। তারা যা কিছু করে আল্লাহ সে সম্পর্কে সম্পূর্ণ অবগত।"],
  "10:37": ["And this reading could not have been fabricated apart from Allah; rather, it is a confirmation of what came before it, and a detailing of the Kitab, in which there is no doubt, from the Rabb of all beings.", "আল্লাহ ব্যতিত অন্য কারো পক্ষে কুরআন রচনা সম্ভব হতেই পারে না। এটি সকল পূর্ববর্তী বার্তা নিশ্চিত করে, এবং প্রদান করে একটি পূর্ণ বিস্তারিত ঐশীগ্রন্থ। এটি ভূলের উর্ধ্বে; কারন এটি মহাবিশ্বের প্রভুর কাছ থেকে আগত।"],
  "10:38": ["Or do they say: \"He fabricated it\"? Say: \"Then bring a chapter like it, and call whomever you can apart from Allah, if you are sadiq.\"", "যদি তারা বলে, “সে এটা মিথ্যা উদ্ভাবন করেছে,”“তবে এগুলোর মতো একটি সুরা তৈরি করো, এবং অন্য যে কাউকে ইচ্ছা আমন্ত্রন করো, আল্লাহ ছাড়া, যদি তোমরা সত্যবাদী হও”।"],
  "10:39": ["No — they denied what they did not yuhitu in knowledge, and whose meaning had not yet come to them. Thus denied those before them. So see how the end of the wrongdoers was.", "নিশ্চয়, তারা এটি অধ্যয়ন এবং পরখ না করে, এবং এটি বুঝার আগেই প্রত্যাখ্যান করেছে। এভাবেই তাদের পূর্ববর্তীরা অবিশ্বাস করেছিল। সুতরাং, সীমাতিক্রমকারীদের পরিণাম লক্ষ্য করো।"],
  "10:40": ["And among them are those who believe in it, and among them are those who do not believe in it. And your Rabb knows best the corrupters.", "তাদের কেউ কেউ বিশ্বাস করে (এই ঐশীগ্রন্থে), যখন অন্যরা এতে অবিশ্বাস করে। তোমার প্রভু মন্দকর্মীদের ব্যাপারে পূর্ণ অবগত।"],
  "10:41": ["And if they deny you, say: \"For me my deeds, and for you your deeds. You are cleared of what I do, and I am cleared of what you do.\"", "যদি তারা তোমাকে প্রত্যাখ্যান করে, তবে বল, “আমার কর্ম আমার জন্য, এবং তোমাদের কর্ম তোমাদের জন্য। আমি যা কিছু করি তার জন্য তোমরা দায়ী নও, এবং তোমরা যা কিছু করো তার জন্য আমি দায়ী নই”।"],
  "10:42": ["And among them are those who listen to you. But can you make the deaf hear, even though they do not reason?", "তাদের কেউ কেউ তোমার কথা শোনে, কিন্তু তুমি কি বধিরকে শোনাতে পারো, যদিও তারা বুঝতে পারে না?"],
  "10:43": ["And among them are those who look at you. But can you guide the unseeing, even though they do not see?", "তাদের কেউ কেউ তোমার দিকে তাকায়, কিন্তু তুমি কি অন্ধকে পথ দেখাতে পারো, যদিও তারা দেখে না?"],
  "10:44": ["Indeed Allah wrongs mankind nothing, but mankind wrong themselves.", "আল্লাহ কখনো লোকদের প্রতি ক্ষতি করেন না; লোকেরা নিজেরাই তাদের আত্মার ক্ষতি করে।"],
  "10:45": ["And the day We gather them, it will be as though they had tarried but an hour of the day, recognizing one another. Those are the khasirin who denied the meeting with Allah, and they were not guided.", "সে দিন যখন তিনি তোমাদের সকলকে সমবেত করবেন, তারা সাক্ষাতের সময়, উপলব্ধি করবে যে তারা এই দুনিয়াতে দিনের একটি ঘণ্টা অবস্থান করেছিল। তারা নিশ্চয় ক্ষতিগ্রস্থ যারা আল্লাহর সাথে সাক্ষাতে অবিশ্বাস করেছিল; এবং পথভ্রষ্টতা বেছে নিয়েছিল।"],
  "10:46": ["And whether We show you some of what We promise them, or We take you back, to Us is their return; then Allah is witness over what they do.", "যে (শাস্তির) বিষয়ে আমরা তাদের অঙ্গীকার করি যদি এর কিছু অংশ আমরা তোমাকে দেখাই, অথবা এর আগেই তোমার জীবনাবসান করি, তবে আমাদের কাছে তাদের চূড়ান্ত প্রত্যাবর্তন। আল্লাহ তাদের করা সবকিছুর সাক্ষী।"],
  "10:47": ["And every community has a Rasul. And when their Rasul comes, judgment is passed between them with equity, and they are not wronged.", "প্রত্যেক সম্প্রদায়ের প্রতি, একজন বার্তাবাহক। তাদের বার্তাবাহক আসার পর, তাদেরকে ন্যায়সঙ্গতভাবে মূল্যায়ন করা হয়, সামান্যতম অবিচার ছাড়াই।"],
  "10:48": ["And they say: \"When is this promise, if you are sadiq?\"", "তারা চ্যালেঞ্জ করেঃ “কখন এই ভবিষ্যৎবানী ঘটবে, যদি তুমি সত্য বলে থাক?"],
  "10:49": ["Say: \"I possess for myself neither harm nor benefit except what Allah wills. Every community has a term; when its term comes, they cannot delay it an hour, nor can they advance it.\"", "বল, “আমার কোন ক্ষমতা নেই নিজের ক্ষতি করার, অথবা নিজের উপকার করার; আল্লাহ যা চান শুধু তা-ই হয়”। প্রত্যেক সম্প্রদায়ের একটি পূর্বনির্ধারিত জীবনকাল রয়েছে। যখন তাদের সময় শেষ হয়ে যায়, তারা একে এক ঘণ্টা বিলম্ব করাতে পারে না, না একে এগোতে পারে।"],
  "10:50": ["Say: \"Tell me — if the punishment of Allah comes upon you by night or by day, what is it that the mujrimin seek to hasten?\"", "বল, “যদি তোমাদের কাছে তাঁর শাস্তি রাতে বা দিনে আসে, তবে কেন সীমালঙ্গনকারীরা এমন তাড়াহুড়া করছে?"],
  "10:51": ["Then, when it befalls, will you believe in it? Now — when you had been seeking to hasten it?", "“যদি এটা ঘটে, তোমরা কি তখন বিশ্বাস করবে? কেন তোমরা তখন বিশ্বাস করবে? তোমরা এর আসার ব্যাপারে চ্যালেঞ্জ করতে?"],
  "10:52": ["Then it will be said to those who did wrong: \"Taste the punishment of eternity. Are you repaid anything but what you used to earn?\"", "সীমালঙ্ঘনকারীদের বলা হবে, “চিরস্থায়ী শাস্তি আস্বাদন করো। তোমরা কি সঠিক প্রতিদান পাওনি যা অর্জন করেছ তার জন্য”।"],
  "10:53": ["And they ask you to tell them: \"Is it true?\" Say: \"Yes, by my Rabb, it is true indeed — and you cannot escape.\"", "তারা তোমার ভবিষ্যদ্বানী করাকে চ্যালেঞ্জ করেঃ “এটা কি সত্যিই ঘটবে?”বল, “হ্যাঁ নিশ্চয়, আমার প্রভুর শপথ, এটাই সত্য, এবং তোমরা কখনই পালাতে পারবে না”।"],
  "10:54": ["And if every nafs that did wrong had all that is in the earth, it would offer it as ransom. And they will conceal regret when they see the punishment, and judgment will be passed between them with equity, and they will not be wronged.", "যদি কোন মন্দ আত্মা পৃথিবীর সবকিছুর অধিকারী হয়, সে তৎক্ষণাৎ মুক্তিপন হিসাবে তা উপস্থাপন করবে। যখন তারা শাস্তি দেখবে তারা অনুশোচনায় জর্জরিত হবে। তারা ন্যায়সঙ্গতভাবে বিচার পাবে, সামান্যতম অবিচার ছাড়া।"],
  "10:55": ["Indeed, to Allah belongs what is in the heavens and the earth. Indeed, the promise of Allah is true — but most of them do not know.", "নিঃসন্দেহে, আকাশমণ্ডলী এবং পৃথিবীর সবকিছু আল্লাহর। নিঃসন্দেহে, আল্লাহর অঙ্গীকার সত্য, কিন্তু তাদের অধিকাংশই জানে না।"],
  "10:56": ["It is Allah who gives life and causes death, and to Allah you return.", "তিনি জীবন এবং মৃত্যু নিয়ন্ত্রন করেন, এবং তাঁর কাছেই তোমাদের প্রত্যাবর্তন।"],
  "10:57": ["O mankind, admonition has come to you from your Rabb, and a healing for what is in the breasts, and a guidance and a mercy for the muminin.", "হে লোকেরা, এখানে তোমাদের প্রভুর কাছ থেকে এসেছে জ্ঞানালোক, এবং যা কিছু তোমাদের হৃদয়কে যন্ত্রণা দেয়, তার জন্য নিরাময়, এবং পথনির্দেশনা, এবং বিশ্বাসীদের জন্য দয়া।"],
  "10:58": ["Say: \"By the favor of Allah and by the mercy of Allah — in that let them rejoice. It is better than what they amass.\"", "বল, “আল্লাহর করুণা এবং তাঁর দয়ায় তারা আনন্দ করবে”। এটা যেকোন সম্পদ থেকে অনেক উত্তম যা তারা সঞ্চয় করতে পারে।"],
  "10:59": ["Say: \"Have you considered what Allah has sent down to you of provision, and you have made some of it forbidden and some lawful?\" Say: \"Has Allah permitted you, or do you fabricate against Allah?\"", "বল, “তোমরা কি লক্ষ্য করেছো, কিভাবে আল্লাহ সকল প্রকার জীবিকা তোমাদের নিকট অবতীর্ণ করেন, এরপর তোমরা এগুলোর কতগুলোকে বে-আইনি, এবং কতগুলোকে আইনসিদ্ধ বলে উপস্থাপন করো?”বল, “আল্লাহ কি তোমাদের এটা করার অনুমতি দিয়েছেন?”নাকি তোমরা মিথ্যা বানাও এবং সেগুলো আল্লাহর প্রতি আরোপ করো?”"],
  "10:60": ["And what do those who fabricate lies against Allah expect on the Day of Resurrection? Indeed Allah is full of favor toward mankind, but most of them do not give thanks.", "যারা আল্লাহ সম্পর্কে মিথ্যা বানায় তাদের কি কখনো এটা মনে হয় যে, তাদেরকে পুনরুত্থান দিনে তাঁর মুখোমুখি হতে হবে? নিশ্চয়, আল্লাহ লোকদের প্রতি তাঁর করুণা বর্ষণ করেন, কিন্তু তাদের অধিকাংশই অকৃতজ্ঞ।"],
  "10:61": ["And you are in no affair, nor do you recite any reading of it, nor do any deed, but We are witness over you as you pour into it. And nothing escapes your Rabb of the weight of a mote in the earth or in the heaven, nor smaller than that nor larger, but it is in a clear record.", "তোমরা এমন কোন পরিস্থিতির মধ্যে জড়িত হও না, না তোমরা আবৃতি করো কোন কুরআন, না তোমরা কোন কিছু করো, যাতে আমরা সাক্ষী থাকি না যখন তোমরা তা করো। এমনকি একটি পরমানুর ভরও তোমার প্রভুর নিয়ন্ত্রনের বাইরে নয়, তা হোক আকাশমণ্ডলীতে অথবা পৃথিবীতে। না কোন কিছু আছে পরমানুর চেয়ে ছোট, অথবা বড়, যা লিপিবদ্ধ নেই একটি সুস্পষ্ট দলিলে।"],
  "10:62": ["Indeed, the allies of Allah — no fear is upon them, nor do they grieve.", "নিঃসন্দেহে, আল্লাহর মিত্রদের কোন ভয় নেই, না তারা শোক করবে।"],
  "10:63": ["Those who believe and have been mindful.", "তারা হচ্ছে সেসব লোক যারা বিশ্বাস করে এবং ন্যায়পরায়ন জীবন-যাপন করে।"],
  "10:64": ["For them is the good news in the life of this world and in the other life. No change is there to the words of Allah. That is the supreme win.", "তাদের জন্য, আনন্দ এবং সুখ এই দুনিয়ায়, সেই সাথে পরকালে। এটা আল্লাহর অপরিবর্তনীয় আইন, এটাই হচ্ছে শ্রেষ্ঠ বিজয়।"],
  "10:65": ["And let not their speech grieve you. Indeed all might belongs to Allah. Allah is the All-Hearing, the All-Knowing.", "তাদের কথায় দুঃখ পেও না। সকল ক্ষমতা আল্লাহর। তিনি সর্বশ্রোতা, সর্বজ্ঞ।"],
  "10:66": ["Indeed, to Allah belongs whoever is in the heavens and whoever is on the earth. And those who call upon apart from Allah follow no associates — they follow only conjecture, and they do nothing but guess.", "নিঃসন্দেহে, আকাশমণ্ডলীর সকলে এবং পৃথিবীর সকলে আল্লাহর অধীন। যারা আল্লাহর পাশে উপাস্য স্থাপন করে তারা প্রকৃতপক্ষে কিছুই অনুসরন করছে না। তারা শুধু ভাবে যে তারা কোন কিছু অনুসরণ করছে। তারা শুধু অনুমান করে।"],
  "10:67": ["It is Allah who made the night for you to rest in, and the day giving sight. Indeed in that are ayat for a people who listen.", "তিনিই সে সত্ত্বা যিনি রাতকে করেছেন তোমাদের বিশ্রামের জন্য, এবং দিনকে করেছেন আলোকিত। এগুলো প্রমান সে লোকদের জন্য যারা শুনতে পারে।"],
  "10:68": ["They say: \"Allah has taken a child.\" Glory be to Allah! Allah is the Self-Sufficient — to Allah belongs what is in the heavens and what is in the earth. Do you have any warrant for this? Do you say of Allah what you do not know?", "তারা বলে, “আল্লাহ পুত্র জন্ম দিয়েছেন!” মহিমা তাঁরই। তিনি সবচেয়ে ধনী। আকাশমণ্ডলীর সবকিছু এবং পৃথিবীর সবকিছু তাঁর। এমন মিথ্যারোপের সমর্থনে তোমাদের কোন প্রমান নেই।  আল্লাহর যে বিষয়ে  তোমরা জানো না, তোমরা কি তা বলছো?"],
  "10:69": ["Say: \"Indeed those who fabricate lies against Allah do not attain success.\"", "ঘোষণা করোঃ “যারা আল্লাহ সম্পর্কে মিথ্যা বানায় তারা কখনোই সফল হবে না”।"],
  "10:70": ["An enjoyment in this world; then to Us is their return; then We make them taste the severe punishment for what they used to disbelieve.", "তারা এই বিশ্বে তাদের ক্ষণস্থায়ী অংশ পায়, এরপর আমাদের কাছে তাদের চুড়ান্ত প্রত্যাবর্তন, এরপর আমরা তাদের অবিশ্বাসের জন্য তাদেরকে কঠিন শাস্তি প্রদান করি।"],
  "10:71": ["And recite to them the story of Nuh: when he said to his people: \"O my people, if my staying among you and my reminding you of the ayat of Allah is too much for you, then upon Allah I have relied. So resolve your affair, you and your associates together, and let not your affair be a clouded thing for you; then carry out your decision concerning me, and give me no respite.\"", "তাদের জন্য আবৃতি করো নুহের ইতিহাস। সে তার লোকদের বলেছিল, “হে আমার লোকেরা,  যদি তোমরা আমার অবস্থান এবং তোমাদেরকে আমার আল্লাহর প্রকাশনাবলি স্মরণ করিয়ে দেয়াকে তোমাদের জন্য সাধ্যের অতীত মনে করো, তাহলে আল্লাহতে আমি আমার আস্থা রাখি। তোমাদের উচিত তোমাদের নেতাদের সাথে মিলিত হওয়া, তোমাদের নিজেদের মাঝে একটি চুড়ান্ত সিদ্ধান্তে সম্মত হওয়া, এরপর অনতিবিলম্বে আমাকে তা জানানো।"],
  "10:72": ["\"But if you turn away, I have not asked you for any reward — my reward is only upon Allah — and I am commanded to be among those who submit.\"", "\"যদি তোমরা মুখ ফিরিয়ে নাও, আমি তো তোমাদের কাছে কোন পারিশ্রমিক চাই নি। আমার পারিশ্রমিক আল্লাহ থেকে আসে। আমাকে একজন আত্মসমর্পণকারী হওয়ার জন্য আদেশ করা হয়েছে।"],
  "10:73": ["But they denied him, so We rescued him and those with him in the ship, and We made them successors, and We drowned those who denied Our ayat. So see how the end of those who were warned was.", "তারা তাকে প্রত্যাক্ষান করলো এবং, পরিনামে, আমরা তাকে এবং যারা তার সাথে নৌকায় যোগ দিয়েছিল তাদের রক্ষা করলাম; আমরা তাদেরকে উত্তরাধিকারী বানালাম। আর আমরা ডুবিয়ে দিলাম তাদেরকে যারা আমাদের প্রকাশনাবলি প্রত্যাক্ষান করেছিল। পরিনাম লক্ষ করো; তাদের সতর্ক করা হয়েছিল।"],
  "10:74": ["Then We sent after him rusul to their people, and they came to them with clear proofs, but they would not believe in what they had denied before. Thus We seal upon the hearts of the transgressors.", "এরপর আমরা তার পরবর্তীতে তাদের লোকদের কাছে বার্তাবাহকদের পাঠালাম, এবং তারা তাদেরকে সুস্পষ্ট প্রমানাদি দেখালো। কিন্তু তারা তাতে বিশ্বাস করার ছিল না যা তারা অতীতে প্রত্যাক্ষান করেছিল। আমরা এভাবে সীমালংঘনকারীদের হৃদয়ে মোহর মেরে দেই।"],
  "10:75": ["Then We sent after them Musa and Harun to Fir'awn and his chiefs with Our ayat, but they were arrogant — and they were a mujrim people.", "এরপর আমরা তাদের পরবর্তীতে ফেরাউন এবং তার দলের কাছে মুসা ও হারুনকে পাঠালাম, আমাদের প্রমানাদি সহকারে। কিন্তু তারা উদ্ধত হলো; এবং তারা সীমালংঘনকারী লোক ছিল।"],
  "10:76": ["And when the truth came to them from Us, they said: \"This is clear sorcery.\"", "আমাদের কাছ থেকে যখন সত্য তাদের কাছে আসলো, তারা বলল, “এটা স্পষ্টতই জাদু!”"],
  "10:77": ["Musa said: \"Do you say of the truth, when it has come to you: is this sorcery? Yet the sorcerers do not attain success.\"", "মুসা বলল, “তোমরা কি এভাবেই সত্যের বর্ণনা করো থাকো যখন তা তোমাদের কাছে আসে? এটা কি জাদু? কিভাবে কোন জাদুকর জয়ী হতে পারে?"],
  "10:78": ["They said: \"Have you come to us to turn us from what we found our fathers upon, and that you two may have the greatness in the land? And we are not muminin in you.\"", "তারা বলল, “তোমরা কি এসেছ আমাদেরকে তা থেকে সরিয়ে দিতে  যা আমরা আমাদের পিতামাতাদের করতে দেখেছি এবং নিজেরা বিশেষ অবস্থান অর্জণ করার জন্য? আমরা কখনই তোমাদের সাথে বিশ্বাসী হিসাবে যোগ দেবো না”।"],
  "10:79": ["And Fir'awn said: \"Bring me every knowing sorcerer.\"", "ফেরাউন বলল, “আমার কাছে প্রত্যেক অভিজ্ঞ জাদুকরকে নিয়ে আসো”।"],
  "10:80": ["And when the sorcerers came, Musa said to them: \"Cast what you are casting.\"", "যখন জাদুকররা আসলো, মুসা তাদের বলল, “তোমরা যা ছুড়ঁতে চাও ছোড়।"],
  "10:81": ["And when they cast, Musa said: \"What you have brought is sorcery; Allah will void it. Indeed Allah does not set right the work of the corrupters.\"", "যখন তারা ছুড়ঁলো, মুসা বলল, “যা তোমরা উপস্থাপন করেছ তা জাদু এবং আল্লাহ তা ব্যর্থ  করে দেবেন। আল্লাহ সীমালঙ্ঘনকারীদের কাজ সমর্থন করেন না”।"],
  "10:82": ["And Allah confirms the truth by the words, even if the mujrimin dislike it.", "আল্লাহ তাঁর বানী দিয়ে সত্যকে প্রতিষ্ঠিত করেন, অপরাধীদের সত্ত্বেও।"],
  "10:83": ["And none believed Musa except offspring of his people, for fear of Fir'awn and his chiefs that they would persecute them. And indeed Fir'awn was lofty in the land, and indeed he was among the exceeders.", "কেউ মুসার সাথে বিশ্বাস করেনি তার লোকদের মধ্যে অল্প কয়েকজন ছাড়া, ফেরাউন এবং তার সভাসদের অত্যাচারের ভয়ে। নিশ্চয়, ফেরাউন ছিল পৃথিবীতে অত্যন্ত উদ্ধত, এবং প্রকৃতই অত্যাচারী।"],
  "10:84": ["And Musa said: \"O my people, if you have believed in Allah, then upon Allah rely, if you are submitters.\"", "মুসা বলল, \"হে আমার লোকেরা, যদি তোমরা সত্যিই আল্লাহতে বিশ্বাস করো, তাহলে তার উপর তোমাদের আস্থা রাখো,  যদি তোমরা সত্যিই আত্মসমর্পণকারী হও।\""],
  "10:85": ["They said: \"Upon Allah we rely. Our Rabb, do not make us a trial for the wrongdoing people.\"", "তারা বলল, \"আমরা আল্লাহতে আস্থা রাখি। আমাদের প্রভু, এই অত্যাচারী লোকদের নির্যাতন থেকে আমাদের রক্ষা করুন।"],
  "10:86": ["\"And rescue us by the mercy of Allah from the committing kufr people.\"", "“আমাদের উদ্ধার করুন, আপনার দয়া দিয়ে, অবিশ্বাসী লোকদের থেকে”।"],
  "10:87": ["And We revealed to Musa and his brother: \"Settle your people in homes in the Riverland, and make your homes a direction, and establish the prayer, and give good news to the muminin.\"", "আমরা মুসা এবং তার ভাইকে উদবুদ্ধ করলাম। “এখনকার জন্য মিসরে তোমাদের ঘর গুলো বহাল রাখ, তোমাদের ঘরগুলো সেনেগগে পরিণত করো, এবং সংযোগ প্রার্থনা (সালাত) পালন করো। বিশ্বাসীদের সুসংবাদ দাও।"],
  "10:88": ["And Musa said: \"Our Rabb, You have given Fir'awn and his chiefs adornment and wealth in the life of this world. Our Rabb, so that they lead astray from Your path — our Rabb, blot out their wealth and harden their hearts, so that they do not believe until they see the painful punishment.\"", "মুসা বলল, “আমাদের প্রভু, আপনি ফেরাউন এবং তার সভাসদদের এই দুনিয়ায় বিলাসিতা এবং সম্পদ দিয়েছেন। আমাদের প্রভু, তারা এগুলো শুধু অন্যদেরকে আপনার পথ থেকে বিতাড়িত করতে ব্যবহার করে। অমাদের প্রভু, তাদের সম্পদ নিশ্চিহ্ন করে দিন, এবং তাদের হৃদয় কঠোর করে দিন তাদেরকে বিশ্বাস করা থেকে বিরত রাখতে, যতক্ষণ না তারা যন্ত্রণাদায়ক শাস্তি দেখে।"],
  "10:89": ["Allah said: \"Your call is answered; so stay straight and do not follow the path of those who do not know.\"", "তিনি বললেন, “তোমারদের প্রার্থনা মঞ্জুর করা হল (হে মুসা এবং হারুন), সুতরাং অবিচল থাকো, এবং তাদের পথ অনুসরণ কর না যারা জানে না”।"],
  "10:90": ["And We crossed the children of Israel over the sea, and Fir'awn and his hosts followed them in transgression and enmity, until when the drowning overtook him, he said: \"I believe that there is no ilah but the One in whom the children of Israel believe, and I am among the submitters.\"", "আমরা সাগর পার করিয়ে ইসরাঈলের সন্তানদের  উদ্ধার করেছিলাম। ফেরাউন এবং তার সৈন্যদল তাদের পিছু ধাওয়া করলো, সহিংসতা এবং পাপের সাথে। যখন ডুবে যাওয়া তার জন্য বাস্তবতা হয়ে গেল, সে বলল, “আমি বিশ্বাস করি যে কোন উপাস্য নাই সেই এক সত্ত্বা ব্যতিত যাকে ইসরাঈলের সন্তানেরা বিশ্বাস করেছে, আমি একজন আত্মসমর্পণকারী”।"],
  "10:91": ["\"Now — when you had disobeyed before, and were among the corrupters?\"", "“অনেক দেরি হয়ে গেছে! কারন তুমি ইতোমধ্যে বিদ্রোহ করেছ, এবং একজন সীমালঙ্ঘনকারী হতে পছন্দ করেছ।"],
  "10:92": ["\"But this day We rescue you in your body, that you may be an aya for those after you.\" And indeed most of mankind are unmindful of Our ayat.", "“আজ, আমরা তোমার দেহ সংরক্ষন করবো, তোমাকে ভবিষ্যৎ প্রজন্মের জন্য একটি শিক্ষা হিসাবে দাড় করাতে। দুর্ভাগ্যবশত, অনেক মানুষ আমাদের নিদর্শনের ব্যাপারে সম্পূর্ণ অন্যমনস্ক।"],
  "10:93": ["And We settled the children of Israel in a sadiq settlement, and We provided them from the good things, and they did not differ until the knowledge came to them. Indeed your Rabb will judge between them on the Day of Resurrection over what they used to differ about.", "আমরা ইসরাইলের সন্তানদেরকে এক সন্মানিত অবস্থান দিয়েছি, এবং তাদেরকে ভালো জীবিকা দিয়ে সৌভাগ্যবান করেছি। তাসত্ত্বেও, এই জ্ঞান যখন তাদের কাছে আসলো তারা বিবাদ করলো। তোমার প্রভু পুনুরুত্থান দিবসে তাদের বিবাদকৃত সকল বিষয়ে বিচার করবেন।"],
  "10:94": ["So if you are in doubt about what We have sent down to you, ask those who read the Kitab before you. The truth has indeed come to you from your Rabb, so do not be among the doubters.", "যদি তোমার প্রভুর পক্ষ থেকে তোমার কাছে যা প্রকাশ করা হয়েছে সে ব্যাপারে তোমার কোন সন্দেহ থাকে, তবে যারা পূর্ববর্তী ঐশীগ্রন্থ পড়ে তাদের জিজ্ঞাসা করো। প্রকৃতপক্ষে, তোমার প্রভুর পক্ষ থেকে তোমার কাছে সত্য এসেছে। সন্ধেহ পোষণকারীদের অন্তর্ভুক্ত না।"],
  "10:95": ["And do not be among those who denied the ayat of Allah, lest you be among the khasirin.", "না তুমি তাদের সাথে যোগ দেবে যারা আল্লাহর প্রকাশনাবলী প্রত্যাখ্যান করেছে, পাছে তুমি ক্ষতিগ্রস্থদের অন্তরভুক্ত হবে।"],
  "10:96": ["Indeed those upon whom the word of your Rabb has come true will not believe.", "নিশ্চিতভাবে, যারা তোমার প্রভুর পক্ষ থেকে একটি হুকুম, জারির দ্বারা দোষী সাব্যস্ত হয়েছে তারা বিশ্বাস কতে পারে না।"],
  "10:97": ["Even if every aya comes to them — until they see the painful punishment.", "যে প্রমানই তুমি তাদের দেখাও না কেন, (তারা বিশ্বাস করতে পারে না), যতক্ষণ না তারা যন্ত্রণাদায়ক শাস্তি দেখে।"],
  "10:98": ["If only there had been a community that believed, and its faith benefited it — except the people of Yunus: when they believed, We removed from them the punishment of disgrace in the life of this world, and We let them enjoy for a time.", "বিশ্বাসী যে কোন সম্প্রদায় অবশ্যই বিশ্বাসের জন্য পুরস্কৃত হবে। উদাহরণ স্বরূপ, ইউনুসের লকেরাঃ যখন তারা বিশ্বাস করল, আমরা সেই অপমানকর শাস্তি মুক্ত করলাম যা তারা এই দুনিয়ায় ভোগ করছিল, এবং আমরা তাদেরকে সমৃদ্ধশালী করলাম।"],
  "10:99": ["And had your Rabb willed, all who are in the earth would have believed, all together. Would you then compel mankind until they are muminin?", "যদি তোমার প্রভু চাইতেন, পৃথিবীর সকল লোক বিশ্বাস করতো। তুমি কি লোকদের বিশ্বাসী হওয়ার জন্য জোর করতে চাও?"],
  "10:100": ["And it is not for a nafs to believe except by leave of Allah; and Allah places filth upon those who do not reason.", "আল্লাহর ইচ্ছা ব্যতিত কোন আত্মা বিশ্বাস করতে পারে না। কারন তিনি তাদের উপর অভিশাপ আরোপ করেন যারা বুঝতে অস্বীকার করে।"],
  "10:101": ["Say: \"Look at what is in the heavens and the earth.\" But neither the ayat nor the warnings avail a people who do not believe.", "বল, \"আকাশমন্ডলী ও পৃথিবীর নিদর্শনাবলি দেখো\"। যারা অবিশ্বাস করার সিদ্ধান্ত নিয়েছে তাদের জন্য সকল প্রমান এবং সকল সতর্কবার্তা কখনো কাজে আসে না।"],
  "10:102": ["Do they await anything but the like of the days of those who passed before them? Say: \"Then wait — I am with you among those waiting.\"", "তারা কি তাদের অনুরূপ অতীত ব্যক্তিদের থেকে আলাদা কোন পরিনাম আশা করতে পারে? বল, \"শুধু অপেক্ষা করো, এবং, তোমাদের সাথে, আমিও অপেক্ষা করছি।\""],
  "10:103": ["Then We rescue Our rusul and those who believe. Thus it is a right due from Us to rescue the muminin.", "আমরা অবশেষে আমাদের বার্তাবাহকদের এবং যারা বিশ্বাস করে তাদের রক্ষা করি। এটা আমাদের অপরিবর্তনীয় আইন যে আমরা বিশ্বাসীদের রক্ষা করি।"],
  "10:104": ["Say: \"O mankind, if you are in doubt about my religion, then I do not worship those you worship apart from Allah; rather I worship Allah, who takes you back in death. And I am commanded to be among the muminin.\"", "বল, \"হে লোকেরা, যদি আমার ধর্ম সম্বন্ধে তোমাদের কোন সন্দেহ থাকে, তোমরা আল্লাহর পাশে যা উপাসনা করো আমি তার উপাসনা করি না; আমি একমাত্র আল্লাহর উপাসনা করি, সেই সত্ত্বা যিনি তোমাদের জীবনাবসান ঘটাবেন আমি আদিষ্ট হয়েছি একজন বিশ্বাসী হওয়ার জন্য।\""],
  "10:105": ["And set your face to the religion, upright, and do not be among those who associate.", "আমি আদিষ্ট হয়েছি: \"নিজেকে একেশ্বরবাদ ধর্মের প্রতি নিবেদিত রাখো; তুমি অংশীদার উপাসনা চর্চা করবে না।"],
  "10:106": ["And do not call upon besides Allah what can neither benefit you nor harm you; for if you do, then you are among the wrongdoers.", "“তুমি আল্লাহর পাশে এমন কিছুর উপাসনা করবে না, যা তোমার উপকার বা ক্ষতি করার কোন ক্ষমতা রাখে না। যদি তুমি তা করো, তবে তুমি সীমালঙ্ঘকারী হবে”।"],
  "10:107": ["And if Allah touches you with harm, there is none to remove it but Allah; and if Allah wills you good, none can repel the favor of Allah. It reaches whom Allah wills among the servants. And Allah is the Most-Forgiving, the Most-Raheem.", "আল্লাহ যদি তোমাকে দুঃখ-কষ্ট দিয়ে স্পর্শ করেন, তবে তিনি ব্যতীত কেউ তা লাঘব করতে পারে না। আর তিনি তোমাকে সৌভাগ্যশালী করলে, কোন শক্তি তাঁর অনুগ্রহকে প্রতিরোধ করতে পারে না। তিনি এটি অর্পণ করেন তাঁর বান্দাদের মধ্যে যাকে তিনি পছন্দ করেন। তিনি ক্ষমাশীল, পরম করুণাময়।"],
  "10:108": ["Say: \"O mankind, the truth has come to you from your Rabb. So whoever is guided — it is only for their own nafs; and whoever strays — it is only against it. And I am not a guardian over you.\"", "ঘোষণা করঃ “হে লোকেরা, তোমাদের প্রভুর পক্ষ থেকে তোমাদের কাছে এখানে সত্য এসেছে। যে কেউ সুপথে পরিচালিত হয় সে তার নিজের ভালোর জন্য সুপথে পরিচালিত হয়। এবং যেকেউ পথভ্রষ্ট হয়, পথভ্রষ্ট হয় তার নিজের ক্ষতির জন্য। আমি তোমাদের অভিভাবক নই।"],
  "10:109": ["And follow what is revealed to you, and be of the sabirin until Allah judges. And Allah is the best of judges.", "যা তোমার কাছে প্রকাশ করা হয় তা অনুসরণ করো, এবং ধৈর্য ধারন করো যতক্ষণ না আল্লাহ তাঁর রায় দেন, তিনি সর্বোত্তম বিচারক।"],
  "11:1": ["Alif Lam Ra. A writing whose ayat are made firm, then set out in detail, from the presence of the Wise, the Aware", "অ, ল, র। এটি একটি ঐশীগ্রন্থ যার আয়াতগুলো নিখুঁত করা হয়েছে, তারপর বিশদভাবে বর্ণিত হয়েছে। এটি এসেছে এক সর্বজ্ঞ, সবজান্তার কাছ থেকে।"],
  "11:2": ["Serve none but Allah. I am a warner to you from Allah, and a bearer of glad tidings", "ঘোষনা করছে “তোমরা আল্লাহ ব্যতীত আর কারো উপাসনা করবে না। আমি তাঁর পক্ষ থেকে তোমাদের কাছে এসেছি একটি সর্তককারী, সেই সাথে, সুসংবাদ বহনকারী হিসেবে।"],
  "11:3": ["And: seek your Rabb's forgiveness, then turn back to Allah; Allah will let you enjoy a good enjoyment until an appointed term, and will give every favored one favor. And if you turn away, then I fear for you the punishment of a great day", "“তোমরা  তোমাদের প্রভুর ক্ষমা পেতে চেষ্টা করবে, আর তাঁর কাছে অনুশোচনা করবে। তাহলে তিনি তোমাদেরকে একটি নির্ধারিত সময় পর্যন্ত উদারভাবে অনুগ্রহ করে যাবেন, এবং  তাঁর করুনা বর্ষণ করবেন তাদের উপর যারা এর যোগ্য।  তোমরা যদি ফিরে যাও, তবে আমি তোমাদের জন্য এক মারাত্মক দিনের শাস্তির ভয় করছি।”"],
  "11:4": ["To Allah is your return, and Allah is over everything powerful", "আল্লাহর কাছে তোমাদের চুড়ান্ত প্রত্যাবর্তন, এবং তিনি সর্বশক্তিমান।"],
  "11:5": ["Truly they fold their chests to conceal from Allah; truly, when they cover themselves with their garments, Allah knows what they conceal and what they make open. Truly Allah is knowing of what the chests hold", "প্রকৃতপক্ষে, তারা তাদের গভীরতম চিন্তাভাবনা লুকায়, যেন তিনি সেগুলো না জানতে পারেন। মূলত, যদিও তারা নিজেদেরকে তাদের কাপড় দিয়ে আর্বৃত করে, তিনি তাদের গোপন ও প্রকাশ্য ব্যাপারগুলো জানেন। তিনি সকল গভীরতম চিন্তাভাবনা জানেন।"],
  "11:6": ["There is no creature on the earth but upon Allah is its provision; and Allah knows its dwelling-place and its depositing-place. All is in a clear writing", "পৃথিবীতে এমন কোন জীব নেই যার জীবিকা আল্লাহ কর্তৃক নির্ধারিত নয়। আর তিনি এর গতিবিধি এবং এর চুড়ান্ত পরিনতি জানেন। সবকিছু একটি সুস্পষ্ট নথিতে লিপিবদ্ধ।"],
  "11:7": ["And Allah is the one who created the heavens and the earth in six days, and the raised-frame was upon the water, that Allah might test you as to which of you is best in deed. And if you say: you will be raised after death, those who disbelieve will surely say: this is nothing but clear sihr", "তিনিই সে সত্ত্বা যিনি আকাশমন্ডলী ও পৃথিবী ছয় দিনে সৃষ্টি করেছেন- আর তাঁর (পৃথিবীর) রাজত্ব পানি দিয়ে পুরোপুরি আবৃত ছিল- তোমাদেরকে পরীক্ষা করার জন্য, তোমাদের মধ্যে যারা সৎ কাজ করে তাদের আলাদা করার জন্য। এরপরও, যখন তোমরা বল, “তোমাদেরকে মৃত্যুর পর পুনরজ্জীবিত করা হবে,”যারা অবিশ্বাস করে তারা বলবে, “এটি সুস্পষ্ট কালো যাদু।”"],
  "11:8": ["And if We postpone the punishment from them for a counted term, they will surely say: what holds it back? Truly, on the day it comes to them, there is no averting it from them, and what they used to mock will encircle them", "এবং আমরা যদি তাদের অর্জিত শাস্তি দিতে দেরি করি- কারণ আমরা তা কোন নির্দিষ্ট সম্প্রদায়ের জন্য জমা রাখি- তারা বলে, “কিসে উনাকে আটকে রেখেছে? মূলত, একবার এটি তাদের কাছে আসলে, কোনকিছুই একে থামাতে পারে না, উলটো তাদের উপহাস তাদেরকে তাড়া করে বেড়াবে।"],
  "11:9": ["And if We let man taste a mercy from Us, then pull it out from him, he is despairing, ungrateful", "আমাদের পক্ষ থেকে যখনই আমরা দয়া দিয়ে মানব জাতিকে অনুগ্রহ করি, এরপর তা সরিয়ে নেই, সে হয়ে যায় নিরাশ, অকৃতজ্ঞ।"],
  "11:10": ["And if We let him taste blessing after hardship that touched him, he will surely say: the evils have gone from me. Truly he is rejoicing, vaunting", "যখনই আমরা অনুগ্রহ করি, সে দুর্দশাগ্রস্থ হওয়ার পর, সে বলে, “আমার কাছ থেকে সকল দুর্দশা চলে গেছে,” সে হয়ে পরে উদ্বেলিত, গর্বিত।"],
  "11:11": ["Except those who sabirly endured and did right deeds; those will have forgiveness and a great reward", "আর যারা দৃড়তার সাথে অবিচল থাকে, এবং সৎ জীবন-যাপন করে, তারা ক্ষমা ও এক উদার প্রতিদানের যোগ্য হয়েছে।"],
  "11:12": ["So perhaps you would leave behind some of what is revealed to you, and your chest is straitened by it, because they say: why has no hoard been sent down upon him, or a malakat come with him? You are only a warner, and Allah is over everything a guardian", "তোমার কাছে যা প্রকাশ করা হয় তুমি হয়তো এর কিছু অংশ উপেক্ষা করতে চাইতে পারো এবং হয়তো এর দ্বারা তুমি বিচলিত হতে পারো। এছাড়াও, তারা হয়তো বলতে পারে, “এটা কেমন যে তার কাছে কোন ধনভান্ডার অথবা কোন ফেরেশতা নেমে আসে না?”তুমি শুধু একজন সতর্ককারী; আল্লাহ সবকিছু নিয়ন্ত্রন করেন।"],
  "11:13": ["Or do they say: he devised it? Say: then bring 10 chapters like it, devised, and call upon whomever you can besides Allah, if you are sadiq", "যদি তারা বলে,“সে (কুরআন) বানিয়েছে,”তাদেরকে বল, “তবে এগুলোর মত দশটি সূরা উপস্থাপন করো,যা বানানো,এবং যাকে পারো আমন্ত্রন করো,আল্লাহকে ছাড়া,যদি তোমরা সত্যবাদী হও।”"],
  "11:14": ["Then if they do not answer you, know that it was sent down only by Allah's knowledge, and that there is no deity but Allah. Will you then submit?", "তারা যদি তোমাদের চ্যালেঞ্জের কাছে পরাস্ত হয়, তবে জেনে রাখো যে এটি আল্লাহর জ্ঞান থেকে প্রকাশিত হয়, এবং তিনি ছাড়া কোন উপাস্য নেই। তোমরা কি এবার আত্মসমর্পণ করবে?"],
  "11:15": ["Whoever wants the nearer life and its adornment, We will give them their deeds in full in it, and they will not be diminished therein", "যারা এই পার্থিব জীবন আর এর বস্তুগত সৌন্দর্যের পিছনে ছুটে বেড়ায়, আমরা এই জীবনে তাদের কাজের জন্য তাদের প্রতিদান দেবো; সামান্যতম কম না দিয়ে।"],
  "11:16": ["Those are the ones who have nothing in the hereafter but the fire; and voided is what they made in it, and null is what they used to do", "এরা তারাই যারা তাদের পরকালের অংশ ছেড়ে দিয়েছে,এবং,পরিনামে,নরকই তাদের নিয়তি। তাদের সকল কাজ অর্থহীন; তারা যা কিছু করেছে সবই বিনষ্ট হয়েছে।"],
  "11:17": ["Is one who stands upon clear proof from Allah, and a witness from Allah recites it, and before it was the Kitab of Musa as a leader and a mercy, among those who believe in it? And whoever of the parties disbelieves in it, the fire is the promised place. So do not be in doubt about it; it is the truth from your Rabb, but most people do not believe", "আর যাদেরকে তাদের প্রভুর পক্ষ থেকে জোড়ালো প্রমান দেয়া হয়েছে,যা তাঁর পক্ষ থেকে একজন স্বাক্ষী দ্বারা উপস্থাপিত, এবং এর আগে,মূসার ঐশীগ্রন্থ এক উদাহরণ ও দয়া স্থাপন করেছে,তারা অবশ্যই বিশ্বাস করবে। আর বিভিন্ন দলের মধ্যে যারা অবিশ্বাস করে,তাদের জন্য নরক অপেক্ষা করছে। কোন সন্দেহ পোষন করো না; এটি তোমার প্রভুর পক্ষ থেকে সত্য, কিন্তু বেশিরভাগ মানুষই অবিশ্বাস করে।"],
  "11:18": ["And who is more zalimun than one who devises against Allah a lie? Those will be presented to their Rabb, and the witnesses will say: these are the ones who lied against their Rabb. Truly the curse of Allah is upon the zalimun", "তাদের থেকে খারাপ আর কারা যারা আল্লাহ সম্পর্কে মিথ্যা বানায়? তাদেরকে তাদের প্রভুর সামনে উপস্থিত করা হবে,এবং স্বাক্ষীরা বলবে,“এরাই তারা যারা তাদের প্রভু সম্পর্কে মিথ্যা বলেছিল। আল্লাহর অভিসম্পাত সীমালঙনকারীদের উপর পড়েছে।”"],
  "11:19": ["Those who turn away from Allah's path and want it crooked, while of the hereafter they are kafirin", "তারা আল্লাহর পথে বাধা দেয় এবং একে বক্র করতে চেষ্টা করে,এবং তারা পরকালে অবিশ্বাসী।"],
  "11:20": ["Those could not frustrate on the earth, and they had no protectors besides Allah; the punishment will be doubled for them. They could not hear, and they could not see", "এরা কখনও পালাতে পারবে না,না তারা আল্লাহর বিপক্ষে তাদেরকে সাহায্য করতে কোন প্রভু বা মনিব পাবে। শাস্তি তাদের জন্য দ্বিগুন করা হবে। তারা শুনতে ব্যর্থ হয়েছে,এবং তারা ব্যর্থ হয়েছে দেখতে।"],
  "11:21": ["Those are the ones who lost themselves, and what they used to devise strayed away from them", "এরাই তারা যারা তাদের আত্মা হারায়, এবং তাদের বানানো উপাস্যরা তাদের পরিত্যাগ করবে।"],
  "11:22": ["Doubtless, they in the hereafter are the greatest losers", "কোন সন্দেহ নেই যে,পরকালে,তারা হবে সর্বাধিক ক্ষতিগ্রস্থ।"],
  "11:23": ["Truly those who believed and did right deeds and were humble to their Rabb, those are the companions of the garden; in it they abide forever", "আর যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে,এবং তাদের প্রভুর প্রতি নিজেদের উৎসর্গ করে,তারা স্বর্গের বাসিন্দা; তারা সেখানে চিরকাল বসবাস করে।"],
  "11:24": ["The likeness of the two parties is as the unseeing and the deaf, and the seeing and the hearing. Are the two equal in likeness? Will you not remember?", "এই দুই শ্রেনীর উদাহরণ হচ্ছে অন্ধ ও বধিরের সাথে,দৃষ্টিবান ও শ্রবনশক্তিবানের তুলনা করার মত। তারা কি সমান? তোমরা কি চিন্তা করবে না?"],
  "11:25": ["And We sent Nuh to his people: I am a clear warner to you", "আমরা নুহকে তার লোকদের কাছে পাঠিয়েছিলাম, এটা বলতে,“আমি তোমাদের কাছে এসেছি স্পষ্ট সতর্ককারী হিসেবে।"],
  "11:26": ["That you serve none but Allah. I fear for you the punishment of a painful day", "“তোমরা আল্লাহ ছাড়া অন্য কারো উপাসনা করবে না। আমি তোমাদের জন্য এক যন্ত্রনাদায়ক দিনের শাস্তির ভয় করি।”"],
  "11:27": ["The chiefs who disbelieved from among his people said: we see you as nothing but a human like us, and we see none following you but the lowliest of us, open to view; and we see no superiority for you over us; rather we think you liars", "তার লোকদের মধ্যে যে নেতারা অবিশ্বাস করেছিল তারা বলল, “আমরা দেখছি যে তুমি আমাদের মত মানুষ ছাড়া কিছু নও, আর আমাদের মধ্যে নিকৃষ্ট লোকেরাই প্রথমে তোমার অনুসরণ করছে। আমরা দেখছি যে আমাদের উপর তোমাদের কোন শ্রেষ্ঠত্ব নেই। মূলত, আমরা তোমাদের মিথ্যাবাদী মনে করি।”"],
  "11:28": ["He said: O my people, have you considered: if I am upon clear proof from my Rabb, and a mercy has been given to me from Allah, but it is hidden from you, shall we bind it fast upon you while you are averse to it?", "সে বলল, “হে আমার লোকেরা,যদি এমন হয় যে আমার প্রভুর পক্ষ থেকে আমার কাছে একটি জোড়ালো প্রমান থাকে? যদি এমন হয় যে তাঁর দয়া থেকে তিনি আমাকে অনুগ্রহ করেছেন, যদিও তোমরা তা দেখতে পারো না? আমরা কি তোমাদেরকে তাতে বিশ্বাস করতে জোর করতে যাচ্ছি?"],
  "11:29": ["And O my people, I ask of you no wealth for it; my reward is only upon Allah. And I am not driving away those who believed; they will meet their Rabb. But I see you as a people who are ignorant", "“হে আমার লোকেরা,আমি তোমাদের কাছে কোন অর্থ চাই না; আমার পারিশ্রমিক একমাত্র আল্লাহ থেকে আসে। যারা বিশ্বাস করে তাদেরকে আমি তাড়িয়ে দিচ্ছি না; তারা তাদের প্রভুর সাথে সাক্ষাত করবে (এবং একমাত্র তিনি তাদের বিচার করবেন )। আমি দেখি যে তোমরা অজ্ঞ লোক।"],
  "11:30": ["And O my people, who will help me against Allah if I drive them away? Will you not remember?", "“হে আমার লোকেরা,আল্লাহর বিরুদ্ধে কে আমাকে সহায়তা করতে পারে,যদি আমি তাদেরকে তাড়িয়ে দেই? তোমরা কি মনোযোগ দিবে না?"],
  "11:31": ["And I do not say to you that I possess the store-houses of Allah, nor do I know the hidden, nor do I say that I am a malakat; nor do I say of those whom your eyes scorn that Allah will never give them good. Allah knows best what is in their nafs; I would then be among the zalimun", "আমি দাবি করি না যে আমার কাছে আল্লাহর ধন-ভান্ডার আছে,না আমি ভবিষৎ জানি,না আমি ফেরেশতা হওয়ার দাবি করি। না আমি ওদেরকে বলি যারা তোমাদের দৃষ্টিতে ঘৃনিত যে আল্লাহ তাদের উপর অনুগ্রহ বর্ষণ করবেন না। আল্লাহ সবচেয়ে ভাল জানেন কি তাদের গভীরতম চিন্তা। (যদি এটি আমি করে থাকি,) আমি একজন সীমালংঘনকারী হবো।”"],
  "11:32": ["They said: O Nuh, you have disputed with us and multiplied dispute upon us. Bring us what you promise us, if you are of the sadiqin", "তারা বলল, “হে নুহ, তুমি আমাদের সাথে তর্ক করছো,এবং তর্ক করেই যাচ্ছো। আমরা তোমাকে সে অনিবার্য ধ্বংস আনতে চ্যালেঞ্জ করি যা দিয়ে তুমি আমাদের ভয় দেখাও, যদি তুমি সত্যবাদী হও।”"],
  "11:33": ["He said: only Allah will bring it to you if Allah wills, and you cannot frustrate", "সে বলল, “আল্লাহই সেই সত্ত্বা যিনি এটি তোমাদের কাছে নিয়ে আসেন, যদি তিনি এমনই চান, তখন তোমরা পালাতে পারবে না।"],
  "11:34": ["And my sincere counsel will not benefit you if I intend sincerity for you, if Allah wills to mislead you. Allah is your Rabb, and to Allah you return", "“যদিও আমি তোমাদের উপদেশ দিয়েছি,তোমাদের বিপথে পাঠানো যদি আল্লাহর ইচ্ছা হয় আমার উপদেশ তোমাদের কোন উপকারে আসতে পারে না। তিনি তোমাদের প্রভু,এবং তাঁর কাছেই তোমরা ফিরে যাবে।”"],
  "11:35": ["Or do they say: he devised it? Say: if I devised it, then upon me is my crime, and I am cleared of what crimes you commit", "যদি তারা বলে,“সে এই গল্প বানিয়েছে,”তাহলে বল, “যদি আমি তা বানিয়ে থাকি,তবে আমি আমার অপরাধের জন্য দায়ী,এবং তোমাদের করা কোন অপরাধের জন্য আমি দায়ী নই।”"],
  "11:36": ["And it was revealed to Nuh: none of your people will believe except those who have already believed; so do not grieve at what they do", "নূহ অনুপ্রানিত হয়েছিলঃ “তোমার লোকদের মধ্যে আর কেউ বিশ্বাস করবে না,যারা ইতোমধ্যে বিশ্বাস করেছে তারা ছাড়া। তাদের কর্মকান্ডে দুঃখ পেয়ো না।"],
  "11:37": ["And make the ship under Our eyes and Our revelation, and do not plead with Me concerning those who did wrong; they shall be drowned", "“নৌকাটি নির্মান করো আমাদের সতর্ক দৃষ্টির আওতায়, এবং আমাদের অনুপ্রেরনায়, এবং তাদের হয়ে আমার কাছে মিনতি করো না যারা সীমালংঘন করেছে;ডুবে মরাই তাদের নিয়তি।”"],
  "11:38": ["And he made the ship, and whenever a band of his chiefs passed by him they mocked him. He said: if you mock us, then we will mock you just as you mock", "যখন সে নৌকাটি বানাচ্ছিল, তার লোকদের কেউ কেউ যখনি তার পাশ দিয়ে যেতো তারা তাকে নিয়ে হাসতো। সে বলেছিল, “তোমরা হয়তো  আমাদের নিয়ে হাসছ, কিন্তু আমরা তোমাদের নিয়ে হাসছি,ঠিক যেমন তোমরা হাসছ।"],
  "11:39": ["Soon you will know to whom comes a punishment that disgraces, and upon whom settles a lasting punishment", "“তোমরা অবশ্যই দেখতে পাবে কারা লজ্জাকর শাস্তি ভোগ করবে,এবং কারা টেনে আনবে এক চিরস্থায়ী শাস্তি”।"],
  "11:40": ["Until when Our command came and the oven boiled over, We said: carry in it two of every pair, and your family, except those against whom the word has preceded, and whoever believes. And none believed with him except a few", "যখন আমাদের বিচার আসলো,এবং বায়ুমণ্ডল অত্যাধিক উত্তপ্ত হয়ে উঠল, আমরা বললাম, “এর উপর প্রত্যেক প্রকারের এক জোড়া তুলো, তোমার পরিবারের সাথে,তাদের ছাড়া যারা দোষী। তোমার সাথে তাদেরকে নাও যারা বিশ্বাস করেছে,”এবং অল্প কয়েকজন তার সাথে বিশ্বাস করেছিল।"],
  "11:41": ["And he said: board it; in the name of Allah be its course and its anchoring. Truly my Rabb is forgiving, merciful", "সে বলেছিল, “আরোহণ করো,আল্লাহর নামে হবে এর ভেসে চলা,এবং এর  নোঙ্গর। আমার প্রভু ক্ষমাশীল, পরম দয়ালু”।"],
  "11:42": ["And it ran with them amid waves like mountains; and Nuh called his son, who was apart: O my son, board with us and do not be with the kafirin", "যখন এটি তাদের নিয়ে পাহাড় সমান ঢেউয়ের মাঝে ভেসে গেল, “নূহ তার ছেলেকে ডাকলো,যে আলাদা হয়েছিলঃ “হে আমার পূত্র, আমাদের সাথে উঠো; অবিশ্বাসীদের সাথে থেকো না।”"],
  "11:43": ["He said: I will shelter to a mountain that will protect me from the water. He said: there is no protector today from Allah's command except those shown mercy. And the wave came between them, and he was among the drowned", "সে বলল, “আমি কোন পাহাড়ের চূড়ায় আশ্রয় নিব, নিজেকে পানি থেকে রক্ষা করতে।”সে বলল, “আজ আল্লাহর বিচার হতে কাউকে কোনকিছুই রক্ষা করতে পারবে না; শুধু তারা (রক্ষা পাবে) যারা তার দয়ার যোগ্য।”ঢেউ তাদের আলাদা করে দিল, এবং সে ছিল তাদের মধ্যে যারা নিমজ্জিত হয়েছিল।"],
  "11:44": ["And it was said: O earth, swallow your water; and O heaven, hold back. And the water subsided, and the command was fulfilled, and it came to rest upon al-Judi. And it was said: away with the zalimun people", "এটি ঘোষনা করা হলঃ “হে পৃথিবী,তোমার পানি গিলে ফেল, ”এবং “হে আকাশ, থামো।”পানি তখন কমে গেল; বিচার পরিপূর্ণ হল। অবশেষে নৌকাটি জুদেয়া-এর পাহাড়গুলোতে থামালো। এটি তখন ঘোষনা করা হলঃ “সীমালঙ্গঘনকারীরা ধংস হয়েছে।”"],
  "11:45": ["And Nuh called his Rabb and said: Rabb, my son is of my family, and Your promise is the truth, and You are the most just of judges", "নূহ তার প্রভুর কাছে মিনতি করলোঃ “আমার প্রভু,আমার পুত্র আমার পরিবারের সদস্য, এবং আপনার অংগীকার সত্য। আপনি বিজ্ঞদের চেয়েও বিজ্ঞ।”"],
  "11:46": ["Allah said: O Nuh, he is not of your family; it is a deed not right. So do not ask about what you have no knowledge of; I admonish you lest you be among the ignorant", "তিনি বলেছিলেন, “হে নূহ, সে তোমার পরিবারের কেউ নয়। এটি অন্যায্য আমার কাছে কোনকিছু চাওয়া যা তুমি জানো না। আমি তোমাকে জ্ঞানালোক দিয়েছি,যাতে তুমি অজ্ঞদের মত না হও।”"],
  "11:47": ["He said: Rabb, I seek refuge with You from asking You what I have no knowledge of; unless You forgive me and have mercy on me I would be among the khasirin", "সে বলল, “আমার প্রভু,আমি আপনার কাছে আশ্রয় চাই, যাতে আমি আবারো আপনার কাছে এমনকিছুর জন্য মিনতি না করি যা আমি জানি না। যদি আপনি আমাকে ক্ষমা না করেন, এবং আমার উপর দয়া না করেন, আমি ক্ষতিগ্রস্থদের অন্তর্ভূক্ত হয়ে যাব।"],
  "11:48": ["It was said: O Nuh, descend with peace from Us, and blessings upon you and upon communities from those with you. And communities We will let enjoy, then a painful punishment from Us will touch them", "এটি ঘোষনা করা হলঃ “হে নূহ, অবতরণ কর, শান্তি এবং অনুগ্রহের সাথে তোমার উপর, এবং সে জাতির উপর যারা তোমার সংগীদের বংশদের হবে। আর অপর জাতি যারা তোমার বংশধর হবে,আমরা তাদেরকে কিছু সময়ের জন্য অনুগ্রহ করবো,এরপর তাদেরকে যন্ত্রনাদায়ক শাস্তি দিব।”"],
  "11:49": ["That is of the tidings of the hidden that We reveal to you; neither you nor your people knew them before this. So be of the sabirin; the final end is for the ilah-fearing", "এটি অতীতের সংবাদ যা আমরা তোমার কাছে প্রকাশ করি। তাদের সম্পর্কে তোমার কোন জ্ঞান ছিল না- না তোমার, বা তোমার লোকদের- এর পূর্বে। অতএব, ধৈর্য্য ধারণ করো। চূড়ান্ত বিজয় সৎকর্মশীলদের জন্য।"],
  "11:50": ["And to Ad We sent their brother Hud. He said: O my people, serve Allah; you have no deity other than Allah. You are only devisers", "আদ জাতির কাছে আমরা তাদের ভাই হুদকে পাঠিয়েছিলাম। সে বলেছিল, “হে আমার লোকেরা,আল্লাহর উপাসনা কর; তাঁর পাশে তোমাদের অন্য কোন উপাস্য নেই। তোমরা উদ্ভাবন করছো।"],
  "11:51": ["O my people, I ask you no reward for it; my reward is only upon the one who originated me. Will you not reason?", "“হে আমার লোকেরা,আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না। আমার পারিশ্রমিক শুধু সেই সত্ত্বার কাছ থেকে আসে যিনি আমার সূচনা করেছেন। তোমরা কি বুঝো না?"],
  "11:52": ["And O my people, seek your Rabb's forgiveness, then turn back; Allah will send the heaven over you pouring, and add strength to your strength; and do not turn away as mujrimin", "“হে আমার লোকেরা,তোমাদের প্রভুর ক্ষমা অন্বেষন করো,এরপর তাঁর কাছে অনুশোচনা করো। তাহলে তিনি আকাশ হতে তোমাদের জন্য জীবিকা বর্ষণ করবেন, এবং তোমাদের শক্তি বৃদ্ধি করবেন। সীমা লঙ্গনকারীদের মাঝে ফিরে যেও না।"],
  "11:53": ["They said: O Hud, you have brought us no clear proof, and we are not ones to leave our deities on your word, nor are we muminin in you", "তারা বলল, “হে হুদ, তুমি আমাদেরকে কোন প্রমান দেখাওনি,আর তোমার কথার উপর ভিত্তি করে আমরা আমাদের উপাস্যগুলো পরিত্যাগ করছি না। আমরা কখনোই তোমার সাথে বিশ্বাসী হবো না।"],
  "11:54": ["We say nothing but that one of our deities has afflicted you with evil. He said: I call Allah to witness, and you bear witness, that I am cleared of what you join", "“আমরা বিশ্বাস করি যে আমাদের কিছু উপাস্য অভিশাপ দিয়ে তোমাকে পীড়িত করেছে।”সে বলল, “আমি আল্লাহর সামনে সাক্ষ্য দিচ্ছি,আর তোমরাও সাক্ষী থাকো যে,আমি সেই উপাস্যগুলোকে পরিত্যাগ করেছি যেগুলো তোমরা স্থাপন করেছ"],
  "11:55": ["Other than Allah! So scheme against me all together; then you shall not wait", "“তাঁর পাশে। সুতরাং তোমাদের সম্মিলিত সিদ্ধান্ত আমাকে জানাও, বিলম্ব না করে।"],
  "11:56": ["I have placed my trust in Allah, my Rabb and your Rabb; there is no creature but Allah holds it by its forelock. Truly my Rabb is on a straight course", "“আমি আল্লাহর উপর ভরসা করেছি,আমার প্রভু এবং তোমাদের প্রভু। এমন কোন সৃষ্টি নেই যাকে তিনি নিয়ন্ত্রন করেন না। আমার প্রভু সঠিক পথে আছেন।"],
  "11:57": ["So if you turn away, I have already conveyed to you what I was sent with to you; and my Rabb will appoint a people other than you as successors, and you will not harm Allah in anything. Truly my Rabb is guardian over everything", "\"যদি তোমরা মুখ ফিরিয়ে নাও, আমি তোমাদের কাছে পৌঁছে দিয়েছি যা দিয়ে আমাকে পাঠানো হয়েছিল। আমার প্রভু তোমাদের জায়গায় অন্য লোকদের আনবেন। তোমরা তাঁর এতটুকু ক্ষতি করতে পারবে না। আমার প্রভু সবকিছু নিয়ন্ত্রন করেণ।"],
  "11:58": ["And when Our command came, We saved Hud and those who believed with him by a mercy from Us; and We saved them from a hard punishment", "যখন আমাদের বিচার আসলো,আমরা আমাদের দয়ায় হুদ এবং যারা তার সাথে বিশ্বাস করেছিল তাদের রক্ষা করেছিলাম। আমরা তাদেরকে এক ভয়ানক শাস্তি থেকে রক্ষা করেছিলাম।"],
  "11:59": ["And that was Ad: they denied the ayat of their Rabb, disobeyed their rusul, and followed the command of every obstinate tyrant", "এমনই ছিল আদ জাতি- তারা তাদের প্রভুর প্রকাশনাবলি অগ্রাহ্য করেছিল, তাঁর বার্তাবাহকদের অমান্য করেছিল, এবং প্রত্যেক একগুঁয়ে অত্যাচারী শাসকের পথ অনুসরণ করলো।"],
  "11:60": ["And the curse followed them in this nearer life, and on the day of resurrection. Truly Ad disbelieved their Rabb. Truly away with Ad, the people of Hud", "ফলশ্রুতিতে,তারা অভিশাপ টেনে এনেছে এই পৃথিবীতে,এবং পুনরুত্থান দিবসে। প্রকৃতই, আদ জাতি তাদের প্রভুকে প্রত্যাখ্যান করেছিল। প্রকৃতই, আদ জাতি,হুদের লোকেরা,বিলুপ্ত হয়েছে।"],
  "11:61": ["And to Thamud We sent their brother Salih. He said: O my people, serve Allah; you have no deity other than Allah. Allah raised you up from the earth and settled you in it to build and keep it; so seek forgiveness, then turn back to Allah. Truly my Rabb is near, answering", "সামূদ জাতির কাছে আমরা তাদের ভাই সালেহকে পাঠিয়েছিলাম। সে বলেছিল, “হে আমার লোকেরা,আল্লাহর উপাসনা কর; তাঁর পাশে তোমাদের আর কোন উপাস্য নেই। তিনি পৃথিবী থেকে তোমাদের সূচনা করেছেন, তারপর এর মধ্যে তোমাদের প্রতিষ্ঠিত করেছেন। তোমাদের উচিত তাঁর কাছে ক্ষমা চাওয়া,এরপর তাঁর কাছে অনুশোচনা করা। আমার প্রভু সর্বদাই নিকটে,সাড়াদানকারী।”"],
  "11:62": ["They said: O Salih, you had been among us one hoped in before this. Do you now forbid us to serve what our fathers served? We are in doubting doubt about what you call us to", "তারা বলল, “হে সালেহ, তুমি তো এর আগে আমাদের মাঝে জনপ্রিয় ছিলে। আমাদের পিতামাতারা যা উপাসনা করে তার উপাসনা করতে তুমি কি আমাদের নিষেধ করছো? তুমি আমাদেরকে যাকিছু বলেছ সে সবকিছু সম্পর্কে আমরা গভীর সন্দেহে আছি।”"],
  "11:63": ["He said: O my people, have you considered: if I am upon clear proof from my Rabb, and a mercy from Allah has been given to me, who would help me against Allah if I disobeyed? You would add nothing for me but loss", "সে বলল, “হে আমার লোকেরা,যদি আমার কাছে থেকে থাকে আমার প্রভুর পক্ষ থেকে জোড়ালো প্রমান, এবং তাঁর পক্ষ থেকে দয়া? আল্লাহর বিপক্ষে কে আমার সহায় হবে,যদি আমি তাঁকে অমান্য করি? তোমরা শুধু আমার ক্ষতি বৃদ্ধি করতে পার।"],
  "11:64": ["And O my people, this is the naqah of Allah, an aya for you; leave her to graze in Allah's earth, and do not touch her with evil, or a near punishment will take you", "“হে আমার লোকেরা,এটি আল্লাহর উট যা তোমাদের জন্য একটি প্রমান হিসেবে কাজ করবে। তোমরা একে আল্লাহর পৃথিবী/ভূমি থেকে খেতে দিবে,এবং কোন প্রকার ক্ষতি করার জন্য একে স্পর্শ করবে না,অন্যথায় তোমরা এক আশু শাস্তি টেনে আনবে।”"],
  "11:65": ["So they cut her down. He said: enjoy yourselves in your homes 3 days; that is a promise not belied", "তারা একে হত্যা করল। এরপর সে বলল, “তোমরা শুধু আর তিন দিন বাচঁবে। এটা একটি ভবিষ্যদ্বানী যা অবধারিত।”"],
  "11:66": ["So when Our command came, We saved Salih and those who believed with him by a mercy from Us, and from the disgrace of that day. Truly your Rabb is the powerful, the mighty", "যখন আমাদের বিচার আসলো,আমাদের কাছ থেকে দয়া দিয়ে আমরা সালেহ এবং তার সাথে যারা বিশ্বাস করেছিল তাদের রক্ষা করেছিলাম দ্বারা,ঐ দিনের অপমানকর অবস্থা হতে। তোমার প্রভু পরম ক্ষমতাবান, সর্বশক্তিমান।"],
  "11:67": ["And the shout took those who did wrong, and they became sprawled in their homes", "যারা সীমালঙ্গন করেছিল সেই দূর্যোগ তাদেরকে ধ্বংস করে দিয়েছিল, তাদেরকে তাদের বাড়িতে ফেলে রেখেছিল, মৃতবস্থায়।"],
  "11:68": ["As though they had never flourished in them. Truly Thamud disbelieved their Rabb. Truly away with Thamud", "এটা এমন ছিল যেন তারা কখনো সেখানে বসবাস করেনি। মূলত, সামূদ তাদের প্রভুকে প্রত্যাখ্যান করেছে। অবশ্যই, সামূদ তাদের ধ্বংস টেনে এনেছে।"],
  "11:69": ["And Our malakat came to Ibrahim with the glad tidings; they said: peace. He said: peace. And he had hardly tarried when he brought a roasted calf", "যখন আমাদের বার্তাবাহকেরা ইব্রাহিমের কাছে সুসংবাদ নিয়ে গিয়েছিল, তারা বলেছিল, “শান্তি।”সে বলল, “শান্তি।”এবং কিছু সময়ের মধ্যেই একটি রোস্ট করা (ঝলসানো) বাছুর নিয়ে আসলো।"],
  "11:70": ["And when he saw their hands not reaching toward it, he found them strange and conceived fear of them. They said: fear not; we have been sent to the people of Lut", "যখন সে দেখলো তাদের হাত এটা স্পর্শ করছে না,সে তাদের ব্যাপারে সন্দেহ পোষন করলো এবং ভীত হল। তারা বলল, “ভয় পেও না,আমাদেরকে লূতের লোকদের কাছে পাঠানো হয়েছে।”"],
  "11:71": ["And his imra'a was standing; she laughed, and We gave her glad tidings of Ishaq, and behind Ishaq, Ya'qub", "তার স্ত্রী দাঁড়িয়ে ছিল, এবং সে হাসলো যখন আমরা সুসংবাদ দিলাম ইসহাকের, এবং ইসহাকের পর ইয়াকুবের।"],
  "11:72": ["She said: woe to me! Shall I bear a child when I am an jawza, and this ba'l of mine an old man? This is indeed a marvelous thing", "সে বলল, “আমার আফসোস, কেমন করে আমি আমার এই বয়সে সন্তান ধারণ করতে পারি,এবং এই হচ্ছে আমার স্বামী; একজন বৃদ্ধলোক? এটি সত্যিই বিস্ময়কর!”"],
  "11:73": ["They said: do you marvel at Allah's command? The mercy of Allah and blessing be upon you, people of the house. Truly Allah is praiseworthy, glorious", "তারা বলল, “তুমি কি আল্লাহর জন্য এটি বিস্ময়কর মনে করো? আল্লাহ তাঁর দয়া এবং অনুগ্রহ তোমাদের উপর অর্পন করেছেন, হে এই ঘরের বাসিন্দারা। তিনি প্রশংসনীয়, মহিমান্বিত।”"],
  "11:74": ["And when the terror left Ibrahim, and the glad tidings came to him, he disputed with Us over the people of Lut", "যখন ইব্রাহিমের ভয় কেটে গেল, এবং সুসংবাদটি তার কাছে পৌঁছে দেয়া হল, সে তখন লুতের লোকদের পক্ষে আমাদের সাথে তর্ক শুরু করলো।"],
  "11:75": ["Truly Ibrahim was forbearing, tenderly grieving, ever turning back", "প্রকৃতপক্ষে,ইব্রাহিম ছিল কোমল হৃদয়, অত্যন্ত দয়ালু,এবং অনুগত।"],
  "11:76": ["O Ibrahim, turn aside from this; the command of your Rabb has already come, and a punishment not turned back will come to them", "“হে ইব্রাহীম, এটা থেকে বিরত হও। তোমার প্রভুর রায় হয়ে গেছে;তারা টেনে এনেছে অনিবার্য শাস্তি।”"],
  "11:77": ["And when Our malakat came to Lut, he was distressed at them and straitened for room by them, and he said: this is a hard day", "যখন আমাদের বার্তাবাহকরা লুতের কাছে গেল, তাদের সাথে দুর্ব্যবহার করা হয়েছিল, এবং সে তাদের উপস্থিতিতে অস্বস্তিকর অবস্থায় পড়লো। সে বলল, “এটা এক কঠিন দিন।”"],
  "11:78": ["And his people came hurrying to him, and before they had been doing evils. He said: O my people, these are my daughters; they are purer for you. So be mindful of Allah and do not disgrace me in my guests. Is there not among you a man of right course?", "তার লোকেরা ছুটে আসলো; তারা তাদের পাপপূর্ণ কর্মকান্ডে অভ্যস্থ হয়ে ওঠেছিল। সে বলল, “হে আমার লোকেরা,এটি তোমাদের জন্য পবিত্রতর হবে,যদি বিনিময়ে তোমরা আমার মেয়েদের গ্রহণ করো। তোমাদের উচিত আল্লাহকে ভয় করা; আমার অতিথিদের ব্যাপারে আমাকে অস্বস্থিকর অবস্থায় ফেলো না। তোমাদের মাঝে কি একজনও কান্ডজ্ঞান সম্পন্ন ব্যক্তি নেই?”"],
  "11:79": ["They said: you know well we have no right concerning your daughters, and you know well what we want", "তারা বলল, “তুমি ভাল করেই জানো যে তোমার মেয়েদের আমাদের কোন প্রয়োজন নেই; তুমি ঠিকই জানো আমরা কী চাই।”"],
  "11:80": ["He said: if only I had strength against you, or could shelter to a firm support", "সে বলল, “আমি যদি যথেষ্ঠ শক্তিশালী হতাম, অথবা আমরা যদি কোন ক্ষমতাবান মিত্র থাকতো!”"],
  "11:81": ["They said: O Lut, we are rusul of your Rabb; they shall not reach you. So set out with your family in a piece of the night, and let not any of you look back except your imra'a; what strikes them will strike her. Their appointment is the morning. Is the morning not near?", "(ফেরেশতারা ) বলল, “হে লুত, আমরা তোমার প্রভুর বার্তাবাহক, এবং এই লোকেরা তোমাকে স্পর্শ করতে পারবে না। তুমি তোমার পরিবার নিয়ে রাতে চলে যাবে,আর তোমাদের কাউকে পিছনে তাকাতে দিবে না,তোমার স্ত্রী ছাড়া; সে তাদের সাথে দোষী যারা দোষীসাব্যস্ত হয়েছে। তাদের নির্ধারিত সময় হচ্ছে সকাল। সকাল কি খুব নিকটে নয়?”"],
  "11:82": ["So when Our command came, We made its highest part its lowest, and We rained upon it stones of clay, layered", "যখন আমাদের বিচার আসলো,আমরা একে উল্টে দিলাম এবং আমরা এর উপর কঠিন, বিধ্বংসী পাথর বর্ষণ করলাম।"],
  "11:83": ["Marked by your Rabb; and it is not far from the zalimun", "এরকম পাথরগুলো সীমালঙ্গনকারীদের আঘাত করার জন্য তোমার প্রভুর দ্বারা নির্বাচিত।"],
  "11:84": ["And to Midian We sent their brother Shu'ayb. He said: O my people, serve Allah; you have no deity other than Allah; and do not diminish the measure and the scale. I see you in plenty, and I fear for you the punishment of a muhit day", "মাদিয়ানবাসীদের কাছে আমরা তাদের ভাই সো’য়েবকে পাঠিয়েছিলাম। সে বলল, “হে আমার লোকেরা,আল্লাহর উপাসনা করো; তাঁর পাশে তোমাদের অন্য কোন উপাস্য নেই। তোমরা যখন পরিমাপ অথবা ওজন করো তখন ধোঁকা দিও না। আমি দেখছি যে তোমরা সমৃদ্ধিশালী,আর আমি তোমাদের জন্য এক বিধ্বংসী দিনের শাস্তির ভয় করছি।"],
  "11:85": ["And O my people, give full the measure and the scale with equity, and do not diminish people their things, and do not ravage in the earth as corrupters", "“হে আমার লোকেরা, তোমরা পূর্ন পরিমাপ এবং পূর্ণ ওজন দেবে,ন্যায়সঙ্গতভাবে। লোকদেরকে তাদের অধিকার থেকে বঞ্চিত করো না, আর পৃথিবীতে দূর্নীতি করে ঘুরে বেড়িও না।"],
  "11:86": ["What Allah leaves remaining is better for you, if you are muminin; and I am not a guardian over you", "যাকিছু আল্লাহ তোমাদের প্রদান করেন, তা যত ক্ষুদ্রই হোক, তোমাদের জন্য অনেক উত্তম, যদি তোমরা সত্যিই বিশ্বাসী হও। আমি তোমাদের কোন অভিভাবক নই।”"],
  "11:87": ["They said: O Shu'ayb, does your prayer command you that we leave what our fathers served, or that we do with our wealth whatever we will? You are indeed the forbearing, the rightly guided", "তারা বলল, “হে শু’আইব, তোমার ধর্ম কি তোমাকে নির্দেশ দেয় যে আমাদের অবশ্যই আমাদের পিতামাতার ধর্ম, বা আমাদের পছন্দমত যেকোন পন্থায় আমাদের ব্যবসা চালানো পরিত্যাগ করতে হবে? নিশ্চয়ই, তুমি দয়ালু, বিজ্ঞ হিসেবে পরিচিত।”"],
  "11:88": ["He said: O my people, have you considered: if I am upon clear proof from my Rabb, and my Rabb has provided me a good provision, and I have no wish to oppose you in what I forbade you; I want only reform, as much as I can, and my success is only through Allah. Upon Allah I trust, and to Allah I turn back", "সে বলল, “হে আমার লোকেরা, যদি এমন হয় যে আমার কাছে আমার প্রভুর পক্ষ থেকে জোড়ালো প্রমান থাকে;  যদি এমন হয় যে তিনি আমাকে এক মহা অনুগ্রহ প্রদান করেছেন? এটা আমার ইচ্ছা নয় যে আমি তা-ই করবো যা আমি তোমাদেরকে করতে নিষেধ করি। আমি শুধু যতবেশি সম্ভব আমার ভুলগুলো সংশোধন করতে চাই। আমার পথপ্রাপ্তি সম্পূর্ণ আল্লাহর উপর নির্ভর করে; আমি আমার আস্থা তাঁর উপর রেখেছি। আমি তাঁর কাছে পুরোপুরি আত্মসমর্পণ করেছি।"],
  "11:89": ["And O my people, let not your falling out with me move you, that there strike you the like of what struck the people of Nuh, or the people of Hud, or the people of Salih; and the people of Lut are not far from you", "“আর, হে আমার লোকেরা, আমার প্রতি তোমাদের বিরোধীতা দ্বারা প্ররোচিত হয়ে একই বিপর্যয় টেনে এনো না নুহের লোকদের, বা হুদের লোকদের, বা সালেহের লোকদের মত; এবং লুতের লোকেরা তোমাদের থেকে খুব বেশি দূরে নয়।"],
  "11:90": ["And seek your Rabb's forgiveness, then turn back; truly my Rabb is merciful, most affectionate", "“তোমাদের উচিত তোমাদের প্রভুর কাছে ক্ষমার জন্য মিনতি করা, এরপর তাঁর কাছে অনুশোচনা করো। আমার প্রভু পরম দয়ালু,প্রেমময়।”"],
  "11:91": ["They said: O Shu'ayb, we do not understand much of what you say, and we see you weak among us. Were it not for your clan we would have stoned you, and you are not mighty over us", "তারা বলল, “হে শু’আইব, তুমি যা বলছো তার অনেক কিছু আমরা বুঝি না, এবং আমরা দেখি যে তুমি আমাদের মাঝে ক্ষমতাহীন। যদি তোমার গোত্র না থাকতো, আমরা তোমাকে পাথর মারতাম। আমাদের কাছে তোমার কোন মূল্য নেই।”"],
  "11:92": ["He said: O my people, is my clan mightier over you than Allah, and you have cast Allah behind your backs? Truly my Rabb is muhit over what you do", "সে বলল, “হে আমার লোকেরা, আমার গোত্র কি আল্লাহর থেকে বেশি সম্মানের অধিকারী? এ কারণেই কি তোমরা তাঁর প্রতি উদাসীন হয়ে আছো? তোমরা যা কিছু করো সে সম্পর্কে আমার প্রভু পূর্ণ অবগত।"],
  "11:93": ["And O my people, work upon your standing-place; I am working. Soon you will know who will come to the disgracing punishment, and who is the liar. And watch; I am with you, watching", "“হে আমার লোকেরা, যা তোমাদের ইচ্ছা করতে থাকো, আর আমিও তা করবো। তোমরা অবশ্যই দেখতে পাবে কে আমাদের মাঝে লজ্জাজনক শাস্তি টেনে আনে; তোমরা দেখতে পাবে মিথ্যাবাদী কে। শুধু আশা নিয়ে অপেক্ষা করো, এবং আমিও তোমাদের সাথে আশা নিয়ে অপেক্ষা করবো।"],
  "11:94": ["And when Our command came, We saved Shu'ayb and those who believed with him by a mercy from Us, and the shout took those who did wrong, and they became sprawled in their homes", "যখন আমাদের বিচার আসলো,আমরা শু’আইব এবং তার সাথে যারা বিশ্বাস করেছিল তাদের রক্ষা করেছিলাম, আমাদের পক্ষ থেকে দয়া দিয়ে। আর যারা মন্দ ব্যক্তি ছিল, তারা এক বিপর্যয় দ্বারা আঘাতপ্রাপ্ত হয়েছিল যা তাদেরকে তাদের বাড়িতে মৃত ফেলে রেখেছিল।"],
  "11:95": ["As though they had never flourished in them. Away with Midian, just as Thamud went away", "এটা এমন ছিল যেন তাদের কখনো অস্থিত্ব ছিল না। এভাবে,মাদিয়ানবাসী বিলুপ্ত হয়েছিল, যেভাবে এর আগে সামুদ জাতি বিলুপ্ত হয়েছিল।"],
  "11:96": ["And We sent Musa with Our ayat and a clear warrant", "আমরা মূসাকে আমাদের নিদর্শনাবলি ও এক সুস্পষ্ট কর্তৃত্বসহ পাঠিয়েছিলাম।"],
  "11:97": ["To Fir'awn and his chiefs, but they followed the command of Fir'awn; and the command of Fir'awn was not rightly guided", "ফেরাউন এবং তার সভাসদদের কাছে। কিন্তু তারা ফেরাউনের আদেশ অনুসরণ করলো আর ফেরাউনের আদেশ বিচক্ষন ছিল না।"],
  "11:98": ["He will go ahead of his people on the day of resurrection, and bring them to the fire; and wretched is the arrival-place arrived at", "সে পুনরুত্থান দিনে তার লোকদের নেতৃত্ব দিবে,নরকের পথে;কি এক শোচনীয় বাসস্থান বসবাসের জন্য!"],
  "11:99": ["And the curse followed them in this life and on the day of resurrection; wretched is the gift bestowed", "তারা এই জীবনে অভিশাপ টেনে এনেছে একইসাথে পুনরুত্থান দিনে; অনুসরণের কি এক শোচনীয় পথ!"],
  "11:100": ["That is of the tidings of the towns We narrate to you; of them are standing and mown down", "এটি অতীত সম্প্রদায়ের সংবাদ যা আমরা তোমাদের কাছে বর্ণনা করি। কিছু এখনো টিকে আছে,আর কিছু বিলুপ্ত হয়েছে।"],
  "11:101": ["We did not wrong them, but they wronged themselves; and their deities that they called upon besides Allah availed them nothing when the command of your Rabb came, and they added to them nothing but ruin", "আমরা কখনও তাদের প্রতি অন্যায় করিনি; তারাই তাদের নিজেদের আত্মার প্রতি অন্যায় করেছে। তাদের উপাস্যরা,যাদেরকে তারা আল্লাহর পাশে ডেকেছে, তাদেরকে একটুও সাহায্য করতে পারেনি যখন তোমার প্রভুর বিচার আসলো। কার্যত, তারা শুধু তাদের সর্বনাশ নিশ্চিত করেছে।"],
  "11:102": ["And thus is the seizing of your Rabb when seizing the towns while they are zalimun; truly the seizing is painful, severe", "এমনই ছিল তোমার প্রভুর আরোপিত শাস্তি যখন সম্প্রদায়গুলো সীমালংঘন করেছিল। প্রকৃতপক্ষে,তাঁর শাস্তি যন্ত্রনাদায়ক, ধ্বংসাত্মক।"],
  "11:103": ["Truly in that is an aya for those who fear the punishment of the hereafter. That is a day of gathering for humankind, and that is a witnessed day", "এটি তাদের জন্য একটি শিক্ষনীয় বিষয় হওয়া উচিত যারা পরকালের শাস্তিকে ভয় করে। এটি এমন এক দিন যখন সকল মানুষকে ডাকা হবে- যেদিন হবে সাক্ষী হওয়ার দিন।"],
  "11:104": ["And We postpone it only for a counted term", "আমরা এটি ঘটানোর জন্য একটি নির্দিষ্ট সময় নির্ধারণ করেছি।"],
  "11:105": ["On the day it comes, no nafs speaks except by permission; and among them are the wretched and the happy", "যেদিন এটি আসবে, কোন আত্মা একটি শব্দও উচ্চারণ করবে না, তাঁর ইচ্ছা ব্যতীত। কেউ কেউ হবে দুর্দশাগ্রস্থ, আর কেউ হবে সুখী।"],
  "11:106": ["As for those who were wretched, they are in the fire; for them therein are roaring and panting", "আর যারা দুর্দশাগ্রস্থ, তারা থাকবে নরকে, যেখানে তারা দীর্ঘশ্বাস ফেলবে ও আর্তনাত করবে।"],
  "11:107": ["Abiding therein as long as the heavens and the earth endure, except what your Rabb wills. Truly your Rabb is a doer of what Allah wills", "তারা সেখানে চিরকাল বাস করে, যতকাল আকাশমন্ডলী এবং পৃথিবী টিকে থাকে, তোমার প্রভুর ইচ্ছা অনুযায়ী। তোমার প্রভু তা-ই করেন যা কিছু তিনি ইচ্ছা করেন।"],
  "11:108": ["And as for those who were happy, they are in the garden, abiding therein as long as the heavens and the earth endure, except what your Rabb wills: a gift unceasing", "আর যারা সৌভাগ্যবান, তারা থাকবে স্বর্গে। তারা সেখানে চিরকাল বাস করবে, যতকাল আকাশমন্ডলী এবং পৃথিবী টিকে থাকে, তোমার প্রভুর ইচ্ছা অনুযায়ী - এক চিরস্থায়ী পুরষ্কার।"],
  "11:109": ["So do not be in doubt about what these ones serve. They serve only as their fathers served before; and We will give them their allotted portion in full, undiminished", "এই লোকেরা যা উপাসনা করে সে ব্যাপারে কোন সন্দেহ রেখো না; তারা উপাসনা করে ঠিক যেভাবে তারা তাদের পিতামাতাকে উপাসনা করতে দেখেছে। আমরা তাদের প্রাপ্য অংশ তাদেরকে সম্পূর্ণরূপে দিয়ে দেবো, কম না করে।"],
  "11:110": ["And We gave Musa the Kitab, and discord was made in it; and had not a prior word from your Rabb gone before, judgment would have been passed between them. And they are in doubting doubt about it", "আমরা মুসাকে ঐশ্বীগ্রন্থ দিয়েছিলাম, কিন্তু এটি বিতর্কিত হয়েছিল, আর যদি তা তোমার প্রভুর দ্বারা জারি করা একটি পূর্বনির্ধারিত আদেশ না হতো, অবিলম্বে তাদের বিচার করা হতো। তারা এ ব্যাপারে পুরোপুরি সন্দেহে আছে,দ্বিধাগ্রস্থ।"],
  "11:111": ["And truly, each and every one, your Rabb will give them in full their deeds; truly Allah is aware of what they do", "তোমার প্রভু অবশ্যই সবাইকে তাদের কাজের প্রতিদান দিবেন। তারা যা করে তিনি সেসব ব্যাপারে সম্পূর্ণ অবগত।"],
  "11:112": ["So stand firm as you were commanded, and whoever repented along with you; and do not transgress. Truly Allah sees what you do", "সুতরাং, সে পথে চলতে থাকো যা তোমাকে অনুসরণের আদেশ করা হয়েছে,তাদের সাথে একত্রে যারা তোমার সাথে অনুশোচনা করেছে, এবং সীমালংঘন করো না। তোমরা যা কিছু করো তিনি তা দেখেন।"],
  "11:113": ["And do not incline toward those who did wrong, lest the fire touch you; and you have no protectors besides Allah; then you will not be helped", "যারা সীমালংঘন করেছে তাদের প্রতি ঝুঁকে পড়ো না,পাছে তোমরা নরক টেনে আনো,এবং আল্লাহর বিপক্ষে তোমাদের সাহায্য করার জন্য কোন মিত্র খোঁজে না পাও, এরপর সবশেষে ক্ষতিগ্রস্থ হও।"],
  "11:114": ["And establish the prayer at the two ends of the day and in the early night. Truly the good deeds take away the evils. That is a remembrance for those who remember", "তুমি দিনের উভয় প্রান্তে সংযোগ প্রার্থনা (সালাত) পালন করবে, এবং রাতের বেলা। সৎকাজ মন্দ কাজকে মুছে ফেলে। এটি একটি সতর্কবার্তা তাদের জন্য যারা চিন্তা-ভাবনা করবে।"],
  "11:115": ["And be of the sabirin; truly Allah does not lose the reward of the muhsinin", "তুমি দৃড়তার সাথে অবিচল থাকবে, কারণ আল্লাহ সৎকর্মশীলদের প্রতিদান দিতে কখনও ব্যর্থ হন না।"],
  "11:116": ["If only there had been, among the generations before you, people of remaining good who forbade corruption in the earth, except a few of those We saved from among them. And those who did wrong pursued the ease in which they were softened, and they were mujrimin", "যদি শুধু পূর্ববর্তী প্রজন্মের মধ্যে কেউ কেউ মন্দ কাজ নিষিদ্ধ করার জন্য যথেষ্ঠ বুদ্ধিমত্তা রাখতো! তাদের অল্প কয়েকজনই আমাদের দ্বারা রক্ষা পাওয়ার যোগ্য ছিল। আর যারা সীমালংঘনকারী,তারা তাদের বৈষয়িক বিলাসিতা নিয়ে ব্যস্ত ছিল, তারা ছিল অপরাধী।"],
  "11:117": ["And it is not for your Rabb to destroy the towns by injustice while their people are reformers", "তোমার প্রভু কখনও অন্যায়ভাবে কোন সম্প্রদায়কে ধ্বংস করেন না,যখন এর লোকেরা সৎকর্মশীল।"],
  "11:118": ["And had your Rabb willed, Allah would have made humankind one community; and they will not cease to differ", "তোমার প্রভু যদি চাইতেন, তবে সকল মানুষ একটি (বিশ্বাসী ) দল হতো। কিন্তু তারা সবসময় (সত্যকে ) বিতর্কিত করবেই।"],
  "11:119": ["Except those your Rabb has mercy on; and for that Allah created them. And the word of your Rabb was completed: I will surely fill hell with the jinn and humankind, all together", "শুধু যারা তোমার প্রভুর কাছ থেকে দয়া দ্বারা অনুগ্রহপ্রাপ্ত  (তারা সত্যকে বিতর্কিত করবে না)। এই জন্য তিনি তাদের সৃষ্টি করেছেন। তোমার প্রভুর রায় পূর্বেই জারি হয়েছেঃ “আমি জীন ও মানুষ দিয়ে নরক পূর্ন করবো,সবাইকে একসাথে।”"],
  "11:120": ["And all of it We narrate to you from the tidings of the Rasuls, by which We make your heart firm. And in this, the truth has come to you, and an admonition, and a remembrance for the muminin", "আমরা তোমাকে বার্তাবাহকদের যথেষ্ঠ পরিমান ইতিহাস বর্ণনা করি তোমার হৃদয়কে শক্তিশালি করতে। এখানে তোমার কাছে সত্য এসেছে, সেই সাথে বিশ্বাসীদের জন্য আলোকিত জ্ঞান ও সতর্কবানী।"],
  "11:121": ["And say to those who do not believe: work upon your standing-place; we are working", "যারা অবিশ্বাস করে তাদের বল, “তোমরা যা পারো করো,এবং আমরাও তা করবো।"],
  "11:122": ["And wait; we are waiting", "“তারপর অপেক্ষা করো; আমরাও অপেক্ষা করবো।”"],
  "11:123": ["And to Allah belongs the hidden of the heavens and the earth, and to Allah returns the whole affair. So serve Allah and trust in Allah; and your Rabb is not unmindful of what you do", "আকাশমন্ডলী ও পৃথিবীর ভবিষ্যৎ আল্লাহর অধীনে, আর সব বিষয় তাঁর দ্বারা নিয়ন্ত্রিত হয়। তুমি তাঁর উপাসনা করবে এবং তাঁর প্রতি আস্থা রাখবে। তোমার প্রভু কখনোই অনবগত নন যা কিছু তোমরা করো।"],
  "12:1": ["Alif Lam Ra. These are the ayat of the clear Kitab.", "অ. ল. র। এইসব (অক্ষরগুলো) এই জ্ঞানগর্ভ ঐশীগ্রন্থের প্রমাণ।"],
  "12:2": ["We have sent it down as a reading in clear Arabic, so that you may reason.", "আমরা একে আরবী কুরআন রূপে প্রকাশ করেছি, যাতে তোমরা বুঝতে পারো।"],
  "12:3": ["We narrate to you the best of narratives in what We have inspired to you of this reading, though before it you were among the unmindful.", "আমরা এই কুরআনের ঐশীবার্তার মাধ্যমে তোমাদের নিকট সবচেয়ে নির্ভূল ইতিহাস বর্ণনা করি। এর আগে, তোমরা ছিলে সম্পূর্ণ অসচেতন।"],
  "12:4": ["When Yusuf said to his father: \"Father, I saw 11 stars, and the sun and the moon — I saw them bowing down to me.\"", "স্মরণ করো যে ইউসুফ তার পিতাকে বলেছিল, \"হে আমার পিতা, আমি এগারটি গ্রহ, ও সূর্য, ও চাঁদ দেখেছি ; আমি দেখেছি এগুলোকে আমার সামনে সেজদা করতে। \""],
  "12:5": ["He said: \"My son, do not narrate your vision to your brothers, lest they scheme against you a scheme. Truly the satan is to the human a clear enemy.\"", "সে বলল, \"আমার পুত্র, তোমার স্বপ্নের বিষয়ে তোমার ভাইদের বলো না, পাছে তারা তোমার বিরুদ্ধে চক্রান্ত করে ও ফন্দি আটে। নিশ্চয়ই, শয়তান হচ্ছে মানুষের ঘোরতর শত্রু।"],
  "12:6": ["\"Thus your Rabb will choose you and teach you the interpretation of ahadith, and complete favor upon you and upon the family of Ya'qub, as it was completed before upon your two fathers, Ibrahim and Ishaq. Truly your Rabb is knowing, wise.\"", "“এভাবে তোমার প্রভু তোমাকে সৌভাগ্যশালী করেছেন, এবং তোমাকে তোমার সপ্নের মাধ্যমে সুসংবাদ দিয়েছেন। তোমার প্রতি এবং ইয়াকুবের পরিবারের প্রতি তিনি তাঁর আশীর্বাদ সুসম্পন্ন করেছেন, যেমন ভাবে এর আগে তিনি তোমার পূর্বপুরুষ ইব্রাহীম এবং ইসহাকের জন্য করেছিলেন। তোমরা প্রভু সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "12:7": ["Already in Yusuf and his brothers were ayat for those who ask.", "ইউসুফ এবং তার ভাইদের মধ্যে অন্বেষণকারীদের জন্য শিক্ষা রয়েছে।"],
  "12:8": ["When they said: \"Yusuf and his brother are more beloved to our father than we, though we are a band. Truly our father is in clear error.\"", "তারা বলেছিল, “ইউসুফ এবং তার ভাই আমাদের পিতার সুনজরে রয়েছে, এবং আমরা সংখ্যায় বেশি। আসলেই, আমাদের পিতা স্পষ্ট ভ্রান্তিতে আছে।"],
  "12:9": ["\"Kill Yusuf, or cast him to some land, so that your father's face may be free for you, and you may be after him a people good.\"", "“চল আমরা ইউসুফকে হত্যা করি, অথবা তাকে নির্বাসিত করি, যাতে তোমরা তোমাদের পিতার মনোযোগ পেতে পারো। এরপর, তোমরা সৎকর্মশীল লোক হতে পারবে।"],
  "12:10": ["A speaker among them said: \"Do not kill Yusuf — cast him into the hidden depths of the well, and some of the travelers will pick him up, if you are doers.\"", "তাদের একজন বলেছিল, “ইউসুফকে হত্যা করো না; চল আমরা তাকে কুপের গভীরে নিক্ষেপ করি। হয়তো কোন কাফেলা তাকে তুলে নিতে পারে, যদি তোমরা এটা করার জন্যই সিদ্ধান্ত নিয়ে থাকো।"],
  "12:11": ["They said: \"Father, what is it with you that you do not trust us with Yusuf? We are indeed sincere to him.\"", "তারা বলল, \"আমাদের পিতা, কেন আপনি ইউসুফের বিষয়ে আমাদের উপর আস্থা রাখেন না? আমরা তাকে ভালো করে দেখে রাখবো।"],
  "12:12": ["\"Send him with us tomorrow, to roam and play; we will keep him safe.\"", "\"কাল তাকে আমাদের সাথে দৌঁড়তে এবং খেলতে পাঠান। আমরা তাকে নিরাপদে রাখবো।\""],
  "12:13": ["He said: \"It grieves me that you should go off with him, and I fear the wolf will eat him while you are unmindful of him.\"", "সে বলল, \"আমার ভয় হয় পাছে তোমরা তাকে নিয়ে দূরে চলে যাও, এরপর যখন তার প্রতি তোমরা খেয়াল না করো নেকড়ে তাকে খেয়ে ফেলতে পারে।\""],
  "12:14": ["They said: \"If the wolf eats him while we are a band, then we are losers indeed.\"", "তারা বলল, \"নিশ্চয়, যদি নেকড়ে তাকে খেয়ে ফেলে, আমরা অনেকেই আশেপাশে থাকা সত্ত্বেও, তাহলে আমরা সত্যিই ক্ষতিগ্রস্ত।\""],
  "12:15": ["So when they went with him and agreed to put him into the hidden depths of the well, We inspired to him: \"You shall tell them of this affair of theirs, and they perceive not.\"", "যখন তারা তাকে নিয়ে দূরে চলে গেল, এবং সর্বসম্মতিক্রমে তাকে কুপের গভীরে নিক্ষেপ করার সিদ্ধান্ত নিল, আমরা তাকে অনুপ্রাণিত করলাম, \"একদিন, তুমি এই সবকিছু সম্পর্কে তাদের বলবে, অথচ তাদের কোন ধারণাই থাকবে না।\""],
  "12:16": ["And they came to their father in the evening, weeping.", "তারা সন্ধ্যায় তাদের পিতার কাছে ফিরে এলো, কাঁদতে কাঁদতে।"],
  "12:17": ["They said: \"Father, we went racing and left Yusuf by our goods, and the wolf ate him; and you would not believe us even if we were sadiq.\"", "তারা বলল, “আমাদের পিতা, আমরা একে অন্যের সাথে দৌড়াতে গিয়েছিলাম, ইউসুফকে আমাদের সরঞ্জামের কাছে রেখে, আর নেকড়ে তাকে খেয়ে ফেলল। আপনি কখনই আমাদের বিশ্বাস করবেন না, যদিও আমরা আপনাকে সত্য বলছি।"],
  "12:18": ["And they came with his shirt, false blood upon it. He said: \"No — your nafs have allured you into an affair. So, beautiful patience! And Allah is the One whose help is sought against what you describe.\"", "তারা তার জামায় নকল রক্ত লাগিয়ে উপস্থাপন করলো। সে বলল, “নিশ্চয়, তোমরা পরস্পর চক্রান্ত করেছ একটা নির্দিষ্ট পরিকল্পনা বাস্তবায়ন করতে। আমি যা করতে পারি তা হল নীরবে ধৈর্য ধারন। তোমাদের ষড়যন্ত্রের মুখে আল্লাহ আমাকে সাহায্য করুন”।"],
  "12:19": ["And a traveling company came and sent their water-drawer, and he let down his bucket. He said: \"Good news — here is a boy!\" And they concealed him as goods. And Allah knows what they do.", "একটি কাফেলা পাশ দিয়ে যাচ্ছিল, এবং শীঘ্রই তাদের পানি সংগ্রাহককে পাঠালো। সে তার বালতি নিচে ফেললো, তারপর বলল, “কি সৌভাগ্য! এখানে তো দেখি এক বালক! তারা তাকে পণ্যদ্রব্য হিসাবে সাথে নিল, এবং তারা যা করেছিল আল্লাহ সে বিষয়ে সম্পূর্ণ অবগত ছিলেন।"],
  "12:20": ["And they sold him for a diminished price, counted dirhams, and they had little regard for him.", "তারা সস্তা মুল্যে তাকে বিক্রি করলো- অল্প কিছু দিরহামে-কারন তাকে তাদের কোন প্রয়োজন ছিল না।"],
  "12:21": ["And the one who bought him, from Riverland, said to his imra'a: \"Give him a generous lodging; perhaps he will benefit us, or we may take him as a son.\" Thus We established Yusuf in the land, that We might teach him the interpretation of ahadith. And Allah overcomes in the affair, but most people do not know.", "যে ব্যক্তি তাকে মিশরে এনেছিল সে তার স্ত্রীকে বলল, \"তার ভাল যত্ন নাও। হয়তো সে আমাদের উপকারে আসবে, অথবা আমরা তাকে দত্তক নিতে পারি।\"এভাবে আমরা ইউসুফকে পৃথিবীতে প্রতিষ্ঠিত করেছি, এবং আমরা তাকে স্বপ্নের ব্যাখ্যা করতে শিখিয়েছি, আল্লাহর নির্দেশ সর্বদাই সম্পন্ন হয়, কিন্তু বেশির ভাগ লোক জানে না।"],
  "12:22": ["And when he reached his full strength, We gave him judgment and knowledge. Thus We reward the muhsinin.", "যখন সে পরিণত বয়সে পৌছল, আমরা তাকে প্রজ্ঞা ও জ্ঞান দান করলাম। আমরা এভাবে সৎকর্মশীলদের পুরষ্কৃত করি।"],
  "12:23": ["And she in whose house he was solicited him, and locked the doors, and said: \"Here you are!\" He said: \"I seek refuge in Allah — indeed, my Rabb has given me a good lodging. Truly the wrongdoers do not attain success.\"", "যেখানে সে বাস করতো সে বাড়ির কর্ত্রী তাকে প্রলুব্ধ করার চেষ্টা করলো। সে দরজাগুলো বন্ধ করলো এবং বলল, \"আমি সম্পূর্ণরূপে তোমার।”সে বলল, \"আল্লাহ আমায় রক্ষা করুক। তিনি আমার প্রভু, যিনি আমাকে একটি ভালো বাসস্থান দিয়েছেন। সীমালঙ্ঘনকারীরা কখনো সফল হয় না।\""],
  "12:24": ["And she resolved upon him, and he resolved upon her, had he not seen the clear proof of his Rabb. Thus We averted from him the evil and the obscenity. Truly he was among Our abd, the mukhlisin.", "সে (মহিলা) তার প্রতি প্রায় ঢলে পড়েছিল এবং সে (ইউসুফ) তার প্রতি প্রায় ঢলে পড়েছিল, যদি সে(ইউসুফ) তার প্রভুর পক্ষ থেকে একটি প্রমাণ না দেখতো। আমরা এভাবে মন্দ ও পাপকে তার থেকে সরিয়ে দিয়েছিলাম, কারণ সে ছিল আমাদের নিবেদিত বান্দাদের একজন।"],
  "12:25": ["And they raced to the door, and she tore his shirt from behind; and they found her master at the door. She said: \"What is the requital of one who intended evil to your family, but that he be imprisoned, or given a painful punishment?\"", "তাদের দুজনে দরজার দিকে ছুটল, এবং, এক পর্যায়ে, সে(মহিলা) পিছন থেকে তার পোষাক ছিঁড়ে ফেললো। তারা তার স্বামীকে দরজায় পেল। সে বলল, \"যে ব্যক্তি তোমার স্ত্রীর সাথে অপকর্ম করতে চেয়েছে তার শাস্তি কি হওয়া উচিত, বন্দী থাকা বা এক যন্ত্রণাকর শাস্তি পাওয়া ছাড়া?\""],
  "12:26": ["He said: \"It was she who solicited me.\" And a witness from her family bore witness: \"If his shirt is torn from the front, then she is sadiq and he is among the kazibin.\"", "সে বলল, “সে-ই আমাকে প্রলুব্ধ করার চেষ্টা করেছিল”। তার পরিবারের একজন সাক্ষী পরামর্শ দিলঃ “যদি তার পোশাক সামনে থেকে ছেঁড়া থাকে, তবে সে (মহিলা) সত্য বলছে, এবং সে(ইউসুফ) মিথ্যুক”।"],
  "12:27": ["\"And if his shirt is torn from behind, then she lies, and he is among the sadiqin.\"", "“এবং যদি তার পোশাক পেছন থেকে ছেঁড়া থাকে, তবে সে (মহিলা) মিথ্যা বলছে, এবং সে(ইউসুফ) সত্য বলছে”।"],
  "12:28": ["So when he saw that his shirt was torn from behind, he said: \"It is of your scheming; your scheme is great indeed.\"", "যখন তার স্বামী দেখলো যে তার পোশাক পেছন থেকে ছেঁড়া, সে বলল, “এটা এক নারীর চক্রান্ত। নিশ্চয়, তোমার চক্রান্ত দূর্ভেদ্য”।"],
  "12:29": ["\"Yusuf, turn away from this; and ask forgiveness for your offense. Truly you were among the erring.\"", "“ইউসুফ, এ ঘটনা উপেক্ষা করো। আর (আমার স্ত্রী) তোমার উচিত তোমার পাপের জন্য ক্ষমা চাওয়া। তুমি একটি ভুল করেছ”।"],
  "12:30": ["And nisa of the town said: \"The Aziz's imra'a is soliciting her young servant; love has smitten her through. We see her in clear error.\"", "শহরে কিছু নারী বলাবলি করতে লাগলোঃ “শাসকের স্ত্রী তার ভৃত্যকে প্রলুব্ধ করার চেষ্টা করছে। সে তার গভীর প্রেমে পড়েছে। আমরা দেখছি যে সে বিপথে গেছে”।"],
  "12:31": ["So when she heard of their scheme, she sent to them and prepared for them a reclining couch, and gave each one of them a knife, and said: \"Come out upon them.\" So when they saw him they were awed by him and cut their hands, and said: \"By Allah, this is no mortal — this is none but a noble malakat.\"", "যখন সে(মহিলা) তাদের রটনা শুনলো, সে তাদের আমন্ত্রণ জানালো, তাদের জন্য একটি আরামদায়ক স্থান প্রস্তুত করলো, এবং তাদের প্রত্যেককে একটি ছুরি দিল। এরপর সে তাকে বলল, \"তাদের কক্ষে প্রবেশ করো।”যখন তারা তাকে দেখল, তারা তার রূপে এতোই বিমুগ্ধ হলো, যে তারা তাদের হাত কেটে ফেলল। তারা বলল, \"মহিমা আল্লাহরই, এ তো কোন মানুষ নয়; এ এক সম্মানিত ফেরেশতা।\""],
  "12:32": ["She said: \"That is the one you blamed me about. And I indeed solicited him, but he protected-held. And if he does not do what I command him, he shall be imprisoned and shall be among the belittled.\"", "সে বলল, \"এই সে ব্যক্তি যার প্রেমে পড়ার কারণে তোমরা আমাকে দোষী করেছিলে। আসলে আমিই তাকে প্রলুব্ধ করার চেষ্টা করেছিলাম, এবং সে প্রত্যাখ্যান করেছিল। যদি সে আমি যা আদেশ করি তা না করে, নির্ঘাৎ সে জেলে যাবে এবং হেয় হবে।"],
  "12:33": ["He said: \"My Rabb, prison is more beloved to me than what they call me to. And if You do not avert their scheme from me, I will incline to them and be among the ignorant.\"", "সে বলল, \"আমার প্রভু, তাদের কাছে নতি স্বীকার করার থেকে জেলে যাওয়া ভাল। যদি না আমার থেকে আপনি তাদের চক্রান্ত সরিয়ে দেন, আমি হয়তো তাদের আকাঙ্ক্ষা করবো এবং নির্বোধের মত আচরণ করবো।"],
  "12:34": ["So his Rabb answered him and averted their scheme from him. Truly Allah is the Hearing, the Knowing.", "তার প্রভু তার প্রার্থনার জবাব দিলেন এবং তার থেকে তাদের চক্রান্ত সরিয়ে দিলেন। তিনি সর্বশ্রোতা, সর্বজ্ঞানী।"],
  "12:35": ["Then, though they had seen the ayat, it appeared to them that they should imprison him for a time.", "পরবর্তীতে, তারা এটি দেখেছিল, স্পষ্ট প্রমাণাদি সত্ত্বেও, যে তাদের উচিৎ তাকে কিছুকালের জন্য বন্দী রাখা।"],
  "12:36": ["And two youths entered the prison with him. One of them said: \"I see myself pressing wine.\" And the other said: \"I see myself carrying bread upon my head, and birds eat of it. Tell us its interpretation — we see you among the muhsinin.\"", "তার সাথে কারাগারে দুজন যুবক ছিল। তাদের একজন বলল, “আমি (আমার স্বপ্নে) দেখেছি যে আমি মদ তৈরি করছি,”এবং অন্যজন বলল, “আমি দেখেছি আমি আমার মাথায় রুটি বহন করছি, যা থেকে পাখিরা খাচ্ছে। এই স্বপ্নগুলোর ব্যাখ্যা আমাদের জানাও। আমরা দেখছি যে তুমি সৎকর্মশীল”।"],
  "12:37": ["He said: \"No food will come to you both that you are provided with, but I will tell you its interpretation before it comes to you. That is of what my Rabb has taught me. I have left the way of a people who do not believe in Allah, and who of the Hereafter are kafirin.\"", "সে বলল, “যদি তোমাদের কোন খাবার দেয়া হয়, তা তোমরা পাওয়ার আগে আমি তোমাদেরকে এর সম্পর্কে জানাতে পারবো। এগুলো আমার প্রতি আমার প্রভুর প্রদত্ত কিছু জ্ঞান। আমি পরিত্যাগ করেছি সেই লোকদের ধর্ম যারা আল্লাহতে বিশ্বাস করে না, এবং পরকালের ব্যাপারে, তারা আসলেই অবিশ্বাসী”।"],
  "12:38": ["\"And I have followed the way of my fathers, Ibrahim and Ishaq and Ya'qub. It was not for us to associate anything with Allah. That is of Allah's favor upon us and upon the people — but most people do not give thanks.\"", "“এবং আমি এর পরিবর্তে অনুসরণ করেছি আমার পূর্বপুরুষ ইব্রাহীম, ইসহাক, এবং ইয়াকুবের ধর্ম। আমরা কখনো আল্লাহর পাশে কোন উপাস্য স্থাপন করি না। এমনই আল্লাহর আশীর্বাদ আমাদের প্রতি এবং মানুষের প্রতি, কিন্তু বেশিরভাগ মানুষ অকৃতজ্ঞ।"],
  "12:39": ["\"O my two prison companions — are separate rabbs better, or Allah, the One, the Overpowering?\"", "“হে আমার কারাসঙ্গিরা, অনেক উপাস্য উত্তম, নাকি একমাত্র আল্লাহ, একক সত্ত্বা, সর্বোচ্চ?”"],
  "12:40": ["\"What you worship apart from Allah is nothing but names you have named, you and your fathers, for which Allah has sent down no warrant. Judgment belongs to Allah alone: the command that you worship none but Allah. That is the upright way — but most people do not know.\"", "“তোমরা তার পাশে কোন কিছুর উপাসনা করো না উদ্ভাবন ছাড়া, যা তোমরা বানিয়েছো, তোমরা এবং তোমাদের পিতামাতারা। আল্লাহ কখনই এমন উপাস্যের অনুমোদন দেননি। সকল বিধান আল্লাহর, এবং তিনি বিধান দিয়েছেন যে তোমরা তাকে ছাড়া অন্যকিছুর উপাসনা করবে না। এটাই সঠিক ধর্ম, কিন্তু বেশিরভাগ মানুষ জানে না”।"],
  "12:41": ["\"O my two prison companions: as for one of you, he will serve his master wine; and as for the other, he will be crucified, and birds will eat from his head. Decided is the affair about which you two asked a ruling.\"", "\"হে আমার কারাসঙ্গীরা, তোমাদের একজন তার মনিবের মদ পরিবেশক হবে, যখন অন্যজন হবে ক্রুশবিদ্ধ- পাখিরা তার মাথা থেকে খাবে। তোমরা যা জানতে চেয়েছ এটা তা পূর্ণ করে।"],
  "12:42": ["And he said to the one of the two whom he supposed would be saved: \"Remember me with your master.\" But the satan made him forget to remember his master, so he tarried in the prison several years.", "সে এরপর যার রক্ষা পাওয়ার কথা তাকে বলল, \"তোমার মনিবের কাছে আমার কথা স্মরণ করো।” এরূপে, শয়তান তাকে তার প্রভুর কথা ভুলিয়ে দিল, এবং, পরিনামে, সে আরো কয়েক বছর কারাগারে রইলো ।"],
  "12:43": ["And the king said: \"I see 7 fat cows being eaten by 7 lean ones, and 7 green ears of grain and others dry. O you chiefs, give me a ruling about my vision, if you can interpret visions.\"", "রাজা বলল, “আমি দেখলাম সাতটি মোটাতাজা গরুকে গিলে ফেলছে সাতটি কঙ্কালসার গরু, এবং (গমের) সাতটি সবুজ শীষ, এবং অন্যগুলো কোঁকড়ানো। হে আমার সভাসদরা, আমাকে আমার স্বপ্নের বিষয়ে পরামর্শ দাও, যদি তোমরা স্বপ্নের ব্যাখ্যা দিতে জানো।”"],
  "12:44": ["They said: \"A jumble of dreams — and we have no knowledge of dream interpretation.\"", "তারা বলল, \"অর্থহীন স্বপ্ন। যখন স্বপ্ন ব্যাখ্যা করার বিষয় আসে, সে ব্যাপারে আমরা জ্ঞানী নই।\""],
  "12:45": ["And the one saved of the two said, remembering after a time: \"I will tell you its interpretation; so send me.\"", "যে ব্যক্তি (কারাগার থেকে) রক্ষা পেয়েছিল সে বলল, অবশেষে যেহেতু তার মনে পড়লো, \"আমি আপনাকে এর ব্যাখ্যা বলতে পারি, তাই আমাকে (ইউসুফের) কাছে পাঠান।\""],
  "12:46": ["\"Yusuf, O sadiq one, give us a ruling about 7 fat cows being eaten by 7 lean ones, and 7 green ears and others dry — that I may return to the people so that they may know.\"", "“আমার বন্ধু ইউসুফ, সাতটি মোটাতাজা গরুকে গিলে ফেলছে সাতটি হাড্ডিসার গরু, এবং সাতটি সবুজ শীষ, ও অন্যগুলো কোঁকড়ানো, এ বিষয়ে আমাদের জানাও। আমি লোকদের জন্য কিছু তথ্য নিয়ে ফিরে যেতে চাই”।"],
  "12:47": ["He said: \"You will crop 7 years unceasingly; so what you harvest, leave in its ears, except a little that you eat.\"", "সে বলল, “পরবর্তী সাত বছর  যা তোমরা আবাদ করো, যখন ফসল তোলার সময় আসে, শস্য তার শীষের মধ্যে রেখে দাও, যা তোমরা খাও সেগুলো ছাড়া”।"],
  "12:48": ["\"Then 7 hard years will come after that, eating what you have laid up for them, except a little that you fortify.\"", "“এরপর, সাত বছরের খরা আসবে, যা এদের জন্য তোমাদের জমা রাখা বেশির ভাগ অংশ সাবাড় করবে।"],
  "12:49": ["\"Then after that a year will come in which the people are given rain, and in which they press.\"", "“এরপর, একটি বছর আসবে যা লোকদের জন্য পরিত্রান নিয়ে আসবে, এবং তারা আবারও, রস নিংড়াবে”।"],
  "12:50": ["And the king said: \"Bring him to me.\" So when the Rasul came to him, he said: \"Return to your master and ask him: what of the nisa who cut their hands? Truly my master is knowing of their scheme.\"", "রাজা বলল, “তাকে আমার কাছে আনো”। যখন বার্তাবাহক তার কাছে আসলো, সে বলল, “তোমার মনিবের কাছে ফিরে যাও এবং তাকে বল সে নারীদের বিষয়ে অনুসন্ধান করতে যারা তাদের হাত কেটে ফেলেছিল। আমার প্রভু তাদের চক্রান্ত সন্মন্ধে পূর্ণ অবগত”।"],
  "12:51": ["He said: \"What was your affair when you solicited Yusuf?\" They said: \"By Allah, we know no evil of him.\" The Aziz's imra'a said: \"Now the truth has come clear: it was I who solicited him, and he is among the sadiqin.\"", "(রাজা সে নারীকে) বলল, \"তোমরা সে ঘটনা সম্পর্কে কি জানো যখন তোমরা ইউসুফকে প্রলুব্ধ করার চেষ্টা করেছিলে? তারা বলল, “আল্লাহ না করুন; তার দ্বারা কোন মন্দ কাজ হয়েছে বলে আমরা জানতাম না। “শাসকের স্ত্রী বলল, \"এখন সত্যের জয় হয়েছে। আমি-ই তাকে প্রলুব্ধ করার চেষ্টা করেছিলাম, এবং সে সত্যবাদী ছিল।"],
  "12:52": ["\"That is so that he may know that I did not betray him in the ghayb, and that Allah does not guide the kayd of the khā'inīn.\"", "“আমি আশা করি- সে (ইউসুফ) বুঝবে যে আমি কখনো তার অনুপস্থিতিতে তাকে প্রতারিত করিনি, যেহেতু আল্লাহ প্রতারণাকারীর পরিকল্পনা আশীর্বাদ করেণ না।"],
  "12:53": ["\"And I do not clear myself; truly the self is ever commanding to evil, except what my Rabb has mercy on. Truly my Rabb is Forgiving, Raheem.\"", "“আমি নিজেকে নির্দোষ দাবি করি না।  স্বীয়-মন খারাপ কাজের পরামর্শ দেয়, তাদের ব্যতীত যারা আমার প্রভুর কাছ থেকে দয়া অর্জণ করেছে। আমার প্রভু ক্ষমাকারী, সবচেয়ে দয়ালু।”"],
  "12:54": ["And the king said: \"Bring him to me — I will take him exclusively for myself.\" So when he spoke with him, he said: \"You are today with us established and trusted.\"", "রাজা বলল, “তাকে আমার কাছে নিয়ে আসো, যেন আমি তাকে আমার জন্য কাজে নিয়োগ দিতে পারি।”যখন সে তার সাথে কথা বলল, সে বলল, “আজ, আমাদের মাঝে তুমি বিশেষ পদমর্যাদা পেয়েছ।”"],
  "12:55": ["He said: \"Set me over the store-houses of the land; I am a keeper, knowing.\"", "সে বলল, “আমাকে কোষাধ্যক্ষ করুন, যেহেতু এক্ষেত্রে আমি অভিজ্ঞ এবং জ্ঞান রাখি”"],
  "12:56": ["Thus We established Yusuf in the land; he settles in it wherever he wishes. We reach with Our mercy whom We wish, and We do not lose the wage of the muhsinin.", "আমরা এভাবে ইউসুফকে পৃথিবীতে প্রতিষ্ঠিত করলাম, তার ইচ্ছামুসারে শাসন করতে। আমরা যার উপর ইচ্ছা আমাদের দয়া বর্ষণ করি, এবং আমরা কখনো সৎকর্মশীলদের প্রতিদান দিতে ব্যর্থ হই না।"],
  "12:57": ["And the wage of the Hereafter is better for those who believe and were ever guarding.", "উপরন্তু, যারা বিশ্বাস করে ও সৎকর্মশীল জীবন-যাপন করে তাদের জন্য পরকালের পুরষ্কার অনেক উত্তম।"],
  "12:58": ["And the brothers of Yusuf came and entered upon him, and he recognized them, while they were strangers to him.", "ইউসুফের ভাইয়েরা আসল; তারা যখন প্রবেশ করলো, সে তাদের চিনতে পারলো, যদিও তারা তাকে চিনেনি।"],
  "12:59": ["And when he had equipped them with their equipment, he said: \"Bring me a brother of yours from your father. Do you not see that I fulfil the measure and am the best of hosts?\"", "সে তাদেরকে তাদের রসদ প্রদান করার পর, সে বলল, “পরের বার, তোমাদের সাথে তোমাদের সৎ ভাইকে নিয়ে এসো। তোমরা কি দেখো না যে আমি পরিপূর্ণ মাপ দেই, এবং তোমাদের প্রতি উদার?"],
  "12:60": ["\"But if you do not bring him to me, there will be no measure for you with me, and you will not come near.\"", "“যদি তোমরা তাকে আমার কাছে আনতে ব্যর্থ হও, তোমরা আমার কাছে কোন অংশ পাবে না; তোমরা আমার নিকটেও আসতে পারবে না।”"],
  "12:61": ["They said: \"We will ask his father about him, and we will do it.\"", "তারা বলল, “আমরা তার বিষয়ে রাজি করাতে তার পিতার সাথে কথা বলবো। অবশ্যই আমরা তা করবো।\""],
  "12:62": ["And he said to his youths: \"Place their goods in their packs, so that they may recognize it when they turn back to their family — perhaps they will return.\"", "সে এরপর তার সহকারীদের নির্দেশ দিল, \"তাদের পন্যগুলো পুনরায় তাদের ব্যাগে রেখে দাও। যখন তারা তাদের পরিবারের কাছে ফিরে এগুলো পাবে, তারা হয়তো শীঘ্রই ফিরে আসবে।\""],
  "12:63": ["So when they returned to their father they said: \"Father, the measure was withheld from us; so send our brother with us, that we may measure — and we will keep him safe.\"", "যখন তারা তাদের পিতার কাছে ফিরল, তারা বলল, \"আমাদের পিতা, আমরা আর কোন খাদ্যদ্রব্য পাব না, যদি না আপনি আমাদের সাথে আমাদের ভাইকে পাঠান। আমরা তা্র ভাল দেখ-ভাল করবো।\""],
  "12:64": ["He said: \"Should I trust him to you, other than as I trusted you with his brother before? Allah is the best keeper, and the most merciful of the merciful.\"", "সে বলল, \"আমি কি তার ব্যাপারে তোমাদের উপর আস্থা রাখবো, যেমন এর আগে আমি তার ভাইয়ের ব্যাপারে আস্থা রেখেছিলাম? আল্লাহ সর্বোত্তম রক্ষাকারী, এবং, সকল দয়ালুদের মধ্যে, তিনি পরম দয়ালু।"],
  "12:65": ["And when they opened their goods they found their merchandise returned to them. They said: \"Father, what more could we want? Here is our merchandise returned to us; we will supply our family, keep our brother, and add a camel's measure — that is an easy measure.\"", "যখন তারা তাদের ব্যাগগুলো খুলল, তারা দেখল যে তাদের পন্য তাদের ফেরত দেয়া হয়েছে। তারা বলল, \"আমাদের পিতা, আমরা এর বেশি কি চাইতে পারি? এগুলো আমাদের পন্য যা আমাদের ফেরত দেয়া হয়েছে। এরুপে আমরা আমাদের পরিবারের প্রয়োজন মেটাতে পারি, আমাদের ভাইকে রক্ষা করতে পারি, এবং আরও এক উট মাল পেতে পারি। এ তো নিশ্চয় এক লাভজনক লেনদেন। \""],
  "12:66": ["He said: \"I will not send him with you until you give me a pledge from Allah that you will bring him to me, unless you are yuhat.\" So when they gave him their pledge, he said: \"Allah is guardian over what we say.\"", "সে বলল, \"আমি তাকে তোমাদের সাথে পাঠাবো না, যদি না তোমরা আল্লাহর সামনে আমাকে দৃঢ় অঙ্গীকার দাও যে তোমরা তাকে ফেরত আনবে, যদি না তোমরা একেবারেই অসহায় হয়ে পড়ো।”যখন তারা তাকে তাদের দৃড় অঙ্গীকার দিল, সে বলল, \"আমাদের বলা সবকিছু আল্লাহ প্রত্যক্ষ করছেন।\""],
  "12:67": ["And he said: \"My sons, do not enter by one gate; enter by separate gates. And it avails you nothing against Allah of anything. Judgment belongs to Allah alone; upon Allah I rely, and upon Allah let the reliant rely.\"", "এবং সে বলল, \"হে আমার ছেলেরা, এক দরজা দিয়ে প্রবেশ করো না; আলাদা আলাদা দরজা দিয়ে প্রবেশ করো। যাহোক, আমি আল্লাহর পূর্বনির্ধারিত কোন কিছু থেকে তোমাদের রক্ষা করতে পারি না। সকল বিচার আল্লাহর অধীন। আমি তাঁর উপর আস্থা রাখি, এবং তাঁর উপরেই সকল আস্থাকারীদের আস্থা রাখা উচিত।\""],
  "12:68": ["And when they entered from where their father commanded them, it availed them nothing against Allah of anything, except a need in Ya'qub's nafs that he fulfilled; and he is possessed of knowledge through what We taught him — but most people do not know.", "যখন তারা (ইউসুফের) কাছে গেল, তারা তাদের পিতার নির্দেশনা অনুযায়ী প্রবেশ করলো। যদিও এটি আল্লাহর আদেশক্রিত কোন কিছু পরিবর্তন করতে পারতো না, ইয়াকুবের একটি ব্যক্তিগত কারণ ছিল তাদেরকে তা করতে বলার জন্য। কারন সে নির্দিষ্ট জ্ঞান অর্জন করেছিল যা আমরা তাকে শিখিয়েছিলাম, কিন্তু অধিকাংশ লোক জানে না।"],
  "12:69": ["And when they entered upon Yusuf, he sheltered his brother with him, saying: \"I am your brother — so do not grieve at what they used to do.\"", "যখন তারা ইউসুফের জায়গায় প্রবেশ করলো, সে তার ভাইকে কাছে আনলো এবং বলল, \"আমি তোমার ভাই, তাদের কাজে দু:খ করো না।\""],
  "12:70": ["So when he had equipped them with their equipment, he placed the drinking-cup in his brother's pack; then a crier cried out: \"O caravan — you are thieves!\"", "যখন সে তাদেরকে তাদের রসদ দিল, সে পানির কাপটি তার ভাইয়ের ব্যাগে রেখে দিল, এরপর একজন ঘোষণাকারী ঘোষনা করলো, \"এই কাফেলার মালিকেরা চোর।\""],
  "12:71": ["They said, coming at them: \"What are you missing?\"", "তারা বলল, যখন তারা তাদের দিকে আসল, \"তোমরা কি হারিয়েছ?\""],
  "12:72": ["They said: \"We miss the king's cup; and whoever brings it shall have a camel's load, and I am its guarantor.\"", "তারা বলল, \"আমরা রাজার কাপ হারিয়েছি। এটি যে-ই ফেরত দেবে সে অতিরিক্ত এক উট বোঝাই মাল পাবে; আমি ব্যক্তিগতভাবে এর নিশ্চয়তা দিচ্ছি”।"],
  "12:73": ["They said: \"By Allah, you know well that we did not come to corrupt the land, and we are not thieves.\"", "তারা বলল, \"আল্লাহর শপথ, তোমরা ভালো করে জানো যে আমরা এখানে মন্দ কাজ করতে আসিনি, আর না আমরা চোর।\""],
  "12:74": ["They said: \"Then what is its requital, if you are liars?\"", "তারা বলল, \"চোরের শাস্তি কি, যদি তোমরা মিথ্যুক হও?"],
  "12:75": ["They said: \"Its requital is that he in whose pack it is found — he is its requital. Thus we requite the wrongdoers.\"", "তারা বলল, \"শাস্তি হচ্ছে, যদি এটি তার ব্যাগে পাওয়া যায়, যে সে চোর তোমাদের মালিকানাভুক্ত হবে। আমরা এভাবে অপরাধীদের শাস্তি দেই।\""],
  "12:76": ["So he began with their packs before his brother's pack; then he drew it out of his brother's pack. Thus We schemed for Yusuf — he could not have taken his brother under the king's law unless Allah willed. We raise in degree whom We wish, and above every knower is a Knower.", "এরপর সে তাদের পাত্রগুলো থেকে পর্যবেক্ষণ শুরু করলো, তার ভাইয়ের পাত্রের কাছে যাওয়ার আগে, এবং সে তার ভাইয়ের পাত্র থেকে এটি বের করলো। আমরা এভাবে পরিকল্পনাটি ইউসুফের জন্য নিখুঁত করলাম; সে তার ভাইকে রাখতে পারতো না, যদি সে রাজার আইন প্রয়োগ করতো। কিন্তু ঐটাই ছিল আল্লাহর ইচ্ছা। আমরা উচ্চতর পদে উন্নীত করি যাকেই আমরা পছন্দ করি। সকল জ্ঞানবানদের মধ্যে, রয়েছেন এমন এক সত্ত্বা যিনি আরোও জ্ঞানবান।"],
  "12:77": ["They said: \"If he steals — well, a brother of his stole before.\" So Yusuf kept it hidden in himself and did not disclose it to them. He said: \"You are in a worse place. And Allah knows best what you describe.\"", "তারা বলল, \"সে চুরি করে থাকলে, অতীতে তার ভাইও তা করেছিল। ইউসুফ নিজের মধ্যে তার অনুভূতি লুকালো, এবং তাদেরকে কোন ইঙ্গিত দেয়নি। সে (নিজে নিজে) বলল, \"তোমরা আসলেই খারাপ। আল্লাহ তোমাদের অভিযোগের বিষয়ে পূর্ণ সচেতন। \""],
  "12:78": ["They said: \"O Aziz, he has a father, an aged sheikh; take one of us in his place — we see you among the muhsinin.\"", "তারা বলল, \"হে উদার বাক্তি, তার একজন পিতা আছে যিনি বয়স্ক ; আপনি কি তার বদলে আমাদের একজনকে নেবেন? আমরা দেখছি যে আপনি একজন দয়ালু ব্যাক্তি।\""],
  "12:79": ["He said: \"I seek refuge in Allah that we should take anyone but him in whom we found our goods — then we would be wrongdoers.\"", "সে বলল, \"আল্লাহ না করুন যে আমরা তাকে ছাড়া অন্য কাউকে নেই যার কাছে আমরা আমাদের পন্য পেয়েছি। অন্যথায়, আমরা অন্যায়কারী হবো।\""],
  "12:80": ["So when they despaired of him, they withdrew to confer privately. The eldest of them said: \"Do you not know that your father has taken from you a pledge from Allah, and how before you fell short in Yusuf? I will not leave the land until my father permits me or Allah decides for me — and Allah is the best of deciders.\"", "যখন তারা তার মন পরিবর্তন করার বিষয়ে হতাশ হলো, তারা একত্রে পরামর্শ করলো। তাদের বয়োজ্যেষ্ঠ জন বলল, \"তোমরা কি অনুধাবন করো যে তোমাদের পিতা তোমাদের থেকে আল্লাহর সামনে একটি দৃঢ় অঙ্গীকার নিয়েছেন? অতীতে তোমরা ইউসুফকে হারিয়েছ। আমি এই স্থান ছেড়ে যাচ্ছি না যতক্ষণ না আমার পিতা আমাকে অনুমতি দেন; অথবা যতক্ষণ না আল্লাহ আমার জন্য সিদ্ধান্ত দেন; তিনি সর্বোত্তম বিচারক।"],
  "12:81": ["\"Return to your father and say: 'Father, your son stole; and we witnessed only what we knew, and we were not keepers of the ghayb.'\"", "“তোমাদের পিতার কাছে ফিরে যাও এবং তাকে বলো..."],
  "12:82": ["\"'And ask the town in which we were, and the caravan in which we came — and we are sadiq.'\"", "আপনি ঐ সম্প্রদায়কে জিজ্ঞেস করতে পারেন যেখানে আমরা ছিলাম, এবং ঐ কাফেলাকে যেটা আমাদের সাথে ফেরত এসেছে। আমরা সত্য বলছি।'"],
  "12:83": ["He said: \"No — your nafs have allured you into an affair. So, beautiful patience! Perhaps Allah will bring them to me all together. Truly Allah is the Knowing, the Wise.\"", "সে বলল, “নিশ্চয়, তোমরা চক্রান্ত করেছ একটা নির্দিষ্ট পরিকল্পনা বাস্তবায়ন করতে। নীরবে ধৈর্যধারণ আমার একমাত্র অবলম্বন। আল্লাহ যেন তাদের সকলকে আমার কাছে ফিরিয়ে আনেন। তিনি সর্বজ্ঞ, সবচেয়ে জ্ঞানী।\""],
  "12:84": ["And he turned away from them and said: \"My grief for Yusuf!\" And his eyes went white from grief; he held it in.", "সে তাদের থেকে মুখ ফিরিয়ে নিল, এ বলে যে, \"আমি ইউসুফকে নিয়ে শোক করছি।” খুব বেশি শোক করার কারনে তার চোখ সাদা হয়ে পড়েছিল; সে আসলেই দু:খ ভারাক্রান্ত ছিল।"],
  "12:85": ["They said: \"By Allah, you will not cease remembering Yusuf until you are worn to a wreck or among the perishing.\"", "তারা বলল, \"আল্লাহর শপথ, আপনি ইউসুফের জন্য শোক করতে থাকবেন যতক্ষণ না আপনি অসুস্থ হচ্ছেন, অথবা যতক্ষণ না আপনি মারা যাচ্ছেন\""],
  "12:86": ["He said: \"I pour out my anguish and my grief only to Allah, and I know from Allah what you do not know.\"", "সে বলল, \"আমি তো কেবল আল্লাহর নিকট আমার দ্বিধা-দ্বন্দ ও দুঃখের বিষয়ে অভিযোগ করি, যেহেতু আমি আল্লাহ থেকে জানি যা তোমরা জানো না।"],
  "12:87": ["\"My sons, go and seek news of Yusuf and his brother, and do not despair of the spirit of Allah — none despairs of the spirit of Allah except the committing kufr people.\"", "\"হে আমার ছেলেরা, ইউসুফ ও তার ভাইকে গিয়ে নিয়ে আসো, এবং কখনো আল্লাহর দয়া থেকে নিরাশ হয়ো না। অবিশ্বাসী লোকেরা ছাড়া আল্লাহর দয়া থেকে কেউ নিরাশ হয় না।\""],
  "12:88": ["So when they entered upon him they said: \"O Aziz, hardship has touched us and our family, and we have brought goods of little worth. So fulfil the measure for us and be charitable to us — truly Allah requites the mutasaddiqin.\"", "যখন তারা (ইউসুফের) আবাসস্থলে প্রবেশ করলো, তারা বলল, \"হে মহানুভব, আমরা অনেক কষ্ট ভোগ করেছি, আমাদের পরিবার সহ, এবং আমরা নিম্নমানের পন্য এনেছি। কিন্তু আমরা আশা করি যে আপনি পূর্ণ মাপ দিবেন এবং আমাদের প্রতি দানশীল হবেন। আল্লাহ দানশীলদের পুরষ্কৃত করেন।\""],
  "12:89": ["He said: \"Do you know what you did to Yusuf and his brother, when you were ignorant?\"", "সে বলল, \"তোমাদের কি মনে পড়ে যা তোমরা ইউসুফ ও তার ভাইয়ের সাথে করেছ যখন তোমরা অজ্ঞ ছিলে?\""],
  "12:90": ["They said: \"Are you indeed Yusuf?\" He said: \"I am Yusuf, and this is my brother. Allah has favored us. Whoever guards and is sabir — truly Allah does not lose the wage of the muhsinin.\"", "তারা বলল, \"তুমি নিশ্চয় ইউসুফ। \"সে বলল, \"আমি ইউসুফ, এবং এই হচ্ছে আমার ভাই। আল্লাহ আমাদের অনুগ্রহ করেছেন। এটা এ কারণে যে - যদি কেউ সৎকর্মশীল জীবন-যাপন করে, এবং অবিচলভাবে অধ্যবসায়ী হয়, আল্লাহ কখনো সৎকর্মশীলদের পুরষ্কৃত করতে ব্যর্থ হন না।\""],
  "12:91": ["They said: \"By Allah, Allah has preferred you over us, and we were indeed among the erring.\"", "তারা বলল, \"আল্লাহর শপথ, আল্লাহ সত্যিই তোমাকে আমাদের উপর পছন্দ করেছেন। আমরা স্পষ্টই ভুল ছিলাম।\""],
  "12:92": ["He said: \"No reproach upon you today. Allah will forgive you, and is the most merciful of the merciful.\"", "সে বলল, \"তোমাদের উপর আজকে কোন অভিযোগ নেই। আল্লাহ তোমাদের ক্ষমা করুন। সকল দয়ালুদের মধ্যে, তিনি সবচেয়ে দয়ালু।"],
  "12:93": ["\"Go with this shirt of mine and cast it on my father's face; he will come seeing. And bring me your family all together.\"", "আমার এই শার্টটি নাও; যখন তোমরা এটি আমার পিতার মুখে ছুড়বে, তার দৃষ্টিশক্তি ফিরে আসবে। তোমাদের পুরো পরিবার নিয়ে আমার কাছে ফিরে আসো। \""],
  "12:94": ["And when the caravan set out, their father said: \"I find the scent of Yusuf — were it not that you would deny me.\"", "এমনকি কাফেলা ফিরে আসার পূর্বেই, তাদের পিতা বলল, \"আমি ইউসুফের গন্ধ আচঁ করতে পারছি। কেউ কি আমাকে এই বিষয়ে জানাবে?\""],
  "12:95": ["They said: \"By Allah, you are in your old error.\"", "তারা বলল, \"আল্লাহর শপথ, আপনি এখনও আপনার পুরনো বিভ্রান্তিতে আছেন।\""],
  "12:96": ["So when the bearer of good news came, he cast it upon his face, and he returned seeing. He said: \"Did I not tell you that I know from Allah what you do not know?\"", "যখন সুসংবাদ বাহক পৌছঁলো, সে তার মুখে (শার্টটি ) নিক্ষেপ করলো, যার ফলে তার দৃষ্টি ফিরে এলো। সে বলল, \"আমি কি তোমাদের বলিনি যে আমি আল্লাহ থেকে জানতাম যা তোমরা জানতে না?”"],
  "12:97": ["They said: \"Father, ask forgiveness for us of our offenses; we were indeed among the erring.\"", "তারা বলল, \"আমাদের পিতা, আমাদের ক্ষমার জন্য প্রার্থনা করুন; সত্যিই আমরা ভুলে ছিলাম।\""],
  "12:98": ["He said: \"I will ask forgiveness for you from my Rabb; truly Allah is the Forgiving, the Raheem.\"", "তারা বলল, \"আমি তোমাদের ক্ষমার জন্য আল্লাহর কাছে মিনতি করবো; তিনি ক্ষমাকারী, সবচেয়ে দয়ালু।\""],
  "12:99": ["So when they entered upon Yusuf, he sheltered his parents with him, and said: \"Enter Riverland, if Allah wills, in safety.\"", "যখন তারা ইউসুফের আবাসস্থলে প্রবেশ করলো, সে তার পিতা-মাতার সাথে আলিঙ্গন করলো, এ বলে যে, \"মিশরে স্বাগতম, আল্লাহ চাইলে, আপনারা এখানে নিরাপদে থাকবেন।\""],
  "12:100": ["And he raised his parents onto the high-seat, and they fell down before him bowing. He said: \"Father, this is the interpretation of my vision of old; my Rabb has made it come true. And Allah has been good to me, bringing me out of the prison and bringing you from the open-land, after the satan had sown discord between me and my brothers. Truly my Rabb is subtle in whatever Allah wills; truly Allah is the Knowing, the Wise.\"", "সে তার পিতা-মাতাকে সিংহাসনের উপর উঠালো, তারা তার সামনে সেজদায় পড়লো। সে বলল, \"হে আমার পিতা, এটি আমার পুরনো স্বপ্নের পূর্ণতা। আমার প্রভু একে সত্য করেছেন। তিনি আমাকে সৌভাগ্যশালী করেছেন, আমাকে কারাগার থেকে মুক্ত করেছেন, এবং মরুভূমি থেকে তোমাদের এনেছেন, শয়তান আমার এবং আমার ভাইদের মধ্যে প্রতিবন্ধকতা সৃষ্টি করার পর।  আমার প্রভু পরম দয়ালু যার উপরই তিনি ইচ্ছা করেন। তিনি সর্বজান্তা, সর্বজ্ঞানী।”"],
  "12:101": ["\"My Rabb, You have given me of the dominion and taught me the interpretation of ahadith. Originator of the heavens and the earth — You are my guardian in the world and the Hereafter. Take me to You in submission and join me with the salihin.\"", "“আমার প্রভু, আপনি আমাকে রাজত্ব দিয়েছেন এবং আমাকে স্বপ্নের ব্যাখ্যা করা শিখিয়েছেন। আকাশমন্ডলী ও পৃথিবীর সূচনাকারী; আপনি আমার অভিভাবক এই জীবনে এবং পরকালে। আমাকে একজন আত্মসমর্পণকারী হিসেবে মৃত্যু দিন, এবং আমাকে সৎকর্মশীলদের সাথে গণনা করুন।”"],
  "12:102": ["That is of the tidings of the ghayb that We inspire to you. And you were not with them when they agreed their affair while they were scheming.", "এটি অতীতের সংবাদ যা আমরা তোমার কাছে প্রকাশ করি। তুমি উপস্থিত ছিলে না যখন তারা তাদের সর্বসম্মত সিদ্ধান্ত নিয়েছিল (ইউসুফকে কূপে ফেলতে), যখন তারা একত্রে ফন্দী এটেঁছিল।"],
  "12:103": ["And most people would not believe, though you ardently want it.", "বেশির ভাগ লোক, তুমি যা-ই করো না কেন, বিশ্বাস করবে না।"],
  "12:104": ["And you ask them no wage for it; it is nothing but a reminder for the worlds.", "তুমি তাদের কাছে কোন অর্থ চাচ্ছ না; তুমি কেবলমাত্র এই স্মারক সকল লোকদের জন্য পৌঁছে দাও।"],
  "12:105": ["And how many an aya in the heavens and the earth they pass by, while they turn away from it.", "আকাশমন্ডলী ও পৃথিবীতে অনেক প্রমানাদি তাদেরকে দেয়া হয়েছে, কিন্তু তারা সেগুলো পিছনে ফেলে যায়, অমনোযোগী হয়ে!"],
  "12:106": ["And most of them do not believe in Allah except while they are associators.", "যারা আল্লাহতে বিশ্বাস করে তাদের অধিকাংশই অংশীদার উপাসনা করা ছাড়া তা করে না।"],
  "12:107": ["Do they feel secure that a covering of Allah's punishment may come upon them, or that the Hour may come to them suddenly while they perceive not?", "তারা কি নিশ্চয়তা পেয়েছে যে আল্লাহ থেকে কোন বিধ্বংসী শাস্তি তাদের আঘাত করবে না, অথবা সেই ঘণ্টা হঠাৎ করেই তাদের কাছে আসবে না, যখন তারা খুব অল্পই এর প্রত্যাশা করে?"],
  "12:108": ["Say: \"This is my way — I call to Allah upon clear sight, I and whoever follows me. And glory be to Allah; and I am not among the associators.\"", "বল, \"এটা আমার পথ: আমি আল্লাহর দিকে আহবান করি, একটি স্পষ্ট প্রমানের ভিত্তিতে, এবং তারাও তা-ই করে যারা আমার অনুসরণ করে। মহিমা আল্লাহর। আমি কোন প্রতিমা উপাসক নই।\""],
  "12:109": ["And We sent before you none but men, whom We inspired, from the people of the towns. Have they not journeyed in the land to see how was the outcome of those before them? And the abode of the Hereafter is better for those who were ever guarding. Will you not then reason?", "আমরা তোমার আগে মানুষ ছাড়া কারো কাছে অনুপ্রেরনা দিয়ে পাঠাইনি, বিভিন্ন সম্প্রদায়ের লোক থেকে পছন্দকৃত। তারা কি পৃথিবীতে ঘুড়ে বেড়ায়নি এবং তাদের পূর্বেকার লোকদের পরিণাম দেখেনি। পরকালের আবাস অনেক উত্তম তাদের জন্য যারা সৎকর্মশীল জীবন যাপন করে। তবে কি তোমরা বুঝবে?"],
  "12:110": ["Until, when the Rasuls despaired and supposed they had been denied, Our help came to them, and We saved whom We wished. And Our might is not turned back from the mujrim people.", "ঠিক যখন বার্তাবাহকরা হতাশ হয়, এবং মনে করে যে তাদের প্রত্যাখ্যান করা হয়েছে, আমাদের বিজয় তাদের কাছে আসে। আমরা এরপর রক্ষা করি যাকে আমরা পছন্দ করি, যখন অপরাধী লোকদের জন্য আমাদের শাস্তি অনিবার্য।"],
  "12:111": ["Truly in their narratives is a lesson for people of understanding. It is no invented hadith, but a confirmation of what is before it, and a detailing of everything, and guidance and mercy for a people who believe.", "তাদের ইতিহাসে, তাদের জন্য শিক্ষা রয়েছে যারা বুদ্ধিমত্তার অধিকারী। এটি মিথ্যা উদ্ভাবিত হাদীস নয়; এটি (কুরআন) সুনিশ্চিত করে পূর্ববর্তী সকল ঐশীগ্রন্থ, সবকিছু সবিস্তারে প্রদান করে,এবং এক আলোকবর্তিকা এবং দয়া তাদের জন্য যারা বিশ্বাস করে।"],
  "13:1": ["Alif Lam Mim Ra. Those are the ayat of the Kitab, and what has been sent down to you from your Rabb is the truth, but most people do not believe.", "অ ল ম র। এই (বর্ণ) গুলো এই ঐশীগ্রন্থের প্রমাণ। তোমার প্রভুর পক্ষ থেকে তোমার কাছে যা অবতীর্ণ হয়েছে তা সত্য, কিন্তু বেশির ভাগ মানুষ বিশ্বাস করে না।"],
  "13:2": ["Allah is the one who raised up the heavens without pillars that you can see, then steadied upon the high seat, and subjected the sun and the moon, each running for an appointed term. Allah manages the whole affair and distinguishes the ayat, so that you may be certain of meeting your Rabb.", "আল্লাহই সেই সত্ত্বা যিনি আকাশমন্ডলীকে খুঁটি ছাড়া তুলে ধরেছেন, যা তোমরা দেখতে পাও, এরপর সকল কর্তৃত্ব গ্রহন করেছেন। তিনি সূর্য এবং চাঁদকে নিয়োজিত করেছেন, প্রত্যেকে (এর কক্ষপথে) একটি পূর্বনির্ধারিত সময় পর্যন্ত ঘুরছে। তিনি সবকিছু নিয়ন্ত্রন করেন, এবং প্রকাশনাবলি ব্যাখ্যা করেন, যাতে তোমরা তোমাদের প্রভুর সাথে সাক্ষাতের ব্যাপারে নিশ্চয়তা অর্জণ করতে পারো।"],
  "13:3": ["And Allah is the one who spread out the earth and placed in it anchors and rivers, and of every fruit made in it two pairs. The night covers the day. Indeed in that are ayat for people who reflect.", "তিনিই সে সত্ত্বা যিনি পৃথিবী নির্মান করেছেন এবং এর উপর স্থাপন করেছেন পর্বতমালা এবং নদীসমূহ।এবং বিভিন্ন ধরনের ফল থেকে, তিনি এদের জোড়ায় তৈরী করেছেন- পুরুষ ও স্ত্রী-জাতিয়। রাত ছাড়িয়ে যায় দিনকে। এগুলো দৃড় প্রমান তাদের জন্য যারা চিন্তা করে।"],
  "13:4": ["In the earth are adjoining plots, and gardens of grapes and crops, and palms twinned and not twinned, all given to drink with one water, yet some are favored above others in food. Indeed in that are ayat for people who understand.", "পৃথিবীতে, সন্নিহিত জমি রয়েছে যা উৎপন্ন করে আংগুরের বাগান, খাদ্যশস্য, খেঁজুর গাছ- এক লিংঙ্গধারী এবং উভলিংঙ্গধারী। যদিও তাদের একই পানি দিয়ে সেচ দেয়া হয়, আমরা এদের কতগুলোকে অন্যগুলোর চাইতে খাওয়ার জন্য উন্নততর করি। এগুলো জোড়ালো প্রমান সেসব লোকদের জন্য যারা বুঝে।"],
  "13:5": ["And if you marvel, then marvel at their saying: \"When we are dust, are we then in a new-made creation?\" Those are the ones who disbelieved in their Rabb; and those are the fetters upon their necks; and those are the companions of the fire. They abide in it forever.", "যদি তুমি কখনও আশ্চর্য হও, তবে প্রকৃত আশ্চর্যের বিষয় হচ্ছে তাদের কথা: “আমরা ধূলায় পরিনত হবার পর, আমরা কি আবার নতুন করে সৃষ্টি হবো?”এরা সেই ব্যক্তি যারা তাদের প্রভুকে অবিশ্বাস করেছে। এরা সেই ব্যক্তি যারা তাদের গলায় টেনে এনেছে জড়ানো শিকল। এরা সেই ব্যক্তি যারা নরক টেনে এনেছে, যেখানে তারা চিরকাল বাস করে।"],
  "13:6": ["They ask you to hasten the bad before the good, though examples like them have passed before. And indeed your Rabb is forgiving to people despite their wrongdoing, and indeed your Rabb is severe in punishment.", "তারা তোমাকে তাদের উপর ধ্বংস আনার চ্যালেঞ্জ করে, সৎকর্মশীল হবার বদলে। অতীতে তাদের জন্য যথেষ্ট দৃষ্টান্ত স্থাপন করা হয়েছে। প্রকৃতপক্ষে, তোমাদের প্রভু লোকদের প্রতি ক্ষমায় পূর্ণ, তাদের সীমালঙ্ঘন সত্ত্বেও, এবং তোমাদের প্রভু শাস্তি আরোপেও কঠোর।"],
  "13:7": ["Those who disbelieve say: \"Why has no aya been sent down to him from his Rabb?\" You are only a warner, and every people has a guide.", "যারা অবিশ্বাস করেছিল তারা বলল, \"শুধু যদি একটি অলৌকিকতা তাঁর প্রভুর পক্ষ থেকে তার কাছে আসত (তবে আমরা বিশ্বাস করতাম)। তুমি কেবল একজন সতর্ককারী - প্রত্যেক সম্প্রদায় একজন পথ-প্রদর্শক শিক্ষক পায়।"],
  "13:8": ["Allah knows what every female carries, and what the wombs fall short of and what they increase, and everything with Allah is by measure.", "আল্লাহ জানেন প্রত্যেক নারী কি বহন করে, এবং প্রত্যেক জরায়ু কি ছেড়ে দেয়, বা অর্জন করে। যা তিনি করেন তা যথাযথভাবে পরিমাপকৃত।"],
  "13:9": ["Knower of the hidden and the witnessed, the Great, the Most High.", "সকল গোপনীয়তা এবং প্রকাশিত বিষয়ের জ্ঞাতা; সর্বপ্রধান, সর্বোচ্চ।"],
  "13:10": ["Alike among you are one who conceals the word and one who proclaims it openly, and one who is hidden by night and one who moves openly by day.", "তুমি তোমার ভাবনাগুলো গোপন, বা প্রকাশ করো, কিংবা রাতের অন্ধকারে লুকাও, অথবা দিনের আলোয় কাজ করো তা একই।"],
  "13:11": ["There are successive guardians before each person and behind, guarding by Allah's command. Indeed Allah does not change what is with a people until they change what is with themselves. And when Allah wills ill for a people, there is no turning it back, and they have no protector besides Allah.", "পালাক্রমে (ফেরেশতারা) অবস্থান নিয়ে; তোমাদের প্রত্যেকের সাথে থাকছে-তারা আছে তোমাদের সামনে এবং তোমাদের পেছনে। তারা তোমাদের সঙ্গে থাকে, এবং তোমাদের পাহারা দেয় আল্লাহর হুকুম অনুসারে। সুতরাং, আল্লাহ কোন লোকের অবস্থা পরিবর্তন করেন না যদিনা তারা নিজেরা পরিবর্তনের সিদ্ধান্ত নেয়। যদি আল্লাহ কোন লোকের জন্য কোন কষ্ট চান, কোন শক্তি তা থামাতে পারে না। কারন তাঁর পাশে তাদের কোনো প্রভু এবং মনিব নেই।"],
  "13:12": ["It is Allah who shows you the lightning, in fear and in hope, and raises the heavy clouds.", "তিনিই সেই সত্ত্বা যিনি তোমাদের বিদ্যুৎ চমক দেখান ভয়ের উৎস হিসেবে, সেই সাথে আশার উৎস হিসেবে, এবং তিনি পুঞ্জিভূত মেঘের সূচনা করেন।"],
  "13:13": ["And the thunder proclaims Allah's praise, and the malakat do so from awe, and Allah sends the thunderbolts, striking with them whom Allah wills — while they dispute about Allah, and Allah is severe in power.", "বজ্র তাঁর মহিমার প্রশংসা করে, এবং ফেরেশতারাও, তাঁর প্রতি ভক্তি থেকে। তিনি বজ্রপাত ঘটান, যা তাঁর ইচ্ছা অনুসারে আঘাত করে। এরপরও, তারা আল্লাহর ব্যাপারে তর্ক করে, যদিও তাঁর ক্ষমতা ভীষন।"],
  "13:14": ["To Allah belongs the call of truth. Those they call upon besides Allah answer them with nothing, any more than one who stretches out his palms toward the water so that it may reach his mouth, but it never reaches it. And the call of the kafirin is only in straying.", "তাঁর কাছে চাওয়াই একমাত্র বৈধ মিনতি, যেখানে তাঁর পাশে যেসব উপাস্যদের তারা মিনতি করে, তারা কখনো ডাকে সাড়া দিতে পারে না। সুতরাং, তারা ওদের মতো যারা পানির দিকে হাত বাড়ায়, কিন্তু তাদের মুখে কিছুই পৌঁছে না। অবিশ্বাসীদের মিনতি নিরর্থক।"],
  "13:15": ["And to Allah bows whoever is in the heavens and the earth, willingly and unwillingly, and their shades in the mornings and the late afternoons.", "আল্লাহকে সেজদা করে আকাশমণ্ডলী এবং পৃথিবীর সকলে, স্বেচ্ছায় অথবা অনিচ্ছায়, এবং তাদের ছায়াও তা করে সকালে এবং সন্ধ্যায়।"],
  "13:16": ["Say: who is the Rabb of the heavens and the earth? Say: Allah. Say: have you taken protectors besides Allah who own for themselves no benefit and no harm? Say: are the unseeing and the seeing equal, or are the darknesses and the light equal? Or have they made for Allah associates who create as Allah creates, so that creation is alike to them? Say: Allah created everything, and Allah is the One, the Overpowering.", "বল, “আকাশমণ্ডলী এবং পৃথিবীর প্রভু কে?”বল, “আল্লাহ।”বল, “তাহলে কেন তোমরা তাঁর পাশে মনিব স্থাপন করো, তাদেরকে, যারা এমনকি তাদের নিজেদেরও উপকার অথবা ক্ষতি করার কোন ক্ষমতা রাখে না?”বল, “অন্ধ কি চক্ষুষ্মানের সমান? অন্ধকার কি আলোর সমান?”তারা কি আল্লাহর পাশে এমন উপাস্যদের পেয়েছে যারা তাঁর সৃষ্টির অনুরুপ সৃষ্টি করেছে, এমনভাবে যে দুটো সৃষ্টিকে আলাদা করা যায় না? বল, “আল্লাহ সকল বস্তুর সৃষ্টিকর্তা, এবং তিনিই এক, সর্বোচ্চ।"],
  "13:17": ["Allah sent down water from the heaven, and valleys flowed by their measure, and the flood carried swelling foam. And from what they kindle in the fire, seeking adornment or goods, comes foam like it. Thus Allah strikes the truth and the falsehood: as for the foam, it passes away as scum, and as for what benefits people, it stays in the earth. Thus Allah strikes the examples.", "তিনি আকাশ থেকে পানি বর্ষণ করে, উপত্যকাগুলোকে প্লাবিত করেন, এরপর স্রোতধারা প্রচুর ফেনা উৎপাদন করে। একইভাবে, তারা যখন তাদের অলঙ্কার বা সরঞ্জামাদির জন্য ধাতু পরিশোধন করতে আগুন ব্যবহার করে, ফেনা উৎপা্দিত হয়। আল্লাহ এভাবে সত্য ও মিথ্যার উপমা দেন। ফেনার ক্ষেত্রে, এটা আবর্জনা হয়ে যায়, যেখানে লোকদের যা উপকারে আসে তা মাটির কাছে থাকে। আল্লাহ এভাবে উপমা দেন।"],
  "13:18": ["For those who answered their Rabb, the fairest reward; and those who did not answer — if they had all that is in the earth and its like with it, they would ransom themselves with it. Those have the evil reckoning, and their destination is hell, and wretched is the couch.", "যারা তাদের প্রভুর ডাকে সাড়া দেয় তারা ভাল পুরস্কারের যোগ্য। আর তাদের ক্ষেত্রে যারা তাঁর ডাকে সাড়া দিতে ব্যর্থ হল, যদি তারা পৃথিবীর সবকিছু অধিকার করে-এমনকি দিগুন পরিমান- তারা তৎক্ষণাৎ তা মুক্তিপণ হিসেবে দিয়ে দেবে। তারা নিকৃষ্টতম হিসাব টেনে এনেছে, এবং তাদের চূড়ান্ত বাসস্থান নরক; কি এক শোচনীয় ভাগ্য।"],
  "13:19": ["Is one who knows that what was sent down to you from your Rabb is the truth like one who is unseeing? Only those of understanding take heed.", "যে ব্যক্তি তোমার প্রতি তোমার প্রভুর প্রকাশনাবলি চিনতে পারে সে কি তার সমান যে অন্ধ? শুধু যারা বুদ্ধিমত্তার অধিকারী তারা মনোযোগ দেবে।"],
  "13:20": ["Those who fulfill the pledge of Allah and do not unbind the pact.", "তারাই সেসব লোক যারা আল্লাহর সাথে তাদের অঙ্গীকার পূর্ণ করে, এবং অঙ্গীকার ভঙ্গ করে না।"],
  "13:21": ["And those who join what Allah commanded to be joined, and hold reverent awe of their Rabb, and fear the evil reckoning.", "তারা তাতে যোগ দেয় যাতে আল্লাহ যোগ দিতে আদেশ করেছেন, তাদের প্রভুকে ভক্তি করে, এবং সেই ভয়ানক হিসাব গ্রহনকে ভয় করে।"],
  "13:22": ["And those who were sabir seeking the face of their Rabb, and established the prayer, and spent from what was provided to them secretly and openly, and ward off the bad with the good — those have the best end of the home.", "তাদের প্রভুর অন্বেষণে তারা দৃঢ়তার সাথে অধ্যবসায়ী, সংযোগ প্রার্থনাসমূহ (সালাত) পালন করে, তাদেরকে দেয়া আমাদের খাদ্যসম্ভার থেকে ব্যয় করে গোপনে এবং প্রকাশ্যে, এবং ভালো দিয়ে মন্দকে প্রতিহত করে। তারা সর্বোত্তম বাসস্থানের যোগ্য হয়েছে।"],
  "13:23": ["Gardens of Eden, which they enter, together with those of their fathers, their zawj, and their descendants who were right — and the malakat enter upon them from every door.", "তারা ইডেনের বাগানগুলোতে প্রবেশ করে, তাদের পিতামাতা, তাদের জীবনসঙ্গি, এবং তাদের সন্তানদের মধ্য থেকে সৎ-কর্মীদের সাথে, একত্রে। ফেরেশতারা তাদের কাছে প্রবেশ করবে প্রত্যেক দরজা দিয়ে।"],
  "13:24": ["Peace upon you for what you were sabir with; and how good is the end of the home.", "“তোমাদের উপর শান্তি বর্ষিত হোক, কারন তোমরা দৃঢ়তার সাথে অধ্যবসায়ী ছিলে। কি এক আনন্দদায়ক নিয়তি”।"],
  "13:25": ["And those who unbind the pledge of Allah after its pact, and sever what Allah commanded to be joined, and do corruption in the earth — those have the curse, and they have the evil of the home.", "আর তাদের ক্ষেত্রে যারা আল্লাহর অঙ্গীকার লঙ্ঘন করে, তা রক্ষা করার অঙ্গীকার করার পর, এবং ছিন্ন করে, যাতে আল্লাহ যুক্ত থাকতে হুকুম করেছেন, এবং দুষ্কর্ম করে বেড়ায়, তারা টেনে এনেছে দন্ডাদেশ; তারা টেনে এনেছে নিকৃষ্টতম নিয়তি।"],
  "13:26": ["Allah spreads out provision for whom Allah wills and restricts it, and they rejoiced in the nearer life — but the nearer life, compared to the final life, is only a passing enjoyment.", "আল্লাহ সেই সত্ত্বা যিনি যার জন্য ইচ্ছা জীবিকা বাড়িয়ে দেন, অথবা তা থামিয়ে রাখেন। তারা এই জীবনে আচ্ছন্ন হয়ে আছে, এবং এই জীবন, পরকালের তুলনায়, কিছুই না।"],
  "13:27": ["Those who disbelieve say: \"Why has no aya been sent down to him from his Rabb?\" Say: Allah lets stray whom Allah wills, and guides to Allah whoever turns back.", "যারা অবিশ্বাস করে তারা বলবে, “যদি শুধু একটি অলৌকিকতা তার কাছে আসতো তার প্রভুর পক্ষ থেকে (তবে আমরা বিশ্বাস করতাম)”। বল, “আল্লাহ যাকে ইচ্ছা পথভ্রষ্ট করেন, এবং শুধু তাদেরকে তাঁর দিকে পথ-প্রদর্শন করেন যারা মান্য করে।"],
  "13:28": ["Those who believed, and whose hearts are settled by the remembrance of Allah — indeed, by the remembrance of Allah are hearts settled.", "তারা সেসব লোক যাদের হৃদয় উল্লসিত হয়, আল্লাহর স্মরণে। নিঃসন্দেহে, আল্লাহর স্মরণে, হৃদয় উল্লসিত হয়।"],
  "13:29": ["Those who believed and did the salihin deeds — blessedness for them, and a goodly return.", "যারা বিশ্বাস করে এবং সৎ জীবন যাপন করে তারা অর্জন করেছে সুখ এবং এক আনন্দদায়ক নিয়তি।"],
  "13:30": ["Thus We sent you to a people before whom other peoples passed, so that you may recite to them what was revealed to you, while they disbelieve in the Rahman. Say: my Rabb is Allah; there is no ilah but Allah; upon Allah I trust, and to Allah is my return.", "আমরা তোমাকে পাঠিয়েছি (হে রাশাদ) এই জাতির কাছে, ঠিক যেমন অতীতে আমরা অন্য জাতির জন্য করেছিলাম। তুমি তাদের কাছে আবৃত্তি করবে যা আমরা তোমার কাছে প্রকাশ করি, কারন তারা পরম করুনাময়ে অবিশ্বাস করেছে। বল, “তিনি আমার প্রভু। তিনি ছাড়া কোন উপাস্য নাই। আমি শুধু তার প্রতি আমার আস্থা রাখি; তার কাছেই আমার চূড়ান্ত নিয়তি।"],
  "13:31": ["And if there were a recitation by which the mountains were set moving, or the earth cleft, or the dead spoken to — rather, to Allah belongs the whole affair. Have those who believed not despaired that if Allah willed, Allah would guide all people? And those who disbelieve will not cease: the striking will befall them for what they made, or alight near their home, until the promise of Allah comes. Indeed Allah does not break the appointment.", "এমনকি কোন কুরআন যদি পাহাড়কে চালিত করে, বা পৃথিবীকে দুই ভাগে বিভক্ত করে দেয়, বা মৃতকে দিয়ে কথা বলায় (তবুও তারা বিশ্বাস করবে না)। আল্লাহ সকল বস্তু নিয়ন্ত্রন করেন। এখনও কি বিশ্বাসীদের জন্য সময় হয় নি চেষ্টা পরিত্যাগ করার এবং এটা অনুধাবন করার যে যদি আল্লাহ চাইতেন, তিনি সকল মানুষকে পথ প্রদর্শন করতে পারতেন? অবিশ্বাসীরা দুর্দশা ভোগ করতে থাকবে, তাদের নিজেদের কাজের পরিণামে, অথবা তাদের কাছেই দুর্দশা আঘাত করবে, যতক্ষন না আল্লাহর অঙ্গীকার পূর্ণ হয়। আল্লাহ কখনোই পূর্বনির্ধারিত নিয়তি পরিবর্তন করেন না।"],
  "13:32": ["And rusul before you were mocked, and I gave respite to those who disbelieved, then I seized them — and how was the punishment!", "তোমার পূর্বেও বার্তাবাহকদের উপহাস করা হয়েছে; আমি অবিশ্বাসীদের চালিয়ে যেতে দিয়েছি, এরপর আমি তাদের শাস্তি দিয়েছি। কেমন ভয়ানক ছিল আমার শাস্তি!"],
  "13:33": ["Is the one who stands over every nafs for what it earned...? And they made for Allah associates. Say: name them! Or do you inform Allah of something Allah does not know on the earth, or is it manifest talk? Rather, their plan was made attractive to those who disbelieved, and they barred from the way. And whomever Allah lets stray has no guide.", "সেই সত্ত্বার সমান কি কিছু আছে যিনি প্রত্যক আত্মা নিয়ন্ত্রন করেন? এরপরও, তারা আল্লাহর সাথে প্রতিদ্বন্দ্বিতা করতে উপাস্য স্থাপন করে। বল, “তাদের নাম বলো, তোমরা কি পৃথিবীর কোনকিছুর বিষয়ে তাঁকে জানাচ্ছ যা তিনি জানেন না? নাকি, তোমরা ফাকা বুলি রচনা করছো? নিশচয়, যারা অবিশ্বাস করে তাদের চক্রান্ত তাদের চোখে সাজিয়ে দেয়া হয়েছে। তারা এভাবে সঠিক পথ থেকে বিচ্যুত হয়। যাকে আল্লাহ পথভ্রষ্ট করেন সে কখনই কোন পথপ্রদর্শক শিক্ষক পায় না।"],
  "13:34": ["They have punishment in the nearer life, and the punishment of the final life is harder, and they have none to shield them from Allah.", "তারা এই জীবনে শাস্তি টেনে এনেছে, এবং পরকালের শাস্তি আরো অনেক নিকৃষ্ট। আল্লাহর বিরুদ্ধে কোন কিছুই তাদের রক্ষা করতে পারে না।"],
  "13:35": ["The likeness of the garden promised to the muttaqin: rivers flow beneath it, its food is everlasting, and its shade. That is the end of those who were mindful, and the end of the kafirin is the fire.", "স্বর্গ, যা সৎকর্মশীলদের জন্য অঙ্গীকার করা হয়, তার উপমা হল প্রবাহিত ঝর্ণা, অফুরন্ত খাদ্যসম্ভার, এবং শীতল ছায়া। তাদের জন্য এমনই ভাগ্য যারা সৎকর্মপরায়নতা বজায় রাখে, যেখানে অবিশ্বাসীদের ভাগ্য নরক।"],
  "13:36": ["Those whom We gave the Kitab rejoice in what was sent down to you, and among the parties are those who disavow some of it. Say: I was only commanded to serve Allah and not to associate anything with Allah; to Allah I call, and to Allah is the return.", "যারা ঐশীগ্রন্থ পেয়েছে তারা তাতে উল্লসিত হয় যা তোমার কাছে প্রকাশিত হয়েছে। অন্যদের কেউ কেউ হয়তো এর কিছু অংশ প্রত্যাখ্যান করে। বল, “আমাকে তো কেবল আদেশ করা হয়েছে আল্লাহর উপাসনা করতে, এবং কখনো তাঁর সাথে অন্যকোন উপাস্য যুক্ত না করতে। আমি তাঁর দিকে আমন্ত্রন জানাই, এবং তাঁর দিকেই আমার চূড়ান্ত নিয়তি।"],
  "13:37": ["And thus We sent it down as a clear Arabic ruling. If you were to follow their desires after the knowledge that came to you, you would have from Allah neither protector nor shield.", "আমরা এই আইনগুলো আরবিতে প্রকাশ করেছি, এবং যদি তুমি কখনো তাদের ইচ্ছায় সম্মত হও, এই জ্ঞান তোমার কাছে আসার পর, তবে আল্লাহর বিরুদ্ধে তোমার কোন মিত্র থাকবে না, না কোন রক্ষাকারী।"],
  "13:38": ["And We sent rusul before you, and We made for them zawj and descendants. It is not for a Rasul to bring an aya except by Allah's leave. For every term is a written record.", "আমরা তোমার আগে বার্তাবাহক পাঠিয়েছি (হে রাশাদ), এবং আমরা তাদেরকে স্ত্রী-সন্তান সহ স্বামী বানিয়েছি। কোন বার্তাবাহক অলৌকিকতা তৈরি করতে পারে না, আল্লাহর অনুমোদন, এবং একটি সুনির্দিষ্ট, পূর্বনির্ধারিত সময়ানুসারে ব্যতীত।"],
  "13:39": ["Allah effaces what Allah wills and confirms, and with Allah is the mother of the Kitab.", "আল্লাহ মুছে দেন যা তিনি চান, এবং ঠিক করে দেন। তাঁর কাছেই রয়েছে প্রকৃত মূল নথি/রেকর্ড।"],
  "13:40": ["Whether We show you some of what We promise them, or We take you — upon you is only the delivery, and upon Us is the reckoning.", "যদি আমরা তোমাকে দেখাই যা আমরা তাদেরকে অঙ্গীকার করেছি, অথবা তোমার জীবন তার আগেই শেষ করে দেই, তোমার একমাত্র উদ্দেশ্য (বার্তা) প্রদান করা। আমরাই তাদেরকে হিসাবের জন্য ডাকবো।"],
  "13:41": ["Have they not seen that We come to the land, diminishing it from its edges? And Allah judges; none can reverse the judgment, and Allah is swift in the reckoning.", "তারা কি দেখে না যে পৃথিবীর প্রতিটি দিন, তাদেরকে সমাপ্তির কাছে নিয়ে যায়, এবং আল্লাহ তাদের জীবনের ব্যপ্তি নির্ধারণ করেন, অপরিবর্তনীয় ভাবে? তিনি সবচেয়ে দক্ষ হিসাব গ্রহণকারী।"],
  "13:42": ["Those before them planned, but to Allah belongs all the planning. Allah knows what every nafs earns, and the kafirin will know whose is the end of the home.", "তাদের পূর্বে অন্যরাও চক্রান্ত করেছে, কিন্তু আল্লাহর অধীনেই রয়েছে চূড়ান্ত চক্রান্ত। তিনি জানেন  প্রত্যেকে কি করছে। অবিশ্বাসীরা দেখবে কারা চূড়ান্ত বিজয়ী।"],
  "13:43": ["Those who disbelieve say: \"You are not mursal.\" Say: \"Allah is sufficient as a witness between me and you, and whoever has knowledge of the Kitab.\"", "যারা অবিশ্বাস করেছিল তারা বলবে, “তুমি কোন বার্তাবাহক নও!” বল, “তোমাদের এবং আমার মাঝে সাক্ষী হিসাবে যথেষ্ট, আল্লাহ এবং যারা ঐশীগ্রন্থের জ্ঞান রাখে”।"],
  "14:1": ["Alif Lam Ra. A Kitab We have sent down to you, so that you may bring the people out from darkness into light, by the leave of their Rabb, to the path of the Almighty, the Praised.", "অ.ল.র। একটি ঐশীগ্রন্থ যা আমরা তোমার কাছে প্রকাশ করেছি, লোকদের অন্ধকার থেকে আলোতে পরিচালিত করার জন্য- তাদের প্রভুর ইচ্ছানুসারে- সর্বশক্তিমান, প্রশংসনীয়-এর পথে।"],
  "14:2": ["Allah — to whom belongs whatever is in the heavens and whatever is in the earth; and woe to the rejecters from a severe punishment.", "আল্লাহ (-এর পথ) ; সেই সত্ত্বা যিনি আকাশমন্ডলীর সবকিছু এবং পৃথিবীর সবকিছুর অধিকারী। অবিশ্বাসীদের জন্য দু:খ; তারা এক ভয়ানক শাস্তি টেনে এনেছে।"],
  "14:3": ["Those who love the nearer life over the later one, and bar from the path of Allah and seek to make it crooked — those are in far error.", "তারাই সে লোক যারা পরকালের উপর এই জীবনকে প্রাধান্য দেয়, আল্লাহর পথে বাঁধা দেয়, এবং একে বাঁকা করার পথ খোঁজে; এরা বহুদূর পথভ্রষ্ট হয়েছে।"],
  "14:4": ["We sent no Rasul except in the tongue of his people, to make things clear to them; then Allah leads astray whomever Allah wills, and guides whomever Allah wills — and Allah is the Almighty, the Wise.", "আমরা কোন বার্তাবাহককে পাঠাইনি তার লোকদের ভাষায় (ধর্ম-প্রচার করার জন্য) ছাড়া, তাদের জন্য বিষয়াদি পরিষ্কার করতে। আল্লাহ এরপর পথভ্রষ্ট করেন যাকে তিনি ইচ্ছা করেন, এবং পথ-প্রদর্শণ করেন যাকে তিনি ইচ্ছা করেন। তিনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "14:5": ["We sent Musa with Our ayat: \"Bring your people out of the darkness into the light, and remind them of the days of Allah.\" Truly in that are ayat for every steadfast, grateful one.", "এভাবে, আমরা মুসাকে আমাদের অলৌকিকতা দিয়ে পাঠিয়েছিলাম, এ বলে যে, \"তোমার লোকদের অন্ধকার থেকে আলোতে পরিচালনা করো, এবং তাদেরকে আল্লাহর দিনগুলো স্মরণ করাও।”এগুলো প্রত্যেক অবিচল, কৃতজ্ঞ লোকের জন্য শিক্ষা।"],
  "14:6": ["And when Musa said to his people: \"Remember Allah's favor upon you, when Allah saved you from the house of Fir'awn, who afflicted you with the worst of punishment, slaughtering your sons and sparing your nisa; and in that was a great test from your Rabb.", "স্মরণ করো যে মুসা তার লোকদের বলেছিল, \"তোমাদের উপর আল্লাহর অনুগ্রহ স্মরণ করো। তিনি তোমাদের রক্ষা করেছিলেন ফেরাউনের লোকদের থেকে যে তোমাদের উপর নির্মম অত্যাচার চালাতো, তোমাদের পুত্রদের হত্যা করতো এবং কন্যাদের ছেড়ে দিতো। সেটা ছিল তোমাদের প্রভুর পক্ষ থেকে এক কঠোর পরীক্ষা।\""],
  "14:7": ["And when your Rabb proclaimed: \"If you give thanks, I will surely increase you; and if you reject, truly My punishment is severe.\"", "তোমাদের প্রভু আদেশ করেছেন, \"যত বেশি তোমরা আমাকে ধন্যবাদ দাও, তত বেশি আমি তোমাদের প্রদান করি।”কিন্তু যদি তোমরা অকৃতজ্ঞ হয়ে পড়ো, তাহলে আমার শাস্তি কঠোর।"],
  "14:8": ["And Musa said: \"If you reject — you and all who are in the earth together — truly Allah is Rich, Praised.\"", "মুসা বলল, \"যদি তোমরা অবিশ্বাস করো, পৃথিবীর সকল লোকদের সাথে, আল্লাহর কোনকিছু্র প্রয়োজন নেই, প্রশংসনীয়। \""],
  "14:9": ["Has the news not come to you of those before you — the people of Nuh, and Ad, and Thamud, and those after them whom none knows but Allah? Their rusul came to them with clear proofs, but they thrust their hands into their mouths and said: \"We reject what you have been sent with, and we are in restless doubt about what you call us to.\"", "তোমরা কি তোমাদের পূর্বে তাদের সম্পর্কে শোননি - নুহ, আদ, সামুদের লোক, এবং অন্যরা যারা তাদের পরে এসেছে এবং যাদেরকে শুধু আল্লাহই জানেন? তাদের বার্তাবাহকরা তাদের কাছে সুস্পষ্ট প্রমাণাদি নিয়ে গিয়েছিল, কিন্তু তারা তাদের অবমাননা করেছিল এবং বলেছিল, \"যা দিয়ে তোমাদের পাঠানো হয়েছে আমরা তা অবিশ্বাস করি; আমরা তোমাদের বার্তার বিষয়ে সংশয়বাদী ; সন্দেহে পরিপূর্ণ। \""],
  "14:10": ["Their rusul said: \"Can there be doubt about Allah, the Originator of the heavens and the earth, who calls you to forgive you part of your offenses and to defer you to a named term?\" They said: \"You are only humans like us; you want to bar us from what our fathers used to serve. So bring us a clear warrant.\"", "তাদের বার্তাবাহকরা বলল, “তোমাদের কি আল্লাহর বিষয়ে সন্দেহ আছে; আকাশমন্ডলী ও পৃথিবীর সূচনাকারী?   তিনি তোমাদের আমন্ত্রন করেন শুধু তোমাদের পাপ ক্ষমা করে দিতে, এবং তোমাদের নিজেদের পাপমুক্ত করার জন্য আরেকটি সুযোগ  দিতে।” তারা বলল, “তোমরা আমাদের মত মানুষ ছাড়া আর কিছু নও, যারা আমাদের মাতা-পিতার করে যাওয়া উপাসনার পথ থেকে আমাদের সরিয়ে দিতে চায়। আমাদের কিছু সুস্পষ্ট কর্তৃত্ব দেখাও।’’"],
  "14:11": ["Their rusul said to them: \"We are only humans like you, but Allah favors whomever Allah wills among Allah's servants; and it was not for us to bring you a warrant except by Allah's leave. And upon Allah let the muminin rely.\"", "তাদের বার্তাবাহকরা তাদের বলেছিল, “আমরা তোমাদের মত মানুষ ছাড়া কিছু নই, কিন্তু আল্লাহ অনুগ্রহ করেন তাঁর বান্দাদের মধ্য থেকে যাকে তিনি পছন্দ করেন। আমরা সম্ভবত তোমাদেরকে কোন ধরণের কর্তৃত্ব দেখাতে পারবো না, আল্লাহর ইচ্ছানুযায়ী ব্যতীত। আল্লাহর প্রতি বিশ্বাসীদের আস্থা রাখা উচিত।"],
  "14:12": ["\"And what reason do we have not to rely upon Allah, when Allah has guided us our paths? And we shall surely endure sabirly whatever harm you do us; and upon Allah let the reliant rely.\"", "\"কেন আমরা আল্লাহর প্রতি আস্থা রাখবো না, যখন তিনি আমাদের পথসমূহে আমাদেরকে পরিচালিত করেছেন? আমরা তোমার নির্যাতনের মুখে দৃড়তার সাথে  অবিচল থাকবো। আল্লাহর প্রতি সকল আস্থাকারীদের আস্থা রাখা উচিত।\""],
  "14:13": ["And those who rejected said to their rusul: \"We will surely drive you out of our land, unless you return to our way.\" Then their Rabb revealed to them: \"We will surely destroy the wrongdoers.\"", "যারা অবিশ্বাস করেছিল তারা তাদের বার্তাবাহকদের বলল, “তোমাদেরকে আমরা আমাদের ভূমি থেকে বের করে দেবো, যদি না তোমরা আমাদের ধর্মে ফিরে আসো।” তাদেরকে তাদের প্রভু অনুপ্রেরণা দিলেন: \"আমরা অবশ্যই সীমালঙ্ঘনকারীদের ধ্বংস করবো।"],
  "14:14": ["\"And We will surely settle you in the land after them. That is for whoever fears My standing and fears My threat.\"", "\"এবং আমরা তোমাদেরকে তাদের পর তাদের ভূমিতে বাস করতে দেবো। এটা (পুরষ্কার) তাদের জন্য যারা আমার ঐশরিক ক্ষমতাকে ভক্তি করে, এবং আমার প্রতিশ্রুতিকে ভক্তি করে।\""],
  "14:15": ["And they sought triumph, and every stubborn tyrant failed.", "তারা একটি চ্যালেঞ্জ করলো, এবং ফলস্বরুপ, প্রত্যেক একগুঁয়ে অত্যাচারী শাসক অবশেষে ধ্বংস হলো।"],
  "14:16": ["Behind them is hell, and they are given drink of foul water.", "তার জন্য অপেক্ষা করছে নরক, যেখানে সে পঁচা পানি পান করবে।"],
  "14:17": ["He gulps it and can barely swallow it; and death comes to him from every side, yet he cannot die; and behind him is a hard punishment.", "সে তা গিলবে, যদিও তা সে সহ্য করতে পারবে না, যেন মৃত্যু প্রত্যেক দিক থেকে তার কাছে আসবে, কিন্তু সে কখনো মরবে না। তার জন্য অপেক্ষায় আছে এক ভয়ানক শাস্তি।"],
  "14:18": ["The likeness of those who reject their Rabb: their works are like ashes that a storm-wind drives on a stormy day — they have no power over anything of what they earned. That is the far error.", "যারা তাদের প্রভুকে অবিশ্বাস করে তাদের উপমা হচ্ছেঃ তাদের কাজগুলো তীব্র বাতাসের মাঝে ছাইয়ের মত, কোন ঝড়ো দিনে। যা কিছু তারা উপার্জন করে তা থেকে তারা কিছুই পায় না; এমনই হচ্ছে দূরতম পথভ্রষ্টতা।"],
  "14:19": ["Have you not seen that Allah created the heavens and the earth in truth? If Allah wills, Allah can do away with you and bring a new creation.", "তুমি কি অনুধাবন করো না যে আল্লাহ আকাশমন্ডলী ও পৃথিবী একটি নির্দিষ্ট উদ্দেশ্যে সৃষ্টি করেছেন? যদি তিনি ইচ্ছা করেন, তিনি তোমাদের সরিয়ে দিতে পারেন, এবং তোমাদের জায়গায় নতুন সৃষ্টি আনতে পারেন।"],
  "14:20": ["And that is not hard for Allah.", "এটি আল্লাহর জন্য খুব কঠিন নয়।"],
  "14:21": ["And they come forth to Allah, all of them; then the weak say to those who had grown arrogant: \"We were your followers — so can you avail us anything of Allah's punishment?\" They say: \"If Allah had guided us, we would have guided you. It is all the same to us whether we fret or endure; there is no escape for us.\"", "যখন তারা সকলে আল্লাহর সামনে দাঁড়াবে, অনুসারীরা নেতাদের বলবে, \"আমরা তোমাদের অনুসরণ করতাম। তোমরা কি আল্লাহর শাস্তি থেকে আমাদের একটুখানি হলেও মুক্তি দিতে পারো? তারা বলবে, \"যদি আল্লাহ আমাদের পথপ্রদর্শণ করতেন, আমরা তোমাদের পথ দেখাতাম। এখন অনেক দেরি হয়ে গিয়েছে, আমরা শোক করি বা ধৈর্য্যধারণ করি, আমাদের কোন নিস্তার নেই।\""],
  "14:22": ["And the Shaytan says, when the matter is decided: \"Allah promised you a true promise, and I promised you — but I failed you. I had no warrant over you except that I called you and you answered me. So do not blame me, but blame yourselves. I cannot rescue you, nor can you rescue me. I reject what you associated with me before. Truly the wrongdoers have a painful punishment.\"", "এবং শয়তান বলবে, বিচার কার্যকর হওয়ার পর, \"আল্লাহ তোমাদের প্রতিশ্রুতি দিয়েছিলেন সত্য প্রতিশ্রুতি, এবং আমি তোমাদের প্রতিশ্রুতি দিয়েছিলাম, কিন্তু আমি আমার প্রতিশ্রুতি ভংগ করেছি। তোমাদের উপর আমার কোন ক্ষমতা ছিল না; আমি শুধু তোমাদের আমন্ত্রণ করতাম, এবং তোমরা আমার আমন্ত্রণ গ্রহণ করতে। অতএব, আমাকে দোষ দিও না, এবং শুধু নিজেদের দোষ দাও। আমার অভিযোগ তোমাদের সাহায্য করতে পারবে না, না তোমাদের অভিযোগ আমার কোন সাহায্য করতে পারবে। আমাকে তোমাদের উপাস্য বানানোকে আমি অবিশ্বাস করেছি। সীমালঙ্ঘনকারীরা এক যন্ত্রণাদায়ক শাস্তি টেনে এনেছে।\""],
  "14:23": ["And Allah admits those who believe and do the right works into gardens beneath which rivers flow, to abide therein forever, by the leave of their Rabb. Their greeting there is \"Peace.\"", "আর তাদের জন্য যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, তারা প্রবাহিত ঝর্নাসহ বাগানগুলোতে প্রবেশ করবে। তারা সেখানে চিরকাল বসবাস করবে, তাদের প্রভুর ইচ্ছানুসারে। সেখানে তাদের সম্ভাষণ হবে, \"শান্তি\"।"],
  "14:24": ["Have you not seen how Allah strikes a likeness? A good word is like a good tree: its root is fixed and its branch is in the heaven.", "তুমি কি দেখো না যে আল্লাহ ভাল কথার উপমা দিয়েছেন একটি ভাল গাছ হিসেবে যার মূল শক্ত করে আটকানো, এবং শাখাগুলো আকাশে বিস্তৃত?"],
  "14:25": ["It gives its fruit every season by the leave of its Rabb; and Allah strikes likenesses for people, so that they may remember.", "এটি প্রত্যেক ঋতুতে এর শস্য উৎপন্ন করে, যেভাবে এর প্রভু নকশা করেছেন। আল্লাহ এভাবে লোকদের জন্য উপমা বর্ণনা করেণ, যাতে তারা উপদেশ নিতে পারে।"],
  "14:26": ["And the likeness of a vile word is like a vile tree, torn up from the surface of the earth — it has no firm place.", "এবং মন্দ কথার উপমা হচ্ছে একটি মন্দ গাছ যা মাটির স্তরে কাঁটা হয়েছে; একে দাঁড় করিয়ে রাখার জন্য এর কোন মূল নেই।"],
  "14:27": ["Allah makes the muminin stand firm with the firm word, in this life and in the next; and Allah leads the wrongdoers astray; and Allah does whatever Allah wills.", "যারা বিশ্বাস করে তাদেরকে প্রমাণিত কথা দিয়ে আল্লাহ শক্তিশালী করেন, এই জীবনে এবং পরকালে। এবং আল্লাহ সীমালঙ্ঘনকারীদের পথভ্রষ্ট করেন। সবকিছু আল্লাহর ইচ্ছানুসারে হয়।"],
  "14:28": ["Have you not seen those who traded Allah's favor for rejection, and settled their people in the house of ruin?", "তুমি কি তাদের লক্ষ্য করেছ যারা অবিশ্বাস দিয়ে আল্লাহর অনুগ্রহের প্রতি সাড়া দিয়েছে, এবং এভাবে তাদের নিজেদের পরিবারের উপর দুর্দশা এনেছে?"],
  "14:29": ["They enter hell's fire — and what an evil resting-place!", "নরক হচ্ছে তাদের নিয়তি, যেখানে তারা দগ্ধ হয়; কি এক শোচনীয় পরিসমাপ্তি!"],
  "14:30": ["And they set up equals to Allah, to lead astray from Allah's path. Say: \"Enjoy — then your arrival is to the fire.\"", "তারা আল্লাহর সমপর্যায়ে স্থান দিতে এবং অন্যদেরকে তাঁর পথ থেকে বিচ্যুত করতে প্রতিদ্বন্দ্বীদের স্থাপন করে। বল, \"ক্ষনিকের জন্য উপভোগ করে নাও; তোমাদের চুড়ান্ত নিয়তি নরক।\""],
  "14:31": ["Say to My servants who believe: \"Establish the prayer, and spend of what We have provided you, secretly and openly, before a day comes in which there is no dealing and no friendship.\"", "আমার বান্দাদের মধ্যে যারা বিশ্বাস করেছে তাদেরকে উদ্বুদ্ধ করো সংযোগ প্রার্থনা (সালাত) পালন করতে, এবং আমাদের দেয়া জীবিকা থেকে দিতে (দান হিসেবে), গোপনে ও প্রকাশ্যে, সে দিন আসার আগে যখন থাকবে না কোন বাণিজ্য, না কোন সজনপ্রীতি।"],
  "14:32": ["Allah is the one who created the heavens and the earth, and sent down from the heaven water, and brought out with it fruits as provision for you; and subjected for you the ships to sail the sea by Allah's command; and subjected for you the rivers.", "আল্লাহই সেই সত্ত্বা যিনি আকাশমন্ডলী ও পৃথিবী সৃষ্টি করেছেন, এবং তোমাদের জীবিকার জন্য সকল প্রকার ফল উৎপন্ন করতে আকাশ থেকে পানি বর্ষণ করেন। তিনি জাহাজগুলোকে সমুদ্রে তোমাদের সেবায় নিয়োজিত করেছেন তাঁর আদেশ অনুসারে। তিনি নদীগুলোকেও একইভাবে তোমাদের সেবায় নিয়োজিত করেছেন।"],
  "14:33": ["And subjected for you the sun and the moon, unceasing; and subjected for you the night and the day.", "তিনি সূর্য ও চাঁদকে তোমাদের সেবায় নিয়োজিত করেছেন, অনবরত। তিনি রাত ও দিনকে তোমাদের সেবায় নিয়োজিত করেছেন।"],
  "14:34": ["And Allah gave you of all that you asked; and if you count Allah's favor, you cannot number it. Truly the human is ever a wrongdoer, a rejecter.", "এবং তিনি তোমাদেরকে সব ধরণের জিনিস দেন যা কিছুর জন্য তোমরা তাঁর কাছে মিনতি করো। যদি তোমরা আল্লাহর অনুগ্রহ গননা করো, তোমরা কখনো সেগুলো বেষ্টন করতে পারবে না। প্রকৃতপক্ষে, মানবজাতি সীমালঙ্ঘনে রত, অকৃতজ্ঞ।"],
  "14:35": ["And when Ibrahim said: \"My Rabb, make this town safe, and keep me and my sons from serving the asnam.\"", "স্মরণ করো যে ইব্রাহিম বলেছিল, \"আমার প্রভু, একে এক শান্তিময় ভূমি করুন, এবং আমাকে ও আমার সন্তানদের অংশীদার উপাসনা থেকে রক্ষা করুন।"],
  "14:36": ["\"My Rabb, they have led many people astray; so whoever follows me is of me, and whoever disobeys me — then You are truly Forgiving, Raheem.\"", "\"আমার প্রভু, তারা অনেক লোককে পথভ্রষ্ট করেছে। আর তাদের জন্য যারা আমাকে অনুসরণ করে, তারা আমার সাথে আছে। আর তাদের ক্ষেত্রে যারা আমাকে অমান্য করে, আপনি ক্ষমাকারী, পরম দয়ালু।"],
  "14:37": ["\"Our Rabb, I have settled some of my offspring in a valley without crops, near Your sacred house — our Rabb — so that they may establish the prayer. So make hearts of people incline to them, and provide them of the fruits, so that they may give thanks.\"", "“আমাদের প্রভু, আমি আমার পরিবারের একাংশের জন্য বসতি স্থাপন করলাম এই তরুলতাহীন উপত্যাকায়, তোমার পবিত্র ঘরে। আমাদের প্রভু, তারা যাতে সংযোগ প্রার্থনা (সালাত) পালন করে, তাই জনতাকে তাদের সাথে একত্রিত করুন, এবং তাদের জন্য সকল প্রকার ফল সরবরাহ করুন, যাতে তারা কৃতজ্ঞ হয়।"],
  "14:38": ["\"Our Rabb, You know what we conceal and what we make open; and nothing is hidden from Allah of anything in the earth or in the heaven.\"", "“আমাদের প্রভু, আপনি জানেন যা কিছু আমরা গোপন করি এবং যা কিছু আমরা প্রকাশ করি- আল্লাহর কাছে কোনকিছু লুকানো নেই পৃথিবীতে, না আছে আকাশমন্ডলীতে।"],
  "14:39": ["\"Praise be to Allah, who granted me Ismail and Ishaq in old age. Truly my Rabb hears the call.\"", "“প্রশংসা আল্লাহর আমাকে দেয়ার জন্য, আমার বৃদ্ধ বয়স সত্ত্বেও, ইসমাইল ও ইসহাককে। আমার প্রভু প্রার্থনার জবাব দেন।"],
  "14:40": ["\"My Rabb, make me an establisher of the prayer, and my offspring too. Our Rabb, accept my call.\"", "“আমার প্রভু, আমাকে এমন একজন করুন যে নিয়ম-মাফিক সংযোগ প্রার্থনা (সালাত) পালন করে, এবং আমার সন্তানদেরও। আমাদের প্রভু, দয়া করে আমাদের প্রার্থনার জবাব দিন।"],
  "14:41": ["\"Our Rabb, forgive me and my parents, and the muminin, on the day the reckoning stands.\"", "“আমার প্রভু, ক্ষমা করুন আমাকে এবং আমার পিতা-মাতাকে, এবং বিশ্বাসীদের, ঐ দিনে যখন হিসাব নেয়া হয়।”"],
  "14:42": ["And never think Allah unaware of what the wrongdoers do. Allah only defers them to a day when the eyes stare.", "কখনো ভেবো না যে সীমালঙনকারীরা যা করছে আল্লাহ সে বিষয়ে অসচেতন। তিনি শুধু তাদের ঐ দিন পর্যন্ত অবকাশ দেন যেদিন চোখগুলো আতঙ্কে বিস্ফোরিত হয়।"],
  "14:43": ["Hurrying with heads raised, their glance not turning back to them, and their hearts void.", "যখন তারা (কবর থেকে) দ্রুত বের হবে,  তাদের মুখগুলো উপরের দিকে তাকানো থাকবে, এমনকি তাদের চোখের পলকও পড়বে না, এবং তাদের হৃদয় আতংকিত হবে।"],
  "14:44": ["And warn the people of the day the punishment comes to them; those who did wrong will say: \"Our Rabb, defer us to a near term — we will answer Your call and follow the Rasuls.\" \"Did you not swear before that for you there was no passing away?\"", "তুমি লোকদের ঐ দিনের বিষয়ে সতর্ক করবে যখন তাদের কাছে শাস্তি আসবে। যারা সীমালংঘন করেছে তারা বলবে, “আমাদের প্রভু, আমাদেরকে আর একবার অবকাশ দিন। তখন আমরা আপনার ডাকে সাঁড়া দিবো এবং বার্তাবাহকদের অনুসরণ করবো।”তোমরা কি অতীতে শপথ করে বলতে না যে তোমরা চিরকাল টিকে থাকবে?"],
  "14:45": ["And you dwelt in the dwellings of those who wronged themselves, and it became clear to you how We dealt with them, and We struck likenesses for you.", "তোমরা তোমাদের পূর্ববর্তীদের বাড়িতে বাস করতে, যারা তাদের আত্মার ক্ষতি করেছিল, এবং তোমরা স্পষ্টই দেখেছ যা আমরা তাদের সাথে করেছিলাম। আমরা তোমাদের জন্য অনেক উদাহরণ স্থাপন করেছি।"],
  "14:46": ["And they schemed their scheme, and with Allah is their scheme — even if their scheme were such as to move the mountains.", "তারা তাদের চক্রান্ত করেছিল, এবং আল্লাহ তাদের চক্রান্ত সম্পর্কে পূর্ণ অবগত। প্রকৃতপক্ষে, তাদের চক্রান্ত পাহাড়গুলো মুছে দিতে যথেষ্ঠ ছিল।"],
  "14:47": ["So never think that Allah fails the promise to the Rasuls. Truly Allah is the Almighty, the Owner of requital.", "মনে করো না যে আল্লাহ কখনো তাঁর বার্তাবাহকদের সাথে করা অঙ্গীকার ভংগ করবেন। আল্লাহ সর্বশক্তিমান, প্রতিশোধ গ্রহনকারী।"],
  "14:48": ["The day the earth is changed for other than the earth, and the heavens; and they come forth to Allah, the One, the Overpowering.", "ঐ দিন আসবে যখন এই পৃথিবীর জায়গায় এক নতুন পৃথিবী আনা হবে, এবং আকাশমন্ডলীও, এবং সকলকে আল্লাহর সামনে উপস্থিত করা হবে, সেই একক সত্ত্বা, সর্বোচ্চ।"],
  "14:49": ["And you will see the guilty that day, bound together in chains.", "আর সেদিন তুমি অপরাধীদের দেখবে শিকলে বাঁধা।"],
  "14:50": ["Their garments are of molten seal, and the fire covers their faces.", "তাদের জামা আলকাতরায় তৈরী হবে, এবং আগুন তাদের মুখ আচ্ছন্ন করবে।"],
  "14:51": ["So that Allah may repay every nafs what it earned. Truly Allah is swift in reckoning.", "কারণ আল্লাহ প্রত্যেক আত্মাকে শোধ করবেন যা তারা অর্জণ করেছে; আল্লাহ সবচেয়ে দক্ষ হিসাব গ্রহনকারী।"],
  "14:52": ["This is a message for the people, so that they may be warned by it, and know that there is only one ilah, and so that those with understanding may remember.", "এটি লোকদের জন্য একটি ঘোষনাপত্র, এর দ্বারা সতর্ক করতে, এবং তাদেরকে জানাতে যে তিনিই একমাত্র উপাস্য, এবং যারা বুদ্ধিমত্তার অধিকারী তারা যেন মনোনিবেশ করে।"],
  "15:1": ["Alif Lam Ra. These are the ayat of the Kitab and a clear recitation.", "অ, ল, র। এই (অক্ষর গুলো) এই ঐশীগ্রন্থের প্রমান; এক জ্ঞানগর্ভ কুরআন।"],
  "15:2": ["Perhaps those who disbelieve would wish that they had been at peace.", "নিশ্চয়, যারা অবিশ্বাস করতো তারা আকাঙ্ক্ষা করবে যে যদি তারা আত্মসমর্পণকারী হতো।"],
  "15:3": ["Leave them to eat and to enjoy, and let hope divert them — soon they will know.", "তাদেরকে খেতে, আনন্দ করতে এবং ইচ্ছেমতো চিন্তায় অন্ধ থাকতে দাও; তারা দেখতে পাবে।"],
  "15:4": ["We never destroyed any town without its having a known decree.", "আমরা কখনও কোন সম্প্রদায়কে ধ্বংস করি না, একটি নির্দিষ্ট, পূর্বনির্ধারিত সময় অনুসারে ছাড়া।"],
  "15:5": ["No community outstrips its term, and they cannot delay it.", "কোন সম্প্রদায়ের সমাপ্তি না কখনো এগোতে পারে, না পেছাতে পারে।"],
  "15:6": ["They say: \"O you upon whom the Reminder was sent down — you are truly mad.\"", "তারা বলল, “হে তুমি যে এই সতর্কবানী পেয়েছ, তুমি একটা পাগল”।"],
  "15:7": ["\"Why do you not bring us the malakat, if you are among the sadiqin?\"", "“কেন তুমি ফেরেশতাদের নামিয়ে আনো না, যদি তুমি সত্যবাদী হও?”"],
  "15:8": ["We do not send the malakat down except in truth, and then they are not given respite.", "আমরা সুনির্দিষ্ট কাজ ছাড়া ফেরেশতাদের অবতরণ করাই না। অন্যথায়, কেউই রেহাই পাবে না।"],
  "15:9": ["It is We, even We, who sent down the Reminder, and We are its guardians.", "নিসন্দেহে, আমরা এই সতর্কবাণী প্রকাশ করেছি, এবং, নিসন্দেহে, আমরা একে সংরক্ষন করবো।"],
  "15:10": ["We sent before you among the parties of the ancients.", "আমরা তোমার আগে অতীতের সম্প্রদায়ের কাছে (বার্তাবাহকদের) পাঠিয়েছি।"],
  "15:11": ["No Rasul came to them but they mocked him.", "প্রতিবার যখন একজন বার্তাবাহক তাদের কাছে গিয়েছিলো, তারা তাকে উপহাস করেছিল।"],
  "15:12": ["Thus We thread it through the hearts of the guilty.", "আমরা এভাবে অপরাধীদের মনকে নিয়ন্ত্রণ করি।"],
  "15:13": ["They do not believe in it, though the way of the ancients has passed before.", "ফলস্বরূপ, তারা তাকে বিশ্বাস করতে পারে না। অতীত প্রজন্মদের থেকে এই রীতিই চলে আসছে।"],
  "15:14": ["And even if We opened for them a door from the heaven and they kept ascending through it,", "এমনকি আমরা যদি তাদের জন্য আকাশে কোন দরজা খুলে দেই, যা দিয়ে তারা আরোহণ করে;"],
  "15:15": ["they would say: \"Only our eyes have fallen into stupor; no, we are a bewitched people.\"", "তারা বলবে, “আমাদের চোখকে ধোঁকা দেয়া হয়েছে। আমরা জাদুগ্রস্থ হয়ে পড়েছি”।"],
  "15:16": ["We placed towers in the heaven and adorned it for those who look.", "আমরা আকাশে নক্ষত্রপুঞ্জ স্থাপন করেছি, এবং দর্শকদের জন্য একে সুসজ্জিত করেছি।"],
  "15:17": ["And We guarded it from every stoned devil,", "এবং আমরা প্রত্যেক বিতাড়িত শয়তান থেকে একে সুরক্ষিত করেছি।"],
  "15:18": ["except whoever steals a hearing — then a clear fire-missile follows him.", "যদি তাদের কেউ শোনার জন্য চুপিসারে ঘুরে বেড়ায়, একটি শক্তিশালী ক্ষেপণাস্ত্র তার পিছু ধাওয়া করবে।"],
  "15:19": ["And the earth — We spread it out, and cast anchors in it, and made grow in it every weighed thing.", "পৃথিবীর বিষয়ে, আমরা একে নির্মাণ করেছি, এবং এর উপর ভারসাম্যরক্ষাকারী (পর্বতমালা) রেখেছি এবং আমরা এর উপর দিয়েছি প্রত্যেক জিনিসের এক নিখুঁত ভারসাম্য।"],
  "15:20": ["And We made in it livelihoods for you, and for those whom you do not provide.", "আমরা একে বানিয়েছি বাসযোগ্য তোমাদের জন্য,  এবং জীবদের জন্য তোমরা যাদের জীবিকা দাও না।"],
  "15:21": ["There is nothing but its stores are with Us, and We do not send it down except in a known measure.", "সেখানে কোন কিছুই নেই যার সীমাহীন পরিমানের মালিক আমরা মালিক নই। কিন্তু আমরা তা সুনির্দিষ্ট পরিমাণে অবতীর্ণ করি।"],
  "15:22": ["And We sent the winds fertilizing, and We sent down from the heaven water, and gave you to drink of it — and you are not its store-keepers.", "এবং আমরা বাতাস পাঠাই পরাগায়নকারী হিসেবে, এবং তোমাদের পান করার জন্য আকাশ থেকে পানি বর্ষনের ব্যবস্থা করি। অন্যথায়, তোমরা একে সুস্বাদু রাখতে পারতে না।"],
  "15:23": ["It is We who give life and bring death, and We are the final heirs.", "আমরাই জীবন ও মৃত্যু নিয়ন্ত্রন করি, এবং আমরাই চূড়ান্ত উত্তরাধিকারী।"],
  "15:24": ["We know those among you who press forward, and We know those who lag behind.", "এবং আমরা তোমাদের মধ্যে তাদেরকে পূর্ণরূপে জানি যারা অগ্রগামী হয়, এবং আমরা তাদেরকে পূর্ণরূপে জানি যারা পশ্চাৎগামী হয়।"],
  "15:25": ["Your Rabb will gather them — your Rabb is wise and knowing.", "তোমার প্রভু অবশ্যই তাদের ডেকে পাঠাবেন। তিনি পরম প্রজ্ঞাবান, সর্বজ্ঞ।"],
  "15:26": ["We created the human from clay of molded mud.", "আমরা মানবজাতিকে সৃষ্টি করেছি পুরনো কাঁদা থেকে, কুমোরের মাটির মতো।"],
  "15:27": ["And the jinn — We created them earlier from scorching fire.", "জীনদের ক্ষেত্রে, আমরা তাদের সৃষ্টি করেছি, এর আগে, জলন্ত আগুন থেকে।"],
  "15:28": ["And when your Rabb said to the malakat: \"I am creating a human from clay of molded mud,", "তোমার প্রভু ফেরেশতাদের বললেন, “আমি একজন মানুষ সৃষ্টি করছি পুরানো কাঁদা থেকে, কুমোরের মাটির মতো।"],
  "15:29": ["and when I have proportioned him and blown into him of My spirit, fall down before him, prostrating.\"", "“একবার আমি তাকে সম্পূর্ণ করার পর, এবং তার মধ্যে আমার রূহ থেকে ফুঁকে দেবার পর, তোমরা তার সামনে সেজদাবনত হবে”।"],
  "15:30": ["So the malakat prostrated, all of them together,", "ফেরেশতারা সেজদাবনত হল; তাদের সকলে,"],
  "15:31": ["except Iblis — he refused to be among those prostrating.", "ইবলিস (শয়তান) ছাড়া। সে সেজদাকারীদের সাথে থাকতে অস্বীকার করলো।"],
  "15:32": ["The Rabb said: \"Iblis, what is it with you that you are not among those prostrating?\"", "তিনি বললেন, “হে ইবলিস (শয়তান), তুমি সেজদাকারীদের সাথে নেই কেন?"],
  "15:33": ["He said: \"I would not prostrate to a human whom You created from clay of molded mud.\"", "সে বলল, “আমি কোন মানুষকে সেজদা করবো না, যাকে আপনি সৃষ্টি করেছেন পুরানো কাঁদা থেকে, কুমোরের মাটির মতো।\""],
  "15:34": ["The Rabb said: \"Then get out from it — you are stoned.", "তিনি বললেন, “সেজন্য, তুমি অবশ্যই বেরিয়ে যাবে; তুমি নির্বাসিত।"],
  "15:35": ["The curse is upon you until the Day of Judgment.\"", "“তুমি বিচার দিন পর্যন্ত আমার অভিশাপ অর্জন করেছো।\""],
  "15:36": ["He said: \"Rabb, grant me respite until the day they are raised.\"", "সে বলল, “আমার প্রভু, তাদের পুনরুত্থানের দিন অবধি আমাকে অবকাশ দিন।\""],
  "15:37": ["The Rabb said: \"You are among the respited,", "তিনি বললেন, “তোমাকে অবকাশ দেয়া হল।\""],
  "15:38": ["until the day of the appointed time, the known one.\"", "“নির্দিষ্ট দিন এবং সময় পর্যন্ত।\""],
  "15:39": ["He said: \"Rabb, because You misled me, I will adorn for them on the earth and mislead them all,", "সে বলল, “আমার প্রভু, যেহেতু আপনি ইচ্ছা করেছেন যে আমি বিপথে যাই, আমি অবশ্যই পৃথিবীতে তাদেরকে প্রলুব্ধ করবো; আমি তাদের সকলকে বিপথে পাঠাবো।"],
  "15:40": ["except Your abd, the mukhlisin among them.\"", "\"শুধু আপনার উপাসনাকারীদের মধ্যে তাদের ছাড়া যারা সম্পূর্ণরূপে একমাত্র আপনার প্রতি উৎসর্গকৃত।\""],
  "15:41": ["The Rabb said: \"This is a path to Me, made straight.", "তিনি বললেন, “এটি একটি আইন যা অলঙ্ঘনীয়"],
  "15:42": ["Over My servants you have no hold, except those of the misled who follow you.", "\"আমার বান্দাদের উপর তোমার কোন ক্ষমতা নেই। তোমার ক্ষমতা আছে শুধু পথভ্রষ্টদের উপর যারা তোমাকে অনুসরণ করে।"],
  "15:43": ["Hell is the promised meeting for them all.", "“এবং নরক তাদের সকলের জন্য অপেক্ষা করছে।"],
  "15:44": ["It has 7 doors; for each door an allotted portion is assigned.", "“এর সাতটি দরজা হবে। প্রত্যেক দরজা তাদের একটি নির্দিষ্ট অংশ পাবে।\""],
  "15:45": ["the muttaqin are in gardens and springs.", "সৎকর্মশীলদের ক্ষেত্রে, তারা বাগান এবং ঝর্না উপভোগ করবে।"],
  "15:46": ["\"Enter them in peace, secure.\"", "তাতে প্রবেশ করো, শান্তিময় এবং নিরাপদ।"],
  "15:47": ["We pull out whatever rancor is in their breasts — as brothers, on couches facing one another.", "আমরা তাদের হৃদয় থেকে সকল হিংসা দূর করবো। তারা পাশাপাশি আসবাবপথ ও সাজসরঞ্জামের মাঝে থাকবে, একটি পরিবারের মতো।"],
  "15:48": ["No toil touches them in it, and they are never made to leave it.", "সেখানে তারা কখনো ক্লান্তি বোধ করবে না; সেখান থেকে কখনো তারা বিতাড়িত হবে না।"],
  "15:49": ["Tell My servants that I am the Forgiving, the Raheem,", "আমার বান্দাদের জানাও যে আমি ক্ষমাকারী, পরম দয়ালু।"],
  "15:50": ["and that My punishment is the painful punishment.", "এবং যে আমার শাস্তি সবথেকে যন্ত্রণাদায়ক শাস্তি।"],
  "15:51": ["And tell them of the guests of Ibrahim,", "তাদেরকে ইব্রাহীমের অতিথিদের বিষয়ে জানাও।"],
  "15:52": ["when they entered upon him and said \"Peace,\" and he said: \"We are in awe of you.\"", "যখন তারা তার বাসায় প্রবেশ করলো, তারা বলল, “শান্তি”। সে বলল, “আমরা তোমাদের ব্যপারে শঙ্কিত।\""],
  "15:53": ["They said: \"Do not be in awe — we bring you tidings of a knowing boy.\"", "তারা বলল, “শঙ্কিত হয়ো না। আমরা তোমার জন্য সুসংবাদ এনেছিঃ এক জ্ঞানদিপ্ত পুত্রের।\""],
  "15:54": ["He said: \"You bring me tidings though old age has touched me — what is it you bring?\"", "সে বলল, “কিভাবে তোমরা আমাকে এমন সুসংবাদ দিতে পারো, যখন আমি এতো বৃদ্ধ? এরপরও কি তোমরা আমাকে এই সুসংবাদ দাও?"],
  "15:55": ["They said: \"We bring you tidings in truth — do not be among those who despair.\"", "তারা বলল, “যে সুসংবাদ আমরা তোমাকে দেই তা সত্য; হতাশ হয়ো না।\""],
  "15:56": ["He said: \"Who despairs of the mercy of the Rabb except those who stray?\"", "সে বলল, “কেউ তার প্রভুর দয়া থেকে হতাশ হয় না, পথভ্রষ্টরা ছাড়া।\""],
  "15:57": ["He said: \"What is your affair, O mursalun?\"", "সে বলল, “তোমাদের পাঠানোর উদ্দেশ্য কি, হে বার্তাবাহকগন?”"],
  "15:58": ["They said: \"We are sent to a guilty people,", "তারা বলল, “আমাদেরকে পাঠানো হয় অপরাধী লোকদের নিকট।"],
  "15:59": ["except the family of Lut — We will surely save them all,", "“লুতের পরিবারের ক্ষেত্রে, আমরা তাদের সকলকে রক্ষা করবো।\""],
  "15:60": ["except his imra'a — We have decreed it: she is surely among the ghābirīn.\"", "“কিন্তু তার স্ত্রীকে নয়; সে দন্ডপ্রাপ্তদের সাথে থাকার জন্য নিয়তিপ্রাপ্ত।\""],
  "15:61": ["So when Our mursalin came to the family of Lut,", "বার্তাবাহকেরা লুতের শহরে গেল।"],
  "15:62": ["he said: \"You are a disavowed people.\"", "সে বলল, “তোমরা অপরিচিত লোক।\""],
  "15:63": ["They said: \"No — we bring you that of which they used to doubt,", "তারা বলল, “আমরা তোমার কাছে এনেছি যাতে তারা সন্ধেহ করছে।"],
  "15:64": ["and we bring you the truth, and we are sadiq.", "“আমরা তোমার কাছে সত্য আনি, আমরা সত্যবাদী।"],
  "15:65": ["Set out by night with your family in a portion of the night, and go behind them, and let none of you turn around — and press on wherever you are commanded.\"", "“রাতে তুমি তোমার পরিবারকে সঙ্গে নিবে। তাদের পেছনে থেকো, এবং নিশ্চিত করো যে তোমাদের কেউ যেন পেছনে না তাকায়। সোজা চলে যাও যেভাবে আদেশ করা হয়েছে।\""],
  "15:66": ["We decreed that matter to him: the end of these will be cut off by morning.", "আমরা তার কাছে এই হুকুম পৌঁছালামঃ ঐ লোকেরা সকালে ধ্বংস হবে।"],
  "15:67": ["The people of the town came, rejoicing.", "শহরের লোকরা আনন্দ করতে করতে আসলো।"],
  "15:68": ["He said: \"These are my guests — do not disgrace me.", "সে বলল, “এরা আমার অতিথি; আমাকে বিব্রত করো না।”"],
  "15:69": ["Be mindful of Allah, and do not shame me.\"", "“আল্লাহকে ভয় করো, এবং আমাকে লজ্জিত করো না।\""],
  "15:70": ["They said: \"Did we not forbid you from all people?", "তারা বলল, “তোমাকে কি আমরা কারো সাথে যোগাযোগ করতে নিষেধ করিনি?”"],
  "15:71": ["He said: \"These are my daughters, if you must act.\"", "সে বলল, “এখানে আছে আমার কন্যারা, যদি তোমাদের দরকারই হয়।\""],
  "15:72": ["By your life — they were in their stupor, wandering blind.", "কিন্তু, হায়, তারা তাদের কাম লালসায় সম্পূর্ণ অন্ধ ছিল।"],
  "15:73": ["The shout seized them at sunrise.", "ফলস্বরূপ, সকালে দুর্যোগ তাদের আঘাত করলো।"],
  "15:74": ["We made its heights into its lowest parts, and rained upon them marked stones.", "আমরা একে উল্টে দিলাম, এবং তাদের উপর ধ্বংসাত্বক পাথর বর্ষণ করলাম।"],
  "15:75": ["In that are ayat for those who take heed.", "এটা তাদের জন্য একটি শিক্ষা যারা বুদ্ধিমত্তার অধিকারী।"],
  "15:76": ["It lies on an abiding road.", "এটাই হবে সবসময়কার রীতি।"],
  "15:77": ["In that is an aya for the muminin.", "এটা বিশ্বাসীদের জন্য একটা নিদর্শন।"],
  "15:78": ["The companions of the Thicket were surely wrongdoers,", "বনের অধিবাসীরাও সীমালঙ্ঘনকারী ছিল।"],
  "15:79": ["so We requited them — and the two of them lie on a clear waymark.", "ফলস্বরূপ, আমরা তাদের থেকে প্রতিশোধ নিলাম, এবং উভয় জনপদ সম্পূর্ণভাবে লিপিবদ্ধ।"],
  "15:80": ["The companions of the Stone denied the mursalin,", "আল-হিজরের লোকেরা বার্তাবাহকদের অবিশ্বাস করেছিল।"],
  "15:81": ["and We gave them Our ayat, but they turned away from them,", "আমরা তাদেরকে আমাদের প্রকাশনাবলি দিয়েছিলাম, কিন্তু তারা সেগুলো উপেক্ষা করেছে।"],
  "15:82": ["for they carved houses from the rocks, feeling secure.", "তারা পাহাড়ে নিরাপদ ঘর খোদাই করতো।"],
  "15:83": ["The shout seized them in the morning.", "সকালে দুর্যোগ তাদের আঘাত করলো।"],
  "15:84": ["What they used to earn availed them nothing.", "যা তারা জমা করেছিল তা তাদের সাহায্য করেনি।"],
  "15:85": ["We created the heavens and the earth and what is between them only in truth, and the Hour is surely coming — so offer the beautiful pardon.", "আমরা আকাশমন্ডলী ও পৃথিবী, এবং এদের মাঝের সবকিছু একটি সুনির্দিষ্ট উদ্দেশ্য ছাড়া সৃষ্টি করিনি। বিশ্বের পরিসমাপ্তি আসবে, সুতরাং তাদেরকে মৃদুভাবে উপেক্ষা করো।"],
  "15:86": ["Your Rabb is the Creator, the Knowing.", "তোমার প্রভু হচ্ছেন সৃষ্টিকর্তা, আর সর্বজ্ঞ।"],
  "15:87": ["We gave you 7 of the oft-repeated, and the mighty recitation.", "আমরা তোমাকে দিয়েছি সাত জোড়া, এবং মহান কুরআন।"],
  "15:88": ["Do not strain your eyes toward what We let some of them enjoy in pairs, and do not grieve over them — and lower your wing to the muminin.", "অন্য (বার্তাবাহকদের) উপর আমরা যা অর্পণ করেছি তাতে ঈর্ষান্বিত হয়ো না, এবং (অবিশ্বাসীদের কারণে) দুঃখিত হয়ো না, এবং বিশ্বাসীদের প্রতি সদয় হও।"],
  "15:89": ["And say: \"I am the clear warner,", "এবং ঘোষণা করো, “আমি স্পষ্ট সতর্ককারী।\""],
  "15:90": ["just as We sent down upon those who divide —", "বিভক্তকারীদের সাথে আমি বোঝাপড়া করবো।"],
  "15:91": ["those who made the recitation into pieces —", "তারা কুরআনকে শুধু আংশিকভাবে গ্রহণ করে।"],
  "15:92": ["so by your Rabb, We will surely ask them all", "তোমার প্রভুর শপথ, আমরা তাদের সবাইকে প্রশ্ন করবো,"],
  "15:93": ["about what they used to do.", "সবকিছু সম্পর্কে যা তারা করেছে।"],
  "15:94": ["Proclaim openly what you are commanded, and turn away from those who join others with Allah —", "সুতরাং, তোমাকে দেয়া হুকুমগুলো পালন করো, এবং প্রতিমা উপাসকদের উপেক্ষা করো।"],
  "15:95": ["We suffice you against the mockers,", "আমরা উপহাসকারীদের থেকে তোমাকে নিষ্কৃতি দেব,"],
  "15:96": ["those who make with Allah another ilah — soon they will know.", "যারা আল্লাহর পাশে অন্য উপাস্য স্থাপন করে, অবশ্যই তারা দেখতে পাবে।"],
  "15:97": ["We know that your chest straitens because of what they say.", "আমরা খুব ভালোভাবে জানি যে তুমি হয়তো তাদের কথায় বিরক্ত হও।"],
  "15:98": ["So glorify your Rabb with praise, and be among those who prostrate,", "তুমি তোমার প্রভুর গুন কীর্তন করবে, এবং সেজদাকারিদের সাথে থাকবে।"],
  "15:99": ["and serve your Rabb until the certainty comes to you.", "এবং তোমার প্রভুর উপাসনা করো, নিশ্চয়তা অর্জন করার জন্য।"],
  "16:1": ["The command of Allah has come, so do not hasten it. Glorified is Allah, high above what they associate.", "আল্লাহর হুকুম এরই মধ্যে এসে গেছে (এবং সবকিছু এরই মধ্যে লেখা হয়ে গেছে), তাই এতে তাড়াহুড়া করো না। মহিমা তাঁরই; সর্বোচ্চ, তাদের স্থাপন করা যেকোন অংশীদার থেকে অনেক ঊর্ধ্বে।"],
  "16:2": ["Allah sends down the malakat with the spirit of the command from Allah upon whom Allah wills of the servants, saying: \"Warn that there is no deity but Me, so be mindful of Me.\"", "তিনি প্রকাশনাবলী দিয়ে ফেরেশতাদের অবতরণ করান, তাঁর হুকুম বহন করে, তার প্রতি যাকে তিনি পছন্দ করেন তাঁর বান্দাদের মধ্য থেকে: “তোমরা প্রচার করবে যে, কোন উপাস্য নাই আমার পাশে; তোমরা আমাকে ভক্তি করবে”।"],
  "16:3": ["Allah created the heavens and the earth in truth. Exalted is Allah above what they associate.", "তিনি আকাশমন্ডলী এবং পৃথিবী একটি সুনির্দিষ্ট উদ্দেশ্যে সৃষ্টি করেছেন। তিনি অনেক অনেক উর্ধ্বে, তাদের স্থাপিত কোন অংশীদার থেকে অনেক উপরে।"],
  "16:4": ["Allah created the human from a drop, and then that one is an open contender.", "তিনি মানুষকে অতিক্ষুদ্র এক ফোঁটা থেকে সৃষ্টি করেছেন, এরপর সে এক প্রকাশ্য প্রতিপক্ষে পরিণত হয়।"],
  "16:5": ["And the cattle — Allah created them for you. In them is warmth and benefit, and from them you eat.", "এবং তিনি তোমাদের জন্য গবাদি পশু সৃষ্টি করেছেন, তোমাদের জন্য উষ্ণতা জোগাতে, এবং আরও অনেক উপকারিতা, সেইসাথে খাবার।"],
  "16:6": ["And in them is beauty for you when you bring them to rest and when you send them out to graze.", "এছাড়াও এগুলো বিলাস দ্রব্যের যোগান দেয় তোমাদের অবসর সময়ে, এবং যখন তোমরা ভ্রমন করো।"],
  "16:7": ["And they carry your loads to a town you could not reach except with hardship to yourselves. Indeed your Rabb is gentle in mercy, merciful.", "এবং তারা তোমাদের বোঝা এমন জায়গায় বহন করে নিয়ে যায় যেখানে তোমরা অনেক কষ্ট ব্যতীত পৌঁছতে পারতে না। নিশ্চয়, তোমার প্রভু দয়াবান, পরম করুণাময়।"],
  "16:8": ["And horses, and mules, and donkeys for you to ride and as adornment; and Allah creates what you do not know.", "এবং (তিনি সৃষ্টি করেছেন) ঘোড়া, খচ্চর, এবং গাধা তোমাদের আরহনের জন্য, এবং বিলাসিতার জন্য। উপরুন্তু, তিনি সৃষ্টি করেন যা তোমরা জানো না।"],
  "16:9": ["And upon Allah rests the mid-course of the path, though among them are deviating side-takers; and if Allah willed, Allah would have guided you all together.", "আল্লাহ পথসমূহ প্রদর্শন করেন, ভুলপথটিও। তিনি চাইলে, তোমাদের সকলকে সুপথপ্রাপ্ত করতে পারতেন।"],
  "16:10": ["It is Allah who sends down water from the heaven for you; from it is a drink, and from it grow trees in which you pasture your herds.", "তিনি আকাশ থেকে পানি বর্ষণ করেন তোমাদের পান করার জন্য, এবং তোমাদের উপকারের জন্য গাছ জন্মাতে।"],
  "16:11": ["Allah grows for you with it the crops, and the olives, and the palms, and the grapes, and every kind of fruit. Indeed in that is an aya for people who reflect.", "তা দিয়ে, তিনি তোমাদের জন্য উৎপাদন করেন শস্য, জলপাই, খেজুর গাছ, আঙ্গুর, এবং সকল প্রকার ফল। এটাই(যথেষ্ট) প্রমান লোকদের জন্য যারা চিন্তা করে।"],
  "16:12": ["And Allah subjected for you the night and the day, and the sun and the moon and the stars, subjected by Allah's command. Indeed in that are ayat for people who understand.", "এবং তিনি  নিয়োজিত করেন, তোমাদের সেবায়, দিন ও রাত্রি, সেই সাথে সূর্য ও চাঁদকে। তারকারাজীও নিয়োজিত রয়েছে  তাঁর হুকুমে। এগুলো (যথেষ্ট) প্রমান লোকদের জন্য যারা বুঝে।"],
  "16:13": ["And what Allah has spread forth on the earth for you, with its colors differing — indeed in that is an aya for people who remember.", "এবং পৃথিবীতে তোমাদের জন্য (তিনি সৃষ্টি করেছেন) বিভিন্ন রঙের জিনিস। এটা (যথেষ্ট) প্রমান লোকদের জন্য যারা মনোযোগ দেয়।"],
  "16:14": ["And it is Allah who subjected the sea, so that you may eat from it fresh flesh, and extract from it adornment that you wear, and you see the ships sailing through it — so that you may seek of Allah's bounty, and so that you may give thanks.", "এবং তিনি সমুদ্রকে নিয়োজিত করেছেন তোমাদের সেবায়; তোমরা এর থেকে নরম মাংস খাও এবং আহরণ করো অলঙ্কার যা তোমরা পরো। এবং তুমি জাহাজগুলোকে দেখো এতে বিচরণ করতে তোমাদের বাণিজ্যিক লাভের জন্য, যখন তোমরা তাঁর অনুগ্রহ অন্বেষণ করো, যাতে তোমরা কৃতজ্ঞ হতে পারো।"],
  "16:15": ["And Allah cast into the earth firm anchors so that it would not sway with you, and rivers and paths, so that you may be guided.", "এবং তিনি পৃথিবীতে ভারসাম্যকারী (পর্বত) স্থাপন করেছেন, পাছে এটি তোমাদের নিয়ে উলটে পড়ে, সেই সাথে নদী এবং রাস্তা, যাতে তোমরা সুপথপ্রাপ্ত হও।"],
  "16:16": ["And landmarks; and by the stars they are guided.", "এবং স্থান নির্দেশক, সেই সাথে তারকারাজী; যান চালনায় ব্যবহারের জন্য।"],
  "16:17": ["Is one who creates like one who does not create? Will you not then remember?", "যে সত্ত্বা সৃষ্টি করেন তিনি কি তার মতো যে সৃষ্টি করে না? এখন কি তোমরা মনোযোগ দেবে?"],
  "16:18": ["And if you count the blessing of Allah, you cannot count it. Indeed Allah is ever forgiving, merciful.", "যদি তুমি আল্লাহর অনুগ্রহ গণনা করো, তুমি কখনো তা পরিবেষ্টন করতে পারবে না। আল্লাহ ক্ষমাকারী, পরম দয়ালু।"],
  "16:19": ["And Allah knows what you hide and what you proclaim.", "এবং আল্লাহ জানেন যাকিছু তোমরা গোপন করো এবং যাকিছু তোমরা প্রকাশ করো।"],
  "16:20": ["And those whom they call upon besides Allah create nothing, while they themselves are created.", "আর আল্লাহর পাশে তাদের স্থাপন করা অংশীদারদের ব্যাপারে, তারা কোন কিছু সৃষ্টি করে না; তারা নিজেরাই সৃজিত।"],
  "16:21": ["They are dead, not alive, and they do not perceive when they will be raised.", "তারা মৃত, জীবিত নয়, এবং তাদের কোন ধারনা নেই কিভাবে বা কখন তারা পুনরুত্থিত হবে।"],
  "16:22": ["Your deity is one deity. As for those who do not believe in the hereafter, their hearts are in rejection, and they are arrogant.", "তোমাদের খোদা হচ্ছেন একজন। তাদের ক্ষেত্রে যারা পরকালে বিশ্বাস করে না, তাদের হৃদয় অস্বীকার করছে, এবং তারা উদ্ধত।"],
  "16:23": ["Without doubt Allah knows what they hide and what they proclaim. Indeed Allah does not love the mustakbirim.", "সম্পূর্ণরূপে, আল্লাহ জানেন সবকিছু যা তারা গোপন করে এবং সবকিছু যা তারা প্রকাশ করে। তিনি তাদের ভালোবাসেন না যারা উদ্ধত।"],
  "16:24": ["And when it is said to them, \"What has your Rabb sent down?\" they say, \"Tales of the ancients.\"", "যখন তাদের জিজ্ঞেস করা হয়, “তোমাদের প্রভুর পক্ষ থেকে এই প্রকাশনাবলির ব্যাপারে তোমরা কি মনে করো,” তারা বলে, “অতীতের কল্প-কাহিনী।\""],
  "16:25": ["So that they may carry their loads complete on the Day of Rising, along with the loads of those whom they mislead without knowledge. Alas, how evil is what they bear!", "পুনরুত্থান দিনে তাদেরকে দায়ী করা হবে তাদের পাপের জন্য, তাদের সকলকে, সেই সাথে ওদের সকলের পাপের জন্য তারা যাদেরকে পথভ্রষ্ট করেছে তাদের অজ্ঞতার দ্বারা। কি এক শোচনীয় বোঝা!"],
  "16:26": ["Those before them planned, but Allah came at their building from the foundations, and the roof collapsed upon them from above, and the punishment came to them from where they did not perceive.", "তাদের মতো অন্যান্যরাও অতীতে চক্রান্ত করেছে, এবং ফলস্বরূপ, আল্লাহ তাদের ইমারতের ভিত্তি ধ্বংস করেছিলেন, তাদের উপর ছাদ পতিত করে। শাস্তি তাদের আঘাত করেছিল যখন তারা খুব কমই প্রত্যাশা করেছিল।"],
  "16:27": ["Then on the Day of Rising Allah will disgrace them and say, \"Where are My associates for whom you used to contend?\" Those who were given knowledge will say, \"Indeed the disgrace and the evil today are upon the kafirin.\"", "এরপর, পুনরুত্থান দিনে, তিনি তাদের লাঞ্ছিত করবেন এবং জিজ্ঞেস করবেন, “কোথায় আমার শরিক-উপাস্যরা যাদেরকে তোমরা আমার পাশে স্থাপন করেছিলে, এবং তাদের কারনে আমার বিরোধিতা করেছিলে?” যারা জ্ঞান পেয়ে সৌভাগ্যশালী হয়েছিল তারা বলবে, “আজকে, লজ্জা ও দুর্দশা অবিশ্বাসীদের উপর পড়েছে।\""],
  "16:28": ["Those whom the malakat take in death while they wrong themselves; then they cast the submission: \"We were not doing any evil.\" \"Yes indeed! Allah knows what you used to do.\"", "তাদের আত্মার ক্ষতি করা অবস্থায় ফেরেশতারা তাদের মৃত্যু ঘটায়। ঠিক তখনই তারা অবশেষে আত্মসমর্পণ করে, এবং বলে, “আমরা কোন অন্যায় করিনি!” হ্যাঁ নিশ্চয়ই! আল্লাহ সবকিছুর ব্যাপারে সম্পূর্ণ অবগত, যা তোমরা করেছো।"],
  "16:29": ["\"Enter the gates of hell, to abide therein.\" How evil is the lodging of the mutakabbirin!", "অতএব, নরকের দরজা দিয়ে প্রবেশ করো, যেখানে তোমরা চিরকাল বাস করো। উদ্ধতদের জন্য কি এক শোচনীয় নিয়তি।"],
  "16:30": ["And it will be said to those who were mindful, \"What has your Rabb sent down?\" They will say, \"Good.\" For those who did good in this nearer life there is goodness, and the home of the hereafter is better; and excellent is the home of the muttaqin.", "সৎ-কর্মীদের ক্ষেত্রে, যখন তাদের জিজ্ঞেস করা হয়, “তোমাদের প্রভুর পক্ষ থেকে এই প্রকাশনাবলির ব্যপারে কি মনে করো,” তারা বলে, “ভাল।\" যারা সৎ জীবন-যাপন করে তাদের জন্য, সুখ, এবং পরকালের গৃহ আরও উত্তম। কি এক পরম সুখের আবাস সৎ-কর্মশীলদের জন্য।"],
  "16:31": ["Gardens of Eden they will enter, with rivers flowing beneath them; for them therein is whatever they will. Thus does Allah repay the muttaqin.", "ইডেনের বাগানগুলো তাদের জন্য সংরক্ষিত রয়েছে, যেখানে নদী প্রবাহিত হয়। সেখানে তাদের তা-ই থাকে যা তারা  ইচ্ছা করে। আল্লাহ এভাবে সৎ-কর্মশীলদের পুরষ্কৃত করেন।"],
  "16:32": ["Those whom the malakat take in death in a good state, saying, \"Peace be upon you; enter the garden for what you used to do.\"", "ফেরেশতারা সৎকর্মশীল অবস্থায় তাদের জীবন পরিসমাপ্তি করে, এ বলে, “তোমাদের উপর শান্তি বর্ষিত হোক। তোমাদের কাজের পুরস্কার হিসেবে (এখন) স্বর্গে প্রবেশ করো।\""],
  "16:33": ["Do they await anything but that the malakat come to them, or the command of your Rabb comes? Thus did those before them act. And Allah did not wrong them, but they used to wrong themselves.", "তারা কি অপেক্ষায় আছে তাদের কাছে ফেরেশতাদের আসবার, নাকি তোমার প্রভুর বিচার এসে যাবার? তাদের পূর্ববর্তীরাও একই কাজ করেছিল। আল্লাহ সেই সত্ত্বা নন যে তাদের প্রতি অন্যায় করেছে, তারা নিজেরাই নিজেদের আত্মার প্রতি অন্যায় করেছিল।"],
  "16:34": ["So the evils of what they did struck them, and there encircled them what they used to mock.", "তারা তাদের মন্দ কাজের ফলাফল অর্জন করেছে, এবং যে বিষয়গুলোকে তারা উপহাস করতো সেগুলোই উল্টো তাদের তাড়া করে বেড়িয়েছিল।"],
  "16:35": ["And those who associated said, \"If Allah had willed, we would not have served anything besides Allah — neither we nor our fathers — nor would we have forbidden anything besides Allah.\" Thus did those before them act. So is there upon the Rasuls anything but the clear delivery?", "প্রতিমা উপাসকরা বলে, “আল্লাহ যদি চাইতেন, আমরা তাঁর পাশে কোন অংশীদার উপাসনা করতাম না, না আমাদের পিতা-মাতারা করতো। না আমরা তাঁর নিষেধগুলোর পাশে কোনকিছু নিষেধ করতাম।\" তাদের পূর্ববর্তীরাও একই রকম করেছিল। বার্তাবাহকরা কি পূর্ণ বার্তা পৌছে দেয়া ছাড়া কিছু করতে পারে?"],
  "16:36": ["And We have surely sent into every community a Rasul: \"Serve Allah and avoid the false arbiter.\" Among them are those whom Allah guided, and among them are those upon whom straying became binding. So journey through the land and look at how was the end of those who denied.", "আমরা প্রত্যেক সম্প্রদায়ের নিকট একজন বার্তাবাহক পাঠিয়েছি, এই বলে, “তোমরা আল্লাহর উপাসনা করবে, এবং অংশিবাদকে এড়িয়ে চলবে। “পরবর্তীতে, কেউ কেউ আল্লাহ দ্বারা পথপ্রাপ্ত হয়েছিল, যখন অন্যরা ছিল পথভ্রষ্টতায় লিপ্ত। ঘুড়ে বেড়াও পৃথিবীতে এবং প্রত্যাখ্যানকারীদের পরিণতি লক্ষ্য করো।"],
  "16:37": ["If you ardently want their guidance, Allah does not guide the one let astray, and they have no helpers.", "তুমি তাদের সুপথপ্রাপ্ত করার যতো চেষ্টা-ই করো না কেন, আল্লাহ তাদের সুপথপ্রাপ্ত করেন না তিনি যাদের পথভ্রষ্ট করেছেন। এরুপে, কেউ তাদের সাহায্য করতে পারে না।"],
  "16:38": ["And they swore by Allah with the utmost of their oaths: \"Allah will not raise the one who dies.\" Yes — a promise binding upon Allah. But most people do not know.", "তারা আল্লাহর নামে দৃড় শপথ করেঃ “আল্লাহ মৃতকে পুনরুত্থিত করবেন না।\" নিঃসন্দেহে, এমনই তাঁর অলঙ্ঘনীয় অঙ্গীকার, কিন্তু অধিকাংশ লোক জানে না।"],
  "16:39": ["So that Allah may make clear to them that about which they differ, and so that those who disbelieved may know that they were liars.", "এরপর তিনি সবাইকে সে সবকিছু দেখাবেন যে বিষয়ে তারা বিবাদ করতো, এবং যারা অবিশ্বাস করেছিল তাদেরকে জানতে দিবেন যে তারা ছিল মিথ্যাবাদী।"],
  "16:40": ["Our word for a thing when We will it is only that We say to it, \"Be,\" and it is.", "কোন কিছু করতে হলে, আমরা একে শুধু বলি, “হও, ”এবং তা হয়ে যায়।"],
  "16:41": ["And those who emigrated for Allah after they were wronged — We will surely settle them in this nearer life in a good place, and the reward of the hereafter is greater — if only they knew.", "যারা আল্লাহর নিমিত্তে দেশ ত্যাগ করেছিল, কারন তারা নির্যাতিত হয়েছিল, আমরা অবশ্যই উদারভাবে এই জীবনে তাদেরকে তা পুরন করে দেব, এবং পরকালের প্রতিদান আরও অধিক, যদি তারা শুধু জানত।"],
  "16:42": ["Those who were sabir and upon their Rabb rely.", "এটা এ কারনে যে তারা অবিচলভাবে অধ্যবসায়ী, এবং তাদের প্রভুর প্রতি তারা আস্থা রাখে।"],
  "16:43": ["And We sent before you only men to whom We revealed. So ask the people of the reminder, if you do not know.", "আমরা তোমার আগে মানুষ ছাড়া কারো কাছে অনুপ্রেরনা পাঠাইনি। তাদের জিজ্ঞেস করো যারা ঐশীগ্রন্থ জানে, যদি তোমরা না জানো।"],
  "16:44": ["With clear proofs and the Kitab. And We sent down to you the reminder, so that you may make clear to people what was sent down to them, and so that they may reflect.", "আমরা তাদেরকে প্রমানাদি এবং ঐশীগ্রন্থাবলী দিয়েছিলাম। এবং আমরা তোমার কাছে এই বার্তা অবতীর্ণ করেছি, লোকদের জন্য সবকিছু ঘোষণা করতে যা তাদের কাছে অবতীর্ণ হয়, সম্ভবত তারা অনুধাবন করবে।\""],
  "16:45": ["Do those who planned the evil deeds feel secure that Allah will not sink them into the earth, or that the punishment will not come to them from where they do not perceive?", "যারা মন্দ পরিকল্পনা করেছিল তারা কি নিশ্চয়তা দিয়েছিল যে আল্লাহ পৃথিবীকে দিয়ে তাদের গ্রাস করাবেন না, অথবা শাস্তি তাদের কাছে এসে যাবে না যখন তারা খুব কমই প্রত্যাশা করে?"],
  "16:46": ["Or that Allah will not seize them in their going back and forth? And then they cannot escape.", "এটা তাদের আঘাত করতে পারে যখন তারা ঘুমন্ত; তারা কখনো পালাতে পারবে না।"],
  "16:47": ["Or that Allah will not seize them with a gradual dread? Yet your Rabb is gentle in mercy, merciful.", "অথবা এটা তাদের আঘাত করতে পারে যখন তারা ভয়ে ভয়ে এর প্রত্যাশা করছে। তোমাদের প্রভু করুণাময়, পরম দয়ালু।"],
  "16:48": ["Have they not looked at what Allah created — how its shadows turn from the right and from the left, prostrating to Allah in humility?", "তারা কি আল্লাহর সৃষ্ট সব কিছু দেখেনি? তাদের ছায়া তাদেরকে ঘিরে থাকে ডানে এবং বায়ে, আল্লাহর প্রতি পরিপূর্ণ সমর্পিত হয়ে, এবং সেচ্ছায়।"],
  "16:49": ["And to Allah prostrates whatever is in the heavens and whatever is in the earth of every creature, and the malakat, and they do not act arrogantly.", "আল্লাহকে সেজদা করে আকাশমণ্ডলীর সবকিছু ও পৃথিবীর সবকিছু-সকল সৃষ্টি- এবং ফেরেশতারাও; সামান্যতম ঔদ্ধত্য ছাড়াই।"],
  "16:50": ["They fear their Rabb above them and do what they are commanded.", "তারা তাদের প্রভুকে ভক্তি করে,  যিনি তাদের অনেক উপরে, এবং তারা করে যা করতে তারা আদিষ্ট হয়।"],
  "16:51": ["And Allah said, \"Do not take two deities. Indeed Allah is one deity, so of Me alone be in awe.\"", "আল্লাহ ঘোষণা করেছেনঃ “দুই উপাস্যের উপাসনা করো না; উপাস্য একজনই। তোমরা একমাত্র আমার উপাসনা করবে”।"],
  "16:52": ["And to Allah belongs whatever is in the heavens and the earth, and to Allah is due the constant duty. So is it other than Allah that you fear?", "আকাশমণ্ডলী ও পৃথিবীর সবকিছু তাঁর এবং সেজন্য, ধর্ম সম্পূর্ণরূপে একমাত্র তাঁর প্রতি উৎসর্গকৃত হবে। তোমরা কি আল্লাহ ছাড়া অন্যকারো উপাসনা করবে?"],
  "16:53": ["And whatever blessing is upon you is from Allah; then when harm touches you, to Allah you cry out.", "যেকোন অনুগ্রহ তোমরা উপভোগ করো তা আল্লাহর পক্ষ থেকে। এরপরও, যখনই কোন দুর্দশা তোমরা টেনে আনো সাথে সাথেই তোমরা তাঁর নিকট অভিযোগ করো।"],
  "16:54": ["Then when the harm is uncovered from you, at once a group of you associate others with their Rabb.", "এরপরও, যখনি তিনি তোমাদের দুর্দশা দূর করেন, তোমাদের কেউ কেউ অংশীদার উপাসনায় ফিরে যায়।"],
  "16:55": ["So as to disbelieve what We have given them. Enjoy yourselves; soon you will know.", "আমরা তাদেরকে যা দিয়েছি তাতে তাদের অবিশ্বাস করতে দাও। চালিয়ে যাও এবং সাময়িকভাবে উপভোগ করো; নিশ্চয় তোমরা দেখবে।"],
  "16:56": ["And they allot a share of what We provided them to what they do not know. By Allah, you will surely be asked about what you fabricate.", "তাদের অজ্ঞতা বশত: স্থাপন করা অংশীদারদের জন্য তারা নির্ধারণ করে,  খাদ্যদ্রব্যের একটি অংশ যা আমরা তাদেরকে দিয়েছি। আল্লাহর শপথ, তোমাদের নব-উদ্ভাবনের জন্য তোমাদেরকে হিসাব দিতে হবে।"],
  "16:57": ["And they assign daughters to Allah — glorified is Allah — while they have whatever they desire.", "তারা এমনকি আল্লাহর জন্য কন্যা সন্তানদের নির্ধারণ করে, মহিমা তাঁরই, যখন তারা নিজেদের জন্য অগ্রাধিকার দেয় যা তারা পছন্দ করে।"],
  "16:58": ["And when one of them is given tidings of a female, his face darkens and he is holding it in.", "যখন তাদের কেউ কন্যা সন্তানপ্রাপ্ত হয়, তাঁর মুখমণ্ডল দূর্বিষহ দুঃখে কালো হয়ে যায়।"],
  "16:59": ["He hides from his people because of the evil of what he was given tidings of: shall he keep it in humiliation, or bury it in the dust? Alas, how evil is what they decide!", "লজ্জায়, সে লোকদের থেকে লুকায়, তাকে দেয়া খারাপ সংবাদটির কারণে। সে এমনকি চিন্তা করে: সে কি শিশুটিকে অনিচ্ছাকৃতভাবে ধরে রাখবে, নাকি তাকে ধুলোয় পুঁতে দেবে? সত্যিই তাদের বিচার কতই না দুঃখজনক।"],
  "16:60": ["For those who do not believe in the hereafter is the likening of evil, and to Allah belongs the highest likening; and Allah is the mighty in power, the wise.", "যারা পরকালে বিশ্বাস করে না তারা নিকৃষ্ট উদাহরণ স্থাপন করে, যখন সবচেয়ে মহৎ উদাহরণ আল্লাহর। তিনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "16:61": ["And if Allah were to take people to task for their wrongdoing, Allah would not leave on it a single moving creature; but Allah defers them to an appointed term. And when their term comes, they cannot delay it by an hour nor advance it.", "যদি আল্লাহ লোকদেরকে তাদের সীমালঙ্ঘনের জন্য শাস্তি দিতেন,  তিনি পৃথিবীর প্রত্যেক সৃষ্টি ধ্বংস করে দিতেন। কিন্তু তিনি তাদেরকে একটি নির্দিষ্ট, পূর্বনির্ধারিত সময়ের জন্য অবকাশ দেন। একবার তাদের অন্তবর্তীকাল শেষ হলে, তারা এক ঘণ্টার জন্য তা বিলম্বিত করতে পারে না, না ত্বরান্বিত করতে পারে।"],
  "16:62": ["And they assign to Allah what they dislike, while their tongues describe the lie that the good is theirs. Without doubt, theirs is the fire, and they are ones who fall short.", "তারা আল্লাহর প্রতি আরোপ করে যা তারা নিজেদের জন্য অপছন্দ করে, এরপর তারা নিজেদের মুখে মিথ্যা উচ্চারণ করে যে তারা সৎ-কর্মী! নিঃসন্দেহে, তারা অর্জন করেছে নরক, তাদের বিদ্রোহের কারনে।"],
  "16:63": ["By Allah, We sent to communities before you, but Shaytan adorned their deeds for them; so today he is their protector, and theirs is a painful punishment.", "আল্লাহর শপথ, তোমার পূর্বে সম্প্রদায় গুলোর কাছে আমরা (বার্তাবাহক) পাঠিয়েছি, কিন্তু শয়তান তাদের চোখে তাদের কাজকে সুসজ্জিত করে দিয়েছিল। পরিনামে, সে এখন তাদের প্রভু, এবং তারা টেনে এনেছে এক যন্ত্রণাদায়ক শাস্তি।"],
  "16:64": ["And We sent down upon you the Kitab only so that you may make clear to them that about which they differ, and as guidance and mercy for people who believe.", "আমরা তোমার কাছে এই ঐশীগ্রন্থ প্রকাশ করেছি, তাদেরকে দেখাতে যাতে তারা মতবিরোধ করে, এবং লোকদের জন্য পথ নির্দেশনা ও দয়া প্রদান করতে যারা বিশ্বাস করে।"],
  "16:65": ["And Allah sends down water from the heaven and revives with it the earth after its death. Indeed in that is an aya for people who hear.", "আল্লাহ ভূমিকে এর মৃত্যুর পর পুনরুজ্জীবিত করতে আকাশ থেকে পানি বর্ষণ করেন। এটি (যথেষ্ট) প্রমান হওয়া উচিত লোকদের জন্য যারা শোনে।"],
  "16:66": ["And indeed in the cattle there is a lesson for you: We give you to drink from what is in their bellies, from between the dregs and the blood — pure milk, palatable to the drinkers.", "এবং গৃহপালিত পশুতে তোমাদের জন্য শিক্ষা রয়েছেঃ আমরা তাদের পেট থেকে তোমাদের পানীয় সরবরাহ করিঃ পরিপাককৃত খাদ্য এবং রক্তের মধ্য থেকে, তোমরা বিশুদ্ধ দুধ পাও, পানকারীদের জন্য সুস্বাদু।"],
  "16:67": ["And from the fruits of the palms and the grapes you take from it a stupor-drink and a good provision. Indeed in that is an aya for people who understand.", "এবং খেজুর গাছ ও আঙুরের ফল থেকে তোমরা মাদকদ্রব্য উৎপন্ন করো, সেই সাথে ভাল খাদ্যদ্রব্য। এটি (যথেষ্ট) প্রমান হওয়া উচিত লোকদের জন্য যারা বোঝে।"],
  "16:68": ["And your Rabb revealed to the bee: \"Take for yourself dwellings in the mountains, and in the trees, and in what they build.\"", "এবং তোমার প্রভু মৌমাছিদের অনুপ্রাণিত করলেনঃ পর্বতসমূহে ও গাছে ঘর বানাও, এবং (মৌচাকে) তারা তোমাদের জন্য তৈরি করে।"],
  "16:69": ["Then eat of every fruit and thread through the paths of your Rabb, made submissive. From their bellies comes out a drink of varied colors, in which there is healing for people. Indeed in that is an aya for people who reflect.", "এরপর সকল প্রকার ফল থেকে খাও, তোমার প্রভুর নকশা অনুসরণ করে, যথাযথভাবে। তাদের পেট থেকে বিভিন্ন রঙের পানীয় বেরিয়ে আসে, যাতে লোকদের জন্য রয়েছে রোগের প্রতিকার। এটি (যথেষ্ট) প্রমান হওয়া উচিত লোকদের জন্য যারা অনুধাবন করে।"],
  "16:70": ["And Allah created you, then takes you in death; and among you is one turned back to the most abject of age, so that one knows nothing after having known. Indeed Allah is knowing, powerful.", "আল্লাহ তোমাদের সৃষ্টি করেছেন, এরপর তিনি তোমাদের জীবনের পরিসমাপ্তি ঘটান। তিনি তোমাদের কতককে বৃদ্ধ বয়স পর্যন্ত বাঁচিয়ে রাখেন, শুধুমাত্র দেখাতে যে তাদের জ্ঞান অর্জন করতে পারার একটি সীমা আছে। আল্লাহ সর্বজ্ঞ, সর্বশক্তিমান।"],
  "16:71": ["And Allah has favored some of you over others in provision; yet those who were favored do not hand back their provision to those whom their right hands possess so that they would be equal in it. So do they deny the blessing of Allah?", "আল্লাহ তোমাদের কাউকে কাউকে অন্যদের থেকে অধিক দিয়েছেন। যাদেরকে প্রচুর দেয়া হয়েছে তারা কখনো তাদের অধিনস্তদেরকে তাদের সম্পদ এমন পরিমানে দেবে না যে তারা তাদের অংশীদার হয়ে যায়। তারা কি আল্লাহর অনুগ্রহসমূহ ত্যাগ করবে?"],
  "16:72": ["And Allah made for you from yourselves zawj, and made for you from your zawj children and grandchildren, and provided you from the good things. So do they believe in falsehood, and do they disbelieve the blessing of Allah?", "এবং আল্লাহ তোমাদের জন্য তোমাদের নিজেদের মধ্য থেকে সহধর্মী/সহধর্মীনি সৃষ্টি করেছেন, এবং তোমাদের সহধর্মী/সহধর্মীনি থেকে তোমাদের জন্য সন্তানাদি এবং নাতি-নাতনি সৃষ্টি করেছেন, এবং তোমাদের জন্য প্রদান করেছেন উত্তাম রিযিক। তাদের কি উচিত মিথ্যায় বিশ্বাস করা, এবং আল্লাহর অনুগ্রহসমূহে অকৃতজ্ঞ হওয়া?"],
  "16:73": ["And they serve besides Allah that which has no power over any provision for them from the heavens and the earth, nor are they able.", "এরপরও, তারা আল্লাহর পাশে উপাসনা করে তার, যা না পৃথিবীতে, না আকাশমণ্ডলীতে তাদের জন্য কোন রিজিকের ব্যবস্তা করে, না তাদের কোন কিছু দিতে পারে।"],
  "16:74": ["So do not strike likenesses for Allah. Indeed Allah knows, and you do not know.", "অতএব, আল্লাহর জন্য কোন উদাহরণ দিও না; আল্লাহ জানেন যখন তোমরা জানো না।"],
  "16:75": ["Allah strikes a parable: a servant owned, with power over nothing, and one whom We provided from Us a good provision — and that one spends from it secretly and openly. Are they equal? Praise be to Allah. Rather, most of them do not know.", "আল্লাহ একজন দাসের উদাহরণ দেন যে মালিকানাধীন, এবং পুরোপুরি ক্ষমতাহীন, তার সাথে তুলনা করে যাকে আমরা ভালো জীবিকা দিয়ে সৌভাগ্যশালী করেছি, যা থেকে সে দান করে গোপনে ও প্রকাশ্যে। তারা কি সমান? প্রশংসা আল্লাহর, তাদের অধিকাংশ জানে না।"],
  "16:76": ["And Allah strikes a parable of two men: one of them is dumb, with power over nothing, and is a burden upon his master — wherever he directs him he brings no good. Is he equal to the one who commands justice and is on a straight path?", "এবং আল্লাহ উদাহরণ দেন দুজন মানুষেরঃ একজন নির্বোধ, কোনকিছু করতে সক্ষম নয়, পুরোপুরি তার মালিকের উপর নির্ভরশীল- যে পথেই সে তাকে নির্দেশ দেয়, সে ভাল কিছু করতে পারে না। সে কি তার সমান যে ন্যায়পরায়নতার সাথে শাসন করে, এবং সঠিক পথপ্রাপ্ত?"],
  "16:77": ["And to Allah belongs the hidden realm of the heavens and the earth, and the command of the hour is but like the blink of an eye, or it is nearer. Indeed Allah has power over everything.", "আকাশমণ্ডলী ও পৃথিবীর ভবিষ্যত আল্লাহর অধীন। যে পর্যন্ত তিনি সম্পর্কিত, বিশ্বের পরিসমাপ্তি (সেই ঘণ্টা) তো চোখের এক পলক দূরে, অথবা আরও কাছে। আল্লাহ সর্বশক্তিমান।"],
  "16:78": ["And Allah brought you out from the bellies of your mothers knowing nothing, and made for you hearing, and sights, and fu'ad, so that you may give thanks.", "আল্লাহ মায়ের পেট থেকে তোমাদের বের করেন যখন কিছুই জানতে না, এবং তিনি তোমাদেরকে দিয়েছেন শ্রবণ শক্তি,  দৃষ্টি শক্তি, এবং মস্তিষ্ক, যাতে তোমরা কৃতজ্ঞ হও।"],
  "16:79": ["Do they not see the birds, subjected in the air of the heaven? Nothing holds them up except Allah. Indeed in that are ayat for people who believe.", "তারা কি আকাশের বায়ুমণ্ডলে পাখিদের উড়তে দেখে না? আল্লাহ ছাড়া কেউ এদেরকে ঊর্ধ্বে বাতাসে ধরে রাখে না। এটি লোকদের জন্য (যথেষ্ট) প্রমান হওয়া উচিত যারা বিশ্বাস করে।"],
  "16:80": ["And Allah made for you from your houses a dwelling, and made for you from the hides of the cattle houses that you find light on the day of your moving and the day of your staying; and from their wool, and their hair, and their fur — furnishings and enjoyment for a time.", "এবং আল্লাহ তোমাদের জন্য দিয়েছেন স্থির ঘর-বাড়ি যেখানে তোমরা বাস করতে পারো। এবং তিনি তোমাদের জন্য দিয়েছেন গবাদিপশুর চামড়া থেকে তৈরি বহনযোগ্য ঘর-বাড়ি, যেন তোমরা সেগুলো ব্যবহার করতে পারো যখন তোমরা ভ্রমন করো, এবং যখন তোমরা অবস্থান নাও। এবং সেগুলোর পশম, লোমশ চামড়া এবং চুল থেকে তোমরা তৈরি করো আসবাবপত্র এবং বিলাসদ্রব্য, কিছুকালের জন্য।"],
  "16:81": ["And Allah made for you, from what Allah created, shade, and made for you from the mountains shelters, and made for you garments that shield you from the heat, and garments that shield you from your dread. Thus does Allah complete the blessing upon you, so that you may submit.", "এবং আল্লাহ তোমাদের জন্য তার সৃষ্ট জিনিসের মাধ্যমে ছায়া দিয়েছেন, এবং তোমাদের জন্য আশ্রয় দিয়েছেন পর্বতে, এবং তোমাদের জন্য পোশাক দিয়েছে্ন যা তোমাদের তাপ থেকে রক্ষা করে, এবং পোশাক যা তোমাদের রক্ষা করে যখন তোমরা যুদ্ধে লড়াই করো। তিনি এভাবে তোমাদের প্রতি তাঁর অনুগ্রহ পূর্ণ করেন।"],
  "16:82": ["So if they turn away, upon you is only the clear delivery.", "যদি তারা এরপরও মুখ ফিরিয়ে নেয়, তবে তোমার একমাত্র কাজ শুধু (বার্তা) পৌঁছে দেয়া।"],
  "16:83": ["They recognize the blessing of Allah, then they disbelieve it; and most of them are the kafirin.", "তারা আল্লাহর অনুগ্রহগুলো সম্পূর্ণ রুপে চেনে, এরপর সেগুলো অস্বীকার করে; তাদের অধিকাংশ অবিশ্বাসী।"],
  "16:84": ["And on the day We raise from every community a witness, then permission will not be granted to those who disbelieved, nor will they be allowed to make amends.", "সে দিন আসবে যখন আমি প্রত্যেক সম্প্রদায় থেকে একজন সাক্ষী উঠাবো, তখন যারা অবিশ্বাস করতো তারা (কথা বলার) অনুমতি পাবে না, না তারা ক্ষমা পাবে।"],
  "16:85": ["And when those who wronged see the punishment, it will not be lightened for them, nor will they be granted respite.", "যারা অবিশ্বাস করেছিল তারা একবার যখন শাস্তি দেখবে, তা খুব দেরি হয়ে যাবে; এটা তাদের জন্য কমানো হবে না, না তারা অবকাশ পাবে।"],
  "16:86": ["And when those who associated see their associates, they will say, \"Our Rabb, these are our associates whom we used to call upon besides You.\" But the word will be cast to them: \"You are indeed liars.\"", "এবং যারা অংশীদার উপাসনা করত ওরা যখন তাদের উপাস্যদের দেখবে, তারা বলবে, “আমাদের প্রভু, এরাই সেই উপাস্যরা যাদের আমরা আপনার পাশে স্থাপন করেছিলাম”। উপাস্যরা তখন তাদের মুখমুখি হবে এবং বলবে, “তোমরা মিথ্যাবাদী”।"],
  "16:87": ["And they will cast the submission to Allah that day, and lost from them will be what they used to fabricate.", "তারা সে দিন সম্পূর্ণরুপে আল্লাহর কাছে আত্মসমর্পণ করবে, এবং যে উপাস্যদের তারা উদ্ভাবন করেছিল তারা তাদের প্রত্যাখ্যান করবে।"],
  "16:88": ["Those who disbelieved and turned away from the path of Allah — We will increase them punishment upon punishment for what they used to corrupt.", "যারা অবিশ্বাস করে এবং আল্লাহর পথে বাধা দেয়, আমরা আরও শাস্তি যোগ করে তাদের শাস্তি বাড়িয়ে দেই, তাদের সীমালঙ্ঘনের কারনে।"],
  "16:89": ["And on the day We raise in every community a witness against them from among themselves, and We bring you as a witness against these. And We sent down upon you the Kitab, a clarification of everything, and guidance, and mercy, and glad tidings for those who submit.", "সে দিন আসবে যখন আমরা প্রত্যেক সম্প্রদায় থেকে একজন সাক্ষী উঠাব তাদেরই মধ্য থেকে, এবং তোমাকে আনব এই লোকদের সাক্ষী হিসাবে। আমরা তোমার কাছে এই গ্রন্থ প্রকাশ করেছি আত্মসমর্পণকারীদের জন্য প্রদান করতে সবকিছুর ব্যাখ্যা, এবং পথ নির্দেশনা, এবং দয়া, এবং সুসংবাদ।"],
  "16:90": ["Indeed Allah commands justice, and excellence, and giving to the near of kin, and forbids obscenity, and the rejected, and transgression. Allah admonishes you, so that you may remember.", "আল্লাহ উপদেশ দেন ন্যায়পরায়ণতা, দান, এবং আত্মীয়স্বজনদের প্রতি দৃষ্টি দেয়ার। এবং নিষেধ করেন মন্দ, অনৈতিকতা, এবং সীমালঙ্ঘন। তিনি তোমাদের জ্ঞান দান করেন, যাতে তোমরা সতর্ক হও।"],
  "16:91": ["And fulfill the pledge of Allah when you pledge, and do not unbind the oaths after confirming them, seeing that you have made Allah your surety. Indeed Allah knows what you do.", "তোমরা আল্লাহর সাথে তোমাদের চুক্তি পূর্ণ করবে যখন তোমরা এমন কোন চুক্তি করো। তোমরা প্রতিজ্ঞা ভঙ্গ করবে না আল্লাহর নামে সেগুলো পালনের শপথ করার পর, কারন তোমরা আল্লাহকে তোমাদের জামিনদার করেছ। আল্লাহ জানেন সবকিছু যা তোমরা করো।"],
  "16:92": ["And do not be like the imra'a who unravels her yarn, after it was strong, into loose strands, taking your oaths as deception among you because one community is more numerous than another. Allah only tests you thereby, and Allah will surely make clear to you on the Day of Rising what you used to differ about.", "সেই বুননকারিণী শিল্পীর মতো হয়ো না যে তার মজবুত বুননের পাঁক খুলে তুচ্ছ সুতার স্তুপে পরিনত করে। এটাই তোমাদের উদাহরণ যদি তোমরা একে অপরের কাছ থেকে সুযোগ নিতে তোমাদের প্রতিজ্ঞার অপব্যবহার করো। এক দল অন্য দলের চেয়ে বড় হোক বা না হোক, আল্লাহ এভাবে তোমাদের পরীক্ষা করেন। তিনি নিশ্চয় পুনরুত্থান দিনে তোমাদের দেখাবেন সে সবকিছু যাতে তোমরা বিবাদ করেছিলে।"],
  "16:93": ["And if Allah willed, Allah would have made you one community; but Allah lets stray whom Allah wills and guides whom Allah wills. And you will surely be asked about what you used to do.", "আল্লাহ যদি চাইতেন, তিনি তোমাদের এক  ধর্মগোষ্ঠী করতে পারতেন। কিন্তু তিনি পথভ্রষ্ট করেন যেকেউ বিপথে যেতে পছন্দ করে, এবং তিনি পথপ্রদর্শন করেন যেকেউ সুপথপ্রাপ্ত হতে চায়। তোমাদের অবশ্যই প্রশ্ন করা হবে সে সব কিছু সম্পর্কে যা তোমরা করেছ।"],
  "16:94": ["And do not take your oaths as deception among you, lest a foot slip after being firm, and you taste the evil for having turned away from the path of Allah; and for you is a tremendous punishment.", "তোমাদের মধ্যকার প্রতিজ্ঞার অপব্যবহার করো না, পাছে তোমরা পিছলে যাও সুদৃড় অবস্থান পাবার পর, এরপর তোমরা দুর্দশা টেনে আনো। এমনি পরিণাম আল্লাহর পথে বাঁধা দেবার (মন্দ উদাহরন স্থাপনের জন্য); তোমরা এক ভয়ানক শাস্তি টেনে আনো।"],
  "16:95": ["And do not exchange the pledge of Allah for a small price. Indeed what is with Allah is better for you, if you knew.", "অল্পতেই আল্লাহর সামনে তোমাদের করা প্রতিজ্ঞা বিকিয়ে দিয়না। আল্লাহর কাছে তোমাদের জন্য যা আছে তা অনেক উত্তম, যদি শুধু তোমরা জানতে।"],
  "16:96": ["What is with you runs out, and what is with Allah remains. And We will surely repay those who were sabir their reward with the best of what they used to do.", "যা তোমাদের কাছে আছে তা শেষ হয়ে যায়, কিন্তু আল্লাহর কাছে যা আছে তা চিরকাল রয়ে যায়। আমরা অবশ্যই তাদের পুরস্কৃত করবো যারা অবিচলভাবে অটল; আমরা তাদের প্রতিদান দেব তাদের সৎ কর্মের জন্য।"],
  "16:97": ["Whoever does a salih deed, whether male or female, while believing — We will surely give that one a goodly life, and We will surely repay them their reward with the best of what they used to do.", "যেকেউ সৎকর্ম করে, পুরুষ হোক বা নারী, বিশ্বাসী অবস্থায়, আমরা অবশ্যই তাদেরকে এই দুনিয়ায় একটি সুখী জীবন দেব, এবং (পুনরুত্থান দিনে)  আমরা অবশ্যই তাদের সৎকর্মের জন্য পূর্ণ প্রতিদান পরিশোধ করবো।"],
  "16:98": ["So when you recite the recitation, seek refuge with Allah from Shaytan, the stoned one.", "যখন তুমি কুরআন পড়ো, তুমি আল্লাহর কাছে আশ্রয় প্রার্থনা করবে বিতাড়িত শয়তান থেকে।"],
  "16:99": ["Indeed Shaytan has no warrant over those who believe and rely upon their Rabb.", "তার কোনও শক্তি নাই ওদের উপর যারা বিশ্বাস করে এবং তাদের প্রভুর প্রতি আস্থা রাখে।"],
  "16:100": ["Shaytan's warrant is only over those who take Shaytan as protector and those who associate others with him.", "তার ক্ষমতা ওদের উপর সীমাবদ্ধ যারা তাকে তাদের মনিব হিসেবে পছন্দ করে, যারা তাকে পছন্দ করে তাদের উপাস্য হিসাবে।"],
  "16:101": ["And when We substitute an aya in place of an aya — and Allah knows best what Allah sends down — they say, \"You are only a fabricator.\" Rather, most of them do not know.", "যখন আমরা কোন প্রকাশনাকে আরেকটির জায়গায় প্রতিস্থাপন করি, এবং আল্লাহ পূর্ণ অবগত যা তিনি প্রকাশ করেন, তারা বলে, “এটি তুমি রচনা করেছ!”প্রকৃতপক্ষে, তাদের বেশির ভাগ জানে না।"],
  "16:102": ["Say, \"The holy spirit sent it down from your Rabb in truth, to steady those who believe, and as guidance and glad tidings for those who submit.\"", "বল, “পবিত্র রূহ তোমার প্রভুর পক্ষ থেকে এটি অবতীর্ন করেছে, সত্যের সাথে, তাদের আশস্ত করতে যারা বিশ্বাস করে, এবং আত্মসমর্পণকারীদের জন্য আলোকবর্তিকা ও সুসংবাদ দিতে।"],
  "16:103": ["And We surely know that they say, \"It is only a human who teaches him.\" The tongue of the one to whom they incline is foreign, while this is a clear Arabic tongue.", "আমরা সম্পূর্ণ অবগত যে তারা বলে, “একজন মানুষ তাকে শিক্ষা দিচ্ছে!” তাদের ইঙ্গিত করা উৎসের ভাষা আরবি নয়, এবং এটি নিখুঁত আরবি ভাষা।"],
  "16:104": ["Indeed those who do not believe in the ayat of Allah — Allah does not guide them, and theirs is a painful punishment.", "নিশ্চয়, যারা আল্লাহর প্রকাশনায় বিশ্বাস করে না, আল্লাহ তাদের সুপথপ্রাপ্ত করেন না। তারা টেনে এনেছে এক যন্ত্রণাদায়ক শাস্তি।"],
  "16:105": ["Only those who do not believe in the ayat of Allah fabricate the lie, and those are the kazibin.", "তারাই কেবল মিথ্যা মতবাদ বানায় যারা আল্লাহর প্রকাশনাবলিতে বিশ্বাস করে না। তারাই আসল মিথ্যাবাদী।"],
  "16:106": ["Whoever disbelieves in Allah after their faith — except one who is compelled while their heart is settled in faith — but whoever opens their chest to disbelief, upon those is wrath from Allah, and theirs is a tremendous punishment.", "যারা আল্লাহতে অবিশ্বাস করে, বিশ্বাস অর্জন করার পর, এবং অবিশ্বাসে পূর্ণ সন্তুষ্ট হয়ে যায়, তারা আল্লাহর অভিশাপ অর্জন করেছে। কেবল তারাই ক্ষমা পেতে পারে অবিশ্বাস স্বীকার করার জন্য যাদের উপর বল প্রয়োগ করা হয়, যখন তাদের হৃদয় বিশ্বাসে পূর্ণ।"],
  "16:107": ["That is because they preferred the nearer life over the hereafter, and because Allah does not guide the committing kufr people.", "এর কারন এই যে তারা এই জীবনকে পরকালের উপর প্রাধান্য দিয়েছে, এবং আল্লাহ এমন অবিশ্বাসী লোকদের পথপ্রদর্শণ করেন না।"],
  "16:108": ["Those are the ones over whose hearts, and hearing, and sight Allah has set a seal; and those are the unmindful.", "এরাই তারা যাদের হৃদয়ে, এবং যাদের শ্রবণশক্তিতে, এবং যাদের দৃষ্টিশক্তিতে আল্লাহ মোহর মেরে দিয়েছেন। ফলস্বরূপ, তারা অসচেতন থাকে।"],
  "16:109": ["Without doubt, in the hereafter they are the khasirin.", "কোন সন্দেহ নেই, তারা পরকালে ক্ষতিগ্রস্ত হবে।"],
  "16:110": ["Then indeed your Rabb — for those who emigrated after they were tried, then strove and were sabir — indeed your Rabb after that is forgiving, merciful.", "ওদের ক্ষেত্রে যারা নিপীড়নের কারনে দেশ ত্যাগ করে, এরপর সংগ্রাম চালিয়ে যায় এবং অবিচলতার সাথে অটল থাকে, তোমরা প্রভু, এই সবের কারনে, ক্ষমাশীল, পরম দয়ালু।"],
  "16:111": ["A day when every nafs comes disputing for itself, and every nafs is paid in full for what it did, and they are not wronged.", "সে দিন আসবে যখন প্রত্যেক আত্মা এর নিজের উকিল হিসেবে দায়িত্ব পালন করবে। এবং প্রত্যেক আত্মা পুরোপুরি মূল্য পাবে যা কিছু সে করেছে, সমান্যতম অবিচার ছাড়া।"],
  "16:112": ["And Allah strikes a parable of a town that was secure and settled, its provision coming to it in plenty from every place; then it was ungrateful for the blessings of Allah, so Allah made it taste the garment of hunger and of fear for what they used to do.", "আল্লাহ একটি জনপদের উদাহরণ দেন যা ছিল নিরাপদ ও সমৃদ্ধশালী, সেখানে সব জায়গা থেকে খাদ্যসম্ভার আসতো। কিন্তু এরপর, তা আল্লাহর অনুগ্রহের প্রতি অকৃতজ্ঞ হয়ে পড়লো। পরিনামে, আল্লাহ তাদেরকে অনাহার ও নিরাপত্তাহীনতার কষ্ট আস্বাদন করালেন। এমনই হচ্ছে তাদের কৃতকর্মের প্রতিদান।"],
  "16:113": ["And a Rasul from among them surely came to them, but they denied him, so the punishment seized them while they were wrongdoers.", "তাদের মধ্য থেকে একজন বার্তাবাহক তাদের কাছে গিয়েছিল, কিন্তু তারা তাকে প্রত্যাখ্যান করলো। ফলস্বরূপ, তাদের সীমালঙ্ঘনের জন্য শাস্তি তাদের আঘাত করেছিল।"],
  "16:114": ["So eat of what Allah has provided you, lawful and good, and give thanks for the blessing of Allah, if it is Allah alone that you serve.", "অতএব, তোমরা আল্লাহর দেয়া সব খাদ্যসামগ্রী থেকে খাবে যা আইনসিদ্ধ ও ভালো, এবং আল্লাহর অনুগ্রহের প্রতি কৃতজ্ঞ হও, যদি তোমরা কেবল তাঁরই উপাসনা করো।"],
  "16:115": ["Forbidden to you are only the carrion, and the blood, and the flesh of the pig, and what has been dedicated to other than Allah. But whoever is compelled, neither desiring nor transgressing — indeed Allah is forgiving, merciful.", "তিনি শুধু তোমাদের জন্য নিষিদ্ধ করেন মৃত পশু, রক্ত, শূকরের মাংস, এবং যে খাদ্য আল্লাহ ছাড়া অন্য কারো প্রতি উৎসর্গ করা হয়। যদি কেউ (এগুলো খেতে) বাধ্য  হয়, ইচ্ছাকৃত বা বিদ্রোহী না হয়ে, তবে আল্লাহ ক্ষমাশীল, পরম করুণাময়।"],
  "16:116": ["And do not say, concerning what your tongues describe falsely, \"This is lawful and this is forbidden,\" so as to fabricate a lie against Allah. Indeed those who fabricate a lie against Allah will not attain success.", "তোমাদের নিজ মুখে তোমরা মিথ্যা বলবে না এ বলে যেঃ “এটা আইনসম্মত, এবং এটা বেআইনী,” মিথ্যা বানাতে এবং তা আল্লাহর প্রতি আরোপ করতে। নিশ্চয়, যারা মিথ্যা বানায় এবং তা আল্লাহর প্রতি আরোপ করে তারা কখনো সফল হবে না।"],
  "16:117": ["A brief enjoyment, and theirs is a painful punishment.", "তারা সাময়িক উপভোগ করে, এরপর ভোগ করে যন্ত্রণাদায়ক শাস্তি।"],
  "16:118": ["And as for those who were Yahud — We forbade them what We narrated to you before; and We did not wrong them, but they used to wrong themselves.", "ইহুদীদের জন্য, আমরা নিষিদ্ধ করেছিলাম পূর্বে যা তোমার কাছে আমরা বর্ণনা করেছি। তাদের ক্ষতি আমাদের দ্বারা হয়নি; তারাই তাদের নিজ আত্মার ক্ষতি করেছিল।"],
  "16:119": ["Then indeed your Rabb — for those who did evil in ignorance, then repented after that and made amends — indeed your Rabb after that is forgiving, merciful.", "তা সত্ত্বেও, তাদের ক্ষেত্রে যারা অজ্ঞতাবশত পাপে পতিত হয় এরপর অনুশোচনা করে ও সংশোধিত হয়, তোমার পালনকর্তা, এসবের পর, ক্ষমাশীল, পরম দয়ালু।"],
  "16:120": ["Indeed Ibrahim was a community in himself, devoted to Allah, upright, and not among those who associate.", "ইব্রাহীম নিশ্চয়ই আল্লাহর কাছে তার আত্মসমর্পণে ছিল এক দৃষ্টান্তস্থাপনকারী অগ্রদূত, একজন একেশ্বরবাদী যে কখনও অংশীদার উপাসনা করেনি।"],
  "16:121": ["Thankful for the blessings; Allah chose Ibrahim and guided Ibrahim to a straight path.", "যেহেতু সে তার প্রভুর অনুগ্রহের প্রতি কৃতজ্ঞ ছিল, তিনি তাকে পছন্দ করেছিলেন এবং তাকে পরিচালিত করেছিলেন এক সরল পথে।"],
  "16:122": ["And We gave Ibrahim goodness in this nearer life, and indeed in the hereafter Ibrahim is among the salihin.", "এই জীবনে আমরা তাকে সুখ দান করেছিলাম, এবং পরকালে সে সৎকর্মশীলদের সাথে থাকবে।"],
  "16:123": ["Then We revealed to you: \"Follow the way of Ibrahim, upright, and not among those who associate.\"", "এরপর (হে মুহাম্মদ) তোমাকে আমরা ইব্রাহীমের ধর্ম অনুসরণ করতে অনুপ্রাণিত করেছিলাম, একেশ্বরবাদী, সে কখনও প্রতিমা উপাসক ছিল না।"],
  "16:124": ["The sabbath was imposed only upon those who differed about it; and indeed your Rabb will judge between them on the Day of Rising concerning what they used to differ about.", "সাব্বাত শুধু ওদের জন্য আদেশ করা হয়েছিল, শেষ পর্যন্ত যারা (ইহুদী এবং খ্রিষ্টানরা) এটাকে বিতর্কিত করেছিল। তোমার প্রভুই সেই সত্ত্বা যিনি পুনরুত্থান দিনে তাদের বিতর্কের বিষয়ে তাদের বিচার করবেন।"],
  "16:125": ["Call to the path of your Rabb with wisdom and good admonition, and dispute with them in the best way. Indeed your Rabb knows best who strays from Allah's path, and knows best the guided.", "তুমি তোমার প্রভুর পথে প্রজ্ঞা ও সদয় জ্ঞানালোক দিয়ে আমন্ত্রন করবে, এবং তাদের সাথে বিতর্ক করবে সম্ভাব্য সর্বোত্তম পন্থায়। তোমার প্রভু সবথেকে ভালো জানেন কে তার পথ থেকে বিচ্যুত হয়েছে, এবং তিনি সবথেকে ভালো জানেন কারা সুপথপ্রাপ্ত।"],
  "16:126": ["And if you punish, then punish with the like of what you were punished with. But if you are sabir, it is better for the sabirin.", "এবং যদি তোমরা শাস্তি দাও, তোমরা সমতুল্য শাস্তি আরোপ করবে। কিন্তু যদি তোমরা ধৈর্য ধারন করো, এটি উত্তম হবে ধৈর্যশীলদের জন্য।"],
  "16:127": ["And be of the sabirin — and your patience is only by Allah — and do not grieve over them, nor be in straitness over what they plan.", "তুমি ধৈর্য ধারন করবে-এবং একমাত্র আল্লাহর সাহায্য দিয়ে তোমার  ধৈর্য ধারন সম্ভব। তাদের জন্য পরিতাপ করো না, এবং তাদের চক্রান্তে বিরক্ত হইও না।"],
  "16:128": ["Indeed Allah is with those who are mindful and those who do good.", "আল্লাহ তাদের সাথে আছেন যারা সৎ জীবন-যাপন করে, এবং যারা দানশীল।"],
  "17:1": ["Glory be to the One who journeyed by night with Allah's servant, from the Sacred Mosque to the Farthest Mosque, whose surroundings We blessed, to show him some of Our ayat. Truly, Allah is the All-Hearing, the All-Seeing.", "সর্বাধিক মহিমান্বিত সেই সত্ত্বা যিনি তাঁর বান্দা (মুহাম্মদ)-কে রাতের বেলায় তলব করেছিলেন, পবিত্র মসজিদ (মক্কা) থেকে সেজদার সবচেয়ে দূরতম স্থানে , যার চারপাশকে আমরা বরকতময় করেছি, তাকে আমাদের কিছু নিদর্শন দেখানোর জন্য। তিনি শ্রবণকারী, দর্শনকারী।"],
  "17:2": ["And We gave Musa the Kitab and made it a guidance for the Children of Israel: take no guardian besides Me.", "একইভাবে, আমরা মুসাকে ঐশীগ্রন্থ দিয়েছিলাম, এবং একে ইসরাইলের সন্তানদের জন্য একটি আলোকবর্তিকা করেছিলাম যেঃ “প্রভু এবং মনিব হিসাবে তোমরা আমার পাশে কোন অংশীদার স্থাপন করবে না”।"],
  "17:3": ["The offspring of those We carried with Nuh. Truly, that one was a thankful servant.", "তারা ছিল তাদের বংশধর যাদেরকে আমরা নুহের সাথে বহন করেছিলাম; সে ছিল একজন কৃতজ্ঞ বান্দা।"],
  "17:4": ["And We decreed to the Children of Israel in the Kitab: you will surely spread corruption on the earth twice, and you will surely rise to a great height.", "আমরা ঐশীগ্রন্থে ইসরাইলের সন্তানদের উদ্দেশ্যে বলেছিলামঃ “তোমরা পৃথিবীতে ঘোর পাপে লিপ্ত হবে, দু'বার। ঔদ্ধত্যের চরম শিখরে উন্নীত হওয়া হচ্ছে তোমাদের নিয়তি।"],
  "17:5": ["So when the promise of the first of the two came, We raised against you servants of Ours, possessors of severe might, and they roamed amidst the homes; and it was a promise fulfilled.", "“প্রথমবার যখন আসে, আমরা তোমাদের বিরুদ্ধে আমাদের বান্দাদের পাঠাবো যারা বিশাল শক্তির অধিকারী, এবং তারা তোমাদের ঘরে হানা দিবে। এটি একটি ভবিষ্যদ্বানী যা অবশ্যই ঘটবে।"],
  "17:6": ["Then We restored the turn to you over them, and We supplied you with wealth and children, and We made you a greater host.", "“পরবর্তীকালে, আমরা তাদের উপর তোমাদের পালা ঘুরিয়ে দেবো, এবং তোমাদের প্রচুর সম্পদ ও সন্তান দেবো; আমরা তোমাদের কর্তৃত্ব দেবো।"],
  "17:7": ["If you do good, you do good only for your own self; and if you do evil, it is only against it. So when the promise of the last comes, they will smite your faces and enter the Mosque just as they entered it the first time, and they will utterly raze what they overran.", "“যদি তোমরা সৎ-কর্ম করো, তোমরা সৎ-কর্ম করো নিজেদের ভালোর জন্যই, কিন্তু যদি তোমরা মন্দ-কর্ম করো তা নিজেদের ক্ষতির জন্যই করো।  সুতরাং, যখন দ্বিতীয ক্ষনটি আসে, তারা তোমাদের পরাজিত করবে এবং মসজিদে ঢুকবে, ঠিক যেরকম তারা প্রথমবার করেছিল। তারা তোমাদের সম্পন্ন করা সকল অর্জন মুছে ফেলবে।"],
  "17:8": ["It may be that your Rabb will have mercy on you; but if you return, We will return. And We made Hell a confinement for the kafirin.", "তোমাদের প্রভু তোমাদের প্রতি তাঁর দয়া বর্ষণ করেন। কিন্তু যদি তোমরা সীমালঙ্ঘনে ফিরে যাও, আমরা বিপরীতে শাস্তি দেবো। আমরা জাহান্নামকে অবিশ্বাসীদের জন্য চূড়ান্ত বাসস্থান হিসাবে নির্ধারণ করেছি।"],
  "17:9": ["Truly, this Recitation guides to that which is most upright, and gives good news to the muminin who do the good deeds, that for them is a great reward.", "এই কুরআন সর্বোত্তম পথ প্রদর্শন করে, এবং সুসংবাদ নিয়ে আসে বিশ্বাসীদের কাছে যারা সৎ-জীবন যাপন করে, যে তারা এক মহা পুরস্কারের যোগ্য হয়েছে।"],
  "17:10": ["And those who do not believe in the Last — We have prepared for them a painful punishment.", "আর তাদের ক্ষেত্রে যারা পরকালে অবিশ্বাস করে, আমরা তাদের জন্য এক যন্ত্রণাদায়ক শাস্তি প্রস্তুত রেখেছি।"],
  "17:11": ["And the human calls to evil with the same calling as to good; and the human was ever hasty.", "মানুষ প্রায়ই প্রার্থনা করে এমন কিছুর জন্য যা হয়তো তাকে কষ্ট দিবে, এই ভেবে যে সে ভালো কিছু প্রার্থনা করছে। মানুষ ধৈর্যহীন।"],
  "17:12": ["And We made the night and the day two ayat; then We blotted out the aya of the night and made the aya of the day sight-giving, so that you may seek bounty from your Rabb, and so that you may know the number of years and the reckoning; and everything We have detailed in detail.", "রাত ও দিনকে আমরা দু'টি নিদর্শন হিসেবে উপস্থাপন করেছি। রাতকে আমরা করেছি অন্ধকার, এবং দিনকে আলোকিত, যাতে তোমরা তাতে তোমাদের প্রভুর কাছ থেকে রিজিক অন্বেষণ করতে পারো। এটি তোমাদের জন্য একটি সময় নির্ধারণ পদ্ধতিও প্রতিষ্ঠা করে, এবং হিসাবের উপায়। আমরা এভাবে সবকিছু বিস্তারিত ব্যখ্যা করি।"],
  "17:13": ["And every human — We bound his omen to his neck; and on the Day of Rising We will bring out for him a Kitab he will find spread open.", "আমরা প্রত্যেক মানুষের ভাগ্য রেকর্ড করেছি; এটি তার গলায় আটকানো। পুনরুত্থান দিনে আমরা তার হাতে একটি রেকর্ড দেবো যা দেখা যায়।"],
  "17:14": ["Read your Kitab; your own self suffices you this day as a reckoner against you.", "পড়ো তোমার নিজের রেকর্ড। আজ, তুমি নিজেই নিজের হিসাবনিকাশের জন্য যথেষ্ট।"],
  "17:15": ["Whoever is guided is guided only for their own self, and whoever strays strays only against it; and no burden-bearer bears the burden of another; and We were never ones to punish until We raised a Rasul.", "যেকেউ সুপথপ্রাপ্ত, তার নিজের ভালোর জন্যই সুপথপ্রাপ্ত, এবং যেকেউ বিপথে যায় তার নিজের ক্ষতির জন্যই যায়। কোন পাপী অন্য কারো পাপ বহন করবে না। আমরা কখনোই শাস্তি দেই না আগে কোন বার্তাবাহক না পাঠিয়ে।"],
  "17:16": ["And when We want to destroy a town, We command its ones softened by ease, and they fasuqu in it; so the word comes true upon it, and We raze it utterly.", "যদি আমাদেরকে কোন সম্প্রদায় ধ্বংস করতে হয়, সেখানে আমরা নেতাদের ব্যাপক দুর্নীতি করতে দেই। যখনই তারা শাস্তির যোগ্য হয়, আমরা একে পুরোপুরি ধ্বংস করি।"],
  "17:17": ["And how many generations We destroyed after Nuh! And your Rabb suffices as knower, seer of the offenses of Allah's servants.", "নুহের পর আমরা অনেক প্রজন্ম ধ্বংস করেছি। তোমার প্রভু তাঁর বান্দাদের পাপের বোঝাপড়ায় সবচেয়ে দক্ষ। তিনি পূর্ণ জ্ঞাত, দ্রষ্টা।"],
  "17:18": ["Whoever wants the immediate, We hasten to them in it whatever We wish, for whomever We want; then We made Hell for them, to enter it, outcast and driven away.", "যেকেউ এই ক্ষণস্থায়ী জীবনকে তার অগ্রাধিকার হিসাবে পছন্দ করে, আমরা তাকে দ্রুত দিয়ে দেবো যা আমরা তাকে দেয়ার সিদ্ধান্ত নেই, এরপর আমরা তাকে জাহান্নামে ছেড়ে দেবো, যেখানে সে চিরকাল যন্ত্রণা ভোগ করে, ঘৃণিত ও পরাজিত হয়ে।"],
  "17:19": ["And whoever wants the Last and strives for it with its striving, while believing — those, their striving is thanked.", "তাদের ক্ষেত্রে যারা পরকালকে তাদের অগ্রাধিকার হিসাবে পছন্দ করে, এবং সৎকর্ম করে, বিশ্বাসী অবস্থায়, তাদের প্রচেষ্টার সমাদর করা হবে।"],
  "17:20": ["To each We extend, these and those, from the gift of your Rabb; and the gift of your Rabb was never withheld.", "আমরা তাদের প্রত্যেককে প্রদান করি; আমরা প্রদান করি ওদেরকে এবং এদেরকে তোমার প্রভুর  উদার দান থেকে। তোমার প্রভুর উদার দানশীলতা অফুরন্ত।"],
  "17:21": ["See how We favored some of them over others; and the Last has greater degrees and greater favoring.", "লক্ষ্য করো কেমন করে (এই দুনিয়াতে) কিছু লোককে আমরা অন্য লোকদের চেয়ে পছন্দ করি। পরকালে এই পার্থক্য অনেক বিশাল এবং অনেক বেশি তাৎপর্য পূর্ণ।"],
  "17:22": ["Set not up with Allah another ilah, lest you sit outcast and forsaken.", "তোমরা আল্লাহর পাশে অন্য কোন উপাস্য স্থাপন করবে না, পাছে তোমরা ঘৃণিত এবং অপদস্থ হয়ে পড়ো।"],
  "17:23": ["And your Rabb decreed that you worship none but Allah, and goodness to the two parents: if one or both of them reach old age with you, do not say to them \"ugh\", nor scold them, but speak to them a generous word.", "তোমার প্রভু হুকুম জারি করেছেন যে তোমরা তাকে ব্যতিত কারো উপাসনা করবে না, এবং তোমাদের পিতা-মাতার সম্মান করবে। যতকাল তাদের একজন বা উভয়জন বেঁচে থাকে, তোমরা কখনো তাদেরকে (বিরক্তির নূন্যতম প্রকাশ)  ‘উহ’ শব্দটি বলবে না, না তোমরা তাদের সাথে চিৎকার-চেঁচামেচি করবে; তোমরা তাদের সাথে অমায়িক আচরণ করবে।"],
  "17:24": ["And lower for them the wing of humility from mercy, and say: My Rabb, have mercy on them as they raised me when I was little.", "এবং তাদের জন্য বিনয়, এবং দয়ার বাহু বাড়িয়ে দাও, এবং বল, “আমার প্রভু, তাদের প্রতি দয়া করুন, কারন তারা আমাকে শৈশব থেকে লালন-পালন করেছেন”।"],
  "17:25": ["Your Rabb knows best what is in your selves; if you are good, then to the returners Allah is ever forgiving.", "তোমাদের প্রভু তোমাদের গভীরতম  চিন্তাগুলো সম্পর্কে পূর্ণ অবগত। যদি তোমরা সততা বজায় রাখো, তিনি তাদের প্রতি ক্ষমাশীল যারা অনুশোচনা করে।"],
  "17:26": ["And give the near kin their due, and the needy, and the wayfarer; and do not squander wastefully.", "তোমরা আত্মীয়-স্বজন, অভাবী, গরিব এবং মুসাফিরদের প্রাপ্য দান দেবে, কিন্তু অতিরিক্ত করো না, অপচয়কারী হয়ো না।"],
  "17:27": ["Truly, the squanderers were brothers of Shaytan; and Shaytan was ever thankless to his Rabb.", "অপচয়কারী শয়তানে ভাই, এবং শয়তান তার প্রভুর প্রতি অকৃতজ্ঞ।"],
  "17:28": ["And if you turn away from them, seeking a mercy from your Rabb that you hope for, then speak to them an easy word.", "এমনকি যদি তোমাকে তাদের কাছ থেকে মুখ ফিরিয়ে নিতে হয়, তুমি যেহেতু তোমার প্রভুর দয়া অন্বেষণ করো, তুমি তাদের সাথে অত্যন্ত সুন্দর ব্যবহার করবে।"],
  "17:29": ["And do not make your hand bound to your neck, nor stretch it out in all stretching, lest you sit blamed and regretful.", "তুমি কৃপণতায় তোমার হাত গলায় বেধে রাখবে না, না তুমি  বোকার মতো তা খুলে রাখবে, পাছে তুমি দোষী ও দুঃখিত হয়ে পড়ো।"],
  "17:30": ["Truly, your Rabb spreads out provision for whomever Allah wills and measures it; truly, Allah is ever knowing, seeing of Allah's servants.", "কারন তোমার প্রভু জীবিকা বাড়িয়ে দেন যার জন্য তিনি পছন্দ করেন, এবং তা কমিয়ে দেন। তিনি তাঁর সৃষ্টিকূলের ব্যাপারে পূর্ণ অবগত, দ্রষ্টা।"],
  "17:31": ["And do not kill your children for fear of want; We provide for them and for you. Truly, their killing was a great error.", "দারিদ্রতার ভয়ে তোমরা তোমাদের সন্তানদের হত্যা করবে না। আমরা প্রদান করি তাদের জন্য, সেই সাথে তোমাদের জন্য। তাদের হত্যা করা একটি গুরুতর অপরাধ।"],
  "17:32": ["And do not come near adultery; it was an obscenity and a worst way.", "তোমরা ব্যভিচার করবে না; এটি এক মহা পাপ, এবং একটি মন্দ আচরণ।"],
  "17:33": ["And do not kill the nafs that Allah has forbidden except by right; and whoever is killed wronged, We have given their kin a warrant — so let them not exceed in the killing, for they are ever helped.", "তোমরা কোন লোককে হত্যা করবে না- কারন আল্লাহ জীবনকে পবিত্র করেছেন- বিচার প্রক্রিয়া ব্যতীত। যদি কেউ অন্যায় ভাবে খুন হয়, তখন আমরা তার উত্তরাধিকারীকে বিচার প্রয়োগের কর্তৃত্ব দেই। সুতরাং, সে খুনের প্রতিশোধ নিতে সীমা অতিক্রম করবে না, যাতে সে সাহায্য প্রাপ্ত হয়।"],
  "17:34": ["And do not come near the wealth of the orphan except with what is better, until they reach their full strength; and fulfill the pledge, for the pledge is ever asked about.", "তোমরা এতিমের অর্থ তাদের নিজেদের মঙ্গলের জন্য ছাড়া স্পর্শ করবে না, যতক্ষণ না তারা পরিণত বয়সে পৌঁছে।  তোমরা তোমাদের অঙ্গীকার পূর্ণ করবে, কারণ অঙ্গীকার এক বিশাল দায়িত্ব।"],
  "17:35": ["And fulfill the measure when you measure, and weigh with the upright scale; that is better and best in outcome.", "তোমরা পূর্ণ পরিমাপ দেবে যখন তোমরা বেচাকেনা করো, এবং সঠিক ওজন করবে। এটি উত্তম এবং অধিক ন্যায়পরায়ণ।"],
  "17:36": ["And do not follow what you have no knowledge of; the hearing, the sight, and the fu'ad — all of those are ever asked about.", "তোমরা কোন তথ্য গ্রহণ করবে না,  যদি না তুমি নিজে তা যাচাই করো। আমি তোমাকে দিয়েছি শ্রবণশক্তি, দৃষ্টিশক্তি, এবং মস্তিষ্ক, এবং তুমি সেগুলো ব্যবহারের জন্য দায়ী।"],
  "17:37": ["And do not walk on the earth strutting; you will never split the earth, nor ever reach the mountains in height.", "তুমি গর্বভরে পৃথিবীতে চলবে না-তুমি পৃথিবী ছেদ করতে পারবে না, না তুমি পারবে উচ্চতায় পর্বত সমান হতে।"],
  "17:38": ["All of that is bad in the sight of your Rabb, detested.", "সকল খারাপ আচরন তোমার প্রভুর দ্বারা নিন্দিত।"],
  "17:39": ["That is of what your Rabb revealed to you of wisdom; and set not up with Allah another ilah, lest you be cast into Hell, blamed and driven away.", "এগুলো হচ্ছে তোমার কাছে তোমার প্রভুর প্রত্যাদিষ্ট কিছু প্রজ্ঞা/ জ্ঞান। তুমি আল্লাহর পাশে অন্য উপাস্য স্থাপন করবে না, পাছে শেষ পর্যন্ত তুমি জাহান্নামে যাও, দোষী এবং পরাজিত হয়ে।"],
  "17:40": ["Has your Rabb then singled you out with sons, and taken females from the malakat? Truly, you say a tremendous thing.", "তোমাদের প্রভু কি তোমাদের পুত্র দিয়েছেন, যখন নিজেকে দিয়েছেন কন্যা হিসাবে স্বর্গ-দূতদের? কিভাবে তোমরা এমন মিথ্যারোপ করো?"],
  "17:41": ["And We have turned about in this Recitation so that they remember, and it only increases them in aversion.", "আমরা এই কুরআনে উল্লেখ করেছি (সকল প্রকার উদাহরণ), যাতে তারা সতর্ক হতে পারে। অথচ এটি তাদের বিমুখতাই বাড়িয়ে দেয়।"],
  "17:42": ["Say: if there were alihah with Allah, as they say, they would seek a way to the Owner of the High Seat.", "বল, “যদি তাঁর পাশে অন্য উপাস্যরা থাকতো, যেমন তারা দাবী করে,  তারা সিংহাসনের অধিকারীকে পরাস্ত করার চেষ্টা করতো।"],
  "17:43": ["Glory be to Allah, exalted high above what they say, a great exalting.", "মহিমা তাঁরই, তিনি অত্যন্ত প্রশংশিত, তাদের কথার অনেক ঊর্ধ্বে।"],
  "17:44": ["The seven heavens and the earth and whoever is in them glorify Allah, and there is nothing that does not glorify with praise; but you do not understand their glorification. Truly, Allah is ever forbearing, forgiving.", "তাঁর গুনকীর্তন করে সাত মহাবিশ্ব, পৃথিবী, এবং তাদের মধ্যকার সকলে। এমন কিছু নেই যা তাঁর গুনকীর্তন করে না, কিন্তু তোমরা তাদের গুনকীর্তন বুঝো না। তিনি সহনশীল, ক্ষমাকারী।"],
  "17:45": ["And when you recite the Recitation, We place between you and those who do not believe in the Last a covering veil.", "যখন তুমি কুরআন পাঠ করো, আমরা তোমার এবং তাদের মাঝে এক অদৃশ্য অন্তরায় রেখে দেই যারা পরকালে বিশ্বাস করে না।"],
  "17:46": ["And We place covers over their hearts lest they understand it, and in their ears a heaviness; and when you mention your Rabb alone in the Recitation, they turn their backs in aversion.", "আমরা তাদের মনের চারপাশে প্রতিরোধক রাখি, এটি বুঝা থেকে তাদের বাধাঁ দিতে, এবং তাদের কানে দেই বধিরতা। এবং যখন তুমি তোমার প্রভুর কথা প্রচার করো, শুধুমাত্র কুরআনের মাধ্যমে, তারা বিরক্তি নিয়ে পালিয়ে যায়/কেটে পড়ে।"],
  "17:47": ["We know best what they listen for when they listen to you, and when they whisper, when the wrongdoers say: you follow only a man bewitched.", "আমরা পূর্ণ অবগত আছি কি তারা শোনে, যখন তারা তোমার দিকে মনোযোগ দেয়, এবং যখন তারা গোপনে চক্রান্ত করে- অবিশ্বাসীরা বলে, “তোমরা এক পাগল লোককে অনুসরণ করছো।\""],
  "17:48": ["See how they strike similitudes for you; so they stray, and cannot find a way.", "লক্ষ্য করো কেমন করে তারা তোমার বর্ণনা করে, এবং কেমন করে এটি  তাদেরকে পথ থেকে সরিয়ে দেয়।"],
  "17:49": ["And they say: when we are bones and fragments, shall we really be raised a new creation?", "তারা বলে, “আমরা হাড় এবং খন্ডিত অংশে পরিণত হবার পর, আমরা কি নতুন করে পুনরুত্থিত হব?”"],
  "17:50": ["Say: be stones or hadid,", "বল, “এমনকি যদিও তোমরা পাথর বা লোহা হয়ে যাও।"],
  "17:51": ["or a creation from what grows great in your chests. Then they will say: who will bring us back? Say: the One who originated you the first time. Then they will wag their heads at you and say: when is it? Say: perhaps it is near.", "এমনকি যদি তোমরা পরিণতও হও এমন কোন সৃষ্টিতে যা তোমরা অসম্ভব বিবেচনা করো। “তারা তখন বলবে, “কে আমাদের ফিরিয়ে আনবে?” বল, “সেই সত্ত্বা যিনি তোমাদের প্রথমবার সৃষ্টি করেছিলেন।\" তারা এরপর তাদের মাথা নাড়াবে এবং বলবে, “সেটা কখন হবে?” বল, “এটি হতে পারে তোমরা যা মনে করো তার চেয়ে নিকটবর্তী।"],
  "17:52": ["The day Allah calls you and you answer with praise, and you think you tarried only a little.", "যেদিন তিনি তোমাদের তলব করবেন, তোমরা সাড়া দেবে তাঁর প্রশংসা দিয়ে, এবং তোমরা তখন উপলব্ধি করবে যে তোমরা এই জীবনে খুব কম সময়েই ছিলে।"],
  "17:53": ["And say to My servants that they say what is best; Shaytan indeed sows discord among them. Truly, Shaytan was ever a clear enemy to the human.", "আমার বান্দাদের বল পরস্পরের সাথে সম্ভাব্য সর্বোত্তম ব্যবহার করতে, কারন শয়তান সব সময় তাদের মধ্যে বিভেদ চালানোর চেষ্টা করবে। নিশ্চয়, শয়তান মানুষের সবচেয়ে ঘোর শত্রু।"],
  "17:54": ["Your Rabb knows you best: if Allah wills, Allah has mercy on you; and if Allah wills, Allah punishes you. And We did not send you over them as a guardian.", "তোমাদের প্রভু তোমাদের সর্বোত্তম জানেন। তার জ্ঞানানুসারে, তিনি তোমাদের উপর দয়া বর্ষণ করতে পারেন, অথবা তিনি হয়তো তোমাদের শাস্তি দিবেন। আমরা তোমাকে তাদের উকিল হতে পাঠাইনি।"],
  "17:55": ["And your Rabb knows best who is in the heavens and the earth; and We have favored some of the nabis over others; and We gave Dawud a the Kitab.", "তোমার প্রভু আকাশমণ্ডলী ও পৃথিবীর মধ্যকার সকলের বিষয়ে সর্বোত্তম জানেন। এই জ্ঞান অনুযায়ী, আমরা কিছু নবীকে অন্যদের থেকে পছন্দ করেছিলাম। উদাহরণ স্বরূপ, আমরা দাউদকে যবুর দিয়েছিলাম।"],
  "17:56": ["Say: call on those you claim besides Allah; they possess no power to remove harm from you, nor to turn it away.", "বল, “মিনতি কর সেসব উপাস্যদের কাছে তোমরা তাঁর পাশে যাদের স্থাপন করেছ।\" তোমাদের দুর্দশা দূর করার কোন শক্তি তাদের নেই, না তারা সেগুলো ঠেকাতে পারে।"],
  "17:57": ["Those whom they call seek a way to their Rabb, whichever is nearest, and they hope for mercy and fear punishment. Truly, the punishment of your Rabb is ever to be feared.", "এমনকি যাদের কাছে তারা মিনতি করে সেই উপাস্যরা তাদের প্রভুর নিকটবর্তী হবার পথ ও উপায় খুঁজছে। তারা তাঁর দয়ার জন্য প্রার্থনা করে, এবং তাঁর শাস্তির ভয় করে। নিশ্চয়, তোমার প্রভুর শাস্তি ভয়াবহ।"],
  "17:58": ["There is no town but We will destroy it before the Day of Rising, or punish it with a severe punishment; that was ever inscribed in the Kitab.", "এমন কোন সম্প্রদায় নেই যে আমরা পুনরুত্থান দিনের আগে ধ্বংস করবো না, কিংবা তাদের উপর কঠোর শাস্তি আরোপ করবো না। এটি ইতোমধ্যেই বইয়ে লেখা আছে।"],
  "17:59": ["Nothing withheld Us from sending the ayat except that the ancients denied them; and We gave Thamud the naqah, plain to see, and they wronged her. And We do not send the ayat except as a warning.", "অলৌকিকতা পাঠানো থেকে যা আমাদের নিবৃত্ত করেছিল তা হলো আগের প্রজন্মরা সেগুলো প্রত্যাখ্যান করেছে। উদাহরণ স্বরূপ, আমরা সামুদকে উট দেখিয়েছিলাম, এক প্রগাঢ় (অলৌকিকতা), কিন্তু তারা এর বিরুদ্ধে সীমাতিক্রম করেছিল। আমরা কেবল ভক্তি সঞ্চারের জন্য অলৌকিকতাগুলো পাঠিয়েছিলাম।"],
  "17:60": ["And when We said to you: your Rabb ahat the people; and We did not make the vision We showed you except a trial for the people, and the cursed tree in the Recitation; and We frighten them, but it only increases them in great transgression.", "আমরা তোমাকে জানিয়েছিলাম যে তোমার প্রভু লোকদের পূর্ণরূপে নিয়ন্ত্রন করেন, এবং আমরা সেই দৃশ্য তোমাকে দেখিয়েছিলাম, যা লোকদের জন্য একটি পরীক্ষা, এবং সেই গাছ যা কুরআনে অভিসপ্ত। আমরা তাদের মধ্যে ভক্তি সঞ্চারের জন্য তাদেরকে দৃঢ় প্রমান দেখিয়েছিলাম, কিন্তু এটি শুধু তাদের অবাধ্যতা বাড়িয়েছে।"],
  "17:61": ["And when We said to the malakat: prostrate to Adam, and they prostrated except Iblis; he said: shall I prostrate to one created of clay?", "যখন আমরা ফেরেশতাদের বললাম, “আদমের সামনে সেজদাবনত হও।\" তারা সেজদাবনত হলো, শয়তান ছাড়া। সে বলল, “আমি কি তার প্রতি সেজদা করবো যাকে আপনি কাদাঁ থেকে সৃষ্টি করেছেন?”"],
  "17:62": ["He said: do You see this one whom You have honored above me? If You postpone me to the Day of Rising, I will gain mastery over their offspring, all but a few.", "সে বলল, “যেহেতু আপনি তাকে আমার উপর সন্মান দিয়েছেন, যদি আপনি আমাকে পুনরুত্থান দিন পর্যন্ত অবকাশ দেন, আমি তার বংশধরদের সকলকে বশে নেব, সামান্য কিছু ছাড়া”।"],
  "17:63": ["Allah said: go; whoever of them follows you — then Hell is your wage, a full wage.", "তিনি বললেন, “তবে যাও; তুমি এবং যারা তোমাকে অনুসরণ করবে তারা তোমাদের শাস্তি হিসাবে শেষ পর্যন্ত নরকে যাবে; এক ন্যায় সঙ্গত শাস্তি।"],
  "17:64": ["And provoke with your voice whomever of them you can, and muster against them your horses and your men, and share with them in wealth and children, and promise them; and Shaytan promises them only deception.", "“তুমি পারো তোমার আওয়াজ দিয়ে তাদের প্রলুব্ধ করতে, এবং তোমার সব ক্ষমতা এবং সব লোক তাদের বিরুদ্ধে একত্রিত করতে, এবং তাদের অর্থ ও সন্তানাদিতে অংশীদার হতে, এবং তাদের অঙ্গীকার দিতে। যা কিছু শয়তান অঙ্গীকার করে তা মায়ার চেয়ে বেশি কিছু নয়।"],
  "17:65": ["Truly, you have no warrant over My servants; and your Rabb suffices as guardian.", "আমার বান্দাদের ক্ষেত্রে, তাদের উপর তোমার কোন ক্ষমতা নেই। তোমার প্রভু উকিল হিসেবে যথেষ্ট।"],
  "17:66": ["It is your Rabb who drives the ships for you on the sea, so that you may seek of bounty. Truly, Allah is ever merciful to you.", "তোমাদের প্রভুই সে সত্ত্বা যিনি জাহাজগুলোকে সাগরে ভাসিয়ে রাখেন, যাতে তোমরা তার অনুগ্রহ অন্বেষণ করতে পারো। তিনি তোমাদের প্রতি সবথেকে দয়ালু।"],
  "17:67": ["And when harm touches you at sea, lost are those you call on except Allah; then when Allah delivers you to dry land, you turn away. And the human is ever thankless.", "যদি তোমরা সমুদ্রের মাঝখানে দুর্দশাগ্রস্থ হও/ যদি তোমরা দুর্দশাগ্রস্থ হও মাঝ সমুদ্রে, তোমরা তোমাদের উপাস্যদের ভুলে যাও এবং মন থেকে শুধু তাঁর কাছে মিনতি করো। কিন্তু তিনি তোমাদের তীরে এনে রক্ষা করা মাত্রই তোমরা আগের অবস্থায় ফিরে যাও। আসলে, মানুষ অকৃতজ্ঞ।"],
  "17:68": ["Do you feel secure that Allah will not sink you into a side of the dry land, or send upon you a storm of burning cast, and then you find no guardian for yourselves?", "তোমরা কি নিশ্চয়তা প্রাপ্ত যে তিনি, তীরের উপরস্থ, ভূমিকে দিয়ে তোমাদেরকে গ্রাস করাবেন না? অথবা তিনি তোমাদের উপর কোন প্রবল ঝড় পাঠাবেন না, এরপর তোমরা কোন রক্ষাকারী না পাও?"],
  "17:69": ["Or do you feel secure that Allah will not return you into it once more, and send upon you a shattering wind, and drown you for what you disbelieved — then you find no pursuer for you against Us?", "তোমরা কি নিশ্চয়তা প্রাপ্ত যে আরেকবার তিনি তোমাদের সমুদ্রে ফিরিয়ে নিয়ে যাবেন না, এরপর তোমাদের উপর ঝড় পাঠাবেন না যা তোমাদের ডুবিয়ে মারবে তোমাদের অবিশ্বাসের কারনে? যখনই এটা ঘটবে, আমরা তোমাদের আর কোন সুযোগ দেবো না।"],
  "17:70": ["And We have honored the children of Adam, and carried them on land and sea, and provided them from the good things, and favored them over many of those We created, with favoring.", "আমরা আদমের সন্তানদের সন্মানিত করেছি, এবং তাদেরকে স্থলে ও সাগরে বাহন দিয়েছি । আমরা তাদের জন্য উত্তম রিজিক দিয়েছি, এবং আমাদের অনেক সৃষ্টির থেকে আমরা তাদের অধিক সুবিধা দিয়েছি ।"],
  "17:71": ["The day We call every people with their leader; whoever is given their Kitab in their right hand — those read their Kutub, and are not wronged a thread.", "সে দিন আসবে যখন আমরা সকল মানুষকে তলব করবো, তাদের রেকর্ড সহকারে। তাদের ক্ষেত্রে যাদেরকে সৎকর্মশীলতার রেকর্ড দেয়া হবে, তারা তাদের রেকর্ড পড়বে এবং সামান্যতম অবিচার ভোগ করবে না।"],
  "17:72": ["Whoever is blind in this one is blind in the Last, and further astray in way.", "আর তাদের ক্ষেত্রে যারা এই জীবনে অন্ধ, তারা পরকালেও অন্ধ হবে; এমনকি আরো অধিক মন্দ।"],
  "17:73": ["And they nearly lured you away from what We revealed to you, so that you might forge against Us another, and then they would have taken you as a bosom friend.", "তারা তোমাকে আমাদের দেয়া প্রকাশনাবলী থেকে প্রায় সরিয়ে দিয়েছিল। তারা চেয়েছিল তুমি কিছু মিথ্যা উদ্ভাবন করো, যেন তোমাকে বন্ধু গন্য করা যায়।"],
  "17:74": ["And had We not made you stand firm, you would nearly have leaned to them a little.", "যদি আমরা তোমাকে দৃঢ়তা না দিতাম, তুমি তাদের প্রতি খানিকটা ঝুকেই পড়েছিলে।"],
  "17:75": ["Then We would have made you taste a double of life and a double of death; then you would have found no helper for you against Us.", "তুমি যদি তা করতে, আমরা তোমার জন্য শাস্তি দিগুন করতাম এই জীবনে, এবং মৃত্যুর পর, এবং তুমি আমাদের বিরুদ্ধে তোমাকে সাহায্য করার জন্য কাউকে পেতে না।"],
  "17:76": ["And they nearly provoked you out of the land to drive you from it; and then they would not have tarried behind you except a little.", "তারা তোমার কাছ থেকে মুক্তি পাওয়ার জন্য দেশ থেকে তোমাকে প্রায় নির্বাসিতই করেছিল, যাতে তুমি চলে যাওয়া মাত্র তারা আগের অবস্থায় ফিরে যেতে পারে।"],
  "17:77": ["A way of those of Our rusul We sent before you; and you will find no change for Our way.", "এটি সব বার্তাবাহকদের সাথে অনবরত ঘটে যাওয়া সেই একই ঘটনা যাদেরকে আমরা তোমার পূর্বে পাঠিয়েছিলাম, এবং তুমি দেখবে যে আমাদের নিয়ম কখনো পরিবর্তন হয় না।"],
  "17:78": ["Keep up the prayer from the sun's decline to the darkness of the night, and the recitation of dawn; the dawn recitation is ever witnessed.", "তুমি সংযোগ প্রার্থনা (সালাত) পালন করবে যখন দুপুরে সূর্য তার সর্বোচ্চ বিন্দু থেকে ঢলে পড়ে, যেহেতু এটি সূর্যাস্তের দিকে অগ্রসর হয়। তোমরা এছাড়া ফজরে কুরআন (আবৃতি ) করবে। ফজরে কুরআন (আবৃতি )-এর সাক্ষী থাকে।"],
  "17:79": ["And from the night keep vigil with it, an extra for you; perhaps your Rabb will raise you to a praised station.", "রাতের বেলায়, তুমি অতিরিক্ত কৃতিত্বের জন্য ধ্যান করবে, যাতে তোমার প্রভু তোমাকে এক সন্মানিত পদে উন্নিত করেন।"],
  "17:80": ["And say: My Rabb, admit me an entrance of truth, and bring me out an exit of truth, and make for me from Your presence a warranting helper.", "এবং বল, “আমার প্রভু, আমাকে সন্মানের সাথে প্রবেশ করান, এবং সন্মানের সাথে বিদায় নিতে দিন, এবং আপনার পক্ষ থেকে আমাকে একটি শক্তিশালী সমর্থন মঞ্জুর করুন।\""],
  "17:81": ["And say: the truth has come, and falsehood has vanished; falsehood is ever vanishing.", "ঘোষণা করো, “সত্যের জয় হয়েছে, এবং মিথ্যা বিলুপ্ত হয়েছে; মিথ্যা অনিবার্যভাবে বিলুপ্ত হবে।\""],
  "17:82": ["And We send down of the Recitation what is a healing and a mercy for the muminin; and it only increases the wrongdoers in loss.", "আমরা বিশ্বাসীদের জন্য কুরআনে আরোগ্য এবং দয়া অবতীর্ণ করেছি। একই সাথে, এটি কেবল সীমালঙ্ঘনকারীদের পাপাচার বাড়ায়।"],
  "17:83": ["And when We bless the human, they turn away and withdraw to their side; and when evil touches them, they are ever despairing.", "আমরা যখন মানুষকে অনুগ্রহ করি, সে আছন্ন এবং অমনোযোগী হয়ে যায়। কিন্তু যখন দুর্দশা তাকে আঘাত করে, সে হতাশ হয়ে পড়ে।"],
  "17:84": ["Say: each works according to their own manner; and your Rabb knows best who is best guided in way.", "বল, “প্রত্যেকে তার বিশ্বাস অনুসারে কাজ করে, এবং তোমার প্রভু সব থেকে ভালো জানেন কারা সঠিক পথে পরিচালিত।\""],
  "17:85": ["And they ask you about the spirit; say: the spirit is from the command of my Rabb, and you are given of knowledge only a little.", "তারা তোমাকে প্রকাশনা সম্পর্কে জিজ্ঞাসা করে। বল, “প্রকাশনা আমার প্রভুর পক্ষ থেকে আসে। তোমাকে দেয়া জ্ঞান অতি সামান্য।\""],
  "17:86": ["And if We willed, We would take away what We revealed to you; then you would find no guardian for you against Us over it.", "যদি আমরা চাই, আমরা ফিরিয়ে নিতে পারি যা আমরা তোমার কাছে প্রকাশ করেছি, তখন তুমি আমাদের বিরুদ্ধে কোন রক্ষাকারী পাবে না।"],
  "17:87": ["But for a mercy from your Rabb; truly, the bounty upon you was ever great.", "এটা তো তোমার প্রভুর পক্ষ থেকে দয়া। তোমার উপর তাঁর অনুগ্রহ বিশাল।"],
  "17:88": ["Say: if humans and jinn assembled to bring the like of this Recitation, they would not bring its like, even if some of them were backers for others.", "বল, “যদি সকল মানুষ ও সকল জিন একত্রিত হয় এর মতো একটি কুরআন তৈরি করার জন্য, তারা কখনই এর মতো কোনকিছু তৈরি করতে পারবে না, যতো সহায়তাই তারা একে অন্যকে করুক না কেন”।"],
  "17:89": ["And We have turned about for the people in this Recitation every similitude, but most people refused except as kafirin.", "এই কুরআনে আমরা লোকদের জন্য সব ধরনের উদাহরণ দিয়েছি, কিন্তু বেশির ভাগ লোক অবিশ্বাসের উপর জোর দেয়।"],
  "17:90": ["And they say: we will not believe you until you burst forth for us from the earth a spring.", "তারা বলল, “আমরা তোমাকে বিশ্বাস করবো না যদি না তুমি  ভুপৃষ্ট থেকে কোন ঝর্না প্রবাহিত করো।"],
  "17:91": ["Or until you have a garden of palms and grapes, and burst rivers through it, bursting.", "“অথবা যদিনা তুমি একটি খেজুর ও আঙুর বাগানের মালিক হও, যার মধ্যে দিয়ে নদী প্রবাহিত হয়!"],
  "17:92": ["Or the heaven falls upon us in fragments, as you claim; or you bring Allah and the malakat before us.", "“অথবা যদিনা, তোমার দাবি অনুযায়ী, আকাশ থেকে আমাদের উপর বস্তুপিন্ডের পতন ঘটাও। অথবা যদিনা তুমি আমাদের চোখের সামনে আল্লাহ এবং ফেরেশতাদের নিয়ে আসো।"],
  "17:93": ["Or there is for you a house of ornament, or you ascend into the heaven — and we will not believe your ascent until you bring down upon us a Kitab we can read. Say: glory be to my Rabb — am I anything but a human, a Rasul?", "“অথবা যদিনা তুমি কোন বিলাসবহুল প্রাসাদের মালিক হও, অথবা যদিনা তুমি আকাশে আরোহণ করো। তুমি যদি আরোহণও করো, আমরা বিশ্বাস করবো না যদি না তুমি কোন বই নিয়ে আসো যা আমরা পড়তে পারি। বল, “মহিমা আমার প্রভুর। আমি কি একজন মনুষ্য বার্তাবাহকের চেয়ে বেশি কিছু?”"],
  "17:94": ["And nothing kept the people from believing when the guidance came to them, except that they said: has Allah sent a human as a Rasul?", "লোকদের কাছে পথ-নির্দেশনা আসার পর বিশ্বাস করা থেকে যা তাদেরকে বাধা দিয়েছিল, তা হচ্ছে তাদের এ কথা যে, “আল্লাহ কি একজন মানুষকে বার্তাবাহক করে পাঠিয়েছিলেন?’"],
  "17:95": ["Say: if there were on the earth malakat walking secure, We would have sent down upon them from the heaven a malakat as a Rasul.", "বল, “যদি পৃথিবী ফেরেশতাদের বসতি হতো, তাহলে আকাশ থেকে আমরা তাদের কাছে অবতীর্ণ করতাম কোন ফেরেশতা বার্তাবাহক”।"],
  "17:96": ["Say: Allah suffices as witness between me and you; Allah is ever knowing, seeing of Allah's servants.", "বল, “আমার এবং তোমাদের মধ্যে আল্লাহ সাক্ষী হিসাবে যথেষ্ট। তিনি পূর্ণ অবগত তাঁর উপাসনাকারীদের ব্যাপারে, দ্রষ্টা”।"],
  "17:97": ["Whoever Allah guides, that one is guided; and whoever Allah leaves astray, you will find no protectors for them besides Allah; and We will gather them on the Day of Rising on their faces, blind and dumb and deaf; their shelter is Hell; whenever it subsides We increase them a blaze.", "সে-ই সত্যিকার পথপ্রাপ্ত ব্যক্তি যাকে আল্লাহ পথ দেখান। এবং তিনি যাকে পথভ্রষ্ট করেন, তাদের জন্য তুমি কখনই তাঁর পাশে কোন প্রভু এবং মনিব পাবে না। আমরা তাদেরকে পুনরুত্থান দিনে জোরপূর্বক তলব করবো; অন্ধ, বোবা এবং বধির করে। তাদের গন্তব্য নরক; যখনি তা শীতল হবে, আমরা সেগুলোর আগুন বাড়িয়ে দেবো।"],
  "17:98": ["That is their repayment, because they disbelieved Our ayat and said: when we are bones and fragments, shall we really be raised a new creation?", "এমনই তাদের উচিত শাস্তি, যেহেতু তারা আমাদের প্রকাশনাবলী প্রত্যাখ্যান করেছে। তারা বলেছিল, “আমরা হাড় এবং খন্ডিত অংশে পরিণত হবার পর, আমরা কি এক নতুন সৃষ্টি হয়ে পুনরুত্থিত হব?”"],
  "17:99": ["Do they not see that Allah, who created the heavens and the earth, is able to create the like of them, and made for them a term in which there is no doubt? But the wrongdoers refused except disbelief.", "তারা কি দেখতে পায় না যে আল্লাহ যিনি আকাশ মণ্ডলী এবং পৃথিবী সৃষ্টি করেছেন, সৃষ্টি করতে সক্ষম সেই একই সৃষ্টি? তিনি তাদের জন্য পূর্বনির্ধারিত করেছেন এক অপরিবর্তনীয় জীবন কাল? এরপরও, অবিশ্বাসীরা অবিশ্বাসের উপরই জোর দেয়।"],
  "17:100": ["Say: if you possessed the treasuries of my Rabb's mercy, you would hold back for fear of spending; and the human is ever withholding.", "ঘোষণা করো, “যদি তোমরা আমার প্রভুর দয়া ভাণ্ডারের মালিক হতে, তোমরা সেগুলো গুটিয়ে রাখতে, এই ভয়ে যে তোমরা সেগুলো শেষ করে ফেলবে। মানুষ কৃপণ।"],
  "17:101": ["And We gave Musa 9 clear ayat; ask the Children of Israel when he came to them, and Fir'awn said to him: I think, Musa, that you are bewitched.", "আমরা মুসাকে নয়টি প্রগাঢ় অলৌকিকতা দিয়ে সমর্থন করেছিলাম- ইসরাইলের সন্তানদের কাছে জিজ্ঞেস করো। যখন সে তাদের কাছে গেল, ফেরাউন তাকে বলেছিল, “আমি মনে করি যে তুমি মুসা জাদুগ্রস্থ”।"],
  "17:102": ["He said: you know that none but the Rabb of the heavens and the earth sent down these as proofs to see; and I think, Fir'awn, that you are doomed.", "সে বলল, “তুমি খুব ভালো করেই জানো যে এগুলো যেকেউ প্রকাশ করতে পারে না কিন্তু, স্পষ্টতই, আকাশমণ্ডলী এবং পৃথিবীর প্রভু ছাড়া। আমি মনে করি যে তুমি ফেরাউন ধ্বংসপ্রাপ্ত”।"],
  "17:103": ["So he wanted to provoke them out of the land, and We drowned him and all who were with him.", "যখন সে তাদের পিছু নিলো,যেভাবে সে তাদেরকে দেশের বাইরে পর্যন্ত ধাওয়া করেছিল, আমরা তাকে ডুবিয়ে দিলাম, তাদের সাথে  একত্রে যারা তার পক্ষ নিয়েছিল, তাদের সকলকে।"],
  "17:104": ["And We said after him to the Children of Israel: settle the land; then, when the promise of the Last comes, We will bring you gathered.", "এবং পরবর্তীতে আমরা ইসরাইলের সন্তানদের বলেছিলাম, “যাও এই দেশে বাস করো। যখন চূড়ান্ত ভবিষ্যদ্বাণী ঘটবে, আমরা তোমাদের সকলকে একটি দল করে তলব করবো”।"],
  "17:105": ["And with truth We sent it down, and with truth it came down; and We did not send you except as a bearer of good news and a warner.", "সত্যের সঙ্গে, আমরা একে অবতীর্ণ করেছি, এবং সত্য নিয়ে এটি অবতীর্ণ হয়েছে। আমরা তোমাকে একজন সুসংবাদ বহনকারী, সেই সাথে সতর্ককারী হিসেবে ছাড়া পাঠাইনি।"],
  "17:106": ["And a Recitation We apportioned, for you to recite to the people over time; and We sent it down by sending down.", "কুরআন যা আমরা ধীরে ধীরে ছেড়েছি, ক্রমান্বয়ে এটি দীর্ঘ সময়কাল ধরে লোকদের কাছে তোমার পরার জন্য, যদিও আমরা একে হঠাৎ করেই অবতীর্ণ করেছি।"],
  "17:107": ["Say: believe in it or do not believe; those who were given knowledge before it, when it is recited to them, fall down on their chins, bowing.", "ঘোষণা দাও, “এতে বিশ্বাস করো, অথবা এতে বিশ্বাস না করো। “যারা পূর্ববর্তী ঐশীগ্রন্থের জ্ঞান রাখে, তাদের কাছে যখন এটা আবৃত্তি করা হয়, তারা তাদের মাথা নত করে সেজদায় পড়ে যায়।"],
  "17:108": ["And they say: glory be to our Rabb; the promise of our Rabb is ever to be fulfilled.", "তারা বলে, “মহিমা আমাদের প্রভুর। এটা আমাদের প্রভুর ভবিষ্যদ্বাণী পূর্ণ করে।\""],
  "17:109": ["And they fall down on their chins, weeping, and it increases them in humility.", "তারা তাদের মাথা নত করে সেজদায় পড়ে যায় এবং কাঁদে। কারন এটা তাদের ভক্তি বৃদ্ধি করে।"],
  "17:110": ["Say: call on Allah or call on the Raheem; whichever you call on, to Allah belong the most beautiful names. And do not be loud in your prayer, nor be hushed in it, but seek between that a way.", "বল, “তাঁকে আল্লাহ ডাকো, অথবা তাঁকে পরম দয়াময় ডাকো; যে নামই তোমরা ব্যবহার করো না কেন, সর্বোত্তম নামগুলো তাঁরই।\" তুমি তোমার সংযোগ প্রার্থনা (সালাত) অতি উচ্চস্বরে পড়বে না, না নীরবে; একটি মধ্যম কণ্ঠস্বর ব্যবহার করো।"],
  "17:111": ["And say: praise belongs to Allah, who took no child, and has no partner in dominion, and has no protector out of abasement; and proclaim Allah's greatness with proclaiming.", "এবং ঘোষণা করঃ “প্রশংসা আল্লাহর, যিনি কখনই কোন পুত্র জন্ম দেননি, না তাঁর রাজত্বে তাঁর কোন অংশীদার আছে, না দুর্বলতাবশত তাঁর কোন মিত্রের প্রয়োজন আছে”, এবং প্রতিনিয়ত তাঁর মহত্ব বর্ণনা করো।"],
  "18:1": ["Praise belongs to Allah, who sent down upon the servant of Allah the Kitab, and made no crookedness in it.", "প্রশংসা আল্লাহর, যিনি তাঁর বান্দার কাছে এই ঐশীগ্রন্থ প্রকাশ করেছেন, এবং একে নির্ভূল করেছেন।"],
  "18:2": ["Upright, to warn of a severe might from the presence of Allah, and to bring glad news to the muminin who do the right deeds, that theirs is a goodly reward.", "একটি যথাযথ (ঐশীগ্রন্থ) তাঁর পক্ষ থেকে কঠিন শাস্তির বিষয়ে সতর্ক করতে, এবং বিশ্বাসীদের শুভ সংবাদ দিতে যারা সৎ জীবন-যাপন করে, যে তারা অর্জন করেছে এক মহা প্রতিদান।"],
  "18:3": ["Abiding in it forever.", "যেখানে তারা চিরকাল বসবাস করে।"],
  "18:4": ["And to warn those who say: Allah has taken a child.", "এবং তাদেরকে সতর্ক করতে যারা বলে, “আল্লাহ পুত্র জন্ম দিয়েছেন!”"],
  "18:5": ["They have no knowledge of it, nor had their fathers. Enormous is the word that comes from their mouths — they say nothing but a lie.", "তারা এ বিষয়ে কোন জ্ঞান রাখে না, না রাখতো তাদের মাতা-পিতারা। কি এক মিথ্যাচারই না তাদের মুখ দিয়ে আসছে! তারা যা বলে তা এক ঘোর মিথ্যাচার।"],
  "18:6": ["Yet perhaps you will destroy yourself with grief over their traces, if they do not believe in this hadith.", "তুমি হয়তো নিজেকে দোষ দিবে এই বর্ণনার প্রতি তাদের প্রতিক্রিয়ার কারণে, এবং এতে তাদের অবিশ্বাসের কারণে; তুমি হয়তো দু:খিত হবে।"],
  "18:7": ["We have made all that is on the earth an adornment for it, so that We may test which of them is best in deed.", "আমরা পৃথিবীর সবকিছু সাজিয়েছি, তাদের পরীক্ষা করার জন্য, এবং এভাবে তাদের মধ্যে যারা সৎ কাজ করে তাদেরকে আলাদা করি।"],
  "18:8": ["And We shall surely turn all that is on it into a barren dust-plain.", "অনিবার্যভাবে, আমরা এর সবকিছু মুছে ফেলব, একে পুরোপুরি ধূলিসাৎ করে দিয়ে।"],
  "18:9": ["Or do you think that the Companions of the Cave and of ar-Raqim were a marvel among Our ayat?", "কেনইবা তুমি ভাবো- আমরাই তো তোমাকে বলছি গুহার লোকদের সম্পর্কে, এবং তাদের সাথে সম্পর্কিত সংখ্যা সম্পর্কে ? তারা আমাদের বিস্ময়কর নিদর্শনগুলোর অন্তর্ভুক্ত।"],
  "18:10": ["When the fitya sheltered in the Cave and said: Our Rabb, bring us mercy from Your presence, and dispose our affair unto a right course.", "যখন তরুনেরা গুহায় আশ্রয় নিয়েছিল, তারা বলেছিল, \"আমাদের প্রভু, আমাদের প্রতি আপনার দয়া বর্ষণ করুন, এবং  আপনার পথ-নির্দেশনা দিয়ে আমাদের কাজগুলোকে অনুগ্রহ করুন।”"],
  "18:11": ["Then We sealed their ears in the Cave for a number of years.", "আমরা এরপর এক পূর্বনির্ধারিত সংখ্যক বছরের জন্য গুহায় তাদের কানে মোহর মেরে দিলাম।"],
  "18:12": ["Then We raised them, so that We might know which of the two parties computed best how long they had tarried.", "এরপর আমরা তাদের পুনঃরুত্থিত করলাম দেখার জন্য যে দু'দলের কোনটি সেখানে তাদের অবস্থানের সময়কাল গননা করতে পারে।"],
  "18:13": ["We narrate to you their account in truth. They were fitya who believed in their Rabb, and We increased them in guidance.", "আমরা তোমার কাছে তাদের ইতিহাস বর্ননা করি, সত্যের সাথে।  তারা ছিল তরুন যারা তাদের প্রভুকে বিশ্বাস করেছিল, এবং আমরা তাদের সঠিক নিরদেশেনা বৃদ্ধি করেছিলাম।"],
  "18:14": ["And We bound their hearts when they stood and said: Our Rabb is the Rabb of the heavens and the earth; we will never call upon any ilah other than Allah — that would be an utter excess.", "আমরা তাদের হৃদয়কে দৃঢ় করেছিলাম যখন তারা দাঁড়ালো এবং ঘোষণা করলো: \"আকাশমন্ডলী এবং পৃথিবীর প্রভুই আমাদের একমাত্র প্রভু। আমরা কখনো তাঁর পাশে অন্যকোন উপাস্যের উপাসনা করবো না। অন্যথায়, আমরা বহুদূরে পথভ্রষ্ট হবো।"],
  "18:15": ["These, our people, have taken alihah other than Allah. Why do they not bring them a clear warrant? Who is more wrong than one who fabricates a lie against Allah?", "এই যে আমাদের লোকেরা তাঁর পাশে উপাস্যদের স্থাপন করছে। যদি শুধু তারা তাদের পক্ষে কোন প্রমান দেখাতে পারতো! কে তার চেয়ে অধিক মন্দ যে মিথ্যা রচনা করে এবং সেগুলো আল্লাহর প্রতি আরোপ করে?"],
  "18:16": ["So withdraw from them and from all they worship other than Allah, and shelter in the Cave; your Rabb will spread out mercy for you and will dispose for your affair a support.", "যেহেতু তোমরা তাদেরকে, এবং আল্লাহ ছাড়া তাদের অন্য কারো উপাসনা করাকে এড়াতে চাও,  সেহেতু চলো আমরা গুহায় আশ্রয় নেই। তোমাদের প্রভু তোমাদেরকে তাঁর দয়া বর্ষণ করুন এবং তোমাদের সঠিক সিদ্ধান্তে পরিচালিত করুন।"],
  "18:17": ["And you would see the sun, when it rises, swerving away from their cave toward the right, and when it sets, cutting past them toward the left, while they were in a cleft of it. That is among the ayat of Allah. Whoever Allah guides is the guided one, and whoever Allah leaves astray, you will never find for them a guiding ally.", "তুমি সূর্যকে তাদের গুহার ডান পাশ থেকে উদিত হতে দেখতে পেতে, এবং যখন এটি অস্ত যেত, এটি তাদের বাম দিক থেকে আলোকিত হতো, সেখানকার গর্তে যখন তারা ঘুমিয়ে ছিল। এটি আল্লাহর একটি সতর্কীকরণ। যাকে আল্লাহ পথপ্রদর্শন করেন সেই সত্যিকার পথপ্রাপ্ত ব্যক্তি, এবং যাকে তিনি পথভ্রষ্ট করেন; তুমি তার জন্য কোন পথনির্দেশক শিক্ষক পাবে না।"],
  "18:18": ["You would think them awake, though they were asleep, and We turned them over, to the right and to the left, and their hound stretched its forelegs across the waṣid. Had you looked upon them, you would have turned from them in flight, and would have been filled with terror of them.", "তুমি মনে করতে যে তারা জাগ্রত, যখন তারা আসলে ঘুমন্ত। আমরা তাদেরকে ডান ও বাম পাশে ফিরাতাম, যখন তাদের কুকুর তার বাহুগুলো তাদের মাঝে টান টান করে রেখেছিল। যদি তুমি তাদের দিকে তাকাতে, তুমি হয়তো তাদের থেকে পালাতে, আতংকগ্রস্থ হয়ে।"],
  "18:19": ["And so We raised them, that they might ask one another. One of them said: How long have you tarried? They said: We tarried a day, or part of a day. They said: Your Rabb knows best how long you tarried. So send one of you with these coins of yours into the town, and let him look for the purest food there, and let him bring you provision from it. Let him be discreet, and let no one perceive you.", "যখন আমরা তাদের পুনরুজ্জীবিত করলাম, তারা একে অন্যকে জিজ্ঞেস করলো, “তোমরা কতক্ষন এখানে আছো?” “আমরা এখানে এক দিন বা দিনের একাংশ জুড়ে আছি,” তারা জবাব দিল। “তোমাদের প্রভু সবচেয়ে ভাল জানেন কত সময় জুড়ে /ধরে আমরা এখানে অবস্থান করছি, তাই চলো এই পয়সা দিয়ে আমরা আমাদের একজনকে শহরে পাঠাই। সে সবচেয়ে পরিষ্কার খাবার নিয়ে আসুক, এবং কিছু আমাদের জন্য কিনে আনুক। সে যেন তাকে জনসম্মুক্ষে কম প্রকাশ করে, এবং কোন দৃষ্টি আকর্ষণ না করে।"],
  "18:20": ["If they emerge upon you, they will stone you or force you back into their way — and then you will never attain success.", "যদি তারা তোমাদের খুঁজে পায়, তারা তোমাদের পাথর মারবে, অথবা জোড় করে তোমাদেরকে তাদের ধর্মে ফিরিয়ে নেবে, সেক্ষেত্রে তোমরা কখনো সফল হতে পারবে না।\""],
  "18:21": ["And so We made them known, that they might know that the promise of Allah is true and that the Hour — there is no doubt in it. When they were contending among themselves over their affair, they said: Build over them a building — their Rabb knows them best. Those who prevailed in the affair said: We will surely raise over them a place of prostration.", "আমরা তাদেরকে প্রকাশ করালাম, সবাইকে জানাতে যে আল্লাহর অঙ্গীকার সত্য, এবং বিশ্বের পরিসমাপ্তির ব্যাপারে সকল সন্দেহ দূর করার জন্য।এরপর লোকেরা নিজেদের মধ্যে তাদের সম্পর্কে বিবাদে জড়ালো। কেউ কেউ বলল, \"চল আমরা তাদের চারপাশে দালান বানাই।” তাদের প্রভু তাদের সম্পর্কে সর্বোত্তম জ্ঞাত। যারা প্রাধান্য  পেয়েছিল তারা বলল, \"তাদের ঘিরে আমরা একটি উপাসনার জায়গা বানাবো।”"],
  "18:22": ["They will say: 3, their hound the 4th of them; and they will say: 5, their hound the 6th of them — guessing at the ghayb; and they will say: 7, and their hound the 8th. Say: My Rabb knows best their number; none knows them but a few. So do not dispute about them except an open dispute, and do not ask any of them about them.", "কেউ কেউ বলে, \"তারা ছিল তিনজন, তাদের কুকুর সহ চার\", যখন অন্যরা বলে, “পাঁচজন; তাদের কুকুর সহ ছয়, ” কারণ তারা অনুমান করেছিল। অন্যরা বলেছিল, \"সাতজন\", এবং আট নম্বরে তাদের কুকুর। বল, \"আমার প্রভু তাদের সংখ্যা সম্পর্কে সবচেয়ে ভাল জানেন। শুধু অল্প কয়েকজনই সঠিক সংখ্যাটি জানত। সেজন্য, তাদের সাথে তর্ক করো না; শুধু তাদের সাথে থাকো।  তোমার এ নিয়ে কারো সাথে পরামর্শের দরকার নেই।"],
  "18:23": ["And never say of anything: I will surely do that tomorrow,", "তুমি কখনো বলবে না যে তুমি কোনকিছু ভবিষ্যতে করবে,"],
  "18:24": ["without adding: if Allah wills. And remember your Rabb when you forget, and say: Perhaps my Rabb will guide me nearer than this to a right course.", "এটা না বলে যে, \"আল্লাহ চাইলে,  যদি তুমি তা করতে ভুলে যাও, সাথে সাথে অবশ্যই তুমি তোমার প্রভুকে স্মরণ করবে এবং বল, \"পরবর্তীতে আরো ভাল করার জন্য আল্লাহ আমায় পথ-প্রদর্শন করুন।\""],
  "18:25": ["And they tarried in their Cave 300 years, and added 9.", "তারা তাদের গুহায় ছিল তিনশত বছর, আরো নয় বাড়িয়ে।"],
  "18:26": ["Say: Allah knows best how long they tarried. To Allah belong the hidden things of the heavens and the earth — how well Allah sees and hears! They have no ally besides Allah, and Allah associates no one in judgment.", "বল, “কত কাল সেখানে তারা ছিল আল্লাহই সবচেয়ে ভাল জানেন।” তিনি আকাশমন্ডলী ও পৃথিবীর সকল রহস্য জানেন। তাঁর দয়ায় তোমরা দেখতে পাও; তাঁর দয়ায় তোমরা শুনতে পাও। তাঁর পাশে প্রভু ও মনিব হিসেবে আর কেউ নেই, এবং তিনি কখনো কোন অংশীদারকে তাঁর রাজত্বে অংশ নিতে অনুমতি দেন না।"],
  "18:27": ["And recite what has been revealed to you of the Kitab of your Rabb. None can change the words of Allah, and apart from Allah you will never find a refuge.", "তুমি আবৃতি করবে তোমার প্রভুর ঐশীগ্রন্থের যাকিছু তোমার কাছে প্রকাশিত হয়। কোন কিছুই তাঁর বানীকে বাতিল/রদ করবে না, এবং এর পাশে অন্যকোন উৎস তুমি খুঁজবে না।"],
  "18:28": ["And keep yourself sabir with those who call upon their Rabb morning and evening, seeking the face of Allah; and do not turn your eyes from them, desiring the adornment of the worldly life. And do not obey the one whose heart We have made unmindful of Our remembrance, who follows their desire, and whose affair is mere excess.", "তাদের সঙ্গে থাকতে তুমি নিজেকে বাধ্য করবে যারা দিনে ও রাতে তাদের প্রভুর উপাসনা করে, একমাত্র তাঁরই খোঁজে।  তাদের কাছ থেকে মুখ ফিরিয়ে নিও না, এই বিশ্বের তুচ্ছ কিছুর খোঁজে। না তুমি সে ব্যাক্তিকে মান্য করবে আমরা যার হৃদয়কে আমাদের বার্তার প্রতি বেখবর রেখেছি; যে ব্যাক্তি তার নিজ ইচ্ছার অনুসরণ করে, যার অগ্রাধিকারগুলো বিভ্রান্তিকর।"],
  "18:29": ["And say: The truth is from your Rabb. So whoever wills, let them believe; and whoever wills, let them disbelieve. We have prepared for the wrongdoers a Fire that ahat them. If they cry for help, they will be given water like molten mire, scalding the faces. Wretched the drink, and evil the resting-place!", "ঘোষনা কর, \"এটি তোমার প্রভুর কাছ থেকে সত্য, ”এরপর যেকেউ চায় তাকে বিশ্বাস করতে দাও, এবং যেকেউ চায় তাকে অবিশ্বাস করতে দাও। আমরা সীমালঙ্ঘনকারীদের জন্য আগুন প্রস্তুত রেখেছি যা তাদেরকে পুরোপুরি ঘিরে ফেলবে। যখন তারা সাহায্যের জন্য চিৎকার করবে, তাদেরকে ঘনীভূত অম্লের মত তরল দেয়া হবে যা মুখগুলোকে ঝলসে দেবে। কি এক শোচনীয় পানীয়!  কি এক শোচনীয় নিয়তি"],
  "18:30": ["Indeed, those who believe and do the right deeds — We never lose the reward of the one who does the best of deeds.", "আর তাদের ক্ষেত্রে যারা বিশ্বাস করে এবং সতকর্মশীল জীবন যাপন করে, যারা সৎকর্ম করে তাদেরকে কখনো আমরা প্রতিদান দিতে ব্যর্থ হই না।"],
  "18:31": ["Those — theirs are Gardens of Eden, with rivers flowing beneath them; adorned therein with bracelets of gold, clothed in green garments of silk and brocade, reclining upon couches therein. Excellent the reward, and fair the resting-place!", "তারা ইডেনের বাগানগুলোর যোগ্য হয়েছে যেখানে প্রবাহিত হয় নদী। সেখানে সোনার ব্রেসলেট দিয়ে তারা সাজবে, এবং পরিধান করবে সবুজ রেশম ও মখমলের কাপড়, এবং বিশ্রাম নিবে আরামদায়ক আসবাবপত্র ও সাজসরঞ্জামের মাঝে। কতই না উৎকৃষ্ট প্রতিদান; কতই না উৎকৃষ্ট আবাস!"],
  "18:32": ["And strike for them a parable of two men: We made for one of them two gardens of grapes, hedged them with palm-trees, and set a crop between them.", "তাদের জন্য দুই জন লোকের উদাহরণ উদ্ধৃতি করোঃ আমরা তাদের একজনকে আংগুরের দুটি বাগান দিয়েছিলাম, খেজুঁর গাছে ঘেরা, এবং তাদের মাঝে ছিল অন্যান্য ফসলাদি।"],
  "18:33": ["Each of the two gardens yielded its produce and diminished nothing of it, and We burst forth a river within them.", "উভয় বাগানই তাদের ফসল ফলাত সময়মত, এবং প্রচুর পরিমানে, কারণ আমরা একটি নদীকে তাদের মধ্য দিয়ে প্রবাহিত করেছিলাম।"],
  "18:34": ["And he had fruit, and he said to his companion, conversing with him: I am greater than you in wealth and mightier in following.", "একবার, ফসল তোলার পর, সে দম্ভভরে তার বন্ধুকে বলল, \"আমি তোমার চেয়ে অনেক বেশি সমৃদ্ধশালী, এবং আমি লোকদের থেকে অধিক সম্মানের দাবিদার।"],
  "18:35": ["And he entered his garden, wronging himself, and said: I do not think this will ever perish,", "যখন সে তার বাগানে প্রবেশ করলো, সে এ বলে তার আত্মার ক্ষতি করলো, \"আমি মনে করি না যে এটা কখনো শেষ হবে।"],
  "18:36": ["and I do not think the Hour is rising. Even if I am returned to my Rabb, I shall surely find a return better than this.", "\"তাছাড়া, আমি মনে করি এটাই সব; আমি মনে করি না যে সেই ঘন্টা (পরকাল) কখনো আসবে। এমনকি আমি আমার প্রভুর কাছে ফিরলেও, ঐখানে এর চেয়েও উত্তম কিছু অধিকার করতে আমি (যথেষ্ট চতুর)  হবো।"],
  "18:37": ["His companion said to him, conversing with him: Do you disbelieve in the One who created you from dust, then from a drop, then shaped you into a man?", "তার বন্ধু তাকে বলল, যখন সে তার সাথে বিতর্ক করছিল, \"তুমি কি সেই সত্ত্বাকে অবিশ্বাস করেছ যিনি তোমাকে সৃষ্টি করেছেন ধুলো থেকে,এরপর এক তুচ্ছ ফোটা থেকে, এরপর তোমাকে একজন পূর্ণ মানুষ হিসেবে সুগঠিত করেছেন?"],
  "18:38": ["As for me, Allah is my Rabb, and I will not associate anyone with my Rabb.", "আমার ক্ষেত্রে, আল্লাহ আমার প্রভু, এবং আমি কখনো আমার প্রভুর পাশে অন্য কোনো উপাস্য স্থাপন করবো না।"],
  "18:39": ["If only, when you entered your garden, you had said: What Allah wills — there is no strength except with Allah. Though you see me less than you in wealth and children,", "\"যখন তুমি তোমার বাগানে প্রবেশ কর, তোমার বলা উচিত ছিল, 'এ তো যা আল্লাহ আমাকে দিয়েছেন (মা শা আল্লাহ)। কেউই ক্ষমতা রাখে না আল্লাহ ছাড়া (লা ক্বু'য়াতা ইল্লা বিল্লাহ) ।' তুমি হয়তো দেখো যে আমি তোমার চেয়ে কম অর্থ এবং কম সন্তানের অধিকারী।"],
  "18:40": ["yet perhaps my Rabb will bring me better than your garden, and send upon it a reckoning from the heaven, so that it becomes a smooth, barren tract,", "“আমার প্রভু আমাকে হয়তো তোমার বাগানের চেয়ে উত্তম প্রদান করবেন। তিনি হয়তো আকাশ থেকে কোন তীব্র ঝড় পাঠাবেন যা তোমার বাগানকে নিশ্চিহ্ন করে দেবে, একে সম্পূর্ণ ধূলিসাৎ করে দিয়ে।"],
  "18:41": ["or its water sinks deep — then you will never be able to seek it out.", "“অথবা, হয়তো এর পানি গভীরে চলে যাবে, তোমার নাগালের বাইরে।\""],
  "18:42": ["And his produce was uhit, and there he was, turning his hands over all he had spent on it, while it lay collapsed upon its trellises — saying: If only I had not associated anyone with my Rabb!", "বাস্তবেই, তার ফসলাদি নিশ্চিহ্ন হয়েছিল, এবং শেষ পর্যন্ত সে দু:খ ভারাক্রান্ত হলো, পরিতাপ করতে থাকলো তার জন্য যা সে এর পিছনে ব্যয় করেছে অনর্থক, যেহেতু তার সম্পত্তি মরুময় হয়ে রইলো। অবশেষে সে বলল, \"আমি যদি কখনো আমার প্রভুর পাশে আমার সম্পত্তিকে উপাস্য হিসেবে স্থাপন না করতাম।\""],
  "18:43": ["He had no band to help him apart from Allah, and he could not be helped.", "পৃথিবীর কোন শক্তি আল্লাহর বিপক্ষে তাকে সাহায্য করতে পারলো না, না তার পক্ষে কোন সাহায্য পাওয়া সম্ভব ছিল।"],
  "18:44": ["There the true Protector is Allah. Allah is better in reward and better in outcome.", "এটা এ কারনে যে একমাত্র সত্য প্রভু এবং মনিব হচ্ছেন আল্লাহ; তিনি সর্বোত্তম প্রতিদান দেন, এবং তাঁর কাছেই রয়েছে সর্বোত্তম নিয়তি।"],
  "18:45": ["And strike for them the parable of the worldly life: like water that We send down from the heaven, with which the vegetation of the earth mixes — then it becomes dry stubble that the wind scatters. And Allah is powerful over all things.", "তাদের জন্য এই জীবনের উদাহরণ দাও যেন পানি যা আমরা আকাশ থেকে বর্ষণ করি পৃথিবীর উদ্ভিদ উৎপন্ন করতে, এরপর এরা পরিণত হয় খড়কূটায় বাতাসে যা উড়ে যায়। আল্লাহ সবকিছু করতে সক্ষম।"],
  "18:46": ["Wealth and children are the adornment of the worldly life, but the enduring good deeds are better with your Rabb for reward, and better for hope.", "অর্থ এবং সন্তানাদি তো হচ্ছে এই জীবনের আনন্দ, কিন্তু সৎকর্ম তোমার প্রভুর পক্ষ থেকে প্রদান করে অনন্তকালের প্রতিদান, এবং অনেক উত্তম আশা।"],
  "18:47": ["On the day We set the mountains moving, and you see the earth laid bare, and We gather them — not one of them will We leave behind.", "সে দিন আসবে যখন আমরা পর্বতগুলোকে নিশ্চিহ্ন করবো, এবং পৃথিবীকে তুমি দেখবে মরুময়। আমরা তাদের সকলকে ডেকে পাঠাবো, তাদের একজনকেও ছাড়া হবে না।"],
  "18:48": ["And they are presented before your Rabb in ranks: You have come to Us just as We created you the first time — yet you claimed We would never make you an appointment.", "তাদেরকে তোমাদের প্রভুর সামনে একটি সাড়ি করে উপস্থিত করা হবে। তোমরা আমাদের কাছে এসেছ আলাদা আলাদাভাবে, ঠিক যেভাবে আমরা প্রথম দিকে তোমাদের সৃষ্টি করেছিলাম।  প্রকৃতপক্ষে, এ তো তা-ই যা কখনো ঘটবে না বলে তোমরা দাবী করেছিলে।"],
  "18:49": ["And the Kitab is laid down, and you see the guilty dismayed at what is in it, saying: Woe to us! What is this Kitab that leaves nothing, small or great, uncounted? And they find all they did present before them. Your Rabb wrongs no one.", "রেকর্ড দেখানো হবে, এবং তুমি অপরাধীদের দেখবে এর ভেতরকার জিনিস দেখে ভীত। তারা বলবে, \"আমাদের দুঃখ। এই বই কেমন করে কোনকিছু ছাড়ে নি, ছোট অথবা বড়, তা গননা না করে?” তারা যা কিছু করেছিল সবকিছু তারা সামনে পাবে। তাদের করা সবকিছু তারা সামনে পাবে। তোমার প্রভু কখনো কারও প্রতি অন্যায়কারী নন।"],
  "18:50": ["And when We said to the malakat: Prostrate before Adam — and they prostrated, except Iblis; he was of the jinn and fasaqa from the command of his Rabb. Will you take him and his offspring as allies instead of Me, when they are your enemies? Wretched an exchange for the wrongdoers!", "আমরা ফেরেশতাদের বললাম, \"আদমের সামনে সেজদাবনত হও।” তারা সেজদাবনত হলো, শয়তান ছাড়া। সে জ্বীন হয়ে পড়লো, কারন সে তাঁর প্রভুর আদেশ অমান্য করেছিল। তোমরা কি আমার বদলে তাকে এবং তার বংশধরদের প্রভু হিসেবে পছন্দ করবে, যদিও তারা তোমাদের শত্রু? কি এক শোচনীয় প্রতিস্থাপন!"],
  "18:51": ["I did not call them to witness the creation of the heavens and the earth, nor the creation of themselves; nor do I take the misleaders as helpers.", "আমি কখনো তাদেরকে আকাশমন্ডলী ও পৃথিবীর সৃষ্টিতে সাক্ষী হবার অনুমতি দেইনি, না দিয়েছি তাদের নিজেদের সৃষ্টিতে। না আমি মন্দকে আমার রাজত্বে কাজ করার অনুমতি দেই।"],
  "18:52": ["On the day Allah says: Call those partners of Mine you claimed — they will call them, but they will not answer them; and We shall set between them a gulf.", "সে দিন আসবে যখন সে বলবে, “আমার অংশীদারদের আহবান করো, যাদেরকে তোমরা আমার পাশে উপাস্য হবার দাবি করতে।” তারা তাদেরকে ডাকবে, কিন্তু তারা তাদের প্রতি সাড়া দিবে না। এক দূর্ভেদ্য অন্তরায় তাদের পরস্পরকে আলাদা করবে।"],
  "18:53": ["And the guilty will see the Fire and think they are about to fall into it, and they will find no way to turn from it.", "অপরাধী নরক দেখবে, এবং বুঝবে যে তারা তাতে পতিত হবে। সেখান থেকে তাদের কোন মুক্তি থাকবে না।"],
  "18:54": ["We have indeed set forth for the people, in this Recital, every parable — yet humankind is the most disputing of all things.", "আমরা এই কুরআনে সব ধরণের উদাহরণ দেই, কিন্তু মানব জাতি সবচেয়ে তর্কপ্রিয় জাঁতী।"],
  "18:55": ["Nothing keeps the people from believing when guidance comes to them, and from seeking forgiveness from their Rabb, except that the way of the ancients comes upon them, or the punishment comes to them face to face.", "কোনকিছুই লোকদের বাধাঁ দেয়নি বিশ্বাস করা থেকে, যখন তাদের কাছে পথ-নিদর্শনা আসলো, এবং দয়া অন্বেষণ করা থেকে তাদের প্রভুর, এছাড়া যে তারা পূর্ববর্তী প্রজন্মদের মত একই (রকম অলৌকিকতা) দেখার দাবি করেছিল, অথবা আগেই শাস্তি দেখার চ্যালেঞ্জ করেছিল।"],
  "18:56": ["We send the mursalin only as bearers of glad news and warners — but those who disbelieve dispute with falsehood to strike down the truth with it, and they take My ayat and the warnings given them as mockery.", "আমরা শুধু বার্তাবাহকদের পাঠাই কেবল সুসংবাদ বহনকারী হিসেবে, সেই সাথে সতর্ককারী হিসেবে। যারা অবিশ্বাস করে তারা মিথ্যা দিয়ে তর্ক করে সত্যকে পরাজিত করতে, এবং তারা আমার প্রমানাদি ও সতর্কসংকেতগুলোকে নিরর্থক নেয়।"],
  "18:57": ["Who is more wrong than one who is reminded of the ayat of their Rabb, then turns away from them and forgets what their hands have sent forward? We have set coverings upon their hearts, so that they cannot understand it, and heaviness in their ears. Even if you call them to guidance, they will never be guided — never.", "তাদের চেয়ে কে অধিক মন্দ যাদেরকে তাদের প্রভুর প্রমাণাদি স্মরণ করানো হয়, এরপর সেগুলো উপেক্ষা করে, তারা যা করছে তা অনুধাবন না করেই। পরিনামে, আমরা তাদের হৃদয়ের উপর আবরণ দিয়ে রাখি তাদেরকে এটি (কুরআন) বুঝতে বাধাঁ দিতে, এবং বধিরতা দেই তাদের কানে। সুতরাং, তুমি তাদেরকে পথপ্রাপ্ত করতে যাই করো না কেন, তারা কখনো কোন কালেও সুপথপ্রাপ্ত হতে পারবে না।"],
  "18:58": ["Your Rabb is the Forgiving, the Possessor of Mercy. Were Allah to seize them for what they have earned, Allah would hasten the punishment for them — but they have an appointment from which they will find no refuge.", "এরপরও, তোমার প্রভু ক্ষমাকারী, দয়ায় পরিপূর্ণ। যদি তিনি তাদের কাজের জন্য হিসাব নিতে তাদেরকে ডাকতেন, তিনি তাদের ঠিক তখনই ধ্বংস করতেন। পরিবর্তে, তিনি তাদেরকে একটি নির্দিষ্ট, পূর্বনির্ধারিত সময় পর্যন্ত অবকাশ দেন; এরপর তারা কখনো পালাতে পারবে না।"],
  "18:59": ["Those towns — We destroyed them when they did wrong, and We set an appointed time for their destruction.", "আমরা অনেক সম্প্রদায়কে ধ্বংস করেছি তাদের সীমালঙ্ঘনের কারনে, আমরা তাদের ধ্বংসের জন্য একটি নির্দিষ্ট সময় মনোনীত করেছি।"],
  "18:60": ["And when Musa said to his young companion: I will not stop until I reach the meeting of the two seas, even if I journey on for an age.", "মূসা তার ভৃত্যকে বলল, \"আমি বিশ্রাম নিবো না যতক্ষণ না আমি দু'নদীর মিলনস্থলে পৌঁছাই, এতে যতো সময়ই লাগুক না কেন।\""],
  "18:61": ["Then, when they reached the meeting of the two, they forgot their huut, and it took its course into the sea, slipping away.", "যখন তারা সে জায়গায় পৌঁছাল যেখানে এরা মিলেছিল, তারা তাদের মাছের কথা ভুলে গেল, এবং এটি নদীতে ফেরার পথ খুঁজে পেয়েছিল, অগচরে।"],
  "18:62": ["Then, when they had crossed over, he said to his young companion: Bring us our midday meal — we have certainly met toil on this journey of ours.", "তারা সেই জায়গা অতিক্রম করার পর, সে তার ভৃত্যকে বলল, \"চল আমরা দুপুরের খাবার খাই। এই পুরো ভ্রমন আমাদের একেবারেই ক্লান্ত করে দিয়েছে।\""],
  "18:63": ["He said: Do you remember when we sheltered by the rock? I forgot the huut — and none made me forget it but Shaytan, that I should forget to mention it — and it made its way into the sea in a marvelous manner.", "সে বলল, \"মনে আছে কি যখন আমরা সেখানে পাথরের পাশে বসে ছিলাম? আমি মাছটির প্রতি কোন নজর দেইনি। শয়তানই তা আমাকে ভুলিয়ে দিয়েছে,  এবং এটি নদীতে ফেরার পথ খুঁজে পেয়েছিল, অদ্ভূতভাবে।\""],
  "18:64": ["He said: That is what we were seeking. So the two turned back on their tracks, retracing.", "(মুসা) বলল, \"ঐটাই ছিল সেই জায়গা যা আমরা খুঁজছিলাম।” তারা তাদের ফেলে আসা পথ ধরে ফিরে গেল।"],
  "18:65": ["Then they found one of Our servants, to whom We had given mercy from Our presence, and whom We had taught knowledge from Our presence.", "তারা আমাদের বান্দাদের একজনকে পেল, যাকে আমরা দয়া দিয়ে অনুগ্রহ করেছিলাম, এবং তাকে আমাদের নিজস্ব জ্ঞান থেকে প্রদান করেছিলাম।"],
  "18:66": ["Musa said to him: May I follow you, so that you teach me of what you have been taught of right course?", "মুসা তাকে বলল, \"আমি কি আপনার অনুসরণ করতে পারি, যাতে আপনি আপনার উপর অর্পিত জ্ঞান এবং পথ-নির্দশনার কিছু আমাকে শেখাতে পারেন?\""],
  "18:67": ["He said: You will never be able to be of the sabirin with me.", "সে বলল, \"তুমি আমার সাথে স্থির থাকতে পারবে না।"],
  "18:68": ["And how could you be of the sabirin over what you have not tuhit in knowledge?", "“কিভাবে তুমি তাতে স্থির থাকবে যা তুমি বোঝো না?”"],
  "18:69": ["He said: You will find me sabir, Allah willing, and I will not disobey any command of yours.", "সে বলল, “আল্লাহ চাইলে, আমাকে আপনি ধৈর্যশীল পাবেন। আমি আপনার দেয়া কোন আদেশে অবাধ্য হবো না।\""],
  "18:70": ["He said: Then if you follow me, do not ask me about anything until I myself speak to you of it.", "সে বলল, \"যদি তুমি আমার অনুসরণ করো, তাহলে আমাকে কোনকিছুর বিষয়ে তুমি জিজ্ঞেস করবে না, যদি না আমি তোমাকে এ বিষয়ে বলতে পছন্দ করি।”"],
  "18:71": ["So the two set out, until, when they boarded the ship, he breached it. He said: Have you breached it to drown its people? You have certainly done a grievous thing.", "সুতারাং তারা চললো। যখন তারা জাহাজে আরোহন করলো, তাতে সে একটি ছিদ্র করলো। সে বলল, \"আপনি কি লোকদের ডুবানোর জন্য এতে ছিদ্র করেছেন? আপনি ভয়ানক কিছু করেছেন।\""],
  "18:72": ["He said: Did I not say that you would never be able to be of the sabirin with me?", "সে বলল, \"আমি কি বলিনি যে তুমি আমার সাথে স্থির থাকতে পারবে না?\""],
  "18:73": ["He said: Do not take me to task for my forgetting, and do not overwhelm my affair with hardship.", "সে বলল, \"আমি দুখিঃত। আমার ভূলো-মনার জন্য আমাকে শাস্তি দিয়েন না; আমার প্রতি এতো রূঢ় হইয়েন না।\""],
  "18:74": ["So the two set out, until, when they met a boy, he killed him. He said: Have you killed a pure nafs for no nafs? You have certainly done a dreadful thing.", "তাই তারা চললো। যখন তারা এক কমবয়সী বালকের সাক্ষাৎ পেল। সে বলল, কেন আপনি এমন নিষ্পাপ আত্মাকে হত্যা করলেন,  যে কিনা অন্য মানুষকে হত্যা করেনি? আপনি জঘন্যতম কিছু করেছেন।\""],
  "18:75": ["He said: Did I not tell you that you would never be able to be of the sabirin with me?", "সে বলল, \"আমি কি বলিনি যে তুমি আমার সাথে স্থির থাকতে পারবে না?\""],
  "18:76": ["He said: If I ask you about anything after this, then keep my company no longer — from me you have an excuse.", "সে বলল, “আমি যদি আপনাকে আর কোনকিছু জিজ্ঞেস করি, তবে আমাকে আপনার সাথে রাখবেন না। আপনি আমার কাছ থেকে যথেষ্ঠ অনুনয় দেখেছেন।”"],
  "18:77": ["So the two set out, until, when they came to the people of a town, they asked its people for food, but they refused to host them. And they found in it a wall about to fall down, and he set it up. He said: If you wished, you could have taken a wage for it.", "সুতারাং তারা চললো। যখন তারা কোন নির্দিষ্ট সম্প্রদায়ের কাছে পৌছঁলো, তারা লোকদের নিকট খাবার চাইলো, কিন্তু তাদের আপ্যায়ন করতে তারা অস্বীকৃতি জানালো। কিছুক্ষনের মধ্যেই, তারা একটি দেয়ালকে ধ্বসে পড়ার মুখে পেল, এবং সে তা মেরামত করলো। সে বলল, “আপনি এর জন্য পারিশ্রমিক চাইতে পারতেন?”"],
  "18:78": ["He said: This is the parting between me and you. I will tell you the interpretation of what you were not able to be of the sabirin over.", "সে বলল, “এখন আমাদের সঙ্গ ত্যাগ করতে হবে। তবে, আমি তোমাকে ব্যাখ্যা দিবো সবকিছুর যাতে তুমি স্থির থাকতে পারো নি।"],
  "18:79": ["As for the ship, it belonged to poor people working the sea, and I intended to damage it — for behind them was a king who seized every ship by force.", "“জাহাজটির বিষয়ে, এটি ছিল দরিদ্র জেলেদের, এবং এটিকে আমি ত্রুটিপূর্ণ করতে চেয়েছিলাম। একজন রাজা তাদের পিছনে আসছিল, যে  জোরপূর্বক সব জাহাজ জব্দ করছিল।"],
  "18:80": ["And as for the boy, his parents were muminin, and we feared he would overwhelm them with transgression and disbelief;", "বালকটির বিষয়ে, তার বাবা-মা ভাল বিশ্বাসী ছিল, এবং আমরা দেখলাম যে সে তার সীমালঙ্গন এবং অবিশ্বাসের কারণে তাদের বোঝা হতে যাচ্ছিল।"],
  "18:81": ["so we intended that their Rabb should substitute for them one better than him in purity and nearer in mercy.", "আমরা চেয়েছিলাম যে তোমার প্রভু তার জায়গায় আরেকটি পুত্র দেন; যে সৎকর্মশীলতা ও দয়ায় উত্তম হবে।"],
  "18:82": ["And as for the wall, it belonged to two orphan boys in the town, and beneath it was a treasure of theirs; their father had been salih. So your Rabb intended that they should reach their full strength and bring out their treasure — as mercy from your Rabb. I did not do it of my own command. That is the interpretation of what you could not be of the sabirin over.", "\"দেয়ালটির বিষয়ে, এটি শহরের দুই এতিম বালকের মালিকানায় ছিল। এর নীচে, তাদের গুপ্তধন ছিল। যেহেতু তাদের পিতা ছিল একজন সৎ লোক, তোমার প্রভু চেয়েছিলেন যে তারা বড় হয়ে উঠুক এবং পূর্ণ শক্তি অর্জন করুক, এরপর তাদের গুপ্তধন বের করে আনুক। এমনই তোমার প্রভুর দয়া। আমি এগুলোর কোনকিছুই নিজের ইচ্ছায় করিনি। এটাই হচ্ছে সেসব বিষয়ের ব্যাখ্যা যাতে তুমি স্থির থাকতে পারো নি।\""],
  "18:83": ["And they ask you about Dhul-Qarnayn. Say: I will recite to you an account of him.", "তারা যুলকারনাইনের বিষয়ে জিজ্ঞেস করে। বল, \"আমি তোমাদেরকে তার কিছু ইতিহাস বর্ণনা করবো।\""],
  "18:84": ["We established him in the land, and gave him the means to all things.", "আমরা পৃথিবীতে তাকে কর্তৃত্ব দিলাম, এবং তাকে সব ধরনের কলা-কৌশল দিলাম।"],
  "18:85": ["So he followed a course,", "এরপর, সে এক পথ ধরলো।"],
  "18:86": ["until, when he reached the setting-place of the sun, he found it setting into a muddy spring, and he found by it a people. We said: O Dhul-Qarnayn, either you punish, or you take among them a good course.", "যখন সে সুদূর পশ্চিমে পৌছঁল, সে সূর্যকে এক সুবিশাল সমুদ্রে অস্ত যেতে দেখলো, এবং সেখানে লোকদের সন্ধান পেয়েছিল। আমরা বললাম, \"হে যুলকারনাইন, তুমি তোমার ইচ্ছেমত শাসন করতে পারো, হয় শাস্তি দাও, অথবা তাদের প্রতি দয়ালু হও।"],
  "18:87": ["He said: As for the wrongdoer, we shall punish him; then he will be returned to his Rabb, who will punish him with a dreadful punishment.", "সে বলল, \"তাদের ক্ষেত্রে যারা সীমালঙ্ঘন করে, আমরা তাদের শাস্তি দিব, এরপর, যখন তারা তাদের প্রভুর কাছে ফিরে যাবে, তিনি তাদেরকে আরও অধিক শাস্তি দেবেন।"],
  "18:88": ["But as for the one who believes and does right — theirs is the fairest reward, and We shall speak to them of Our command with ease.", "\"আর যারা বিশ্বাস করে এবং সৎ-জীবন যাপন করে, তারা ভাল পুরষ্কার পায়; আমরা তাদের সাথে সদয় আচরণ করবো।\""],
  "18:89": ["Then he followed a course,", "এরপর, সে অন্য পথ ধরলো।"],
  "18:90": ["until, when he reached the rising-place of the sun, he found it rising upon a people for whom We had made no shelter from it.", "যখন সে সুদূর পূবে পৌছঁল, সে সূর্যকে লোকদের উপর উদয় হতে দেখল যাদের কাছে এটি থেকে আশ্র‍য় নেয়ার কিছু ছিল না।"],
  "18:91": ["So it was; and We ahatna in knowledge all that was with him.", "স্বভাবতই, আমরা তার দেখতে পাওয়া সবকিছু সম্পর্কে পূর্ণ অবগত ছিলাম।"],
  "18:92": ["Then he followed a course,", "এরপর, সে অন্য পথ ধরলো।"],
  "18:93": ["until, when he reached the stretch between the two barriers, he found beyond them a people who could scarcely understand a word.", "যখন সে দু’টি পর্বত চূড়ার মধ্যবর্তী উপত্যকায় পৌছাঁল, সে লোকদের পেয়েছিল যাদের ভাষা সামান্যই বুঝা যেতো।"],
  "18:94": ["They said: O Dhul-Qarnayn, Ya'juj and Ma'juj are spoilers in the land. Shall we pay you a tribute, on condition that you set a barrier between us and them?", "তারা বলল, “হে যুলকারনাইন, ইয়াজুজ ও মাজুজ পৃথিবীতে বিপর্যয় সৃষ্টিকারি। আমরা কি আমাদের ও তাদের মাঝে দেয়াল সৃষ্টি করার জন্য তোমাকে মজুরী দিতে পারি?\""],
  "18:95": ["He said: What my Rabb has established me in is better. So help me with strength, and I will set between you and them a rampart.", "সে বলল, “আমার প্রভু আমাকে মহা প্রাচুর্য দিয়েছেন। যদি তোমরা আমার সাথে সহযোগীতা করো, আমি তোমাদের ও তাদের মাঝে বাধঁ নির্মান করবো।"],
  "18:96": ["Bring me blocks of hadid. Then, when he had leveled between the two sides, he said: Blow — until, when he had made it a blaze, he said: Bring me molten metal to pour over it.", "আমার কাছে লোহার স্তুপ নিয়ে আসো।” যখনি সে দু’টি পর্বত চূড়ার মাঝখানের খালি জায়গা পূর্ণ করলো, সে বলল, \"বাতাস দাও”। যখন তা তপ্ত লাল হলো, সে বলল, “আমাকে এর উপর পিচ ঢালতে সাহায্য করো।”"],
  "18:97": ["So they could neither scale it nor make a breach in it.", "যেন, তারা এতে চড়তে করতে না পারে, না তারা এতে গর্ত খুঁড়তে পারে।"],
  "18:98": ["He said: This is a mercy from my Rabb. But when the promise of my Rabb comes, it will be leveled flat — and the promise of my Rabb is ever true.", "সে বলল, “এটি আমার প্রভুর পক্ষ থেকে দয়া। যখন আমার প্রভুর ভবিষদ্বানী ঘটবে, তিনি বাধঁটিকে ভেঙে টুকরো টুকরো করে দিবেন। আমার প্রভুর ভবিষ্যদ্বানী সত্য।"],
  "18:99": ["And that day We will leave them surging one into another, and the trumpet will be blown, and We will gather them as one gathering.", "সেই সময়, আমরা তাদের পরস্পরকে হানা-হানি করতে দেব, এরপর শিঙায় ফুঁ দেয়া হবে, এবং আমরা তাদের সবাইকে একত্রে তলব করবো"],
  "18:100": ["And We will present Hell on that day to the kafirin in full view,", "আমরা নরক উপস্থাপন করবো, ওই দিন, অবিশ্বাসীদের কাছে।"],
  "18:101": ["those whose eyes were under a covering from My remembrance, and who could not hear.", "তারাই সেইসব লোক যাদের চোখ এতটাই আবৃত ছিল যে তারা আমার বার্তা দেখতে পারছিল না। না তারা শুনতে পারছিল।"],
  "18:102": ["Do the kafirin think that they can take My servants as allies instead of Me? We have prepared Hell for the kafirin as a welcome.", "যারা অবিশ্বাস করে তারা কি মনে করে যে আমার বান্দাদেরকে উপাস্য বানিয়ে তারা পার পেয়ে যাবে? আমরা অবিশ্বাসীদের জন্য নরককে এক চিরস্থায়ী আবাস হিসেবে প্রস্তুত করেছি।"],
  "18:103": ["Say: Shall We tell you of the greatest losers in deeds?", "বল, “আমি কি তোমাদের বলব যে কারা সর্বাধিক ক্ষতিগ্রস্ত?"],
  "18:104": ["Those whose striving goes astray in the worldly life, while they think they are doing good work.", "“তারা সেই ব্যক্তি যাদের কাজ এই জীবনে পুরোপুরি বিপথে গেছে, কিন্তু তারা মনে করে যে তারা ভাল কাজ করছে।\""],
  "18:105": ["Those are the ones who disbelieve in the ayat of their Rabb and in the meeting with Him — so their deeds come to nothing, and on the Day of Standing We shall set no weight for them.", "তারা এমনই যারা তাদের প্রভুর প্রকাশনাবলিকে এবং তাঁর সাথে সাক্ষাতের বিষয়কে অবিশ্বাস করেছে। সুতরাং, তাদের কাজগুলো ব্যর্থ; পুনরুত্থান দিনে, তাদের কোন ওজন থাকবে না।"],
  "18:106": ["That is their recompense — Hell — for that they disbelieved and took My ayat and My rusul as mockery.", "তাদের উচিত প্রতিদান হচ্ছে নরক, তাদের অবিশ্বাসের বিনিময়ে, এবং আমার প্রকাশনাবলি ও বার্তাবাহকদের উপহাস করার কারনে।"],
  "18:107": ["Indeed, those who believe and do the right deeds — theirs are the Gardens of Paradise, as a welcome,", "তাদের ক্ষেত্রে যারা বিশ্বাস করে ও সৎ-জীবন যাপন করে তারা তাদের বাসস্থান হিসেবে এক পরম সুখের স্বর্গোদ্যানের যোগ্য হয়েছে।"],
  "18:108": ["abiding therein forever, never desiring any change from it.", "তারা চিরকাল সেখানে বসবাস করে; তারা কখনো অন্যকোন বিকল্প চাইবে না।"],
  "18:109": ["Say: If the sea were ink for the words of my Rabb, the sea would run dry before the words of my Rabb ran dry, even if We brought its like as more ink.", "বল, “আমার প্রভুর কথার জন্য সাগর যদি কালি হয়, সাগর ফুরিয়ে যাবে, আমার প্রভুর কথা ফুরানোর আগেই, এমনকি যদি আমরা কালির পরিমান দ্বিগুণও করি।"],
  "18:110": ["Say: I am only a human like you; it is revealed to me that your ilah is one ilah. So whoever hopes for the meeting of their Rabb, let them do a salih deed, and let them not associate anyone in the worship of their Rabb.", "বল,  “আমি তোমাদের মত একজন মানুষের চেয়ে বেশি কিছু নই,  প্রত্যাদিষ্ট হয়েছি যে তোমাদের খোদা একজন। যারা তাদের প্রভুর সাথে সাক্ষাতের আশা করে তারা সৎকর্ম করবে, এবং তার প্রভুর পাশে কখনো অন্যকোন উপাস্যের উপাসনা করবে না।"],
  "19:1": ["Kaf Ha Ya 'Ayn Sad", "ক. হ. উ. আ. স. (ক্বাফ হা ইয়া আইন সোয়াদ)"],
  "19:2": ["A mention of the mercy of your Rabb to Allah's servant Zakariya,", "এটি তোমার প্রভুর দয়া বিষয়ে একটি বর্ণনা তাঁর বান্দা জাকারিয়ার প্রতি।"],
  "19:3": ["when he secretly called his Rabb,", "সে তার প্রভুকে ডেকেছিল, গোপনে।"],
  "19:4": ["saying: My Rabb, my bones have weakened within me and my head has blazed white with age, and never, my Rabb, in calling You have I been wretched.", "সে বলল, \"আমার প্রভু, আমার দেহের হাড়গুলো ভঙ্গুর হয়ে পড়েছে, এবং আমার চুল পেকে সাদা হয়ে গেছে। আমার প্রভু, যেহেতু আমি আপনার কাছে প্রার্থনা করি, আমি কখনো হতাশ নই।"],
  "19:5": ["And I fear for my kin behind me, and my imra'a is barren; so grant me from Your presence a protector", "আমি আমার পর আমার উপর নির্ভরশীলদের জন্য চিন্তিত, এবং আমার স্ত্রী বন্ধা হয়ে আছে। আমাকে আপনার পক্ষ থেকে একজন উত্তরাধিকারী প্রদান করুন।"],
  "19:6": ["who will inherit me and inherit from the family of Yaqub; and make him, my Rabb, a pleasing one.", "তাকে আমার উত্তরাধিকারী করুন এবং উত্তরাধিকারি করুন ইয়াকুব গোত্রের, এবং আমার প্রভু, তাকে গ্রহনযোগ্য করুন।”"],
  "19:7": ["It was said: O Zakariya, We give you glad tidings of a boy whose name is Yahya; We have not made for him before a namesake.", "হে যাকারিয়া, আমরা তোমাকে সুসংবাদ দিচ্ছি; একটি বালকের যার নাম হবে ইয়াহিয়া। আমরা এর আগে কখনো তার মত কাউকে সৃষ্টি করিনি।”"],
  "19:8": ["He said: My Rabb, how can there be for me a boy when my imra'a is barren and I have reached extreme old age?", "সে বলল, “আমার প্রভু, আমি কি আমার স্ত্রীর বন্ধাত্য সত্ত্বেও, এবং আমার বৃদ্ধ বয়স সত্ত্বেও পুত্রসন্তান পাবো?"],
  "19:9": ["He said: So it shall be. Your Rabb has said: It is easy for Me, and I created you before when you were nothing.", "তিনি বললেন, “তোমার প্রভু এমনই বলেছেন: এটি আমার জন্য করা সহজ। এর আগে তোমাকে আমি সৃষ্টি করেছি, এবং তুমি কিছুই ছিলে না।”"],
  "19:10": ["He said: My Rabb, make for me an aya. He said: Your aya is that you shall not speak to the people for three nights running.", "সে বলল, “আমার প্রভু, আমাকে একটি নিদর্শন দিন।”তিনি বললেন, “তোমার নিদর্শন হচ্ছে যে তুমি পর পর তিন রাত লোকদের সাথে কথা বলবে না।”"],
  "19:11": ["Then he came out to his people from the niche and inspired to them that they should glorify morning and evening.", "সে বেড়িয়ে আসলো তার পরিবারের কাছে, উপাসনার জায়গা থেকে, এবং তাদের সংকেত দিলঃ “(আল্লাহর) ধ্যান করো দিনে এবং রাতে।”"],
  "19:12": ["O Yahya, take the Kitab resolutely; and We gave him judgment while a child,", "“হে ইয়াহইয়া, তুমি ঐশীগ্রন্থ আকঁড়ে থাকবে, দৃড়ভাবে।” আমরা তাকে প্রজ্ঞা দান করেছিলাম, এমনকি তার যৌবনেও।"],
  "19:13": ["and tenderness from Our presence, and purity; and he was of the muttaqin,", "এবং (আমরা তাকে দান করেছিলাম) আমাদের পক্ষ থেকে দয়া ও পবিত্রতা, কারণ সে ছিল সৎকর্মশীল।"],
  "19:14": ["and dutiful to his parents, and not overpowering, disobedient.", "সে তার মাতা-পিতাকে সম্মান করতো, এবং কখনো অবাধ্য স্বেচ্ছাচারী ছিল না।"],
  "19:15": ["And peace upon him the day he was born, the day he dies, and the day he is raised alive.", "তার উপর শান্তি বর্ষিত হোক যেদিন সে জন্মেছিল, যেদিন সে মারা যায়, এবং যেদিন সে জীবিত হয়ে পুনঃরুত্থিত হবে।"],
  "19:16": ["And mention in the Kitab Maryam, when she withdrew from her people to a place to the east.", "ঐশীগ্রন্থে মরিয়মের বিষয়ে উল্লেখ করো। সে তার পরিবার থেকে নিজেকে বিচ্ছিন্ন করেছিল, পূর্বদিকের একটি স্থানে।"],
  "19:17": ["And she took a veil, staying apart from them; then We sent Our ruh to her, and it appeared to her as a well-formed human.", "যখন একটি অন্তরায় তাদের থেকে তাকে আলাদা করলো, আমরা তার কাছে আমাদের আত্মা পাঠালাম। সে তার কাছে একজন মানুষ হিসেবে গিয়েছিল।"],
  "19:18": ["She said: I seek refuge with the Rahman from you, if you are of the muttaqin.", "সে (মরিয়ম) বলল, \"আমি পরম দয়ালুর নিকট আশ্রয় প্রার্থনা করি, যে তুমি হয়তো সৎকর্মশীল হবে।"],
  "19:19": ["He said: I am only a Rasul of your Rabb, to grant you a pure boy.", "সে বলল, \"আমি তোমার প্রভুর বার্তাবাহক, তোমাকে একটি নিষ্কলুষ পুত্র সন্তান দান করতে।"],
  "19:20": ["She said: How can there be for me a boy when no human has touched me and I have not been immoral?", "সে বলল, \"কিভাবে আমার কোন পুত্র সন্তান হতে পারে,  যখন কোন পুরুষ আমাকে স্পর্শ করেনি; আমি কখনো অসতী ছিলাম না।\""],
  "19:21": ["He said: So it shall be. Your Rabb has said: It is easy for Me, and that We may make him an aya for the people and a mercy from Us; and the matter was decreed.", "সে বলল, “তোমার প্রভু এমনই বলেছেন: 'এটি আমার জন্য সহজ। আমরা লোকদের জন্য তাকে করবো একটি নিদর্শন, এবং আমাদের পক্ষ থেকে দয়া। এটি একটি পূর্বনির্ধারিত বিষয়।\""],
  "19:22": ["So she carried him and withdrew with him to a remote place.", "যখন সে তাকে গর্ভে ধারণ করলো, সে নিজেকে দূরবর্তী স্থানে আড়াল করলো।"],
  "19:23": ["And the labor pangs drove her to the trunk of the palm. She said: Would that I had died before this and become a forgotten thing, forgotten.", "একটি খেঁজুর গাছের কান্ডের পাশে তার জন্মদান প্রক্রিয়াটি ঘটলো। সে বলল, \"(আমার এতো লজ্জা হচ্ছে;) এটা ঘটার আগে যদি আমার মৃত্যু হতো, এবং পুরোপুরি বিস্মৃত হতাম।"],
  "19:24": ["Then one called her from beneath her: Do not grieve; your Rabb has made beneath you a flowing stream.", "(নবজাতক) তার নীচ থেকে তাকে ডাকল, এ বলে যে, \"দুঃখ করো না। তোমার প্রভু তোমাকে একটি ঝর্ণা প্রদান করেছেন।"],
  "19:25": ["And shake the trunk of the palm toward you; it will drop upon you fresh dates, ripe.", "“যদি তুমি এই খেঁজুর গাছের কান্ডে ঝাঁকি দাও, এটি তোমার জন্য পাঁকা খেঁজুড় ফেলবে।"],
  "19:26": ["So eat and drink and comfort your eye; and if you see any human, say: I have vowed to the Raheem an abstention, so I shall not speak today to any human.", "“খাও ও পান করো, এবং সুখী হও। যখন তুমি কাউকে দেখবে, বলবে, ‘আমি মৌন থাকার প্রতিজ্ঞা করেছি; আজ আমি কারো সাথে কথা বলছি না।’”"],
  "19:27": ["She brought him to her people, carrying him. They said: O Maryam, you have surely brought a shocking thing.", "সে তার পরিবারের কাছে আসলো, তাকে (ঈসা) বহন করে। তারা বলল, হে মরিয়ম, তুমি এমন  কিছু করেছো যা পুরোপুরি অপ্রত্যাশিত।"],
  "19:28": ["O sister of Harun, your father was not a man of evil, nor was your mother immoral.", "হে হারুনের বংশধর, তোমার পিতা কোন খারাপ লোক ছিল না, না তোমার মা অসতী ছিল।\""],
  "19:29": ["So she gestured to him. They said: How can we speak to one who is in the cradle, a child?", "সে (মরিয়ম) তার দিকে নির্দেশ করলো। তারা বলল, \"কেমন করে কোলের শিশুর সাথে আমরা কথা বলবো?\""],
  "19:30": ["He said: I am the servant of Allah; Allah gave me the Kitab and made me a Nabi,", "(নবজাতক কথা শুরু করল এবং) বলল, \"আমি আল্লাহর একজন সেবক। তিনি আমাকে ঐশীগ্রন্থ দিয়েছেন, এবং আমাকে একজন নবী নিযুক্ত করেছেন।"],
  "19:31": ["and made me blessed wherever I may be, and enjoined on me prayer and purity as long as I remain alive,", "যেখানেই আমি যাই তিনি আমাকে সৌভাগ্যশালী করেছেন, এবং আমাকে আদেশ করেছেন সংযোগ প্রার্থনা (সালাত) ও বাধ্যতামূলক দান (যাকাত) পালন করতে যতদিন আমি বাঁচি।"],
  "19:32": ["and dutiful to my mother, and did not make me a tyrant, wretched.", "আমাকে আমার মায়ের সম্মান করতে হবে; আমাকে তিনি (আল্লাহ) অবাধ্য বিদ্রোহী বানাননি।"],
  "19:33": ["And peace upon me the day I was born, the day I die, and the day I am raised alive.", "“এবং আমার উপর শান্তি হোক যেদিন আমি জন্মেছি, যেদিন আমি মারা যাই, এবং যেদিন আমি পুনরুত্থিত হই।\""],
  "19:34": ["That is Isa, son of Maryam — a word of truth in which they doubt.", "সে-ই ছিল ঈসা, মরিয়ম পুত্র, এবং এটা-ই সত্য, যে বিষয়ে তারা সন্দেহ করতে থাকে।"],
  "19:35": ["It is not for Allah to take a child; glory be to Allah. When Allah decrees a matter, Allah only says to it: Be, and it is.", "এটা আল্লাহর সাথে মানায় না যে তিনি পুত্র সন্তান জন্ম দেন, তিনি মহিমান্বিত। কোনকিছু করতে হলে, তিনি একে শুধু বলেন, “হও, ”এবং তা হয়ে যায়।"],
  "19:36": ["And indeed Allah is my Rabb and your Rabb, so worship Allah; this is a straight path.", "তিনি আরো ঘোষনা করলেন, “আল্লাহ আমার প্রভু এবং তোমাদের প্রভু; তোমরা কেবল তাঁরই উপাসনা করবে। এটাই সত্য পথ।"],
  "19:37": ["So the parties differed among themselves. Woe to those who disbelieve from the witnessing of a great day.", "(ঈসার পরিচয়ের বিষয়ে) বিভিন্ন দল নিজেদের মাঝে বিবাদ করেছে। একারণে, দূর্ভোগ তাদের প্রতি যারা এক ভয়ানক দিনের সাক্ষাতে অবিশ্বাস করে।"],
  "19:38": ["How keenly they will hear and see the day they come to Us; but the wrongdoers are today in clear error.", "অপেক্ষা কর যে পর্যন্ত না তুমি তাদের শুনছো এবং দেখছো যখন তারা আমাদের মুখোমুখি হতে আসে। সীমালঙ্ঘনকারীরা ঐদিন পুরোপুরি ক্ষতিগ্রস্ত হবে।"],
  "19:39": ["And warn them of the day of regret, when the matter is decreed while they are unaware, and they do not believe.", "তাদেরকে অনুশোচনার দিন সম্পর্কে সতর্ক করো, যখন বিচার প্রকাশ হবে।  তারা পুরোপুরি বেখবর; তারা বিশ্বাস করে না।"],
  "19:40": ["Indeed We shall inherit the earth and whoever is upon it, and to Us they will be returned.", "আমরাই সেই সত্ত্বা যারা পৃথিবীর এবং এর সবকিছুর উত্তরাধিকার করি; আমাদের কাছেই সকলে ফিরে আসবে।"],
  "19:41": ["And mention in the Kitab Ibrahim; he was a sadiq Nabi,", "ঐশীগ্রন্থে ইব্রাহিমের উল্লেখ করো; সে ছিল একজন সাধু, একজন নবী।"],
  "19:42": ["when he said to his father: My father, why do you worship what neither hears nor sees nor avails you anything?", "সে তার পিতাকে বলল, \"হে আমার পিতা, কেন তুমি তার উপাসনা করো যা না পারে শুনতে, না পারেদেখতে, না তোমাকে কোনভাবে সাহায্য করতে পারে?"],
  "19:43": ["My father, knowledge has come to me that has not come to you; so follow me, I will guide you to a straight path.", "হে আমার পিতা,  আমি সুনির্দিষ্ট জ্ঞান পেয়েছি যা তুমি পাও নি। আমাকে অনুসরণ করো, এবং আমি তোমাকে সোজা পথ দেখাবো।"],
  "19:44": ["My father, do not worship Shaytan; indeed Shaytan was ever disobedient to the Raheem.", "হে আমার পিতা, শয়তানের উপাসনা করো না। শয়তান পরম দয়ালুর বিরুদ্ধে বিদ্রোহ করেছে।"],
  "19:45": ["My father, I fear that a punishment from the Rahman will touch you, so that you become an ally of Shaytan.", "হে আমার পিতা, আমার ভয় হয় পাছে তুমি পরম দয়ালু থেকে শাস্তি টেনে আনো, এরপর শয়তানের মিত্র হয়ে পড়ো।"],
  "19:46": ["He said: Are you so eager to turn from my alihah, Ibrahim? If you do not cease, I will surely stone you; so leave me for a long while.", "সে বলল, \"তুমি কি আমার উপাস্যদের পরিত্যাগ করছো, হে ইব্রাহিম? যদি না তুমি থামো, আমি তোমাকে পাথর মারবো। আমাকে আমার মত থাকতে দাও।"],
  "19:47": ["He said: Peace be upon you; I shall ask forgiveness for you from my Rabb; indeed my Rabb has ever been gracious to me.", "সে বলল, \"তোমার উপর শান্তি বর্ষিত হোক। তোমার ক্ষমার জন্য আমি আমার প্রভুর কাছে মিনতি করবো; তিনি আমার প্রতি পরম দয়ালু।"],
  "19:48": ["And I withdraw from you and from what you call upon besides Allah, and I call upon my Rabb; perhaps in calling my Rabb I shall not be wretched.", "আমি তোমাকে এবং আল্লাহর পাশে তোমার উপাসনা করা উপাস্যদের পরিত্যাগ করবো। আমি শুধু আমার প্রভুর উপাসনা করবো। শুধুমাত্র আমার প্রভুর কাছে প্রার্থনা করে, আমি ভুল করতে পারিনা।"],
  "19:49": ["Then when he withdrew from them and from what they worshipped besides Allah, We granted him Ishaq and Yaqub, and each We made a Nabi,", "যেহেতু সে তাদেরকে এবং আল্লাহর পাশে তাদের উপাসনা করা উপাস্যদের পরিত্যাগ করেছিল, আমরা তাকে দিয়েছিলাম ইসহাক ও ইয়াকুব, এবং আমরা তাদের প্রত্যেককে নবী বানিয়েছিলাম।"],
  "19:50": ["and We granted them of Our mercy, and We gave them a tongue of truth, raised high.", "আমরা তাদের প্রতি আমাদের দয়া বর্ষণ করেছিলাম, এবং আমরা তাদেরকে ইতিহাসে এক সম্মানিত স্থান দিয়েছিলাম।"],
  "19:51": ["And mention in the Kitab Musa; he was devoted, and was a Rasul, a Nabi,", "ঐশীগ্রন্থে মুসার উল্লেখ করো। সে ছিল নিবেদিত, এবং সে ছিল বার্তাবাহক নবী।"],
  "19:52": ["and We called him from the right side of the Mount and drew him near in private.", "আমরা সিনাই পর্বতের ডান পাশ থেকে তাকে ডেকেছিলাম। আমরা তাকে নিকটে এনেছিলাম, তার সাথে পরামর্শ করতে।"],
  "19:53": ["And We granted him of Our mercy his brother Harun, a Nabi.", "এবং আমরা তাকে দিয়েছিলাম, আমাদের দয়া থেকে, তার ভাই হারুনকে একজন নবী হিসেবে।"],
  "19:54": ["And mention in the Kitab Ismail; he was true to the promise, and was a Rasul, a Nabi,", "এবং ঐশীগ্রন্থে ইসমাইলের উল্লেখ করো। সে ছিল সত্যবাদী যখন সে কোন প্রতিজ্ঞা করতো, এবং সে ছিল একজন বার্তাবাহক নবী।"],
  "19:55": ["and he used to command his household with prayer and purity, and he was pleasing near his Rabb.", "সে তার পরিবারকে সংযোগ প্রার্থনা (সালাত) ও বাধ্যতামূলক দান (যাকাত) পালনের নির্দেশ দিত; সে ছিল তার প্রভুর কাছে গ্রহণযোগ্য।"],
  "19:56": ["And mention in the Kitab Idris; he was a sadiq Nabi,", "এবং ঐশীগ্রন্থে ইদ্রিসের উল্লেখ করো। সে ছিল একজন সাধু, একজন নবী।"],
  "19:57": ["and We raised him to a high place.", "আমরা তাকে এক সম্মানিত পদমর্যাদায় উন্নীত করেছিলাম।"],
  "19:58": ["Those are the ones upon whom Allah bestowed favor among the nabis: from the offspring of Adam, and from those We carried with Nuh, and from the offspring of Ibrahim and Israel, and from those We guided and chose; when the ayat of the Rahman are recited to them, they fall down prostrating and weeping.", "এরা হচ্ছে নবীদের কয়েকজন যাদেরকে আল্লাহ অনুগ্রহ করেছিলেন। তদের পছন্দ করা হয়েছিল আদমের বংশধরদের থেকে, এবং তাদের বংশধর থেকে যাদেরকে আমরা নুহের সাথে বহন করেছিলাম, এবং ইব্রাহিম ও ইসরাইলের বংশধরদের থেকে, এবং তাদের মধ্য থেকে যাদের আমরা পথপ্রদর্শণ এবং নির্বাচিত করেছিলাম। যখন পরম দয়ালুর প্রকাশনাবলি তাদের কাছে আবৃতি করা হয়, তারা সেজদায় পড়ে কাদঁতে থাকে।"],
  "19:59": ["Then after them came successors who lost the prayer and followed the desires; so they will soon meet error,", "তাদের পর, তিনি সে প্রজন্মদের প্রতিস্থাপন করেছিলেন যারা সংযোগ প্রার্থনা (সালাত) হারিয়েছিল, এবং তাদের লালসার পিছনে ছুটেছিল। তারা পরিনাম ভোগ করবে।"],
  "19:60": ["except whoever repents and believes and works salihness; those will enter the Garden and will not be wronged in anything.", "কেবল যারা অনুশোচনা করে, বিশ্বাস করে, এবং সৎকর্মশীল জীবন যাপন করে তারা স্বর্গোদ্যানে প্রবেশ করবে, সামান্যতম অবিচার ছাড়াই।"],
  "19:61": ["Gardens of Adn that the Rahman promised to Allah's servants in the ghayb; indeed the promise of Allah is sure to come.", "ইডেনের বাগানগুলো তাদের জন্য অপেক্ষা করে, যেমন পরম দয়ালু অংগীকার করেছিলেন তাদের জন্য যারা তাঁর উপাসনা করে, এমনকি একাকিত্বে। নিশ্চিতভাবে, তাঁর অংগীকার অবশ্যই সংঘটিত হবে।"],
  "19:62": ["They will not hear idle talk therein, only peace; and their provision is theirs therein morning and evening.", "তারা সেখানে কোন আজে-বাজে কথা-বার্তা শুনবে না; কেবলই শান্তি। তারা সেখানে তাদের রিজিক পাবে, দিন ও রাতে।"],
  "19:63": ["That is the Garden We make Our servants heirs to — whoever is of the muttaqin.", "এমনই স্বর্গোদ্যান; আমরা আমাদের বান্দাদের মধ্য থেকে তাদের জন্য এটা মঞ্জুর করি যারা সৎকর্মশীল।"],
  "19:64": ["And We do not descend except by command of your Rabb. To Allah belongs what is before us and what is behind us and what is between that; and your Rabb is not forgetful.", "তোমার প্রভুর আদেশ ছাড়া আমরা অবতরণ করি না। তাঁর অধীনে রয়েছে আমাদের অতীত, আমাদের ভবিষ্যৎ, এবং এদের মধ্যকার সবকিছু। তোমার প্রভু কখনো ভূলেন না।"],
  "19:65": ["Rabb of the heavens and the earth and what is between them, so worship Allah and persevere in Allah's worship. Do you know any namesake of Allah?", "প্রভু আকাশমণ্ডলী ও পৃথিবীর, এবং এদের মধ্যকার সবকিছুর; তোমরা তাঁর উপাসনা করবে এবং তাঁর উপাসনায় অবিচলতার সাথে অটল থাকবে। তুমি কি কাউকে জানো যে তাঁর সমান?"],
  "19:66": ["And the human says: When I have died, will I really be brought out alive?", "মানুষ জিজ্ঞেস করে, \"আমি মরে যাবার পর, আমি কি পুনরায় জীবিত হব?\""],
  "19:67": ["Does the human not remember that We created him before, when he was nothing?", "মানুষ কি ভুলে যায় যে আমরা তাকে ইতোমধ্যেই সৃষ্টি করেছি, এবং সে কিছুই ছিল না?"],
  "19:68": ["So by your Rabb, We will surely gather them and the satans; then We will surely bring them around Jahannam, kneeling.", "তোমার প্রভুর শপথ, আমরা অবশ্যই তাদের তলব করবো, শয়তানের সাথে একসঙ্গে, এবং নরকের চারপাশে তাদের একত্র করবো, অপদস্থ অবস্থায়।"],
  "19:69": ["Then We will surely draw out from every party which of them was strongest in insolent defiance against the Rahman.", "এরপর আমরা প্রত্যেক দল থেকে পরম দয়ালুর সবচেয়ে ঘোর বিরোধীদের বেছে নিব।"],
  "19:70": ["Then We know best those who are most worthy of it, entering the fire.", "আমরা তাদেরকে খুব ভাল করেই জানি যারা সেখানে পোড়ার সবচেয়ে উপযুক্ত।"],
  "19:71": ["There is not one of you but will arrive at it; upon your Rabb is a decree, decided.", "তোমাদের প্রত্যেকে অবশ্যই এটি দেখবে; এটা তোমার প্রভুর এক অনড় সিদ্ধান্ত।"],
  "19:72": ["Then We will save those who were muttaqin and leave the wrongdoers in it, kneeling.", "এরপর আমরা সৎকর্মশীলদের উদ্ধার করবো, এবং সীমালঙ্ঘনকারীদের এতে ছেড়ে দেবো, অপদস্থ অবস্থায়।"],
  "19:73": ["And when Our ayat are recited to them clear, those who disbelieve say to those who believe: Which of the two groups is better in station and better in call?", "যখন তাদের কাছে আমাদের প্রকাশনাবলি অবৃতি করা হয়, সুস্পষ্টভাবে, যারা অবিশ্বাস করে তারা যারা বিশ্বাস করে তাদেরকে বলে, \"আমাদের মধ্যে কারা অধিক সমৃদ্ধশালী? আমাদের মধ্যে কারা সংখ্যাগরিষ্ঠ?"],
  "19:74": ["And how many generations We destroyed before them who were better in goods and appearance.", "তাদের আগে আমরা অনেক প্রজন্মকে ধ্বংস করেছি; তারা ছিল অধিক ক্ষমতাবান, এবং অধিক সমৃদ্ধশালী।"],
  "19:75": ["Say: Whoever is in error — let the Rahman extend him an extension, until when they see what they are promised: either the punishment or the Hour. Then they will know who is worse in place and weaker in host.", "বল, \"যারা বিপথে যাওয়া পছন্দ করে, পরম দয়ালু তাদের পরিচালিত করবেন, যে পর্যন্ত না তারা দেখে যা তাদের অংগীকার করা হয়েছে- হয় শাস্তি নয়তো সেই ঘন্টা। ঠিক তখনই তারা দেখবে যে কে অধিকতর মন্দ অবস্থায় রয়েছে, এবং ক্ষমতায় দূর্বলতম।"],
  "19:76": ["And Allah increases those who are guided in guidance; and the lasting good deeds are better near your Rabb in reward and better in return.", "আল্লাহ তাদের পথপ্রাপ্তি বাড়িয়ে দেন যারা পথপ্রাপ্ত হওয়া পছন্দ করে। কেননা ভাল কাজ তোমার প্রভুর দ্বারা চিরস্থায়ীভাবে পুরষ্কৃত হয়, এবং অনেক উত্তম প্রতিদান ফিরিয়ে আনে।"],
  "19:77": ["Have you seen the one who disbelieved in Our ayat and said: I shall surely be given wealth and children?", "তুমি কি সে ব্যক্তিকে লক্ষ্য করেছ যে আমাদের প্রকাশনাবলিকে প্রত্যাখ্যান করেছিল এরপর বলল, \"আমাকে সম্পদ এবং সন্তানাদি দেয়া হবে\"?!"],
  "19:78": ["Has he perceived the ghayb, or taken a covenant near the Rahman?", "সে কি ভবিষ্যৎ দেখেছে? সে কি পরম করুণাময়ের কাছ থেকে এমন কোন অঙ্গীকার নিয়েছে?"],
  "19:79": ["No indeed; We will write what he says and extend for him from the punishment an extension,", "নিশ্চয়, আমরা সংরক্ষন করবো যা সে বলে, এরপর তাকে চিরবর্ধনশীল শাস্তিতে ফেলবো।"],
  "19:80": ["and We will inherit what he says, and he will come to Us alone.", "এরপর আমরা তার অধিকৃত সবকিছু উত্তরাধিকার করি, এবং সে আমাদের কাছে ফিরে আসে সম্পূর্ণ একা।"],
  "19:81": ["And they took alihah besides Allah, that they might be for them a protection.", "তারা আল্লাহর পাশে অন্য উপাস্যদের উপাসনা করে যাতে তাদের সাহায্যে আসতে পারে।"],
  "19:82": ["No indeed; they will soon disbelieve their worship of them and will be opposed to them.", "উলটো; তারা তাদের অপখোদা উপাসনা করাকে প্রত্যাখ্যান করবে, এবং তাদের শত্রু হয়ে যাবে।"],
  "19:83": ["Have you not seen that We sent the satans upon the kafirin, inciting them to frenzy?", "তুমি কি দেখো না কিভাবে আমরা অবিশ্বাসীদের পিছনে শয়তানদের ছেড়ে দেই তাদের উত্তেজিত করতে?"],
  "19:84": ["So do not hasten over them; We only count for them a counting.", "অধৈর্য হইও না; আমরা তাদের জন্য প্রস্তুত করছি কিছু প্রস্তুতি।"],
  "19:85": ["The day We gather the ilah-fearing to the Rahman as a delegation,", "সে দিন আসবে যখন আমরা পরম করুণাময়ের সামনে সৎকর্মশীলদের তলব করবো একটি দলে।"],
  "19:86": ["and We drive the mujrimin to Jahannam, arriving.", "এবং আমরা অপরাধীদেরকে নরকের দিকে দলবদ্ধভাবে নিয়ে যাবো, তাদের চিরস্থায়ী আবাসে থাকার জন্য।"],
  "19:87": ["They will not possess intercession, except whoever took a covenant near the Rahman.", "কেউ সুপারিশ করার অধিকার রাখবে না, তারা ব্যতীত যারা পরম করুণাময়ের আইনের অনুরুপ কাজ করবে।"],
  "19:88": ["And they said: The Raheem has taken a child.", "তারা বলল, “পরম করুনাময় পুত্র জন্ম দিয়েছেন!”"],
  "19:89": ["You have surely come with a monstrous thing —", "তোমরা এক ঘোর মিথ্যাচার উচ্চারণ করেছো।"],
  "19:90": ["nearly the heavens burst apart from it, and the earth splits open and the mountains fall down in haddan —", "আকাশমণ্ডলী যেন চূর্ণ হয়ে যাবে, পৃথিবী যেন খন্ড-বিখন্ড হয়ে যাবে, এবং পর্বত যেন টুকরো টুকরো হয়ে যাবে।"],
  "19:91": ["that a child was claimed for the Raheem.", "কারণ তারা দাবী করে যে পরম করুনাময় পুত্র জন্ম দিয়েছেন।"],
  "19:92": ["And it is not befitting for the Raheem to take a child.", "এটা পরম করুনাময়কে মানায় না যে তিনি পুত্র জন্ম দিবেন।"],
  "19:93": ["Indeed every one in the heavens and the earth comes to the Rahman only as a servant;", "আকাশমন্ডলী ও পৃথিবীর প্রত্যেকে পরম করুনাময়ের বান্দা।"],
  "19:94": ["indeed Allah has counted them all and numbered them one by one,", "তিনি তাদের বেষ্টন করে আছেন, এবং তাদেরকে এক এক করে গুনে রেখেছেন।"],
  "19:95": ["and every one of them will come to Allah on the day of Resurrection, alone.", "পুনরুত্থান দিনে তারা সকলে তাঁর সামনে আসবে, পৃথকভাবে।"],
  "19:96": ["Indeed those who believe and work salihness — the Rahman will make affection for them.", "নিশ্চয়ই, যারা বিশ্বাস করে এবং সৎ জীবন যাপন করে, পরম করুনাময় তাদের উপর ভালবাসা বর্ষণ করবেন।"],
  "19:97": ["So We have made it easy only upon your tongue, that you may give glad tidings with it to the ilah-fearing and warn with it a quarrelsome people.", "আমরা এভাবে তোমার ভাষায় একে (কুরআন) সহজ করেছি, সৎকর্মশীলদের কাছে সুসংবাদ পৌঁছে দিতে, এবং প্রতিপক্ষকে এর দ্বারা সতর্ক করতে।"],
  "19:98": ["And how many generations We destroyed before them — do you perceive anyone of them, or hear from them a sound?", "তাদের পূর্বে আমরা অনেক প্রজন্ম ধ্বংস করেছি; তুমি কি তাদের কাউকে অনুধাবন করো, অথবা তাদের কোন শব্দ শুনো?"],
  "20:1": ["Ta Ha", "ত. হা."],
  "20:2": ["We did not reveal the Recitation upon you to make you wretched,", "তোমাকে কোন কষ্টে ফেলতে, আমরা তোমার কাছে কুরআন প্রকাশ করিনি।"],
  "20:3": ["but as a reminder for whoever holds reverent awe.", "শুধুমাত্র ভক্তদের স্মরণ করাতে।"],
  "20:4": ["A revelation from the One who created the earth and the highest heavens —", "পৃথিবী ও উর্ধ্ব আকাশমন্ডলীর সৃষ্টিকর্তার পক্ষ থেকে একটি প্রকাশনা।"],
  "20:5": ["the Rahman is established above the high seat.", "পরম দয়ালু; তিনি সকল কর্তৃত্ব গ্রহন করেছেন।"],
  "20:6": ["To Allah belongs what is in the heavens and what is in the earth, and what is between them, and what is beneath the soil.", "আকাশমন্ডলী, ও পৃথিবীর সবকিছু, এবং এগুলোর মাঝের সবকিছু, এবং ভূপৃষ্ঠের নিম্নস্থ সবকিছু তাঁর অধীন।"],
  "20:7": ["And if you speak open and loud, then Allah knows the secret and what is more hidden.", "তুমি তোমার প্রত্যয় প্রকাশ করো (বা না করো) তিনি জানেন গোপন বিষয়টি, এবং যা তার চেয়েও গভীরে লুকায়িত।"],
  "20:8": ["Allah — there is no ilah except Allah; to Allah belong the finest names.", "আল্লাহ : তাঁর পাশে অন্য কোন উপাস্য নেই। সবচেয়ে সুন্দর নামগুলো তাঁরই।"],
  "20:9": ["Has the hadith of Musa come to you?", "তুমি কি মুসার ইতিহাস লক্ষ্য করেছ?"],
  "20:10": ["When he saw a fire, and said to his people: \"Stay; I have perceived a fire. Perhaps I can bring you from it a flaming brand, or find at the fire some guidance.\"", "যখন সে আগুন দেখল, সে তার পরিবারকে বলল, \"এখানে থাকো। আমি আগুন দেখেছি। হয়তো আমি তা থেকে তোমাদের জন্য কিছু নিয়ে আসতে পারি, অথবা আগুনের কাছে কিছু পথ-নির্দেশনা পেতে পারি।”"],
  "20:11": ["When he came to it, he was called: \"O Musa!\"", "যখন সে এর কাছে এলো, তাকে ডাকা হলো, \"হে, মুসা।"],
  "20:12": ["\"Indeed, I am your Rabb. So remove your sandals; you are in the holy valley of Tuwa.\"", "আমি তোমার প্রভু; তোমার জুতো খুলো। তুমি পবিত্র উপত্যকা তুয়ায়।"],
  "20:13": ["\"And I have chosen you, so listen to what is revealed:\"", "আমি তোমাকে পছন্দ করেছি, অতঃএব শুনো যা প্রকাশিত হচ্ছে।"],
  "20:14": ["\"Indeed, I am Allah; there is no ilah except I. So worship Me and establish the prayer for remembrance of Me.\"", "\"আমি আল্লাহ; আমার পাশে অন্যকোন উপাস্য নেই। তুমি কেবল আমারই উপাসনা করবে, এবং আমার স্মরনার্থে/আমাকে স্মরণ করতে সংযোগ প্রার্থণা (সালাত) পালন করবে।"],
  "20:15": ["\"Indeed, the Hour is coming — I nearly conceal it — so that every nafs may be recompensed for what it strives.\"", "সেই সময় (বিশ্বের সমাপ্তি) নিশ্চিতই আসছে; একে আমি প্রায় গোপনই রাখবো। কেননা প্রত্যেক আত্মাকে এর কাজের পাওনা অবশ্যই পেতে হবে।"],
  "20:16": ["So let no one who does not believe in it and has followed his desire turn you away from it, and plunge to ruin.", "“তাদের দ্বারা এ থেকে বিচ্যুত হইও না যারা এতে বিশ্বাস করে না- যারা নিজেদের ধারনার অনুসরন করে - যাতে তোমার পতন না হয়।"],
  "20:17": ["\"And what is that in your right hand, O Musa?\"", "“তোমার ডান হাতে এটা কি, মুসা?”"],
  "20:18": ["He said: \"It is my staff; I lean on it, and I beat down leaves with it for my sheep, and I have other uses for it.\"", "সে বলল, “এটি আমার লাঠি। আমি এতে ভর দেই, এটি দিয়ে আমার ভেড়া চরাই, এবং একে আমি অন্য কাজেও ব্যবহার করি।”"],
  "20:19": ["He said: \"Cast it down, O Musa.\"", "তিনি বললেন, “এটি নিচে ছুড়ো,  মুসা।”"],
  "20:20": ["So he cast it down, and behold, it was a living snake, moving swiftly.", "সে এটি নিচে ছুড়ঁলো, যারপর এটি পরিনত হলো একটি চলন্ত সাপে।"],
  "20:21": ["He said: \"Take it, and do not fear. We will restore it to its former movement.\"", "তিনি বললেন, তোলো এটা; ভয় পেয়ো না। আমরা একে এর আসল অবস্থায় ফিরিয়ে দেবো।"],
  "20:22": ["\"And clasp your hand to your side; it will come out white, without harm — another aya,\"", "এবং তোমার হাত তোমার বাহুর নিচে রাখো; এটি নিখুঁত সাদা হয়ে বেড়িয়ে আসবে; আরেকটি প্রমান।"],
  "20:23": ["that We may show you some of Our greatest ayat.", "এভাবে আমরা তোমাকে আমাদের মহানিদর্শণগুলোর কিছু দেখাই।"],
  "20:24": ["Go to Fir'awn; he has transgressed.", "ফেরাউন-এর কাছে যাও, কারণ সে সীমালংঘন করেছে।”"],
  "20:25": ["He said: \"Rabb, open my chest for me,", "সে বলল, “আমার প্রভু, আমার মেজাজ শান্ত করুন।"],
  "20:26": ["and make my affair easy for me,", "এবং এ বিষয়টা আমার জন্য সহজ করে দিন।"],
  "20:27": ["and untie a knot from my tongue,", "এবং আমার মুখের জড়তা দূর করে দিন।"],
  "20:28": ["that they may understand my speech.", "যেন তারা আমার কথা বুঝতে পারে।"],
  "20:29": ["And appoint for me a vizier from my family,", "এবং আমার পরিবার থেকে আমার জন্য একজন সহকারী নিযুক্ত করে দিন।"],
  "20:30": ["Harun, my brother.", "আমার ভাই হারুন।"],
  "20:31": ["Strengthen my back through him,", "তাকে দিয়ে আমাকে শক্তিশালী করুন।"],
  "20:32": ["and let him share in my affair,", "তাকে এই বিষয়ে আমার অংশীদার করুন।"],
  "20:33": ["that we may glorify You much", "যাতে আমরা প্রতিনিয়ত আপনার মহিমা প্রকাশ করতে পারি।"],
  "20:34": ["and remember You much.", "এবং প্রতিনিয়ত আপনার স্মরণ করতে পারি।"],
  "20:35": ["Indeed, You have been watchful over us.\"", "‘‘আপনি আমাদের দ্রষ্টা।’’"],
  "20:36": ["He said: \"You have been given your request, O Musa.", "তিনি বললেন, “তোমার অনুরোধ মঞ্জুর করা হলো, হে মূসা।"],
  "20:37": ["And We favored you another time,", "আমরা তোমাকে আরেকবার অনুগ্রহ করেছিলাম।"],
  "20:38": ["when We revealed to your mother what was revealed:", "যখন আমরা তোমার মায়ের কাছে যা প্রকাশ করার ছিল তা প্রকাশ করেছিলাম।"],
  "20:39": ["Cast him into the chest, then cast it into the sea, and the sea will throw it onto the shore; an enemy of Mine and an enemy of his will take him. And I cast upon you love from Me, and that you be made under My eye.", "এ বলে যেঃ ‘তাকে বাক্সে রাখো, এরপর তাকে নদীতে ভাসিয়ে দাও। নদী তাকে তীরে নিয়ে যাবে, আমার এবং তার একজন শত্রু তাকে তুলে নেবার জন্য।’’ আমি আমার পক্ষ থেকে তোমার প্রতি ভালোবাসা বর্ষণ করেছিলাম, এবং আমার সজাগ দৃষ্টির সামনেই আমি তোমাকে তৈরি করেছিলাম।"],
  "20:40": ["When your sister walked by and said: \"Shall I point you to one who will undertake his care?\" So We returned you to your mother, that her eye might be comforted and she might not grieve. And you killed a nafs, and We saved you from grief, and We tested you with a test. And you tarried years among the people of Midian; then you came as destined, O Musa.", "“তোমার বোন তাদের কাছে গেলো এবং বলল, ‘আমি তোমাদেরকে একজন স্তন্যদানকারিনী মায়ের বিষয়ে বলতে পারি যে তার ভাল যত্ন নিতে পারবে।’ এভাবে আমরা তোমাকে তোমার মায়ের কাছে ফিরিয়ে দিলাম, যাতে সে খুশী হতে পারে এবং দুশ্চিন্তা বন্ধ করে। এবং তুমি যখন একটি আত্মাকে হত্যা করেছিলে, আমরা তোমাকে মর্মান্তিক পরিনাম থেকে রক্ষা করেছিলাম; নিশ্চয়ই আমরা তোমাকে সম্পূর্ণরূপে পরীক্ষা করেছি। তুমি মাদিয়ানের লোকদের সাথে বছরের পর বছর থেকেছো, এবং এখন তুমি ফিরে এসেছ একটি সুনির্দিষ্ট পরিকল্পনা অনুসারে।"],
  "20:41": ["And I fashioned you for Myself.", "আমি তোমাকে কেবল আমার জন্য গড়েছি।"],
  "20:42": ["Go, you and your brother, with My ayat, and do not slacken in remembrance of Me.", "তোমার ভাইয়ের সাথে যাও, আমার নিদর্শনাবলির সমর্থণ নিয়ে, এবং আমার স্মরনে শৈথিল্য করো না।"],
  "20:43": ["Go, both of you, to Fir'awn; he has transgressed.", "ফেরাউনের কাছে যাও, কারণ সে সীমালংঘন করেছে।"],
  "20:44": ["And speak to him a gentle word, so that perhaps he may remember or hold reverent awe.", "তার সাথে সুন্দর করে কথা বল; সে হয়তো উপদেশ গ্রহন করবে, অথবা শ্রদ্ধাশীল হয়ে যাবে।”"],
  "20:45": ["They said: \"Our Rabb, we fear that he will rush upon us or transgress.\"", "তারা বলল, “আমাদের প্রভু, আমরা ভয় করি যে সে হয়তো আমাদের আক্রমন করবে, অথবা সীমালংঘন করবে।”"],
  "20:46": ["He said: \"Do not fear; indeed, I am with you both — I hear and I see.\"", "তিনি বললেন, “ভয় পেয়ো না, কারণ আমি তোমাদের সাথে থাকবো, শুনতে এবং দেখতে থাকবো।"],
  "20:47": ["So go, both of you, to him and say: \"We are two rusul of your Rabb; so send with us the Children of Israel, and do not punish them. We have come to you with an aya from your Rabb; and peace be upon whoever follows the guidance.\"", "তার কাছে যাও এবং বল, \"তোমার প্রভুর পক্ষ থেকে আমরা দু'জন বার্তাবাহক। ইসরাইলের সন্তানদের যেতে দাও। তাদেরকে নিপীড়ন করা থেকে তোমাকে অবশ্যই বিরত থাকতে হবে। তোমার প্রভুর পক্ষ থেকে আমরা একটি নিদর্শন এনেছি, এবং শান্তিই তাদের নিয়তি যারা পথ- নির্দেশনায় মনোযোগ দেয়।"],
  "20:48": ["\"It has been revealed to us that the punishment is upon whoever denies and turns away.\"", "“আমাদের প্রত্যাদেশ করা হয়েছে যে শাস্তি অনিবার্যভাবে আঘাত করবে তাদেরকে, যারা অবিশ্বাস করে এবং মুখ ফিরিয়ে নেয়।”"],
  "20:49": ["He said: \"So who is your Rabb, O Musa?\"", "সে বলল, \"কে তোমার প্রভু, হে মুসা। \""],
  "20:50": ["He said: \"Our Rabb is the One who gave everything its creation, then guided it.\"", "সে বলল, “আমাদের প্রভু সেই সত্ত্বা যিনি সবকিছুকে এর অস্তিত্ব, এবং এর পথ-নির্দেশনা দান করেছেন।\""],
  "20:51": ["He said: \"So what of the former generations?\"", "সে বলল, “অতীত প্রজন্মের কি হবে?\""],
  "20:52": ["He said: \"Their knowledge is with my Rabb, in a record; my Rabb does not err and does not forget —", "সে বলল, \"তার জ্ঞান আছে আমার প্রভুর একটি নথিভুক্ত আছে। আমার প্রভু কখনো ভুল করেন না, না তিনি ভুলে যান।\""],
  "20:53": ["the One who made the earth a cradle for you, and threaded for you paths in it, and sent down water from the heaven, and with it We brought out pairs of diverse plants.", "তিনিই তোমাদের জন্য পৃথিবীকে বাসযোগ্য করেছেন, এবং এতে তোমাদের জন্য রাস্তা খোদাই করে দিয়েছেন। এবং তিনি আকাশ থেকে পানি বর্ষণ করেন যা দিয়ে আমরা বহু ধরণের উদ্ভিদ উৎপন্ন করি।"],
  "20:54": ["Eat and graze your herds. Indeed, in that are ayat for people of understanding.", "খাও এবং তোমাদের পালিত পশুদের প্রতিপালন কোর। এগুলো তাদের জন্য যথেষ্ট প্রমান যারা বুদ্ধিমত্তার অধিকারী।"],
  "20:55": ["From it We created you, and into it We return you, and from it We bring you out another time.\"", "এর থেকে আমরা তোমাদের সৃষ্টি করেছি, এর মধ্যে আমরা তোমাদের ফিরিয়ে দেবো, এবং এর থেকেই আরো একবার আমরা তোমাদের বের করে আনবো।"],
  "20:56": ["And We showed him all Our ayat, and he denied and refused.", "আমরা তাকে আমাদের সব প্রমান দেখালাম, কিন্তু সে অবিশ্বাস করলো এবং প্রত্যাক্ষান করলো।"],
  "20:57": ["He said: \"Have you come to us to drive us out of our land with your sihr, O Musa?", "সে বলল, “তুমি কি তোমার জাদু দিয়ে আমাদেরকে আমাদের দেশ থেকে নিয়ে যেতে এসেছো, হে মুসা?"],
  "20:58": ["So we will surely bring you sihr like it. Make between us and you an appointment that neither we nor you will break, at a level place.\"", "“আমরা অবশ্যই তোমাকে অনুরূপ জাদু দেখাবো। অতএব, সাক্ষাতের জন্য একটি সময় নির্ধারণ করো যা না আমরা, না তুমি লঙ্ঘন করবে; একটি নিরপেক্ষ স্থানে।"],
  "20:59": ["He said: \"Your appointment is the day of adornment, and that people be gathered in the forenoon.\"", "সে বলল, \"তোমাদের নির্ধারিত সময়টি হবে উৎসবের দি্নে। চল আমরা সবাই পূর্বাহ্নে একত্রিত হই।”"],
  "20:60": ["So Fir'awn turned away, gathered his scheme, then came.", "ফেরাউন তার বাহিনীকে তলব করলো, এরপর আসলো।"],
  "20:61": ["Musa said to them: \"Woe to you! Do not fabricate a lie against Allah, or Allah will destroy you with a punishment; and whoever fabricates fails.\"", "মূসা তাদের বলল, \"দূর্ভাগ্য তোমাদের। তোমরা কি আল্লাহর সাথে লড়াই করতে মিথ্যা উদ্ভাবন করো এবং এভাবে তাঁর শাস্তি টেনে আনো? এমন মিথ্যা উদ্ভাবকেরা নিশ্চয় ব্যর্থ হবে।”"],
  "20:62": ["So they disputed their affair among themselves, and conferred in secret,", "তারা নিজেদের মধ্যে বিবাদে জড়ালো, যখন তারা একান্তে পরামর্শ করছিলো।"],
  "20:63": ["saying: \"These two are surely two sihrians who want to drive you out of your land with their sihr, and to take away your exemplary way.", "তারা বলল, \"এরা দু'জন যাদুকরের চেয়ে বেশি কিছু না যারা চায় তাদের যাদু দিয়ে তোমাদেরকে তোমাদের দেশ থেকে বের করে নিয়ে যেতে, এবং তোমাদের আদর্শ জীবন-ব্যবস্থা ধ্বংস করতে।"],
  "20:64": ["So gather your scheme, then come forward in ranks; and success today is for whoever gains the upper hand.\"", "চল আমরা একটি পরিকল্পনায় একমত হই এবং সম্মিলিতভাবে তাদের মুখোমুখি হই। আজকের বিজয়ীর কর্তৃত্ব থাকবে।"],
  "20:65": ["They said: \"O Musa, either you cast, or we will be the ones to cast.\"", "তারা বলল, \"হে মুসা, হয় তুমি ছুঁড়ো, না হয় প্রথমে আমরা ছুড়ঁবো।"],
  "20:66": ["He said: \"No, you cast.\" And behold, their ropes and staffs were made to appear to him, by their sihr, as if they were moving swiftly,", "সে বলল, \"তোমরা ছুঁড়ো। “যারপর, তাদের যাদুর কারণে তার কাছে এমন মনে হলো যেন তাদের দড়ি এবং লাঠিগুলো নড়ছিল।"],
  "20:67": ["and Musa felt a fear within himself.", "মুসা কিছুটা ভয় পেয়ে গেলো।"],
  "20:68": ["We said: \"Do not fear; indeed, you are the uppermost.", "আমরা বললাম, “কোন ভয় করো না। তুমি বিজয়ী হবে।"],
  "20:69": ["Cast what is in your right hand; it will swallow what they have made. They have made only the scheme of a sihrian, and the sihrian does not succeed from wherever he comes.\"", "ছুঁড়ো, যা তুমি তোমার ডান হাতে ধরে আছো, এবং এটি গিলে ফেলবে যা তারা বানিয়েছে।  যা তারা বানিয়েছে করেছে তা যাদুকরের কলা-কৌশলের চেয়ে বেশি কিছু নয়। যাদুকরের কাজ সফল হবে না।\""],
  "20:70": ["So the sihrians were cast down prostrate; they said: \"We believe in the Rabb of Harun and Musa.\"", "যাদুকরেরা সেজদায় লুটিয়ে পড়লো, এ বলে যে, \"আমরা হারুন এবং মুসার প্রভুকে বিশ্বাস করি।\""],
  "20:71": ["He said: \"You believed in him before I permitted you? Indeed, he is your chief who taught you sihr. So I will surely cut off your hands and your feet from opposite sides, and crucify you on the trunks of palm trees; and you will surely know which of us is more severe in punishment and more lasting.\"", "সে বলল, “তোমরা কি তাকে আমার অনুমতি ছাড়াই বিশ্বাস করলে? সে নিশ্চয় তোমাদের প্রধান; যে তোমাদের যাদু শিখিয়েছে। আমি অবশ্যই তোমাদের বিপরীত দিকের হাত এবং পা কেটে ফেলবো। আমি তোমাদেরকে খেজুর গাছে ক্রুশবিদ্ধ করবো। তোমরা দেখবে আমাদের মধ্যে কে নিকৃষ্ট শাস্তি আরোপ করতে পারে, এবং কে কার চেয়ে অধিক টিকে থাকে।”"],
  "20:72": ["They said: \"We will never prefer you over what has come to us of clear proofs, nor over the One who originated us. So decree whatever you will decree; you decree only this worldly life.", "তারা বলল, \"আমাদের কাছে যে স্পষ্ট প্রমাণাদি এসেছে তার উপরে, এবং যেই সত্বা আমাদের সৃষ্টি করেছেন তাঁর উপর আমরা তোমাকে পছন্দ করবো না। সুতরাং, তুমি যে বিচার করতে চাও করো। তুমি শুধু এই তুচ্ছ জীবনেই শাসন করতে পারো।"],
  "20:73": ["Indeed, we believe in our Rabb, that Allah may forgive us our errors and what you compelled us to of sihr. And Allah is better and more lasting.\"", "আমরা আমাদের প্রভুতে বিশ্বাস করেছি, যাতে তিনি ক্ষমা করেন আমাদের পাপ, এবং এই যাদু যা দেখাতে তুমি আমাদের বাধ্য করেছো। আল্লাহ আরো অনেক উত্তম এবং চিরস্থায়ী।"],
  "20:74": ["Indeed, whoever comes to his Rabb as a mujrim — for him is Hell: he neither dies in it nor lives.", "যেকেউ তার প্রভুর কাছে অপরাধী হয়ে আসে সে টেনে আনবে নরক, যেখানে সে কখনো মরে না, না জীবিত থাকে।"],
  "20:75": ["And whoever comes to Allah a mumin, having done the salihin deeds — those are the ones for whom are the highest degrees:", "আর যারা তাঁর কাছে বিশ্বাসী হিসেবে আসে, যারা কিনা সৎকর্মশীল জীবন যাপন করেছে, তারা উচ্চ পদ অর্জন করে।"],
  "20:76": ["gardens of Eden, beneath which rivers flow, abiding therein. And that is the recompense for whoever purifies himself.", "ইডেনের বাগানগুলো, যার তলদেশে নদী প্রবাহিত হয়, তাদের চিরকালের আবাস হবে। এমনই তাদের জন্য পুরষ্কার যারা নিজেদের পরিশুদ্ধ করে।"],
  "20:77": ["And We revealed to Musa: \"Set out by night with My servants, and strike for them a dry path in the sea; you will not fear being overtaken, nor be in dread.\"", "আমরা মুসাকে প্রত্যাদেশ করলাম: \"আমার বান্দাদের বের করে নিয়ে যেতে নেতৃত্ব দাও, এবং তাদের জন্য সাগরে আঘাত করে একটি শুকনো রাস্তা বের করো। তোমরা ভয় পাবে না যে তোমরা ধরা পড়ে যাবে, না তোমরা উদ্বিগ্ন হবে।"],
  "20:78": ["So Fir'awn followed them with his hosts, and the sea covered them with what covered them.", "ফেরাউন তার দল নিয়ে তাদের পিছু নিল, কিন্তু সাগর তাদের নিমজ্জিত করলো, যেমন তার নিয়তি ছিল তাদেরকে নিমজ্জিত করা।"],
  "20:79": ["And Fir'awn led his people astray, and did not guide.", "এভাবে, ফেরাউন তার লোকদের পথভ্রষ্ট করেছিলো; সে তাদের পথ-প্রদর্শণ করেনি।"],
  "20:80": ["O Children of Israel, We saved you from your enemy, and We promised you the right side of the Mount, and We sent down upon you the manna and the quails:", "হে ইসরাইলের সন্তানেরা, আমরা তোমাদেরকে তোমাদের শত্রু থেকে উদ্ধার করেছিলাম, তোমাদেরকে সিনাই পর্বতের ডান পাশে তলব করেছিলাম, এবং আমরা তোমাদের কাছে মান্না ও কোয়েল অবতীর্ণ করেছিলাম।"],
  "20:81": ["eat of the good things We provided you, and do not transgress in it, lest My wrath descend upon you; and upon whoever My wrath descends has indeed plunged.\"", "আমরা যে ভাল জিনিস তোমাদেরকে দিয়েছি তা থেকে খাও, এবং সীমালঙ্ঘন করো না, যাতে না তোমরা আমার ক্রোধ টেনে আনো। যেকেউ আমার ক্রোধ টেনে আনে সে পতিত হয়েছে।"],
  "20:82": ["And indeed, I am Forgiving for whoever repents and believes and does a salih deed, then is guided.", "আমি অবশ্যই তাদের জন্য ক্ষমাশীল যারা অনুশোচনা করে, বিশ্বাস করে, সৎকর্মশীল জীবন যাপন করে, এবং দৃড়তার সাথে পথে থাকে।"],
  "20:83": ["\"And what made you hurry from your people, O Musa?\"", "\"কেন তুমি তোমার লোকদের থেকে তারাহুড় করে চলে গেলে, হে মুসা?\""],
  "20:84": ["He said: \"They are those on my track, and I hurried to You, Rabb, that You be pleased.\"", "সে বলল, \"তারা আমার পিছনে নিকটেই আছে। আমি আপনার কাছে ছুটে এসেছি, আমার প্রভু, যাতে আপনি খুশি হোন।\""],
  "20:85": ["He said: \"We have tested your people after you, and the Samiri has led them astray.\"", "তিনি বললেন, \"তুমি চলে আসার পর আমরা তোমার লোকদের পরীক্ষায় ফেলেছি, কিন্তু সামিরীয় ব্যক্তিটি তাদের বিভ্রান্ত করেছে।”"],
  "20:86": ["So Musa returned to his people, angry and grieving. He said: \"My people, did your Rabb not promise you a good promise? Did the time seem too long for you, or did you want wrath from your Rabb to descend upon you, so you failed my appointment?\"", "মুসা তার লোকদের কাছে ফিরে এল, রাগান্বিত ও হতাশ হয়ে, এই বলল যে, \"হে আমার লোকেরা, তোমাদের প্রভু কি তোমাদেরকে  একটি ভাল অংগীকার করেননি?  তোমরা কি অপেক্ষা করতে পারলেনা? তোমরা কি তোমাদের প্রভুর কাছ থেকে ক্রোধ টেনে আনতে চেয়েছিলে? এ কারনেই কি তোমরা আমার সাথে তোমাদের চুক্তি ভঙ্গ করেছ?"],
  "20:87": ["They said: \"We did not fail your appointment by our own will; but we were made to carry loads of the people's adornment, so we cast them — and so did the Samiri cast.\"", "তারা বলল, \"আমরা ইচ্ছা করে তোমার সাথে আমাদের চুক্তি ভঙ্গ করিনি। কিন্তু আমাদের গহনা আমাদের জন্য বোঝা হয়ে গিয়েছিল, এবং আমরা সিদ্ধান্ত নিলাম আমাদের বোঝাগুলো এর মধ্যে নিক্ষেপ করতে। এই পরামর্শই সামিরীয় ব্যক্তি দিয়েছিল।\""],
  "20:88": ["And he brought out for them a calf — a body with a lowing sound — and they said: \"This is your ilah and the ilah of Musa.\" And he forgot.", "সে তাদের জন্য একটি খোদাইকৃত বাছুর বানিয়েছিল, যা বাছুরের মত ডাকতে  সক্ষম ছিল। তারা বলল, “এটি তোমাদের উপাস্য, এবং মুসার উপাস্য।”এভাবে, সে ভুলে গিয়েছিল।"],
  "20:89": ["Do they not see that it does not return to them a word, and possesses for them neither harm nor benefit?", "তারা কি দেখতে পায়নি যে এটি না তাদের প্রতি সাড়া দিচ্ছিল, না এর কোন ক্ষমতা ছিল তাদের ক্ষতি করার, বা তাদের উপকার করার?"],
  "20:90": ["And Harun had said to them before: \"My people, you have only been tested by it; and your Rabb is the Rahman, so follow me and obey my command.\"", "এবং হারুন তাদেরকে বলেছিল, \"হে আমার লোকেরা, এটি তোমাদের জন্য একটি পরীক্ষা। পরম দয়ালুই  তোমাদের একমাত্র প্রভু, তাই আমাকে অনুসরণ করো, এবং আমার আদেশ মান্য করো।”"],
  "20:91": ["They said: \"We will not leave it, cleaving to it, until Musa returns to us.\"", "তারা বলল, “আমরা এর উপাসনা চালিয়া যাব, যতক্ষণ না মূসা ফিরে আসে”।"],
  "20:92": ["He said: \"O Harun, what withheld you, when you saw them going astray,", "(মুসা) বলল, “হে হারুন, যখন তুমি তাদেরকে বিপথে যেতে দেখলে, কিসে তোমাকে বাধা দিয়েছিল,"],
  "20:93": ["that you did not follow me? Did you disobey my command?\"", "আমার নির্দেশ অনুসরণ করা থেকে? তুমি কি আমার বিরুদ্ধে বিদ্রোহ করেছ?\""],
  "20:94": ["He said: \"O son of my mother, do not take me by my beard or my head. I feared you would say: You divided the Children of Israel and did not wait for my word.\"", "সে বলল, \"হে আমার মায়ের সন্তান, আমাকে আমার দাড়ি আর মাথা ধরে টেনো না। আমি ভয়ে ছিলাম যে তুমি হয়তো বলবে, 'তুমি ইসরাইলের সন্তানদের বিভক্ত করেছ, এবং আমার আদেশ অমান্য করেছো। ' \""],
  "20:95": ["He said: \"So what is your affair, O Samiri?\"", "সে বলল, “তোমার সমস্যা কি, হে সামারীয়?”"],
  "20:96": ["He said: \"I saw what they did not see, so I took a handful from the track of the Rasul and threw it, and so my nafs made it seem fair to me.\"", "সে বলল, “আমি দেখেছিলাম যা তারা দেখতে পাইনি। আমি সেখান থেকে এক মুঠো (ধুলো)  তুলে নিলাম যেখানে বার্তাবাহক দাড়িয়েছিল, এবং তা (স্বর্ণের বাছুরের সাথে মেশাতে) ব্যবহার করলাম। এটা  করতেই আমার মন আমাকে উদ্বুদ্ধ করেছিল।"],
  "20:97": ["He said: \"Go! For you in this life is only to say: No touch. And you have an appointment you will not miss. And look at your ilah that you remained cleaving to: we will burn it, then scatter it into the sea.\"", "সে বলল, “তাহলে যাও, এবং, তোমার সারাজীবনে কাছেও এসো না। (তোমার চূড়ান্ত বিচারের জন্য) তোমার একটি নির্ধারিত সময় আছে যা তুমি কখনো এড়াতে পারবে না। তোমার উপাস্যের দিকে তাকাও যেটাকে তুমি উপাসনা করতে; আমরা এটাকে পুড়িয়ে ফেলব এবং একে সাগরে নিক্ষেপ করবো, যেন তা চিরকাল সেখানে তলিয়ে থাকে।"],
  "20:98": ["Your ilah is only Allah — there is no ilah except Allah — encompassing everything in knowledge.", "তোমাদের একমাত্র উপাস্য আল্লাহ; সেই সত্ত্বা যারঁ পাশে অন্য কোন উপাস্য নেই। তাঁর জ্ঞান সবকিছুকে ঘিরে আছে।"],
  "20:99": ["Thus We narrate to you accounts of what has passed before; and We have given you from Our presence a remembrance.", "আমরা এভাবে তোমার কাছে অতীত প্রজন্মের কিছু সংবাদ বর্ননা করি। আমরা তোমার কাছে আমাদের পক্ষ থেকে একটি বার্তা প্রকাশ করেছি।"],
  "20:100": ["Whoever turns away from it — he will carry, on the Day of Resurrection, a load,", "যারা তা উপেক্ষা করে তারা পুনরুত্থান দিনে (পাপের) বোঝা বহন করবে।"],
  "20:101": ["abiding therein. And evil for them, on the Day of Resurrection, is the load —", "তারা সেখানে চিরকাল বাস করে; পুনরুত্থান দিনে কি এক শোচনীয় বোঝা!"],
  "20:102": ["the day the blast is blown, and We gather the mujrimin that day, blinded,", "ওটা সে দিন যখন শিঙায় ফু দেয়া হয়, এবং আমরা ঐ দিন অপরাধীদের তলব করি নীল বর্ণে।"],
  "20:103": ["whispering among themselves: \"You tarried only 10.\"", "নিজেদের মধ্যে ফিসফিস করে, তারা বলবে, “তোমরা (প্রথম জীবনে) দশ দিনের বেশি অবস্থান করোনি!”"],
  "20:104": ["We know best what they say, when the most moderate of them in manner says: \"You tarried only a day.\"", "তারা যা বলে তা সম্পর্কে  আমরা সম্পূর্ণ অবগত। তাদের মধ্যে যে সবচেয়ে নির্ভূল সে বলবে, “তোমরা এক দিনের বেশি অবস্থান করোনি।”"],
  "20:105": ["And they ask you about the mountains; so say: \"My Rabb will scatter them away", "তারা তোমাকে পাহাড় সম্পর্কে জিজ্ঞেস করে। বল, “আমার প্রভু এগুলো মুছে ফেলবেন।"],
  "20:106": ["and leave it a smooth, level plain,", "তিনি এগুলোকে অনুর্বর, সমতল ভূমির মতো করে দিবেন।"],
  "20:107": ["where you will see neither crookedness nor any rise.\"", "এমনকি তুমি সেখানে সামান্যতম টিলাও দেখবে না, না কোন খাঁদ।”"],
  "20:108": ["That day they follow the caller — there is no crookedness in him — and the voices are humbled before the Rahman, and you hear nothing but a whisper.", "ঐ দিনে, প্রত্যেকেই আহ্বানকারীকে অনুসরণ করবে, সামান্যতম বিচ্যুতি ছাড়া। পরম করুনাময়ের সামনে সব শব্দ স্থব্ধ হয়ে যাবে; তুমি ফিসফিস ছাড়া কিছু শুনতে পাবে না।"],
  "20:109": ["That day intercession is of no benefit, except for one the Rahman has permitted and approved a word for.", "ঐ দিনে, সুপারিশ কোন কাজে আসবে না, তাদের ব্যতিত যারা পরুম করুনাময়ের দ্বারা অনুমোদিত, এবং যাদের কথা তাঁর ইচ্ছা মোতাবেক হয়।"],
  "20:110": ["Allah knows what is before them and what is behind them, and they do not yuhituna Allah in knowledge.", "তিনি তাদের অতীত এবং ভবিষ্যৎ জানেন, যখন কেউ তাঁর জ্ঞান পরিবেষ্টন করে না।"],
  "20:111": ["And faces are humbled before the Ever-Living, the Self-Sustaining; and whoever carried wrong has failed.", "সকল মুখমণ্ডল সমর্পণ করবে সেই জীবিত, চিরস্থায়ীর কাছে, এবং যারা তাদের সীমালংঘনের দ্বারা ভারাক্রান্ত,  তারা ব্যর্থ হবে।"],
  "20:112": ["And whoever does the salihin deeds while a mumin — he will fear neither wrong nor loss.", "আর যারা সৎ কাজ করেছে, বিশ্বাসী অবস্থায়, তাদের কোন  অবিচার বা দুর্দশার ভয় থাকবে না।"],
  "20:113": ["And thus We sent it down, a clear Arabic recitation, and varied the warnings in it, so that perhaps they may be wary, or that it may bring them a reminder.", "আমরা এভাবে এটি প্রকাশ করেছি, একটি আরবী কুরআন, এবং আমরা এতে সব রকমের ভবিষ্যদ্বানী উদ্ধৃত করেছি, যাতে তারা রক্ষা পেতে পারে, অথবা এটি  হয়তো  তাদের উপদেশ গ্রহনের কারণ হবে।"],
  "20:114": ["So exalted is Allah, the True Sovereign. And do not hurry with the recitation before its revelation is completed to you; and say: \"Rabb, increase me in knowledge.\"", "সবচেয়ে উচ্চে  আল্লাহ,  একমাত্র প্রকৃত রাজা। কুরআনের ব্যাপারে তাড়াহুড়া করো না তোমার কাছে এটা প্রকাশ হওয়ার আগে, এবং বলো, “আমার প্রভু, আমার জ্ঞান বৃদ্ধি করুন।”"],
  "20:115": ["And We pledged to Adam before, and he forgot; and We found no resolve in him.", "অতীতে আমরা আদমকে পরীক্ষা করেছি, কিন্তু সে ভুলে গিয়েছিলো, এবং আমরা তাকে সিদ্ধান্তহীন/ দ্বিধান্বিত পেয়েছিলাম।"],
  "20:116": ["And when We said to the malakat: \"Prostrate to Adam,\" and they prostrated — except Iblis; he refused.", "স্মরণ কর যে আমরা ফেরেশতাদের বলেছিলাম, “আদমের সামনে সেজদাবনত হও।”তারা সেজদাবনত হলো, শয়তান ছাড়া; সে প্রত্যাক্ষান করলো।"],
  "20:117": ["Then We said: \"O Adam, this is an enemy to you and to your mate; so let him not drive you both out of the garden, so you become wretched.", "আমরা তারপর বললাম, “হে আদম, এ তোমার এবং তোমার স্ত্রীর একজন শত্রু। তাকে  তোমাদেরকে স্বর্গ থেকে তাড়াতে দিও না, পাছে তোমরা দুর্দশাগ্রস্থ হয়ে পড়ো।"],
  "20:118": ["Indeed, for you: you will not go hungry in it, nor be naked,", "তোমাদের নিশ্চয়তা দেয়া হল যে সেখানে কখনো ক্ষুধার্থ হবে না, না আশ্রয়হীন হবে।"],
  "20:119": ["and you will not thirst in it, nor be scorched by the forenoon sun.\"", "না তোমরা সেখানে পিপাসার্ত হবে, না কোনরকম গরমে কষ্ট পাবে।'"],
  "20:120": ["Then Shaytan whispered to him; he said: \"O Adam, shall I point you to the tree of eternity, and a kingdom that does not wear out?\"", "কিন্তু শয়তান তার কাছে ফিসফিসিয়ে বলল, \"হে আদম, চল আমি তোমাকে অমরত্ব এবং অন্তহীন রাজত্বের গাছটি দেখাই।\""],
  "20:121": ["So they both ate of it, and their shame became manifest to them, and they began stitching upon themselves leaves of the garden. And Adam disobeyed his Rabb, and went astray.", "তারা তা থেকে খেলো, যারপর তাদের দেহ তাদের কাছে দৃশ্যমান হয়ে পড়লো, এবং তারা স্বর্গের পাতা দিয়ে নিজেদের ঢাকার চেষ্টা করলো। আদম এভাবে তার প্রভুকে অমান্য করলো, এবং পতিত হলো।"],
  "20:122": ["Then his Rabb chose him, turned to him in forgiveness, and guided him.", "পরবর্তীতে, তার প্রভু তাকে মনোনীত  করলেন, তাকে উদ্ধার করলেন, এবং তাকে পথ দেখালেন।"],
  "20:123": ["He said: \"Descend from it, both of you, together. Some of you are an enemy to others. And if guidance comes to you from Me, then whoever follows My guidance will not go astray nor be wretched,", "তিনি বললেন, \"এখান থেকে নেমে যাও, তোমরা সবাই। তোমরা একে অপরের শত্রু। আমার কাছ থেকে তোমাদের নিকট যখন পথ-নির্দেশনা আসে, যেকেউ আমার পথ-নির্দেশনা অনুসরণ করবে সে বিপথে যাবে না, না কোন দুর্দশা ভোগ করবে।"],
  "20:124": ["and whoever turns away from My remembrance — for him is a straitened living, and We will gather him, on the Day of Resurrection, blind.\"", "আর যে-ই আমার বার্তা উপেক্ষা করবে, তার থাকবে দুর্দশাময় জীবন, এবং আমরা তাকে পুনরুত্থিত করবো, পুনরুত্থান দিনে, অন্ধ অবস্থায়।\""],
  "20:125": ["He will say: \"Rabb, why have You gathered me blind, when I used to see?\"", "সে বলবে, \"আমার প্রভু, কেন আপনি আমাকে অন্ধ করে তলব করলেন, যখন আমি চক্ষুষ্মান ছিলাম?\""],
  "20:126": ["He will say: \"Thus Our ayat came to you, and you forgot them; and thus today you are forgotten.\"", "তিনি বলবেন, \"কারণ তুমি আমাদের প্রকাশনাবলি ভুলে গিয়েছিলে যখন সেগুলো তোমার কাছে এসেছিল, এখন তোমাকে ভুলে যাওয়া হয়েছে।\""],
  "20:127": ["And thus We recompense whoever is excessive and does not believe in the ayat of his Rabb; and the punishment of the Hereafter is harder and more lasting.", "এভাবে আমরা তাদেরকে  প্রতিফল দেই, যারা সীমালঙ্ঘন করে এবং তোমার প্রভুর প্রকাশনাবলি বিশ্বাস করতে প্রত্যাখ্যান করে। পরকালের শাস্তি আরও অধিক মন্দ এবং চিরস্থায়ী।"],
  "20:128": ["Has it not guided them — how many generations We destroyed before them, who walk in their dwellings? Indeed, in that are ayat for people of understanding.", "তারা কি কখনো এটা উপলব্ধি করে যে, আমরা পূর্ববর্তী কতগুলো প্রজন্ম ধ্বংস করে দিয়েছি? তারা এখন  তাদের বাড়ি-ঘরে বিচরন করছে, যারা তাদের পূর্বে ছিল। এগুলো তাদের জন্য নিদর্শন, যারা বুদ্ধিমত্তার অধিকারী।"],
  "20:129": ["And had not a word preceded from your Rabb, it would have been binding, and an appointed term.", "যদি এটা তোমার প্রভুর পূর্বনির্ধারিত পরিকল্পনার কারণে না হতো, তবে তৎক্ষণাৎ তাদের বিচার করা হতো।"],
  "20:130": ["So be of the sabirin over what they say, and glorify with the praise of your Rabb before the rising of the sun and before its setting, and in hours of the night — glorify — and at the edges of the day, so that perhaps you may be pleased.", "অতএব, তাদের কথার মুখে ধৈর্য ধরো, এবং তোমার প্রভুর প্রশংসা এবং  মহিমা ঘোষণা করো সূর্যোদয়ের আগে এবং সূর্যাস্তের আগে। এবং রাতে তাঁর মহিমা ঘোষণা করো, সেই সাথে দিনের দুই প্রান্তে, যাতে তুমি সুখী হতে পারো।"],
  "20:131": ["And do not stretch your eyes toward that with which We have given pairs among them enjoyment — the bloom of worldly life — that We may test them by it. And the provision of your Rabb is better and more lasting.", "এবং তাতে লোভ করো না যা আমরা অন্য লোকেদের দান করেছি। এমনই এই জীবনের অস্থায়ী অলংকার, যা দিয়ে আমরা তাদের পরীক্ষায় ফেলি। যা তোমার প্রভু তোমার জন্য প্রদান করেন, তা অনেক উত্তম, এবং চিরস্থায়ী।"],
  "20:132": ["And command your family to the prayer and be steadfast upon it. We do not ask you for provision; We provide you. And the outcome is for the wary.", "তুমি তোমার পরিবারকে সংযোগ প্রার্থনা (সালাত) পালন করতে নির্দেশ দেবে, এবং তা করতে দৃঢ়ভাবে অবিচল থাকবে। আমরা তোমার কাছে কোন জীবিকা চাই না; আমরাই তোমার জন্য প্রদান করি। চুড়ান্ত বিজয় সৎকর্মশীলদের।"],
  "20:133": ["And they say: \"Why does he not bring us an aya from his Rabb?\" Has there not come to them the clear proof of what is in the former writings?", "তারা বলল, \"সে যদি কেবল তার প্রভুর পক্ষ থেকে আমারদেরকে কোন অলৌকিক কিছু দেখাতে পারতো!”আগের বার্তাগুলোর সাথে তারা কি যথেষ্ট অলৌকিকতা পায়নি?"],
  "20:134": ["And if We had destroyed them with a punishment before it, they would have said: \"Our Rabb, why did You not send us a Rasul, so that we might follow Your ayat before we were abased and disgraced?\"", "আমরা যদি এর আগেই তাদের ধ্বংস করে দিতাম, তারা বলত, \"আমাদের প্রভু, আপনি যদি আমাদের কাছে কোন বার্তাবাহক পাঠাতেন, আমরা তাহলে আপনার প্রকাশনাবলি অনুসরণ করতাম, এবং এই লজ্জা ও অপদস্থতা এড়াতে পারতাম।"],
  "20:135": ["Say: \"Everyone is waiting, so wait; and you will come to know who are the companions of the even path and who is guided.\"", "বল, \"আমরা সবাই অপেক্ষা করছি, সুতরাং অপেক্ষা করো; তোমরা নিশ্চয় দেখবে, কারা সঠিক পথে আছে, এবং কারা সত্যই পথপ্রাপ্ত।"],
  "21:1": ["The people's reckoning has drawn near, yet they are unaware, turning away.", "দ্রুত ঘনিয়ে আসছে লোকদের জন্য হিসাব গ্রহনের সময়, কিন্তু তারা বেখবর, বিমুখ।."],
  "21:2": ["Whenever a newly-arriving reminder comes to them from their Rabb, they listen to it while they play.", "যখন তাদের প্রভুর পক্ষ থেকে তাদের কাছে কোন প্রমান আসে, যা নতুন, তারা তা শুনে অমনোযোগী হয়ে।"],
  "21:3": ["Their hearts are in diversion, and those who did wrong keep the secret counsel secret: \"Is this anything but a human like you? Do you then come to the sihr while you can see?\"", "তাদের মন অমনোযোগী। এবং সীমালংঘনকারীরা গোপনে পরামর্শ করেঃ “সে কি তোমাদের মতই একজন মানুষ নয়? যে যাদু তোমাদের কাছে উপস্থাপন করা হয়েছে তোমরা কি তা গ্রহন করবে?"],
  "21:4": ["Allah says: speech in the heaven and the earth is known to Allah; and Allah is the All-Hearing, the All-Knowing.", "সে বলল, “আমার প্রভু আকাশ এবং পৃথিবীতে প্রতিটি চিন্তা সম্পর্কে অবগত। তিনি শ্রোতা, সর্বজ্ঞ।”"],
  "21:5": ["No; they say: \"A jumble of dreams! No, he fabricated it! No, he is a poet! Let him bring us an aya, as the former ones were sent.\"", "তারা এমনকি বলল, “দৃষ্টিভ্রম, ” “সে এটা  বানিয়েছে,”এবং, “সে একজন কবি। সে আগের বার্তাবাহকদের মতো আমাদের কাছে কোন অলৌকিকতা  প্রদর্শন করুক।”"],
  "21:6": ["No town that We destroyed believed before them — will they then believe?", "অতীতে  আমরা কখনো  কোন বিশ্বাসী সম্প্রদায়কে ধ্বংস করিনি। এই লোকেরা কি বিশ্বাসী?"],
  "21:7": ["We sent no one before you but men to whom We gave revelation — so ask the people of the reminder, if you do not know.", "আমরা তোমার আগে মানুষ ছাড়া কারো কাছে প্রত্যাদেশ দিয়ে পাঠাইনি। তাদের জিজ্ঞেস করো যারা ঐশীগ্রন্থ জানে, যদি তোমরা না জানো।"],
  "21:8": ["We did not make them bodies that eat no food, nor were they immortal.", "আমরা তাদের এমন দেহ দেইনি যা খাওয়া-দাওয়া করতো না, না তারা অমর ছিল।"],
  "21:9": ["Then We made the promise true for them, and We saved them and whom We willed, and We destroyed the exceeders.", "তাদের প্রতি আমরা আমাদের অঙ্গীকার পূর্ণ করেছিলাম;  আমরা তাদের  রক্ষা করেছি,  যাদেরকে আমরা চেয়েছি তাদের সাথে, এবং সীমালঙ্ঘনকারীদের ধ্বংস করে দিয়েছিলাম।"],
  "21:10": ["We have indeed brought down to you a Kitab containing your reminder — will you not reason?", "আমরা তোমাদের কাছে তোমাদের বার্তা সংবলিত একটি ঐশীগ্রন্থ অবতীর্ণ করেছি। তোমারা কি বোঝো না?"],
  "21:11": ["How many a town that did wrong We have crushed, and We raised up after it other people!", "আমরা অনেক সম্প্রদায়কে তাদের সীমালঙ্ঘনের কারণে শেষ করে দিয়েছিলাম, এবং আমরা তাদের জায়গায় অন্য লোকদের প্রতিস্থাপন করেছিলাম।"],
  "21:12": ["So when they perceived Our might, there they were, fleeing from it!", "যখন আমাদের প্রতিফল আসলো, তারা দৌড়ানো শুরু করলো।"],
  "21:13": ["Do not run! Return to the ease-softened life you lived in and to your dwellings — perhaps you will be asked.", "দৌড়িও না, এবং তোমাদের বিলাসিতা ও অট্রালিকায় ফিরে আসো, কারন অবশ্যই তোমাদের হিসাব নেয়া হবে।"],
  "21:14": ["They said: \"Woe to us! We were zalimun.\"", "তারা বলল, “দুর্ভাগ্য আমাদের, আমরা আসলেই অন্যায়কারী ছিলাম”।"],
  "21:15": ["That cry of theirs did not cease until We made them like a mown field, stilled.", "তাদের এই ঘোষনাই অব্যাহত ছিল, যতক্ষণ না আমরা তাদেরকে পুরোপুরি ধ্বংস করে দিয়েছিলাম।"],
  "21:16": ["We did not create the heaven and the earth and what is between them in play.", "আমরা আকাশমন্ডলী ও পৃথিবী, এবং তাদের মধ্যকার সবকিছু শুধুমাত্র আমোদ-প্রমোদের জন্য তৈরি করিনি।"],
  "21:17": ["Had We willed to take a diversion, We would have taken it from Our presence — if We were to do so.", "যদি আমাদের আমোদ-প্রমোদের দরকার হতো, আমরা এগুলোর কোনকিছু ছাড়াই তা শুরু করতে পারতাম, যদি তা-ই আমরা করতে চাইতাম।"],
  "21:18": ["Rather, We cast the truth upon the falsehood, and it crushes it — and there it is, vanishing! And woe to you for what you describe!", "বরং,  সত্যকে  সমর্থন করাই আমাদের পরিকল্পনা মিথ্যার উপর, একে পরাজিত করার উদ্দেশ্যে।  দুর্ভোগ তোমাদের প্রতি  তোমাদের বলা কথার জন্য।"],
  "21:19": ["Allah has whatever is in the heavens and the earth; and those near Allah are not too proud to worship Allah, nor do they lose heart.", "আকাশমণ্ডলী ও পৃথিবীর সকলেই তাঁর, এবং তাঁর কাছে যারা রয়েছে তারা কখনো এতোটা উদ্ধত নয় যে তাঁকে উপাসনায করবে না,  না তারা কখনো দ্বিধান্বিত করে/ গড়ি-মসি করে।"],
  "21:20": ["They glorify night and day, and they never flag.", "তারা রাত-দিন মহিমা প্রকাশ করে, কখনো ক্লান্ত না হয়ে।"],
  "21:21": ["Or have they taken alihah from the earth that can raise the dead?", "তারা কি পৃথিবীতে কোন উপাস্য পেয়েছে যারা সৃষ্টি করতে পারে?"],
  "21:22": ["Had there been in the two alihah other than Allah, both would have corrupted — so glory be to Allah, Rabb of the arsh, above what they describe!", "যদি এগুলোর (আকাশমন্ডলী ও পৃথিবীর) মধ্যে আল্লাহর পাশে অন্য উপাস্য থাকতো, সেখানে বিশৃঙ্খলা হতো। মহিমা আল্লাহর; পরম কর্তৃত্বময় প্রভু। তিনি তাদের দাবীর অনেক উর্ধ্বে।"],
  "21:23": ["Allah is not questioned about what Allah does — but they are questioned.", "তিনি যা করেন তার কোনকিছু সম্পর্কে তিনি কখনই জিজ্ঞাসিত হবার নন, যেখানে অন্য সকলে প্রশ্ন করা হবে।"],
  "21:24": ["Or have they taken alihah besides Allah? Say: \"Bring your clear proof! This is the reminder of those with me and the reminder of those before me.\" But most of them do not know the truth, so they are turning away.", "তারা কি তাঁর পাশে অন্য উপাস্যদের পেয়েছে? বল, \"আমাকে তোমাদের প্রমান দেখাও।\" এটি আমার প্রজন্মের প্রতি, পূর্ববর্তী সকল বার্তার সুসম্পন্নকারী একটি বার্তা। নিশ্চয়,  তাদের অধিকাংশই সত্য চিনে না, একারনেই তারা এতো শত্রুভাবাপন্ন।"],
  "21:25": ["We never sent a Rasul before you without revealing to him: \"There is no ilah but Me, so worship Me.\"", "আমরা তোমার আগে কোন বার্তাবাহক পাঠাইনি এই প্রত্যাদেশ ছাড়া যে: “আমি ছাড়া অন্যকোন উপাস্য নেই; তোমরা শুধু আমারই উপাসনা করবে।\""],
  "21:26": ["And they say: \"The Rahman has taken a child.\" Glory be to Allah! Rather, they are honored servants.", "এরপরও, তারা বলল, \"পরম করুনাময় পুত্র সন্তান জন্ম দিয়েছেন!” মহিমা তাঁরই। সকল (বার্তাবাহক তাঁর) সম্মানিত বান্দা।"],
  "21:27": ["They do not precede Allah in speech, and they act by Allah's command.", "তারা কখনো নিজ থেকে  কিছু বলে না, এবং তারা যথাযথভাবে তাঁর আদেশ অনুসরণ করে।"],
  "21:28": ["Allah knows what is before them and what is behind them, and they do not intercede except for one Allah approves; and they are ever in awe of Allah.", "তিনি তাদের অতীত এবং তাদের ভবিষ্যৎ জানেন। তারা সুপারিশ করে না, তাদের ব্যতীত যারা তাঁর দ্বারা ইতিপূর্বেই স্বীকৃত হয়েছে, এবং তারা তাদের নিজেদের ব্যাপারেই চিন্তিত।"],
  "21:29": ["And if any of them says: \"I am a ilah besides Allah,\" that one We repay with Hell — thus We repay the wrongdoers.", "যদি তাদের কেউ তাঁর পাশে কোন উপাস্য হবার দাবি করে, আমরা নরক দিয়ে তার প্রতিফল দেই; আমরা এভাবে পাপীদের প্রতিফল দেই।"],
  "21:30": ["Have those who disbelieve not seen that the heavens and the earth were a joined mass, and We split them apart? And We made from water every living thing — will they not then believe?", "অবিশ্বাসীরা কি অঅনুধাবন করে না যে আকাশমন্ডলী ও পৃথিবী একটি নিরেট ভর হয়ে ছিল যার বিস্ফোরণ ঘটিয়ে আমরা অস্তিত্বে এনেছি এবং পানি থেকে আমরা সকল জীবন্ত জিনিস তৈরি করেছি। তারা কি বিশ্বাস করবে?"],
  "21:31": ["And We placed in the earth firm anchors so that it does not sway with them, and We placed in it wide passes as ways, that they may be guided.", "এবং আমরা পৃথিবীতে ভারসাম্যকারী স্থাপন করেছি, পাছে তা তোমাদের নিয়ে উলটে পড়ে, এবং আমরা সেখানে সোজা রাস্তা স্থাপন করেছি, যাতে তারা পথ-নির্দেশনা পায়।"],
  "21:32": ["And We made the heaven a protected roof — yet they turn away from its ayat.", "এবং আমরা আকাশকে একটি  সুরক্ষিত ছাদ করেছি। এরপরও, তারা সেখানের সব নিদর্শনের প্রতি পুরোপুরি বেখেয়াল।"],
  "21:33": ["And it is Allah who created the night and the day and the sun and the moon, each in an orbit, swimming on.", "এবং তিনিই সেই সত্ত্বা যিনি সৃষ্টি করেছেন রাত ও দিন, এবং সূর্য ও চাঁদ; প্রত্যেকেই নিজ নিজ কক্ষপথে ভাসছে।"],
  "21:34": ["We assigned no human before you immortality — if you die, will they be the immortals?", "তোমার আগে আমরা কখনো  কারো জন্য অমরত্বের নিয়ম করিনি; তোমার মৃত্যু হলে, তারা কি অমর?"],
  "21:35": ["Every nafs tastes death, and We test you with evil and with good as a trial — and to Us you return.", "প্রতিকূলতা এবং সমৃদ্ধির মাধ্যমে আমরা তোমাদের পরীক্ষায় ফেলবার পর, প্রত্যেক আত্মা মৃত্যু আস্বাদন করবে, পরিশেষে আমাদের কাছে তোমরা ফিরে আসো।"],
  "21:36": ["And when those who disbelieve see you, they take you only as a mockery: \"Is this the one who mentions your ilahs?\" — while it is the mention of the Rahman that they disbelieve in.", "যারা অবিশ্বাস করে তারা যখন তোমাকে দেখে, তারা তোমাকে নিয়ে উপহাস করে: \"এই কি  সে, যে তোমাদের উপাস্যদের চ্যালেঞ্জ করে? \"এদিকে, তারা পরম দয়ালুর বার্তায় পুরোপুরি অমনোযোগী থাকে।"],
  "21:37": ["The human was created of haste — I will show you My ayat, so do not press for haste.", "মানুষ স্বভাবগতভাবে অধৈর্য। আমি অনিবার্যভাবে তোমাদেরকে আমার নিদর্শন দেখাব; এমন তাড়াহুড়ায় থেকো না।"],
  "21:38": ["And they say: \"When is this promise, if you are sadiq?\"", "তারা চ্যালেঞ্জ করে: \"কোথায় সেই (শাস্তি), যদি তোমরা সত্যবাদী হও?”"],
  "21:39": ["If only those who disbelieve knew — at the moment when they cannot hold back the fire from their faces nor from their backs, nor will they be helped!", "যারা অবিশ্বাস করে তারা যদি শুধু তাদের নিজেদেরকে দেখতে পেত যখন তারা আগুন সরাতে চেষ্টা করে, তাদের মুখ এবং তাদের পিঠ থেকে ! কেউই তখন তাদের সাহায্য করবে না।"],
  "21:40": ["Rather, it comes to them suddenly and stuns them — they cannot turn it back, nor can they look.", "নিশ্চয়, এটি তাদের কাছে হঠাৎ আসবে, এবং তারা একেবারে হতভম্ব হয়ে পড়বে। না  তারা সেটা এড়াতে পারবে, না তারা কোন অবকাশ পাবে।"],
  "21:41": ["Rusul before you were indeed mocked, but what they mocked befell those who mocked.", "তোমার পূর্বেও বার্তাবাহকদের উপহাস করা হয়েছে, এবং, পরিনামে, যারা তাদের নিয়ে উপহাস করেছে তারা তাদের  উপহাসের জন্য শাস্তি টেনে এনেছে।"],
  "21:42": ["Say: \"Who guards you by night and day against the Rahman?\" Rather, they turn away from the reminder of their Rabb.", "বল, \"কে তোমাদের পরম দয়ালুর কাছ থেকে রক্ষা করতে পারবে রাতে অথবা দিনে? নিশ্চয়,  তারা তাদের প্রভুর বার্তার প্রতি পুরোপুরি বেখবর।"],
  "21:43": ["Or do they have alihah that withhold them from Us? They cannot help themselves, nor will they be supported by Us.", "তাদের কাছে কি উপাস্যরা আছে যারা আমাদের  কাছ থেকে তাদের বাচাঁতে পারে? তারা এমনকি তাদের নিজেদেরকেও সাহায্য করতে পারে না। না তারা একে অন্যের সঙ্গ পাবে যখন তাদেরকে আমাদের মুখোমুখি হবার জন্য একত্রিত করা হবে।"],
  "21:44": ["Rather, We let these and their fathers enjoy life until their life-term grew long. Do they not see that We come to the land, diminishing it at its edges? Are they the ones who overcome?", "এইসব লোকদের এবং তাদের পূর্বপুরুষদের জন্য আমরা জীবিকা প্রদান করেছি, বুড়ো বয়স পর্যন্ত। তারা কি দেখে না যে পৃথিবীর প্রত্যেকটি দিন তাদেরকে সমাপ্তির কাছে নিয়ে যায়? তারা কি এই প্রক্রিয়া উল্টাতে পারে?"],
  "21:45": ["Say: \"I only warn you by the revelation.\" But the deaf do not hear the call when they are warned.", "বল, \"আমি তোমাদেরকে সতর্ক করছি ঐশ্বরিক প্রত্যাদেশ অনুসারে।” কিন্তু, বধির ব্যক্তি ডাক শুনতে পারে না, যখন তাদের সতর্ক করা হয়।"],
  "21:46": ["And if a breath of your Rabb's punishment touches them, they will surely say: \"Woe to us! We were wrongdoers.\"", "যখন তোমার প্রভুর শাস্তির একটি নমুনা তাদের আঘাত করে, তারা অবলীলায় বলে, “আমরা আসলেই মন্দ ছিলাম”।"],
  "21:47": ["We set the fair scales for the Day of Rising — no nafs is wronged in anything; and if it be the weight of a grain of mustard, We bring it. And sufficient is Allah as the One who takes account.", "আমরা পুনরুত্থান দিনে বিচারের দাঁড়িপাল্লা স্থাপন করবো। কোন আত্মাই সামান্যতম অবিচার ভোগ করবে না। এমনকি একটি সরিষা বীজের সমতুল্য পরিমানেরও হিসাব নেয়া হবে। আমরা সবচেয়ে দক্ষ হিসাব গ্রহণকারী।"],
  "21:48": ["We gave Musa and Harun the Criterion, and a light and a reminder for those who guard themselves.", "আমরা মূসা এবং হারুনকে দিয়েছিলাম বিধান গ্রন্থ, একটি আলোকবর্তিকা, এবং একটি স্মারক সৎকর্মপরায়নদের জন্য।"],
  "21:49": ["Those who stand in awe of their Rabb in the ghayb, and they are in awe of the Hour.", "যারা তাদের প্রভুকে ভক্তি  করে, এমনকি তাদের একাকীত্বে, এবং তারা সেই ঘন্টার ব্যাপারে উদ্বিগ্ন।"],
  "21:50": ["And this is a blessed reminder that We brought down — so are you the ones who reject it?", "এটিও একটি বরকতময় স্মারক যা আমরা অবতীর্ণ করেছি। তোমরা কি একে প্রত্যাখ্যান করছো?"],
  "21:51": ["We gave Ibrahim his right course of old, and We knew him well.", "তার আগে, আমরা ইব্রাহিমকে তার পথ-নির্দেশনা এবং বুঝার ক্ষমতা প্রদান করেছিলাম, কারণ আমরা তার বিষয়ে পুরোপুরি অবগত ছিলাম।"],
  "21:52": ["When he said to his father and his people: \"What are these statues that you are so devoted to?\"", "সে তার পিতাকে এবং তার লোকদের বলল, \"কি এই মূর্তিগুলো যেগুলোর প্রতি তোমরা নিজেদের উৎসর্গ করছো?\""],
  "21:53": ["They said: \"We found our fathers worshipping them.\"", "তারা বলল, \"আমরা আমাদের পিতা-মাতাদের দেখেছি এদের উপাসনা করতে।\""],
  "21:54": ["He said: \"You and your fathers were indeed in clear error.\"", "সে বলল, \"নিশ্চয়, তোমরা এবং তোমাদের পিতা-মাতারা পুরোপুরি পথভ্রষ্ট হয়েছো।\""],
  "21:55": ["They said: \"Have you brought us the truth, or are you one of those who play?\"", "তারা বলল, \"তুমি কি আমাদের সত্য বলছো, নাকি তামাশা করছো?\""],
  "21:56": ["He said: \"Rather, your Rabb is the Rabb of the heavens and the earth, the One who originated them — and I am one of those who bear witness to that.\"", "সে বলল, \"তোমাদের একমাত্র প্রভু হচ্ছেন আকাশমন্ডলী এবং পৃথিবীর প্রভু, যিনি তাদের সৃষ্টি করেছেন। এটা সেই সাক্ষ্য যার সাক্ষী আমি দেই।"],
  "21:57": ["And by Allah, I will surely scheme against your asnam after you turn your backs.", "\"আমি আল্লাহর নামে শপথ করছি, তোমাদের মূর্তিগুলোর সাথে আমার কিছু একটা করার পরিকল্পনা আছে, তোমরা চলে যাওয়া মাত্রই।\""],
  "21:58": ["So he reduced them to pieces, except their biggest, so that they would return to it.", "সে সেগুলোকে টুকরো টুকরো করে ফেলল, বড়টাকে ছাড়া, যাতে তারা সেটাকে জিজ্ঞেস করতে পারে।"],
  "21:59": ["They said: \"Who did this to our alihah? He is surely one of the wrongdoers.\"", "তারা বলল, \"যে-ই আমাদের উপাস্যদের সাথে এরকম করেছে, সে আসলেই সীমালংঘনকারী।\""],
  "21:60": ["They said: \"We heard a youth speaking of them — he is called Ibrahim.\"", "তারা বলল, \"আমরা এক তরুনকে শুনেছি এগুলোকে হুমকি দিতে; তার নাম হলো ইব্রাহিম।"],
  "21:61": ["They said: \"Then bring him before the eyes of the people, so that they may bear witness.\"", "তারা বলল, তাকে সকল লোকের চোখের সামনে আনো; যাতে তারা সাক্ষী দিতে পারে।\""],
  "21:62": ["They said: \"Was it you who did this to our alihah, Ibrahim?\"", "তারা বলল, \"তুমি কি আমাদের উপাস্যদের সাথে এরকম করেছ, হে ইব্রাহিম?\""],
  "21:63": ["He said: \"No — this biggest one of theirs did it. So ask them, if they can speak.\"", "সে বলল, \"এটা তো ঐ বড়টা করেছে। তাদেরকে গিয়ে জিজ্ঞেস করো, যদি তারা কথা বলতে পারে।\""],
  "21:64": ["So they returned to themselves and said: \"You yourselves are the wrongdoers.\"", "তারা অবাক হয়ে গেলো, এবং নিজেদের মধ্যে বলাবলি করলো, \"নিশ্চয়, তোমরাই সীমালঙ্ঘন করছিলে।\""],
  "21:65": ["Then they hung their heads: \"You know well that these do not speak.\"", "এরপরও, তারা তাদের পুরনো ধারণায় ফিরে গেল: \"তুমি ভাল করেই জানো যে এরা কথা বলতে পারে না।\""],
  "21:66": ["He said: \"Do you then worship, besides Allah, what can neither benefit you in anything nor harm you?\"", "সে বলল, \"তবে কি তোমরা আল্লাহর পাশে তার উপাসনা করো যা তোমাদের উপকার বা ক্ষতি করার কোন ক্ষমতা রাখে না?"],
  "21:67": ["Shame on you and on what you worship besides Allah! Will you not reason?", "আল্লাহর পাশে অন্য উপাস্যদের উপাসনা করে তোমরা লাঞ্চনা টেনে এনেছ। তোমরা কি বোঝো না?\""],
  "21:68": ["They said: \"Burn him and help your ilahs, if you are to do anything!\"", "তারা বলল, \"তাকে পুড়িয়ে ফেলো এবং তোমাদের উপাস্যদের সমর্থন করো, যদি তোমরা এটাই করার সিদ্ধান্ত নাও।\""],
  "21:69": ["We said: \"O fire, be coolness and safety upon Ibrahim.\"", "আমরা বললাম, \"হে আগুন, ইব্রাহিমের জন্য শীতল এবং নিরাপদ হয়ে যাও।\""],
  "21:70": ["They schemed against him, and We made them the greatest losers.", "এভাবে, তারা তার বিরুদ্ধে ষড়যন্ত্র করেছিলো, কিন্তু আমরা তাদেরকেই পরাজিত করে দিয়েছিলাম।"],
  "21:71": ["And We saved him and Lut to the land in which We blessed, for all peoples.", "আমরা তাকে রক্ষা করেছিলাম, এবং আমরা রক্ষা করেছিলাম লূতকে, সেই ভূমিতে  নিয়ে যা আমরা সকল লোকদের জন্য অনুগ্রহময় করেছিলাম।"],
  "21:72": ["And We granted him Ishaq and Ya'qub as an additional gift, and each We made salih.", "এবং আমরা তাকে ইসহাক ও ইয়াকুবকে দিয়েছিলাম উপহার হিসেবে, এবং আমরা তাদের উভয়কে সৎকর্মশীল করেছিলাম।"],
  "21:73": ["And We made them leaders guiding by Our command, and We revealed to them the doing of good deeds, the keeping up of prayer, and the giving of alms — and they were worshippers to Us.", "আমরা তাদেরকে ইমাম বানিয়েছিলাম যারা আমাদের প্রত্যাদেশ অনুসারে পথ দেখাতো, এবং আমরা তাদের শিখিয়েছিলাম কিভাবে সৎকর্ম করতে হয়, এবং কিভাবে সংযোগ প্রার্থনা (সালাত) এবং বাধ্যতামূলক দান (যাকাত) পালন করতে হয়। আমাদের কাছে, তারা নিবেদিত উপাসনাকারী ছিল।"],
  "21:74": ["And Lut — We gave him judgment and knowledge, and We saved him from the town that used to do the vile deeds; they were a people of evil, fasiqin.", "লূতের ক্ষেত্রে, আমরা তাকে প্রজ্ঞা ও জ্ঞান প্রদান করেছিলাম, এবং আমরা তাকে সেই সম্প্রদায় থেকে রক্ষা করেছিলাম যারা নিদারুণ ঘৃণ্য কাজ চর্চা করতো; তারা ছিল অন্যায়কারী এবং মন্দ লোক।"],
  "21:75": ["And We admitted him into Our mercy — he is indeed among the salihin.", "আমরা তাকে আমাদের  অনুগ্রহের অন্তর্ভূক্ত করিয়েছিলাম, কারণ সে ছিল সৎকর্মপরায়ন।"],
  "21:76": ["And Nuh — when he called of old, We answered him, and We saved him and his family from the great distress.", "এবং, এর আগে, নূহ ডেকেছিল এবং আমরা তার ডাকে সাড়া দিয়েছিলাম। আমরা তাকে এবং তার পরিবারকে সেই মহা দূর্যোগ থেকে বাঁচিয়েছিলাম।"],
  "21:77": ["And We helped him against the people who denied Our ayat; they were a people of evil, so We drowned them all together.", "আমরা তাকে সে লোকদের বিপক্ষে সমর্থন দিয়েছিলাম যারা আমাদের প্রকাশনাবলি প্রত্যাখ্যান করেছিল। তারা ছিল মন্দ লোক, তাই আমরা তাদের সকলকে ডুবিয়ে দিয়েছিলাম।"],
  "21:78": ["And Dawud and Sulayman, when they judged concerning the field when the people's flock strayed into it — and We were witness to their judgment.", "আর দাউদ এবং সোলায়মান, একবার তারা যখন বিচার করেছিলো কোন একজনের ফসল নিয়ে  যা আরেকজনের ভেড়া নষ্ট করেছিলো। আমরা তাদের বিচার প্রত্যক্ষ করেছিলাম।"],
  "21:79": ["So We gave Sulayman understanding of it, and to each We gave judgment and knowledge. And We subjected with Dawud the mountains, glorifying, and the birds — and We were ever doers.", "আমরা সোলায়মানকে সঠিক বুঝ দিয়েছিলাম, যদিও আমরা তাদের দু'জনকেই প্রজ্ঞা ও জ্ঞান দান করেছিলাম। (আল্লাহর) মহিমা প্রকাশে আমরা দাউদের সেবায় নিযুক্ত করেছিলাম পাহাড়দেরকে, সেই সাথে পাখিদেরও।  আমরা এটাই করেছিলাম।"],
  "21:80": ["And We taught him the making of garments for you, to fortify you in your clash of might — so are you grateful?", "এবং যুদ্ধে তোমাদের রক্ষা করতে আমরা তাকে ঢাল বানানোর কৌশল শিখিয়েছিলাম। তবে কি তোমরা কৃতজ্ঞ ?"],
  "21:81": ["And for Sulayman the wind, storming, running at his command to the land in which We blessed — and We knew all things.", "সোলায়মানের জন্য, আমরা তার আয়ত্তে এনে দিয়েছিলাম বায়ুকে যা তার ইচ্ছামতো আন্দোলিত এবং প্রবাহিত হতো,  সে একে তার ইচ্ছামতো নির্দেশ করতে পারতো, তার পছন্দের যে কোন ভূমিতে, এবং আমরা এমন ভূমিকে তার জন্য ধন্য করতাম। আমরা সব বিষয়ে পুরোপুরি অবগত।"],
  "21:82": ["And among the devils were those who dived for him and did work other than that — and We were watching over them.", "এবং শয়তানদের মধ্যে ছিল তারা যারা তার জন্য ডুব দিতো (সাগর থেকে উত্তোলন করতে), অথবা তা-ই করতো যা সে তাদেরকে করতে আদেশ করতো। আমরা তার সেবায় তাদের নিযুক্ত করেছিলাম।"],
  "21:83": ["And Ayyub, when he called his Rabb: \"Harm has touched me, and You are the Raheem of the merciful.\"", "এবং আয়ুব তার প্রভুর কাছে মিনতি করেছিল: \"আমি দূর্দশা  পীড়িত হয়েছি, এবং, সকল দয়ালুর মধ্যে, আপনি সবচেয়ে দয়ালু।"],
  "21:84": ["So We answered him and removed the harm that was on him, and We gave him his family and the like of them with them — a mercy from Us and a reminder for the worshippers.", "আমরা তার ডাকে সাড়া দিয়েছিলাম, তার দূর্দশা দূর করেছিলাম, এবং তার জন্য তার পরিবারকে ফিরিয়ে দিয়েছিলাম, এমনকি দ্বিগুণ আকারে। সেটা ছিল আমাদের পক্ষ থেকে দয়া, এবং উপাসনাকারীদের জন্য একটি স্মারক।"],
  "21:85": ["And Ismail and Idris and Dhu al-Kifl — each was among the sabirin.", "আরও, ইসমাইল, ইদ্রিস, জুল-কিফল; সকলেই ছিল অবিচল, ধৈর্যশীল।"],
  "21:86": ["And We admitted them into Our mercy — they are indeed among the salihin.", "আমরা তাদেরকে আমাদের দয়ার অন্তর্ভুক্ত করিয়েছিলাম, কারণ তারা ছিল সৎকর্মশীল।"],
  "21:87": ["And Dhu al-Nun, when he went off in anger and thought that We would have no power over him; then he called in the darkness: \"There is no ilah but You; glory be to You; I was indeed one of the wrongdoers.\"", "এবং জান-নূন (ইউনুছ,  যার নামে 'ন' আছে), প্রতিবাদে তাকে দেওয়া বিশেষ কাজ থেকে সরে দাঁড়িয়েছিল, এই ভেবে যে আমরা তাকে নিয়ন্ত্রণ করতে পারবো না, শেষ পর্যন্ত সে (বড় মাছের পেটের) অন্ধকার থেকে অনুনয় করতে লাগলো: \"আপনি ছাড়া অন্যকোন উপাস্য নেই। আপনি মহিমান্বিত। আমি এক গুরুতর পাপ করেছি।"],
  "21:88": ["So We answered him and saved him from the gloom — and thus We save the muminin.", "আমরা তার ডাকে সাড়া দিয়েছিলাম, এবং তাকে সেই সংকট থেকে রক্ষা করেছিলাম;  আমরা এভাবে বিশ্বাসীদের রক্ষা করি।"],
  "21:89": ["And Zakariya, when he called his Rabb: \"Rabb, do not leave me alone, and You are the best of inheritors.\"", "এবং জাকারিয়া তার প্রভুর কাছে মিনতি করেছিল: \"আমার প্রভু,  আমাকে উত্তরাধিকার শূন্য করে রাখবেন না, যদিও আপনিই সর্বোত্তম উত্তরাধিকারী।”"],
  "21:90": ["So We answered him and granted him Yahya, and We made his zawj sound for him. They used to race to the good deeds and call on Us in eagerness and in awe, and they were humble before Us.", "আমরা তার ডাকে সাড়া দিয়েছিলাম এবং তাকে দান করেছিলাম ইয়াহিয়া; আমরা তার জন্য তার স্ত্রীকে সারিয়ে দিয়েছিলাম। সেটা এ কারনে যে তারা সৎকর্ম করতে ঝাঁপিয়ে পড়তো, এবং আমাদের কাছে অনুনয় করতো আনন্দের সময়ে, একই সাথে ভয়ের সময়। আমাদের কাছে, তারা ছিল ভক্ত।"],
  "21:91": ["And she who fortified her opening — We blew into her of Our ruh, and We made her and her son an aya for all peoples.", "তার ক্ষেত্রে যে তার সতীত্ব বজায় রেখেছিল, আমরা তার মধ্যে আমাদের রূহ ফুঁকে দিয়েছিলাম, আর এভাবে, আমরা তাকে এবং তার পুত্রকে পুরো বিশ্বের জন্য একটি নিদর্শন করেছিলাম।"],
  "21:92": ["Indeed, this community of yours is one community, and I am your Rabb — so worship Me.", "তোমাদের ধর্মগোষ্ঠী তো এক ধর্মগোষ্ঠী, এবং কেবল আমিই তোমাদের প্রভু; তোমরা একমাত্র আমার উপাসনা করবে।"],
  "21:93": ["Yet they cut their affair into pieces among themselves — but all will return to Us.", "কিন্তু, তারা নিজেদেরকে বিতর্কিত ধর্মে বিভক্ত করে ফেলল। (বিচারের জন্য) তারা সকলে আমাদের কাছে ফিরে আসবে।"],
  "21:94": ["So whoever does salih deeds while a mumin — no rejection of his striving; and We are recording it for him.", "আর যারা সৎ-কাজ করে, বিশ্বাসী অবস্থায়, তাদের কাজ বিফলে যাবে না; আমরা তা লিপিবদ্ধ করছি।"],
  "21:95": ["And there is a ban upon any town We destroyed: they will not return.", "আমরা ধ্বংস করে দিয়েছি এমন কোন জনপদের জন্য আবার ফিরে আসা নিষেধ।"],
  "21:96": ["Until, when Ya'juj and Ma'juj are let loose and pour forth from every ridge,", "যতক্ষণ না ইয়াজুজ এবং মাজুজ পুনরাবির্ভুত হয়,  তখন তারা ফিরবে- তারা সবদিক থেকে আসবে।"],
  "21:97": ["and the true promise draws near — and there, staring, are the eyes of those who disbelieved: \"Woe to us! We were indeed unaware of this; rather, we were wrongdoers.\"", "তখনই সেই অনিবার্য ভবিষ্যদ্বাণী পূর্ণ হবে, এবং অবিশ্বাসীরা আতঙ্কিত দৃষ্টিতে তাকিয়ে থাকবেঃ “দুর্ভাগ্য আমাদের, আমরা বেখবর হয়ে ছিলাম। নিশ্চয়, আমরা অন্যায়কারী ছিলাম”।"],
  "21:98": ["Indeed, you and what you worship besides Allah are fuel of Hell — you will be arriving at it.", "তোমরা এবং আল্লাহর পাশে যাদেরকে তোমরা উপাসনা করো, তারা নরকের জ্বালানি হবে; এটাই তোমাদের অনিবার্য নিয়তি।"],
  "21:99": ["If these had been alihah, they would not have arrived at it — yet all abide in it forever.", "ঐগুলো যদি উপাস্য হতো, তারা শেষ পর্যন্ত নরকে যেতো না। এর সব বাসিন্দারা এর মধ্যে চিরকাল বাস করবে।"],
  "21:100": ["For them therein is groaning, and therein they hear nothing.", "তারা সেখানে দীর্ঘশ্বাস ফেলবে এবং আর্তনাদ করবে, এবং তারা কোনো সংবাদ পাবেনা।"],
  "21:101": ["Indeed, those for whom the good has preceded from Us — those are far removed from it.", "আর যারা আমাদের চমৎকার পুরস্কার অর্জন করবে, তারা এর থেকে সুরক্ষিত থাকবে।"],
  "21:102": ["They will not hear its slightest sound, and they abide forever in whatever their nafs desired.", "তারা এর হিস-হিস শব্দ শুনবে না। তারা এক বাসস্থান উপভোগ করবে যেখানে তারা যা কিছু আকাঙ্ক্ষা করবে তাই পাবে, চিরকাল।"],
  "21:103": ["The greatest dread will not grieve them, and the malakat will receive them: \"This is your day that you were promised.\"", "সেই মহা আতঙ্ক তাদেরকে চিন্তিত করবে না, এবং স্বর্গ-দূতেরা তাদেরকে আনন্দের সাথে গ্রহণ করবেঃ “এটা তোমাদের দিন, যার প্রতিশ্রুতি তোমাদেরকে দেয়া হয়েছে”।"],
  "21:104": ["The day We fold the heaven like the folding of a written scroll — as We began the first creation, We will repeat it. A promise binding on Us — indeed We were ever doers.", "সেই দিনে, আমরা আকাশকে গুটিয়ে নেব, একটা বই গুটিয়ে নেয়ার মত। ঠিক যেভাবে আমরা প্রথম সৃষ্টির সূচনা করেছিলাম, আমরা তার পুনরাবৃত্তি করবো। এটা আমাদের অঙ্গীকার; আমরা অবশ্যই তা সম্পাদন করবো।"],
  "21:105": ["And We wrote in the Kitab after the reminder: \"The earth — My salih servants shall inherit it.\"", "আমরা যবুরে প্রকাশ করেছি, সেই সাথে অন্যান্য ঐশী-গ্রন্থে, যে পৃথিবীর উত্তরাধিকারী হবে আমার সৎ-কর্মশীল উপাসনাকারীরা।"],
  "21:106": ["Indeed, in this is a message reaching through, for a people of worshippers.", "এটা সেসব লোকদের জন্য একটি ঘোষণা যারা উপাসনাকারী।"],
  "21:107": ["And We sent you only as a mercy for all peoples.", "পুরো দুনিয়ার প্রতি আমাদের দয়া থেকে আমরা তোমাকে পাঠিয়েছি।"],
  "21:108": ["Say: \"It is revealed to me only that your ilah is one ilah — so will you be ones who submit?\"", "ঘোষণা করো, “আমাকে ঐশ্বরিক প্রত্যাদেশ দেওয়া হয়েছে যে তোমাদের খোদা একজনই।  তবে কি তোমরা নিজেদেরকে সমর্পণ করবে?"],
  "21:109": ["But if they turn away, say: \"I have proclaimed to you all alike, and I do not know whether what you are promised is near or far.\"", "যদি তারা মুখ ফিরিয়ে নেয়, তবে বল, “আমি তোমাদেরকে যথেষ্ট সতর্ক করেছি, এবং আমার কোন ধারনা নেই কতটা শীঘ্র বা দেরিতে (শাস্তি) তোমাদের কাছে আসবে।"],
  "21:110": ["Indeed, Allah knows the open speech and knows what you hide.", "“তিনি পরিপূর্ণ অবগত তোমাদের প্রকাশ্য বক্তব্যের ব্যাপারে, এবং তিনি পরিপূর্ণ অবগত সে সবকিছু সম্পর্কে, যা তোমরা গোপন করো।"],
  "21:111": ["And I do not know — perhaps it is a trial for you, and an enjoyment until a time.", "“যতো দূর আমি জানি, এই দুনিয়া তোমাদের জন্য একটি পরীক্ষা, এবং একটি সাময়িক উপভোগ”।"],
  "21:112": ["Say: \"Rabb, judge with the truth! Our Rabb is the Rahman, the One whose help is sought against what you describe.\"", "বল, “আমার প্রভু, আপনার বিচার পূর্ণ ন্যায়বিচার। আমাদের প্রভু পরম করুণাময়, তোমাদের দাবীর মুখে শুধুমাত্র তাঁর সাহায্য অন্বেষণ করি”।"],
  "22:1": ["O people, be ilahfearing toward your Rabb; the quaking of the Hour is a tremendous thing.", "হে লোকেরা, তোমারদের উচিত তোমাদের প্রভুকে ভক্তি করা, কারন সেই সময়ের কম্পন ভয়াবহ।"],
  "22:2": ["On the day you see it, every nursing mother will be dazed away from what she nursed, and every imra'a bearing a burden will lay down her burden, and you will see people in stupor while they are not drunk — but the punishment of Allah is severe.", "যেদিন তোমরা তা প্রত্যক্ষ করবে, এমনকি একজন স্তন্য দানকারিণী মাও তার শিশুকে পরিত্যাগ করবে, এবং একজন অন্তঃসত্ত্বা নারী গর্ভপাত করবে। তুমি লোকদের টলমল করে হাটঁতে দেখবে, যেন তারা মাতাল, যদিও তারা মাতাল নয়। এটা এ কারনে যে আল্লাহর শাস্তি খুবই ভয়ানক।"],
  "22:3": ["And among people are those who dispute about Allah without knowledge, and follow every defiant devil.", "লোকেদের মধ্যে, এমনও আছে যারা আল্লাহর ব্যাপারে তর্ক করে জ্ঞান ছাড়াই, এবং প্রত্যেকটি বিদ্রোহী শয়তানের অনুসরণ করে।"],
  "22:4": ["It is decreed upon him that whoever takes him as an ally, he will lead him astray and guide him to the punishment of the Blaze.", "এটা নিয়ম করা হয়েছে যে, যেকেউ তার সাথে মিত্রতা করে, তাকে সে পথভ্রষ্ট করবে এবং তাকে নরকের যন্ত্রণার দিকে পথ দেখাবে।"],
  "22:5": ["O people, if you are in doubt about the raising: We created you from dust, then from a drop, then from a clot, then from a lump of tissue, formed and unformed, to make clear to you; and We settle in the wombs what We will until an appointed term; then We bring you out as a child, that you may reach your prime; and some of you die, and some of you are returned to the frailest age, so that they know nothing after once knowing. And you see the earth lifeless; then when We send down water upon it, it stirs and swells and grows from every pair something lovely.", "হে লোকেরা, যদি পুনরুত্থানের ব্যাপারে তোমাদের কোন সন্ধেহ থাকে, (স্মরণ করো যে) আমরা তোমাদের ধুলো থেকে সৃষ্টি করেছি, এবং পরবর্তীতে এক অতি ক্ষুদ্র ফোঁটা থেকে, যা এক ঝুলন্ত (ভ্রুনে) পরিণত হয়, এরপর এটি পরিনত হয় একটি মানবাকৃতির ভ্রুনে যাতে জীবন দেওয়া হয় অথবা  জীবনহীন গণ্য করা হয়। আমরা এভাবে তোমাদের জন্য বিষয়গুলো সুস্পষ্ট করি। আমরা গর্ভে স্থাপন করি যা আমাদের ইচ্ছা একটি পূর্ব নির্ধারিত সময়ের জন্য। এরপর আমরা তোমাদের নবজাতক হিসেবে বের করে আনি, এরপর তোমরা প্রাপ্ত বয়সে পৌঁছাও। যেখানে তোমাদের কেউ কেউ যৌবনে মারা যাও, অন্যরা নিকৃষ্ট বয়স পর্যন্ত বেঁচে থাকো, শুধুমাত্রে এটা দেখার জন্য যে একটি নির্দিষ্ট সীমার পর কোন জ্ঞান আহরণ করা যায় না। আবার, তোমরা একটি ভূমিকে দেখো যা কিনা মৃত, এরপর যখনই আমরা এতে পানি বর্ষণ করি, এতে জীবন স্পন্দিত হয় এবং সকল প্রকার সুন্দর উদ্ভিদ জন্মায়।"],
  "22:6": ["That is because Allah is the Truth, and gives life to the dead, and has power over everything.", "এটা প্রমান করে যে আল্লাহ সত্য, এবং যে তিনি মৃতকে জীবিত করেন, এবং যে তিনি সর্বশক্তিমান।"],
  "22:7": ["And that the Hour is coming — no doubt in it — and that Allah will raise those in the graves.", "এবং যে সেই ঘণ্টা আসছে, এ ব্যাপারে কোন সন্ধেহ নেই, এবং যে আল্লাহ পুনরুজ্জীবিত করেন, তাদেরকে, যারা কবরে রয়েছে।"],
  "22:8": ["And among people are those who dispute about Allah without knowledge, without guidance, and without an enlightening Kitab.", "লোকদের মধ্যে রয়েছে সে ব্যক্তি, যে আল্লাহ সম্পর্কে তর্ক করে জ্ঞান ছাড়া, এবং পথ নির্দেশনা ছাড়া, এবং কোন জ্ঞানালোকপূর্ণ ঐশী-গ্রন্থ ছাড়া।"],
  "22:9": ["He bends himself aside to lead astray from the way of Allah; for him in this world is disgrace, and on the Day of the Standing We will let him taste the punishment of the burning.", "দাম্ভিকতার সাথে সে সংগ্রাম করে আল্লাহর পথ থেকে লোকদের সরিয়ে দিতে। এই ভাবে সে এ জীবনে অপমান টেনে আনে, এবং পুনরুত্থান দিনে আমরা তাকে দহন যন্ত্রণায় সোপর্দ করবো।"],
  "22:10": ["That is for what your hands sent ahead, and Allah is not zalimun to the servants.", "এটা তাই যা তোমার হাত তোমার জন্য পাঠিয়েছে। আল্লাহ কখনই লোকদের প্রতি অন্যায়কারী নন।"],
  "22:11": ["And among people are those who worship Allah on shifting ground: if good befalls them they settle into it, but if a trial befalls them they flip over on their faces; they lose this world and the next — that is the clear loss.", "লোকদের মধ্যে রয়েছে সে ব্যক্তি যে শর্তসাপেক্ষে আল্লাহর উপাসনা করে। যদি সবকিছু তার মত অনুযায়ী যায়, সে সন্তুষ্ট। কিন্তু যদি কিছু দুর্দশা তার উপর পতিত হয়, সে মুখ ফিরিয়ে নেয়। এভাবে, সে এই জীবন এবং পরকাল উভয়ই হারায়। এমনই আসল ক্ষতি।"],
  "22:12": ["He calls upon besides Allah what neither harms him nor benefits him; that is the far error.", "সে আল্লাহর পাশে তার উপাসনা করে যা তার ক্ষতি অথবা তার উপকার করার কোন ক্ষমতা রাখে না; এমনই আসল পথভ্রষ্টতা।"],
  "22:13": ["He calls on one whose harm is nearer to him than his benefit — what a wretched patron, and what a wretched companion.", "সে তার উপাসনা করে যা তার উপকারের চেয়ে ক্ষতি করার বেশি সম্ভাবনা রাখে। কি এক শোচনীয় প্রভু! কি এক শোচনীয় সঙ্গি!"],
  "22:14": ["Allah will surely admit those who believe and do the good deeds into gardens beneath which rivers flow. Allah does what Allah wills.", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে আল্লাহ তাদের প্রবেশ করাবেন প্রবাহিত ঝর্না সহ বাগানে। সবকিছু আল্লাহর ইচ্ছা অনুযায়ী হয়।"],
  "22:15": ["Whoever thinks that Allah will not help him in this world and the next — let him stretch a rope toward the heaven, then cut it off, and let him see whether his scheme removes what enrages him.", "যদি কেউ ভাবে যে আল্লাহ এই জীবনে এবং পরকালে তাকে পালন করতে পারবে না, তাকে সম্পূর্ণ ভাবে স্বর্গের (তার সৃষ্টিকর্তার) দিকে ফিরতে দাও, এবং ছিন্ন করতে দাও (অন্য কারো প্রতি তার নির্ভরশীলতা)। সে তখন দেখবে যে এই পরিকল্পনা অপসরণ করে যে কোন কিছু, যা তাকে কষ্ট দেয়।"],
  "22:16": ["And so We sent it down with clear ayat, and Allah guides whom Allah wills.", "এখানে, আমরা এভাবে স্পষ্ট প্রকাশনাবলী প্রকাশ করেছি, অতঃপর আল্লাহ যাকে ইচ্ছা পথপ্রদর্শন করেন।"],
  "22:17": ["Those who believe, and those who joined the rivaling party, and the Sabians, and the Nasara, and the Magians, and those who associate — Allah will surely decide between them on the Day of the Standing; Allah is witness over everything.", "যারা বিশ্বাস করে, যারা ইহুদী, ধর্মান্তরিত, খ্রিষ্টান, জরথুস্ট্রীয়, এবং প্রতিমা উপাসকরা, আল্লাহই সেই স্বত্ত্বা যিনি পুনরুত্থান দিনে তাদের মধ্যে বিচার করবেন। আল্লাহ সবকিছু প্রত্যক্ষ করেন।"],
  "22:18": ["Have you not seen that whatever is in the heavens and whatever is on the earth bows to Allah — the sun, the moon, the stars, the mountains, the trees, the creatures, and many of the people? And many deserve the punishment. And whoever Allah humiliates has no one to honor him. Allah does what Allah wills.", "তুমি কি অনুধাবন করো না যে আল্লাহকে সেজদা করে আকাশমন্ডলী এবং পৃথিবীর সবকিছু, এবং সূর্য, এবং চাঁদ, এবং তারাকারাজি, এবং পর্বতসমূহ, এবং বৃক্ষরাজি, এবং পশুকূল এবং অনেক লোকরা? লোকদের মধ্যে অন্য অনেকের ধ্বংস অবধারিত। যাকে আল্লাহ লজ্জিত করেন, কেউ তাকে সম্মান করবে না। সবকিছু আল্লাহর ইচ্ছা অনুসারে হয়।"],
  "22:19": ["These are two contending parties who contended about their Rabb. As for those who disbelieved, garments of fire are cut out for them, and scalding water is poured over their heads.", "এই যে দুটি পক্ষ তাদের প্রভুর ব্যাপারে বিবাদ করছে। যারা অবিশ্বাস করে, তাদের জন্য আগুনের পোশাক তৈরি করা হবে। নারকীয় তরল তাদের মাথার উপর ঢালা হবে।"],
  "22:20": ["It melts what is in their bellies, and the skins.", "এটা তাদের ভিতর গলিয়ে দেবে, সেই সাথে তাদের চামড়া।"],
  "22:21": ["And they have maces of hadid.", "তারা লোহার পাত্রে আবদ্ধ থাকবে।"],
  "22:22": ["Whenever they want to leave it because of the gloom, they are put back into it: \"Taste the punishment of the burning!\"", "যখনি তারা এমন দুর্দশা থেকে বের হতে চেষ্টা করবে, তাদের জোরপূর্বক তাতে ফিরিয়ে দেওয়া হবেঃ  “দহন যন্ত্রণা আস্বাদন করো”।"],
  "22:23": ["Allah will surely admit those who believe and do the good deeds into gardens beneath which rivers flow, adorned in them with bracelets of gold and pearls, and their garment in it is silk.", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, আল্লাহ তাদেরকে প্রবেশ করাবেন প্রবাহিত ঝর্নাসহ বাগানে। তাদেরকে সেখানে সোনার ব্রেচলেট এবং মুক্তা দিয়ে সাজানো হবে, এবং সেখানে তাদের পোশাক হবে রেশমের।"],
  "22:24": ["And they are guided to the good of speech, and guided to the path of the Praiseworthy.", "তারাকে উত্তাম বাক্যের দিকে পরিচালিত করা হয়েছে; তারা পথপ্রদর্শিত হয়েছে পরম প্রশংসনীয়- এর পথে।"],
  "22:25": ["Those who disbelieve and bar from the way of Allah and from the Sacred Mosque, which We made for people alike — the one cleaving to it and the desert-dweller — whoever intends in it deviation with injustice, We will make him taste a painful punishment.", "অবশ্যই, যারা অবিশ্বাস করে এবং অন্যদের বাধাঁ দেয় আল্লাহর পথ থেকে, এবং পবিত্র মসজিদ থেকে যা আমরা সকল লোকদের জন্য নির্ধারিত করেছি- হোক তারা স্থানিয় অথবা দর্শনার্থী - এবং একে দূষিত এবং কলুষিত করতে চায়, আমরা তাদেরকে যন্ত্রণাদায়ক শাস্তি দিয়ে পীড়িত করবো।"],
  "22:26": ["And when We settled Ibrahim at the site of the House: \"Associate nothing with Me, and purify My House for those who go around it, for those who stand, and for those who bow and prostrate.\"", "আমরা ইব্রাহিমকে পবিত্র গৃহ স্থাপন করতে নিযুক্ত করেছিলাম : “তুমি আমার পাশে অন্য কোন উপাস্যের উপাসনা করবে না, এবং আমার ঘর পবিত্র রাখবে তাদের জন্য যারা তা দর্শন করতে আসে, যারা এর নিকটে বাস করে, এবং যারা রুকু ও সেজদা করে।"],
  "22:27": ["And proclaim among the people the pilgrimage; they will come to you on foot and on every lean mount, coming from every deep ravine.", "এবং ঘোষণা করো যে লোকেরা হজ্জ তীর্থযাত্রা পালন করবে। তারা তোমার কাছে হেঁটে অথবা বিভিন্ন ক্লান্তিকর (পরিবহনে) চড়ে আসবে। তারা সর্বাধিক দূরবর্তী স্থান থেকে আসবে।"],
  "22:28": ["That they may witness benefit for themselves and remember the name of Allah in appointed days over what Allah provided them of the beasts of the herds; so eat of it and feed the wretched and the needy.", "তারা বানিজ্যিক সুবিধা অন্বেষণ করতে পারে, এবং তারা নির্দিষ্ট দিনগুলোতে আল্লাহর নাম স্মরণ করবে তদেরকে গৃহপালিত পশু প্রদান করার জন্য। “সেখান থেকে খাও এবং দুঃস্থ ও গরিবদের খাওয়াও”।"],
  "22:29": ["Then let them settle their unkempt rites and fulfill their vows, and go around the Ancient House.", "তারা তাদের কর্তব্য সম্পন্ন করবে, তাদের প্রতিজ্ঞা পূর্ণ করবে, এবং প্রাচীন পবিত্র গৃহটি দর্শন করবে।"],
  "22:30": ["So it is; and whoever honors the sanctity of Allah — that is better for him with his Rabb. The herds are made lawful for you except what is recited to you; so avoid the filth of idols, and avoid swerving speech.", "যারা আল্লাহর আদেশক্রিত ধর্মানুষ্ঠানগুলো সম্মান করে তারা তাদের প্রভুর কাছে এক ভালো পুরস্কারের যোগ্য হয়েছে।  সকল গৃহপালিত পশু তোমাদের খাদ্য হিসেবে আইনসিদ্ধ করা হল, সেগুলো ছাড়া যেগুলো তোমাদের জন্য সুনির্দিষ্টভাবে নিষিদ্ধ করা হয়েছে। তোমরা অংশীদার উপাসনার জঘন্যতা এড়িয়ে চলবে, এবং মিথ্যা সাক্ষ্য দেওয়া এড়িয়ে চলবে।"],
  "22:31": ["Turned upright to Allah, not associating anything with Allah; and whoever associates with Allah, it is as if he fell from the heaven, and a bird snatches him, or the wind sweeps him down into a far-off place.", "তোমরা তোমাদের একনিষ্ঠতা সম্পূর্ণরূপে কেবল আল্লাহর প্রতি বজায় রাখবে। যেকেউ আল্লাহর পাশে কোনো উপাস্য স্থাপন করে সে তার মতো যে আকাশ থেকে পড়লো, তারপর শকুনেরা তাকে ছিনিয়ে নিল, অথবা বাতাস তাকে এক গভীর গিরিখাতের মধ্যে উড়িয়ে নিয়ে ফেলল।"],
  "22:32": ["So it is; and whoever honors the rites of Allah — that is from the devotion of hearts.", "নিশ্চয়, যারা আল্লাহর আদেশক্রিত ধর্মানুষ্ঠানগুলোকে সম্মান করে তারা তাদের হৃদয়ের ন্যায়পরায়ণতা প্রদর্শন করলো।"],
  "22:33": ["In them you have benefit until an appointed term; then their destination is the Ancient House.", "গৃহপালিতপশু তোমাদেরকে একটি নির্দিষ্ট সময়ের জন্য অনেক উপকারিতা দেয়, প্রাচীন পবিত্র গৃহে দান করার আগে।"],
  "22:34": ["For every community We appointed a rite, that they may remember the name of Allah over what Allah provided them of the beasts of the herds. Your ilah is one ilah, so to Allah submit — and give good news to the mukbitin.", "প্রত্যেক জনপদের জন্য আমরা ধর্মানুষ্ঠানের আদেশ করেছি যার দ্বারা তারা আল্লাহর নাম স্মরণ করে তাদেরকে পালনযোগ্য পশু প্রদান করার জন্য। তোমাদের উপাস্য এক এবং সেই একই উপাস্য। তোমরা সকলে তাঁর কাছে সমর্পিত হবে। অনুগতদের সুসংবাদ দাও।"],
  "22:35": ["Those who, when Allah is remembered, their hearts tremble with awe, and those sabir over what befalls them, and those who keep up the prayer, and who spend from what We provided them.", "তারা সে লোক যাদের হৃদয় আল্লাহর উল্লেখে কম্পিত হয়, তারা প্রতিকূলতার সময়  দৃঢ়তার সাথে অবিচল, তারা সংযোগ প্রার্থনা (সালাত) পালন করে, এবং তাদেরকে দেয়া আমাদের জীবিকা থেকে তারা দান করে।"],
  "22:36": ["And the sacrificial beasts We made for you among the rites of Allah; in them is good for you. So remember the name of Allah over them, lined in ranks; then when their sides collapse, eat of them and feed the contented and the beggar. Thus We subjected them to you, so that you may give thanks.", "আল্লাহর আদেশক্রিত ধর্মানুষ্ঠানগুলোর মধ্যে পশু কোরবানি রয়েছে তোমাদের নিজেদের ভালোর জন্য। তোমরা এগুলোর উপর আল্লাহর নাম উচ্চারন করবে যখন এরা সারিতে দাড়িয়ে থাকে। এগুলো কোরবানির জন্য উৎসর্গ হয়ে গেলে তোমরা এদের থেকে খাবে এবং গরীব ও অভাবীদের খাওয়াবে। এই জন্যই আমরা এগুলোকে তোমাদের জন্য বশীভূত করে দিয়েছি, যাতে তোমরা তোমাদের কৃতজ্ঞতা প্রদর্শন করতে পারো।"],
  "22:37": ["Neither their flesh nor their blood reaches Allah, but the devotion from you reaches Allah. Thus We subjected them to you, that you may magnify Allah for what Allah guided you to. And give good news to the muhsinin.", "না তাদের মাংস, না তাদের রক্ত আল্লাহর কাছে পৌঁছায়। যা তাঁর কাছে পৌঁছায় তা হল তোমাদের সৎ-কর্মশীলতা। তিনি এগুলোকে তোমাদের জন্য বশীভূত করে দিয়েছেন, যাতে আল্লাহর মহিমা ঘোষণা করে তোমার তোমাদের কৃতজ্ঞতা প্রদর্শন করো তোমাদের পথ প্রদর্শন করার জন্য। দানশীলদের সুসংবাদ দাও।"],
  "22:38": ["Allah pushes harm back from those who believe; Allah does not love any khawwān kafūr.", "আল্লাহ তাদের পক্ষে থাকেন যারা বিশ্বাস করে। আল্লাহ কোন বিশ্বাসঘাতক, অকৃতজ্ঞকে ভালোবাসেন না।"],
  "22:39": ["Permission is given to those who are fought, because they were wronged; and Allah is powerful to help them.", "তাদেরকে অনুমতি দেয়া হলো যারা নির্যাতিত হচ্ছে, যেহেতু তাদের উপর অবিচার করা হয়েছে, এবং আল্লাহ অবশ্যই তাদের সমর্থন করতে সক্ষম।"],
  "22:40": ["Those who were driven from their homes without right, only because they said, \"Our Rabb is Allah.\" Had Allah not pushed back some people by means of others, monasteries, churches, synagogues, and mosques — in which the name of Allah is much remembered — would have been demolished. And Allah will surely help whoever helps Allah. Allah is powerful, mighty.", "তারা তাদের বাড়ি থেকে উচ্ছেদ হয়েছিল অন্যায়ভাবে, অন্য কোন কারনে না শুধু এটুকু বলার জন্য “আমাদের প্রভু আল্লাহ”। যদি আল্লাহ কিছু লোককে সমর্থন না করতেন অন্যদের বিরুদ্ধে, মঠ, গির্জা, সিনেগগ এবং মসজিদগুলো- যেখানে আল্লাহর নাম প্রতিনিয়ত স্মরণ করা হয়-ধ্বংস হয়ে যেত। নিঃসন্দেহে, আল্লাহ তাদের সমর্থন করেন যারা তাঁকে সমর্থন করে। আল্লাহ ক্ষমতাধর, সর্বশক্তিমান।"],
  "22:41": ["Those who, if We establish them in the earth, keep up the prayer, give the purifying share, command what is recognized, and forbid what is rejected; and to Allah belongs the outcome of affairs.", "তারা হচ্ছে সেসব লোক, যাদেরকে যদি আমরা পৃথিবীতে শাসক হিসেবে নিয়োগ/মনোনীত করি, তারা সংযোগ প্রার্থনা (সালাত)এবং বাধ্যতামূলক দান (যাকাত) প্রতিষ্ঠা করবে, এবং সৎকর্মশীলতার ওকালতি করবে এবং মন্দ থেকে নিষেধ করবে। আল্লাহ চূড়ান্ত শাসক।"],
  "22:42": ["If they deny you, then before them the people of Nuh denied, and Ad and Thamud,", "যদি তারা তোমাকে প্রত্যাক্ষান করে, তাদের আগে নুহের, আদের এবং সামুদের লোকেরাও অবিশ্বাস করেছিল।"],
  "22:43": ["and the people of Ibrahim, and the people of Lut,", "ইব্রাহীমের লোকেরা এবং লুতের লোকেরাও।"],
  "22:44": ["and the companions of Midian; and Musa was disbelieved. So I gave respite to the kafirin, then I seized them — and how was My disavowal!", "এবং মাদিয়ানের বাসিন্দারা। মুসাকেও প্রত্যাখ্যান করা হয়েছিল। আমি ঐ সকল লোকদের সুযোগ দিয়ে রেখেছিলাম, এরপর আমি তাদেরকে হিসাবের জন্য ডেকেছিলাম; কেমন (ধ্বংসাত্মক) ছিল আমার শাস্তি!"],
  "22:45": ["How many a town We destroyed while it did wrong, and it lies collapsed on its raised frames, with an abandoned well and a towering palace.", "অনেক জনপদ আমরা ধ্বংস করে দিয়েছি তাদের অন্যায়ের কারনে। তারা শেষ পর্যন্ত ধ্বংসাবশেষে পরিণত হয়েছিল, নিথর কুয়া এবং বিশাল শূন্য প্রাসাদ সহ।"],
  "22:46": ["Have they not journeyed through the earth, so as to have hearts they reason with, or ears they hear with? It is not the sights that go blind, but the hearts within the chests that go blind.", "তারা কি পৃথিবী ঘুরে দেখেনি, এরপর তাদের মন ব্যাবহার করে নি বোঝার জন্য, এবং তাদের কান ব্যবহার করেনি শোনার জন্য? নিশ্চয়, চোখের অন্ধত্ব প্রকৃত অন্ধত্ব নয়, বুকের ভেতরে হৃদয়ের অন্ধত্বই প্রকৃত অন্ধত্ব।"],
  "22:47": ["And they urge you to hurry the punishment, but Allah will never fail Allah's promise; and a day with your Rabb is like 1,000 years of what you count.", "তারা তোমাকে শাস্তি আনার জন্য চ্যালেঞ্জ করে, এবং আল্লাহ কখনো তাঁর ভবিষদ্বানী পূর্ণ করতে ব্যর্থ হন না। তোমার প্রভুর এক দিন তোমাদের এক হাজার বছরের মত।"],
  "22:48": ["And how many a town I gave respite to while it did wrong; then I seized it — and to Me is the arrival.", "অতীতে অনেক জনপদ মন্দ করেছে, এবং আমি তাদেরকে কিছু সময়ের জন্য সুযোগ দিয়ে রেখেছিলাম, এরপর আমি তাদেরকে শাস্তি দিয়েছি। আমার দিকেই চূড়ান্ত নিয়তি।"],
  "22:49": ["Say: O people, I am only a clear warner to you.", "বল, “হে লোকেরা, আমাকে তোমাদের কাছে পাঠানো হয়েছে একজন সুস্পষ্ট সতর্ককারী হিসাবে”।"],
  "22:50": ["Those who believe and do the good deeds — for them is forgiveness and a generous provision.", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে তারা যোগ্য হয়েছে ক্ষমা এবং উদার প্রতিদানের।"],
  "22:51": ["And those who strive against Our ayat, seeking to thwart Us — those are the companions of the Blaze.", "আর যারা আমাদের প্রকাশনাবলীকে চ্যালেঞ্জ করতে সংগ্রাম করে, তারা নরক টেনে আনে।"],
  "22:52": ["We never sent before you any Rasul or Nabi but that when he wished, the devil cast into his wish; then Allah abolishes what the devil casts, and then Allah confirms the ayat. Allah is knowing, wise.", "তোমার আগে না আমরা পাঠিয়েছি কোন বার্তাবাহক, না কোন নবী, যার ইচ্ছায় শয়তান হস্তক্ষেপ করেনি। এরপর আল্লাহ তা অকার্যকর করেন যা শয়তান করেছে। আল্লাহ তাঁর প্রকাশনাবলীকে যথাযথ করেন। আল্লাহ সর্বজ্ঞ, সব থেকে জ্ঞানী।"],
  "22:53": ["That Allah may make what the devil casts a trial for those in whose hearts is sickness and whose hearts are hardened; and the wrongdoers are indeed in far opposition.", "তিনি এভাবে শয়তানের চক্রান্তকে তাদের জন্য একটি পরীক্ষা স্বরুপ করেন যারা তাদের হৃদয়ে সন্দেহ পোষণ করে, এবং যাদের হৃদয় কঠিন হয়ে পড়েছে। অন্যায়কারীরা অবশ্যই বিরোধী দলের সাথে থাকবে।"],
  "22:54": ["And that those given knowledge may know that it is the truth from your Rabb, and believe in it, and their hearts may grow humble to it; and Allah surely guides those who believe to a straight path.", "যারা জ্ঞান পেয়ে অনুগ্রহপ্রাপ্ত তারা তোমার প্রভুর পক্ষ থেকে আসা সত্য চিনতে পারবে, এরপর তাতে বিশ্বাস করবে, এবং তাদের হৃদয় নির্দ্বিধায় তা গ্রহন করবে। অবশ্যই, আল্লাহ বিশ্বাসীদের সঠিক পথে পরিচালিত করেন।"],
  "22:55": ["And the kafirin will not cease doubting it until the Hour comes upon them suddenly, or there comes to them the punishment of a barren day.", "আর যারা অবিশ্বাস করে, তারা সন্ধেহ পোষণ করতে থাকবে যতক্ষণ না সেই ঘণ্টা হঠাৎ করেই তাদের কাছে চলে আসে, অথবা যতক্ষণ না এক ভয়ানক দিনের শাস্তি তাদের কাছে এসে যায়।"],
  "22:56": ["Sovereignty that day belongs to Allah; Allah judges between them. Those who believe and do the good deeds will be in the Garden of Bliss.", "সে দিন সকল সার্বভৌম ক্ষমতা আল্লাহর হবে, এবং তিনি তাদের মধ্যে বিচার করবেন। তাদের ক্ষেত্রে যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, তারা পরম সুখের বাগানগুলোর যোগ্য হয়েছে।"],
  "22:57": ["And those who disbelieve and deny Our ayat — those have a humiliating punishment.", "যখন যারা অবিশ্বাস করেছিল এবং আমাদের প্রকাশনাবলী প্রত্যাখ্যান করেছিল, তারা টেনে এনেছে এক লজ্জাকর শাস্তি।"],
  "22:58": ["And those who emigrate in the way of Allah, then are killed or die — Allah will surely provide them a good provision, and Allah is the best of providers.", "যারা আল্লাহর খাতিরে দেশ ত্যাগ করে, এর পর নিহত হয়, অথবা মারা যায়, আল্লাহ অবশ্যই তাদের প্রতি ভালো জীবিকা বর্ষণ করবেন। আল্লাহ নিশ্চয় সর্বোত্তম জীবিকা প্রদানকারী।"],
  "22:59": ["Allah will surely admit them to a place that pleases them; and Allah is knowing, forbearing.", "অবশ্যই, তিনি তাদেরকে এমন জায়গায় প্রবেশ করাবেন যা তাদেরকে সন্তুষ্ট করবে। আল্লাহ সর্বজ্ঞ, কৃপাময়।"],
  "22:60": ["So it is; and whoever requites with the like of what was done to him, and is then transgressed against — Allah will help him. Allah is pardoning, forgiving.", "এটা নিয়ম করা হয়েছে যে যদি কেউ তার উপর আরোপিত কোন অবিচারের প্রতিশোধ গ্রহণ করে, ন্যায়সঙ্গতভাবে, এরপর এর কারনে নির্যাতিত হয়, আল্লাহ অবশ্যই তাকে সমর্থন করবেন। আল্লাহ ক্ষমাকারী, ক্ষমাশীল।"],
  "22:61": ["That is because Allah enters the night into the day and enters the day into the night, and Allah is hearing, seeing.", "এটি বাস্তবতা যে আল্লাহ রাতকে দিনের সাথে মিলিয়ে দেন, এবং দিনকে রাতের সাথে মিলিয়ে দেন, এবং যে আল্লাহ শ্রোতা, দ্রষ্টা।"],
  "22:62": ["That is because Allah is the Truth, and what they call upon besides Allah is falsehood, and Allah is the High, the Great.", "এটি বাস্তবতা যে আল্লাহ হচ্ছেন সত্য, যেখানে তাঁর পাশে কোন উপাস্য স্থাপন করা হচ্ছে এক মিথ্যা দাড় করানো, এবং যে আল্লাহ সর্বোচ্চ, সর্বপ্রধান।"],
  "22:63": ["Have you not seen that Allah sends down water from the heaven, and the earth turns green? Allah is subtle, aware.", "তুমি কি দেখো না যে আল্লাহ আকাশ থেকে পানি বর্ষণ করেন যা ভূমিকে সবুজে করে তোলে? আল্লাহ মহিমান্বিত, জ্ঞাতা।"],
  "22:64": ["To Allah belongs what is in the heavens and what is on the earth; and Allah is the Free-of-Need, the Praiseworthy.", "তাঁর অধীনে রয়েছে আকাশ মণ্ডলীর সবকিছু এবং পৃথিবীর সবকিছু। নিঃসন্দেহে, আল্লাহ সবচেয়ে ধনী, সবচেয়ে প্রশংসনীয়।"],
  "22:65": ["Have you not seen that Allah subjected to you what is on the earth, and the ship runs on the sea by Allah's command, and Allah holds the heaven so it will not fall on the earth except by Allah's leave? Allah is gentle, compassionate to people.", "তুমি কি দেখনা যে আল্লাহ তোমাদের সেবায় নিয়োজিত করেছেন পৃথিবীর সব কিছু? জাহাজগুলো মহাসাগরে তাঁর আদেশ মত চলে। তিনি আকাশস্থ বস্তুগুলোকে পৃথিবীর সাথে সংঘর্ষ হওয়া থেকে বিরত রাখেন, তাঁর আদেশ অনুসারে ব্যতীত। আল্লাহ লোকদের প্রতি পরম দয়ালু, পরম করুণাময়।"],
  "22:66": ["And it is Allah who gave you life, then makes you die, then gives you life again; the human being is truly ungrateful.", "তিনিই সে সত্ত্বা যিনি তোমাদেরকে জীবন দান করেছেন, এরপর তিনি তোমাদেরকে মৃত্যু দেন, এরপর তিনি তোমাদেরকে জীবন ফিরিয়ে দেন। নিশ্চয়, মানুষ অকৃতজ্ঞ।"],
  "22:67": ["For every community We appointed a rite that they perform; so let them not pull you away in the matter. Call to your Rabb; you are indeed upon straight guidance.", "প্রত্যেক ধর্মগোষ্ঠীর জন্য, আমরা আদেশ করেছি কিছু ধর্মানুষ্ঠান যা তাদেরকে অবশ্যই পালন করতে হবে। অতএব, তাদের উচিত নয় তোমার সাথে তর্ক করা। তুমি তোমার প্রভুর দিকে সকলকে নিমন্ত্রন করতে থাকবে। অবশ্যই, তুমি সঠিক পথে রয়েছ।"],
  "22:68": ["And if they dispute with you, say: Allah knows best what you do.", "যদি তারা তোমার সাথে তর্ক করে, তবে বল, “তোমরা যা কিছুই করো আল্লাহ তা সম্পর্কে পুরোপুরি অবগত”।"],
  "22:69": ["Allah will judge between you on the Day of the Standing concerning what you used to differ about.", "পুনরুত্থান দিনে আল্লাহ তোমাদের মধ্যে বিচার করবেন তোমাদের সকল বিতর্ক নিয়ে।"],
  "22:70": ["Do you not know that Allah knows what is in the heaven and the earth? That is indeed in a record; that is easy for Allah.", "তোমরা কি উপলব্ধি করো না যে আল্লাহ আকাশমণ্ডলীর সবকিছু এবং পৃথিবীর সবকিছু জানেন? এই সবকিছু এক নথীতে নথিভুক্ত আছে। এটা করা আল্লাহর জন্য সহজ।"],
  "22:71": ["And they worship besides Allah that for which Allah sent down no warrant, and of which they have no knowledge; and the wrongdoers have no helper.", "তবুও, তারা আল্লাহর পাশে উপাস্যদের উপাসনা করে যাতে তিনি কোন ক্ষমতা রাখেননি। সীমালঙ্ঘনকারীদের কোন সাহায্যকারী নেই।"],
  "22:72": ["And when Our clear ayat are recited to them, you recognize disbelief on the faces of those who disbelieve; they nearly lunge at those who recite Our ayat to them. Say: Shall I tell you of worse than that? The Fire — Allah has promised it to those who disbelieve, and wretched is the arrival.", "যখন আমাদের প্রকাশনাবলী তাদের কাছে আবৃত্তি করা হয়, স্পষ্টভাবে, তুমি তাদের মুখমণ্ডলে পাপ দেখতে পাবে যারা অবিশ্বাস করে। তারা তাদেরকে প্রায় আক্রমণই করে বসে যারা তাদের কাছে আমাদের প্রকাশনাবলী আবৃত্তি করে। বল, “আমি কি তোমাদেরকে আরও খারাপ কিছু সম্পর্কে জানাবো? আল্লাহ নরকের অঙ্গীকার করেছেন তাদের জন্য যারা অবিশ্বাস করে; কি এক শোচনীয় নিয়তি।\""],
  "22:73": ["O people, a parable is struck, so listen to it: those you call upon besides Allah will never create a fly, even if they gathered together for it; and if a fly snatches something from them, they cannot rescue it from it. Weak are the seeker and the sought.", "হে লোকেরা, এই যে এক উপমা যা তোমাদেরকে অবশ্যই সতর্ককতার সাথে ভেবে দেখতে হবেঃ আল্লাহর পাশে তোমরা যে উপাস্যদের স্থাপন করো তারা একটি মাছিও সৃষ্টি করতে পারে না, এমনকি যদি তারা তা করতে একত্রে সঙ্গবদ্ধ/দলবদ্ধ হয়। উপরন্তু, যদি মাছি তাদের কাছ থেকে কোন কিছু চুরি করে,  তারা সেটা পুনরুদ্ধার করতে পারে না; অনুসরণকারী এবং অনুসৃত উভয়ই দূর্বল।"],
  "22:74": ["They did not measure Allah with the measure due to Allah; Allah is powerful, mighty.", "তারা আল্লাহকে মুল্যায়ন করে না যেভাবে তাঁকে মুল্যায়ন করা উচিৎ। আল্লাহ সবচেয়ে ক্ষমতাধর, সর্বশক্তিমান।"],
  "22:75": ["Allah chooses rusul from the malakat and from people; Allah is hearing, seeing.", "আল্লাহ ফেরেশতাদের মধ্য থেকে বার্তাবাহকদের বাছাই করেন, একইভাবে মানুষদের মধ্য থেকেও। আল্লাহ শ্রোতা, দ্রষ্টা।"],
  "22:76": ["Allah knows what is before them and what is behind them, and to Allah all affairs return.", "তিনি জানেন তাদের অতীত এবং তাদের ভবিষ্যৎ। আল্লাহর অধীনেই সবকিছুর চূড়ান্ত নিয়ন্ত্রন।"],
  "22:77": ["O you who believe, bow and prostrate, and worship your Rabb, and do good — that you may attain success.", "হে তোমরা যারা বিশ্বাস করো, তোমরা রুকু করবে, সেজদা করবে, তোমাদের প্রভুর উপাসনা করবে, এবং সৎ কাজ করবে, যাতে তোমরা সফল হতে পারো।"],
  "22:78": ["And strive in Allah with the striving due to Allah. Allah has chosen you, and has laid on you in the religion no constriction — the way of your father Ibrahim. Allah named you submitters before and in this, so that the Rasul may be a witness over you, and you be witnesses over people. So keep up the prayer, give the purifying share, and hold fast to Allah; Allah is your patron — so what an excellent patron, and what an excellent helper.", "তোমরা আল্লাহর উদ্দেশ্যে সংগ্রাম করবে যেভাবে তাঁর উদ্দেশ্যে তোমাদের সংগ্রাম করা উচিত। তিনি তোমাদের পছন্দ করেছেন এবং তোমাদের উপর কোন কষ্ট আরোপ করেননি তোমাদের ধর্ম চর্চায় –তোমাদের পিতা ইব্রাহীমের ধর্ম। সে-ই প্রথম তোমাদের নাম দিয়েছিল “মুসলিম’। সুতরাং, বার্তাবাহক তোমাদের মধ্যে সাক্ষী হিসেবে কাজ করবে, এবং তোমরা লোকেদের মধ্যে সাক্ষী হিসেবে কাজ করবে। অতএব, তোমরা সংযোগ প্রার্থনা (সালাত) পালন করবে এবং বাধ্যতামূলক দান (যাকাত) দেবে, এবং আল্লাহকে  দৃঢ়ভাবে  ধারণ করবে; তিনি তোমাদের প্রভু, সর্বশ্রেষ্ঠ প্রতিপালক এবং সর্বশ্রেষ্ঠ সমর্থনকারী।"],
};
